                            Exercise(id: "de-listen-wohnung-gewaehlt-q4", kind: "choice", prompt: "Was ist für Anna am wichtigsten ?", options: ["Das Licht", "Der Preis", "Der Balkon", "Die Küche"], answers: ["Das Licht"], explain: "Sie arbeitet von zu Hause."),
