                            Exercise(id: "de-listen-samstag-geplant-q2", kind: "choice", prompt: "Warum nicht der Berg ?", options: ["Es wird regnen", "Sie sind müde", "Das Museum ist gratis", "Der Berg ist weit"], answers: ["Es wird regnen"], explain: "Es wird regnen, deshalb Museum."),
