    ListeningText(id: "de-listen-nie-gemacht", languageID: "de", title: "Was ich nie gemacht habe", level: "B1", topic: "reisen", unitID: "de-foundations-u6",
        text: "In der Küche einer Herberge vergleichen drei Reisende ihr Leben. Jonas ist in zwanzig Ländern gewesen, aber er hat nie schwimmen gelernt: « Ich weiß, es ist lächerlich ». Amira ist schon zweimal mit Schildkröten getaucht, aber sie hat Afrika vor dieser Reise nie verlassen. Und Coco, die seit sechs Jahren unterwegs ist, ist noch nie geflogen: sie überquert die Ozeane mit dem Schiff und die Grenzen mit dem Bus. « Nie ? » fragt Jonas. « Nie. Die Angst ist älter als ich. » Sie lachen über die Dinge, die sie nicht gemacht haben, und Coco sagt einen Satz, der bleibt: « Man muss nicht alles gemacht haben. Man muss nur noch wollen ».",
        questions: [
                            Exercise(id: "de-listen-nie-gemacht-q1", kind: "choice", prompt: "Was hat Jonas nie gemacht ?", options: ["Schwimmen lernen", "Zwanzig Länder besuchen", "Mit dem Schiff fahren", "Afrika verlassen"], answers: ["Schwimmen lernen"], explain: "Er ist in zwanzig Ländern gewesen, aber nie schwimmen gelernt."),
                            Exercise(id: "de-listen-nie-gemacht-q2", kind: "written", prompt: "Wie oft ist Amira getaucht ?", options: [], answers: ["zweimal", "2 mal", "zwei mal"], explain: "Amira ist schon zweimal mit Schildkröten getaucht."),
                            Exercise(id: "de-listen-nie-gemacht-q3", kind: "choice", prompt: "Wie überquert Coco die Ozeane ?", options: ["Mit dem Schiff", "Mit dem Flugzeug", "Mit dem Bus", "Zu Fuß"], answers: ["Mit dem Schiff"], explain: "Sie überquert die Ozeane mit dem Schiff."),
                            Exercise(id: "de-listen-nie-gemacht-q4", kind: "choice", prompt: "Was sagt Coco über die Angst ?", options: ["Sie ist älter als sie", "Sie ist jünger", "Es ist lächerlich", "Sie ist weg"], answers: ["Sie ist älter als sie"], explain: "Die Angst ist älter als ich."),
                            Exercise(id: "de-listen-nie-gemacht-q5", kind: "written", prompt: "Was reicht, laut Coco ?", options: [], answers: ["noch wollen", "man muss noch wollen"], explain: "Man muss nur noch wollen.")], skills: ["listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"], exposureSkills: ["grammar:relative-clauses"]),
    ListeningText(id: "de-listen-stadt-dorf", languageID: "de", title: "Von der Stadt ins Dorf", level: "B1", topic: "veränderungen", unitID: "de-foundations-u6",
        text: "Lukas erzählt, warum er Berlin verlassen hat. Früher hat er in einer kleinen Wohnung gewohnt und elf Stunden am Tag gearbeitet: « Ich habe gut verdient, aber kein Leben gehabt ». Einen Winter wurde er krank, und da hat er verstanden: so konnte es nicht weitergehen. Heute wohnt er in einem Dorf mit tausend Einwohnern, arbeitet morgens von zu Hause und gartelt nachmittags. « Ich verdiene weniger, aber ich habe Zeit. » Am Anfang haben seine Eltern es nicht verstanden; heute kommen sie jeden Monat. « Bereust du etwas ? » fragt seine Freundin. « Dass ich es nicht früher gemacht habe ».",
        questions: [
                            Exercise(id: "de-listen-stadt-dorf-q1", kind: "choice", prompt: "Wo hat Lukas früher gewohnt ?", options: ["In Berlin", "In einem Dorf", "In Hamburg", "In einer Herberge"], answers: ["In Berlin"], explain: "Lukas erzählt, warum er Berlin verlassen hat."),
                            Exercise(id: "de-listen-stadt-dorf-q2", kind: "written", prompt: "Wie viele Stunden hat er am Tag gearbeitet ?", options: [], answers: ["elf stunden", "11 stunden", "elf"], explain: "Elf Stunden am Tag."),
                            Exercise(id: "de-listen-stadt-dorf-q3", kind: "choice", prompt: "Was hat ihn verändert ?", options: ["Er wurde krank", "Er verlor seinen Job", "Er gewann im Lotto", "Er traf jemanden"], answers: ["Er wurde krank"], explain: "Einen Winter wurde er krank, und da hat er verstanden."),
                            Exercise(id: "de-listen-stadt-dorf-q4", kind: "choice", prompt: "Was macht er nachmittags ?", options: ["Er gartelt", "Er arbeitet mehr Stunden", "Er reist jeden Monat", "Er lernt"], answers: ["Er gartelt"], explain: "Er arbeitet morgens und gartelt nachmittags."),
                            Exercise(id: "de-listen-stadt-dorf-q5", kind: "written", prompt: "Was bereut Lukas ?", options: [], answers: ["dass ich es nicht frueher gemacht habe", "dass ich es nicht früher gemacht habe", "nicht frueher", "nicht früher"], explain: "« Dass ich es nicht früher gemacht habe ».")], skills: ["listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions"]),
    ListeningText(id: "de-listen-handel-tisch", languageID: "de", title: "Das Feilschen um den Tisch", level: "B2", topic: "verhandeln", unitID: "de-foundations-u7",
        text: "Auf einer Gebraucht-App will Lena einen Holztisch für 80 Euro. « Wären Sie bei 60 dabei ? », fragt sie. Der Verkäufer lehnt ab: « Nur wenn Sie ihn heute abholen ». Lena überlegt: « Ich würde 65 geben, wenn Sie den Stuhl dazugeben ». « Unmöglich », lacht er, « aber ich würde Ihnen den Tisch für 70 lassen und ihn Ihnen hochtragen ». Lena zögert nicht: « Würden Sie ihn allein hochtragen ? ». « Ich habe einen Handwagen », antwortet er. « Abgemacht », sagt sie, und fügt hinzu: « Wenn er so schön ist wie auf dem Foto, gibt es fünf Sterne ».",
        questions: [
                            Exercise(id: "de-listen-handel-tisch-q1", kind: "choice", prompt: "Wie viel verlangt der Verkäufer ?", options: ["80 Euro", "60 Euro", "70 Euro", "65 Euro"], answers: ["80 Euro"], explain: "Der Tisch kostet 80 Euro."),
                            Exercise(id: "de-listen-handel-tisch-q2", kind: "written", prompt: "Was schlägt Lena zuerst vor ?", options: [], answers: ["60 euro", "bei 60 dabei", "sechzig euro"], explain: "« Wären Sie bei 60 dabei ? »."),
                            Exercise(id: "de-listen-handel-tisch-q3", kind: "choice", prompt: "Welche Bedingung stellt der Verkäufer ?", options: ["Heute abholen", "Bar bezahlen", "Fünf Sterne geben", "Morgen kommen"], answers: ["Heute abholen"], explain: "« Nur wenn Sie ihn heute abholen »."),
                            Exercise(id: "de-listen-handel-tisch-q4", kind: "choice", prompt: "Was bietet der Verkäufer für 70 ?", options: ["Den Tisch hochtragen", "Den Stuhl dazugeben", "Auf 60 sinken", "Einen Handwagen leihen"], answers: ["Den Tisch hochtragen"], explain: "« Ich würde ihn Ihnen hochtragen »."),
                            Exercise(id: "de-listen-handel-tisch-q5", kind: "written", prompt: "Was verspricht Lena, wenn der Tisch gefällt ?", options: [], answers: ["funf sterne", "fünf sterne", "5 sterne"], explain: "Fünf Sterne.")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "de-listen-nachricht-viertel", languageID: "de", title: "Die Nachricht im Viertel", level: "B2", topic: "nachrichten", unitID: "de-foundations-u8",
        text: "Am Markt besprechen Hannah und Tom, was man sagt. « Man sagt, sie machen die Hauptstraße autofrei », erzählt Hannah. « Schon wieder ? », lacht Tom. « Die Nachricht, die ich gelesen habe, sagt, dass es im Frühling beginnt ». Laut Rathaus wäre es nur am Samstag, aber die Händler, deren Umsatz vom Tourismus abhinge, haben schon demonstriert. « Es stimmt, dass der Lärm sinken würde », räumt Tom ein, « aber, und die Parkplätze ? ». Hannah verteidigt die Maßnahme: « Einerseits würden mehr Leute laufen; andererseits hielten die Busse direkt vor der Tür ». Sie entscheiden es nicht, aber versprechen, wieder darüber zu sprechen, wenn der Plan veröffentlicht wird.",
        questions: [
                            Exercise(id: "de-listen-nachricht-viertel-q1", kind: "choice", prompt: "Was sagt man über die Hauptstraße ?", options: ["Dass sie autofrei wird", "Dass sie breiter wird", "Dass sie geschlossen wird", "Dass sie umbenannt wird"], answers: ["Dass sie autofrei wird"], explain: "« Man sagt, sie machen die Hauptstraße autofrei »."),
                            Exercise(id: "de-listen-nachricht-viertel-q2", kind: "written", prompt: "Wann würde es beginnen ?", options: [], answers: ["im fruhling", "im frühling", "frühling"], explain: "« …dass es im Frühling beginnt »."),
                            Exercise(id: "de-listen-nachricht-viertel-q3", kind: "choice", prompt: "Was sagt das Rathaus ?", options: ["Nur am Samstag", "An allen Tagen", "Nur im Sommer", "An Feiertagen"], answers: ["Nur am Samstag"], explain: "Laut Rathaus wäre es nur am Samstag."),
                            Exercise(id: "de-listen-nachricht-viertel-q4", kind: "choice", prompt: "Wer hat demonstriert ?", options: ["Die Händler", "Die Anwohner", "Die Taxifahrer", "Das Rathaus"], answers: ["Die Händler"], explain: "Die Händler haben schon demonstriert."),
                            Exercise(id: "de-listen-nachricht-viertel-q5", kind: "written", prompt: "Was versprechen Hannah und Tom ?", options: [], answers: ["daruber zu sprechen", "darüber zu sprechen", "wieder daruber sprechen"], explain: "Sie versprechen, wieder darüber zu sprechen.")], skills: ["listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors"]),
    ListeningText(id: "de-listen-radio-debatte", languageID: "de", title: "Radio-Debatte: Vier Tage", level: "C1", topic: "arbeit", unitID: "de-foundations-u9",
        text: "Im Studio diskutiert die Moderatorin Karin Brandt mit dem Unternehmer Sven Ostermann über die Vier-Tage-Woche. « Zunächst eine Zahl », beginnt Brandt, « in der Pilotfirma stieg die Zufriedenheit um zwanzig Prozent ». Ostermann bleibt skeptisch: « Zwar arbeiten alle konzentrierter, aber vier Tage reichen selten, um Projekte ordentlich abzuschließen ». Brandt widerspricht: « Genau deshalb braucht es Struktur, sozusagen weniger Meetings, mehr Fokus ». Der Unternehmer räumt ein: « Es stimmt, dass der Meeting-Wahnsinn Zeit frisst ». Seine Sorge bleibt: Wer betreut am fünften Tag die Kunden ? Die Moderatorin hält dagegen: « Aus meiner Sicht entscheiden am Ende die Zahlen, nicht die Gefühle ». Zusammenfassend bittet sie beide zu einer Pilotrechnung. Nächste Woche debattiert das Studio die Bürokratie.",
        questions: [
                            Exercise(id: "de-listen-radio-debatte-q1", kind: "choice", prompt: "Welche Zahl nennt Brandt zuerst ?", options: ["Zwanzig Prozent mehr Zufriedenheit", "Zwanzig Prozent mehr Umsatz", "Vier Tage weniger Urlaub", "Fünfzig Prozent weniger Meetings"], answers: ["Zwanzig Prozent mehr Zufriedenheit"], explain: "« …stieg die Zufriedenheit um zwanzig Prozent »."),
                            Exercise(id: "de-listen-radio-debatte-q2", kind: "choice", prompt: "Warum ist Ostermann skeptisch ?", options: ["Vier Tage reichen selten für Projekte", "Die Pilotfirma war zu klein", "Ihm sind Zahlen egal", "Kunden wollen keine Zahlen"], answers: ["Vier Tage reichen selten für Projekte"], explain: "« Vier Tage reichen selten, um Projekte ordentlich abzuschließen »."),
                            Exercise(id: "de-listen-radio-debatte-q3", kind: "written", prompt: "Was nennt Brandt als Struktur ?", options: [], answers: ["weniger meetings, mehr fokus", "weniger meetings mehr fokus"], explain: "« …sozusagen weniger Meetings, mehr Fokus »."),
                            Exercise(id: "de-listen-radio-debatte-q4", kind: "written", prompt: "Worauf räumt Ostermann ein ?", options: [], answers: ["dass der meeting-wahnsinn zeit frisst", "dass meetings zeit fressen", "meeting-wahnsinn frisst zeit"], explain: "« Es stimmt, dass der Meeting-Wahnsinn Zeit frisst »."),
                            Exercise(id: "de-listen-radio-debatte-q5", kind: "written", prompt: "Wovon soll am Ende entschieden werden ?", options: [], answers: ["den zahlen", "von den zahlen", "zahlen, nicht gefuhlen", "zahlen, nicht gefühlen"], explain: "« Aus meiner Sicht entscheiden am Ende die Zahlen, nicht die Gefühle ».")], skills: ["listening:inference", "listening:gist", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "de-listen-podcast-nuancen", languageID: "de", title: "Podcast: Feines Deutsch", level: "C1", topic: "sprache", unitID: "de-foundations-u9",
        text: "Im Podcast « Feines Deutsch » sprechen Wiebke und Tarek darüber, wie man Meinungen abschwächt, ohne an Profil zu verlieren. « Irgendwie klingt alles weicher, wenn man eher sagt », meint Wiebke. Tarek hält dagegen: « Wenn du alles abschwächst, nimmt dich niemand mehr ernst ». Sozusagen einigen sie sich auf eine Regel: Bei Fakten darf man schärfen, bei Menschen sollte man abschwächen. Wiebke ergänzt eine Farbe aus dem Büroalltag: « Aus meiner Sicht » klinge sachlicher als « Ich finde ». Tarek lacht: « Und nicht unbedingt ist die höflichste Form von Nein ». Zum Schluss empfehlen sie den Hörern eine Woche Übung: erst bewusst abschwächen, dann bewusst schärfen – und auf die Reaktionen achten.",
        questions: [
                            Exercise(id: "de-listen-podcast-nuancen-q1", kind: "choice", prompt: "Wovor warnt Tarek ?", options: ["Dass ständiges Abschwächen unglaubwürdig macht", "Dass « eher » unhöflich klingt", "Dass Fakten weicher werden", "Dass Podcasts zu kurz sind"], answers: ["Dass ständiges Abschwächen unglaubwürdig macht"], explain: "« Wenn du alles abschwächst, nimmt dich niemand mehr ernst »."),
                            Exercise(id: "de-listen-podcast-nuancen-q2", kind: "written", prompt: "Auf welche Regel einigen sich die beiden ?", options: [], answers: ["bei fakten schärfen, bei menschen abschwächen", "bei fakten scharfen, bei menschen abschwachen", "bei fakten darf man schärfen"], explain: "« Bei Fakten darf man schärfen, bei Menschen sollte man abschwächen »."),
                            Exercise(id: "de-listen-podcast-nuancen-q3", kind: "choice", prompt: "Wie klingt « Aus meiner Sicht » laut Wiebke ?", options: ["Sachlicher als « Ich finde »", "Freundlicher als « Ich finde »", "Unsicherer als « Ich finde »", "Härter als « Ich finde »"], answers: ["Sachlicher als « Ich finde »"], explain: "« …klinge sachlicher als « Ich finde » »."),
                            Exercise(id: "de-listen-podcast-nuancen-q4", kind: "written", prompt: "Was ist laut Tarek die höflichste Form von Nein ?", options: [], answers: ["nicht unbedingt"], explain: "« Nicht unbedingt ist die höflichste Form von Nein »."),
                            Exercise(id: "de-listen-podcast-nuancen-q5", kind: "written", prompt: "Was üben die Hörer eine Woche lang ?", options: [], answers: ["erst abschwächen, dann schärfen", "erst abschwachen dann scharfen", "bewusst abschwächen und schärfen"], explain: "« erst bewusst abschwächen, dann bewusst schärfen ».")], skills: ["listening:inference", "function:express-opinion", "vocab:social-expressions", "vocab:collocations"]),
    ListeningText(id: "de-listen-vortrag-schluessel", languageID: "de", title: "Vortrag: Schlüsselkompetenzen", level: "C1", topic: "bildung", unitID: "de-foundations-u9",
        text: "Herzlich willkommen zur Vorlesung « Berufe von morgen ». Ich teile meinen Vortrag in drei Schritte. Zunächst kläre ich den Begriff: Schlüsselkompetenzen sind Fähigkeiten, die über Fachwissen hinausgehen, etwa im Team kommunizieren oder komplexe Informationen sortieren. Im Folgenden vergleiche ich zwei Studien. Die erste zeigt, dass Arbeitgeber Durchhaltevermögen und Lernbereitschaft höher bewerten als Notendurchschnitte. Die zweite warnt: Wer nur Spezialist bleibt, verliert im Berufsalltag schnell den Anschluss. Daraus folgt meine These: Universitäten sollten Projektarbeit verpflichtend machen. Zusammenfassend merken Sie sich drei Dinge: erstens Transfer, zweitens Kommunikation, drittens Neugier. Zum Schluss öffne ich die Fragerunde; präzise Fragen bekommen präzisere Antworten.",
        questions: [
                            Exercise(id: "de-listen-vortrag-schluessel-q1", kind: "choice", prompt: "Wie beginnt der Vortrag ?", options: ["Mit einer Begriffsklärung", "Mit zwei Studien", "Mit der Fragerunde", "Mit einer These"], answers: ["Mit einer Begriffsklärung"], explain: "« Zunächst kläre ich den Begriff… »."),
                            Exercise(id: "de-listen-vortrag-schluessel-q2", kind: "choice", prompt: "Was bewerten Arbeitgeber laut erster Studie höher ?", options: ["Notendurchschnitte", "Durchhaltevermögen und Lernbereitschaft", "Auslandserfahrung", "Gehaltsvorstellungen"], answers: ["Durchhaltevermögen und Lernbereitschaft"], explain: "« …höher bewerten als Notendurchschnitte »."),
                            Exercise(id: "de-listen-vortrag-schluessel-q3", kind: "choice", prompt: "Wovor warnt die zweite Studie ?", options: ["Dass reine Spezialisten den Anschluss verlieren", "Dass Noten alles entscheiden", "Dass Teams zu groß werden", "Dass Universitäten schließen"], answers: ["Dass reine Spezialisten den Anschluss verlieren"], explain: "« Wer nur Spezialist bleibt, verliert … den Anschluss »."),
                            Exercise(id: "de-listen-vortrag-schluessel-q4", kind: "written", prompt: "Welche These vertritt der Dozent ?", options: [], answers: ["universitäten sollten projektarbeit verpflichtend machen", "universitaten sollten projektarbeit verpflichtend machen", "projektarbeit sollte verpflichtend sein"], explain: "« Universitäten sollten Projektarbeit verpflichtend machen »."),
                            Exercise(id: "de-listen-vortrag-schluessel-q5", kind: "written", prompt: "Nenne die drei Merkdinge in Kurzform.", options: [], answers: ["transfer, kommunikation, neugier", "transfer kommunikation neugier"], explain: "« erstens Transfer, zweitens Kommunikation, drittens Neugier ».")], skills: ["listening:detail", "listening:connected-speech", "vocab:work", "grammar:connectors"]),
    ListeningText(id: "de-listen-neue-wohnung", languageID: "de", title: "Die neue Wohnung", level: "A1", topic: "Wohnen", unitID: "de-foundations-u10",
        text: "Lena hat eine neue Wohnung. Sie ist klein, aber sie gefällt Lena sehr. Es gibt ein Wohnzimmer, ein Schlafzimmer und eine Küche. Das Bad ist sehr klein. Im Wohnzimmer gibt es ein Sofa und einen Tisch. Der Tisch steht neben dem Fenster. Auf dem Sofa liegt eine grüne Decke. Der Schrank ist im Schlafzimmer, neben dem Bett. Am Samstag bringt Jonas eine Lampe. Lena freut sich.",
        questions: [
                            Exercise(id: "de-listen-neue-wohnung-q1", kind: "choice", prompt: "Was hat Lena ?", options: ["Eine kleine Wohnung", "Ein großes Haus", "Ein Zimmer im Hotel", "Ein Haus im Dorf"], answers: ["Eine kleine Wohnung"], explain: "Lena hat eine neue Wohnung. Sie ist klein, aber sie gefällt ihr."),
                            Exercise(id: "de-listen-neue-wohnung-q2", kind: "choice", prompt: "Wie viele Zimmer gibt es ?", options: ["Zwei", "Drei", "Vier", "Eins"], answers: ["Zwei"], explain: "Es gibt ein Wohnzimmer und ein Schlafzimmer: zwei Zimmer."),
                            Exercise(id: "de-listen-neue-wohnung-q3", kind: "written", prompt: "Wo steht der Tisch ?", options: [], answers: ["neben dem fenster", "Neben dem Fenster."], explain: "Der Tisch steht neben dem Fenster."),
                            Exercise(id: "de-listen-neue-wohnung-q4", kind: "choice", prompt: "Wo ist der Schrank ?", options: ["Im Schlafzimmer", "In der Küche", "Im Bad", "Auf dem Balkon"], answers: ["Im Schlafzimmer"], explain: "Der Schrank ist im Schlafzimmer, neben dem Bett."),
                            Exercise(id: "de-listen-neue-wohnung-q5", kind: "written", prompt: "Was liegt auf dem Sofa ?", options: [], answers: ["eine grüne decke", "eine gruene decke"], explain: "Auf dem Sofa liegt eine grüne Decke."),
                            Exercise(id: "de-listen-neue-wohnung-q6", kind: "choice", prompt: "Was bringt Jonas am Samstag ?", options: ["Eine Lampe", "Einen Tisch", "Einen Stuhl", "Blumen"], answers: ["Eine Lampe"], explain: "Am Samstag bringt Jonas eine Lampe.")], skills: ["listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home"]),
    ListeningText(id: "de-listen-viertel-spaziergang", languageID: "de", title: "Spaziergang im Viertel", level: "A1", topic: "Im Viertel", unitID: "de-foundations-u11",
        text: "Miguel ist neu im Viertel. Er fragt Mia: „Gibt es hier einen Supermarkt ?“ „Ja“, sagt Mia, „in der Bahnhofstraße, neben der Apotheke.“ „Und wo kann ich Obst kaufen ?“ „Am Obststand, um die Ecke.“ Sie gehen zusammen los: geradeaus bis zum Park, dann links. Der Obststand ist klein, aber die Äpfel sind lecker. Miguel kauft ein Kilo. Jetzt kennt er sein neues Viertel besser.",
        questions: [
                            Exercise(id: "de-listen-viertel-spaziergang-q1", kind: "choice", prompt: "Was fragt Miguel zuerst ?", options: ["Nach einem Supermarkt", "Nach dem Bahnhof", "Nach einer Schule", "Nach dem Park"], answers: ["Nach einem Supermarkt"], explain: "Er fragt: Gibt es hier einen Supermarkt ?"),
                            Exercise(id: "de-listen-viertel-spaziergang-q2", kind: "choice", prompt: "Wo ist der Supermarkt ?", options: ["In der Bahnhofstraße", "Am Park", "Um die Ecke", "Im ersten Stock"], answers: ["In der Bahnhofstraße"], explain: "Der Supermarkt ist in der Bahnhofstraße, neben der Apotheke."),
                            Exercise(id: "de-listen-viertel-spaziergang-q3", kind: "written", prompt: "Wo kann Miguel Obst kaufen ?", options: [], answers: ["am obststand", "Am Obststand.", "am obststand um die ecke"], explain: "Obst gibt es am Obststand, um die Ecke."),
                            Exercise(id: "de-listen-viertel-spaziergang-q4", kind: "choice", prompt: "Wo gehen sie nach dem Park hin ?", options: ["Nach links", "Nach rechts", "Geradeaus weiter", "Nach Hause"], answers: ["Nach links"], explain: "Sie gehen geradeaus bis zum Park, dann links."),
                            Exercise(id: "de-listen-viertel-spaziergang-q5", kind: "written", prompt: "Was kauft Miguel ?", options: [], answers: ["ein kilo äpfel", "ein kilo aepfel"], explain: "Miguel kauft ein Kilo Äpfel."),
                            Exercise(id: "de-listen-viertel-spaziergang-q6", kind: "choice", prompt: "Wie sind die Äpfel ?", options: ["Lecker", "Zu teuer", "Nicht reif", "Klein"], answers: ["Lecker"], explain: "Der Obststand ist klein, aber die Äpfel sind lecker.")], skills: ["listening:gist", "listening:detail", "grammar:there-is-are", "vocab:town", "function:ask-for-directions"]),
    ListeningText(id: "de-listen-anruf-oma", languageID: "de", title: "Anruf bei Oma", level: "A1", topic: "Familie", unitID: "de-foundations-u12",
        text: "Nadia ruft ihre Oma an. Oma Helga nimmt ab. „Hallo, hier ist Nadia!“ — „Nadia! Du rufst nie an! Wie geht es dir ?“ „Gut, Oma. Ist Opa da ?“ — „Nein, er ist nicht da. Er geht oft im Park spazieren. Und du ? Was machst du ?“ — „Ich lese viel und gehe manchmal ins Kino.“ „Schön. Rufst du mich nächste Woche wieder an ?“ — „Ja, Oma. Bis dann!“",
        questions: [
                            Exercise(id: "de-listen-anruf-oma-q1", kind: "choice", prompt: "Wen ruft Nadia an ?", options: ["Ihre Oma", "Ihre Mutter", "Ihren Onkel", "Ihre Schwester"], answers: ["Ihre Oma"], explain: "Nadia ruft ihre Oma an."),
                            Exercise(id: "de-listen-anruf-oma-q2", kind: "choice", prompt: "Was sagt Oma zuerst über Nadias Anrufe ?", options: ["Du rufst nie an!", "Du rufst immer an!", "Du rufst oft an!", "Du rufst manchmal an!"], answers: ["Du rufst nie an!"], explain: "Oma sagt: Du rufst nie an!"),
                            Exercise(id: "de-listen-anruf-oma-q3", kind: "choice", prompt: "Wo ist Opa ?", options: ["Im Park", "Im Kino", "Zu Hause", "In der Schule"], answers: ["Im Park"], explain: "Er geht oft im Park spazieren."),
                            Exercise(id: "de-listen-anruf-oma-q4", kind: "written", prompt: "Was macht Opa oft ?", options: [], answers: ["er geht spazieren", "spazieren", "er geht im park spazieren"], explain: "Er geht oft im Park spazieren."),
                            Exercise(id: "de-listen-anruf-oma-q5", kind: "written", prompt: "Was macht Nadia manchmal ?", options: [], answers: ["ins kino", "sie geht ins kino", "sie geht manchmal ins kino"], explain: "Ich gehe manchmal ins Kino."),
                            Exercise(id: "de-listen-anruf-oma-q6", kind: "choice", prompt: "Wann ruft Nadia wieder an ?", options: ["Nächste Woche", "Heute Abend", "Morgen", "Am Wochenende"], answers: ["Nächste Woche"], explain: "Rufst du mich nächste Woche wieder an ? — Ja.")], skills: ["listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ListeningText(id: "de-listen-regnerisches-wochenende", languageID: "de", title: "Ein regnerisches Wochenende", level: "A1", topic: "Wetter", unitID: "de-foundations-u13",
        text: "Es ist Samstagmorgen. Kim sieht aus dem Fenster: Es regnet. „Oh nein“, sagt Sam, „das Wetter ist schlecht.“ — „Ja, kalt und nass“, sagt Kim. „Wir gehen oft in den Park, aber heute nicht. Was machen wir ?“ „Ich lese nicht gern bei Regen“, sagt Sam, „aber ich koche gern.“ „Super, wir kochen zusammen und spielen Karten.“ — „Und morgen ?“ „Morgen ist es sonnig und warm.“",
        questions: [
                            Exercise(id: "de-listen-regnerisches-wochenende-q1", kind: "choice", prompt: "Wie ist das Wetter heute ?", options: ["Es regnet", "Es schneit", "Es ist sonnig", "Es ist warm"], answers: ["Es regnet"], explain: "Kim sieht aus dem Fenster: Es regnet."),
                            Exercise(id: "de-listen-regnerisches-wochenende-q2", kind: "choice", prompt: "Wohin gehen sie oft ?", options: ["In den Park", "Ins Kino", "In die Schule", "Zum Markt"], answers: ["In den Park"], explain: "Wir gehen oft in den Park, aber heute nicht."),
                            Exercise(id: "de-listen-regnerisches-wochenende-q3", kind: "written", prompt: "Was macht Sam gern ?", options: [], answers: ["kochen", "koche", "er kocht gern"], explain: "Ich lese nicht gern bei Regen, aber ich koche gern."),
                            Exercise(id: "de-listen-regnerisches-wochenende-q4", kind: "written", prompt: "Wie ist das Wetter morgen ?", options: [], answers: ["sonnig und warm", "es ist sonnig und warm", "warm"], explain: "Morgen ist es sonnig und warm."),
                            Exercise(id: "de-listen-regnerisches-wochenende-q5", kind: "choice", prompt: "Was machen sie heute zusammen ?", options: ["Kochen und Karten", "Lesen und Laufen", "Einkaufen und Kino", "Schwimmen"], answers: ["Kochen und Karten"], explain: "Wir kochen zusammen und spielen Karten."),
                            Exercise(id: "de-listen-regnerisches-wochenende-q6", kind: "choice", prompt: "Warum gehen sie heute nicht in den Park ?", options: ["Es regnet", "Sie sind müde", "Kim muss arbeiten", "Sie haben keine Zeit"], answers: ["Es regnet"], explain: "Heute regnet es — deshalb bleiben sie zu Hause.")], skills: ["listening:gist", "listening:detail", "vocab:weather", "vocab:daily-routine", "grammar:frequency-adverbs", "function:talk-about-weather"]),
    ListeningText(id: "de-listen-ubahn-verlaufen", languageID: "de", title: "Im falschen Zug", level: "A1", topic: "Unterwegs", unitID: "de-foundations-u14",
        text: "Sam ist neu in Berlin. Er möchte zu Kim, aber er sitzt im falschen Zug. „Oh nein — das ist die U8, nicht die U2 !“ Er fragt eine Frau: „Entschuldigung, wann fährt die nächste Bahn ?“ — „Um Viertel nach zehn, von Gleis 3“, sagt die Frau. Sam fährt zurück zum Alexanderplatz. Dort steigt er in die U2. Um halb elf klingelt er bei Kim. „Du bist spät !“ — „Ab jetzt nehme ich immer die U2“, sagt Sam.",
        questions: [
                            Exercise(id: "de-listen-ubahn-verlaufen-q1", kind: "choice", prompt: "Wo ist Sam neu ?", options: ["In Berlin", "In Bonn", "In Köln", "In Wien"], answers: ["In Berlin"], explain: "Sam ist neu in Berlin."),
                            Exercise(id: "de-listen-ubahn-verlaufen-q2", kind: "choice", prompt: "Welche Bahn möchte Sam nehmen ?", options: ["Die U2", "Die U8", "Die U3", "Die S7"], answers: ["Die U2"], explain: "Das ist die U8, nicht die U2 — er möchte die U2."),
                            Exercise(id: "de-listen-ubahn-verlaufen-q3", kind: "written", prompt: "Wann fährt die nächste Bahn ?", options: [], answers: ["um viertel nach zehn", "Viertel nach zehn", "10:15 Uhr"], explain: "Um Viertel nach zehn, von Gleis 3."),
                            Exercise(id: "de-listen-ubahn-verlaufen-q4", kind: "choice", prompt: "Wo steigt Sam in die U2 ?", options: ["Am Alexanderplatz", "Am Hauptbahnhof", "Bei Kim", "In Bonn"], answers: ["Am Alexanderplatz"], explain: "Sam fährt zurück zum Alexanderplatz. Dort steigt er in die U2."),
                            Exercise(id: "de-listen-ubahn-verlaufen-q5", kind: "written", prompt: "Wann ist Sam bei Kim ?", options: [], answers: ["um halb elf", "halb elf", "10:30", "10:30 Uhr"], explain: "Um halb elf klingelt er bei Kim."),
                            Exercise(id: "de-listen-ubahn-verlaufen-q6", kind: "choice", prompt: "Was nimmt Sam ab jetzt immer ?", options: ["Die U2", "Die U8", "Die Bahn von Gleis 3", "Ein Fahrrad"], answers: ["Die U2"], explain: "Ab jetzt nehme ich immer die U2, sagt Sam.")], skills: ["listening:gist", "listening:detail", "vocab:transport", "function:tell-time"]),
    ListeningText(id: "de-listen-apotheke-samstag", languageID: "de", title: "Samstag in der Apotheke", level: "A1", topic: "Gesundheit", unitID: "de-foundations-u15",
        text: "Es ist Samstagmorgen. Mia hat Kopfschmerzen und Fieber. Kim geht mit ihr in die Apotheke. „Guten Tag, meine Freundin fühlt sich nicht gut“, sagt Kim. „Sie braucht etwas gegen die Schmerzen.“ — „Nehmen Sie diese Tabletten“, sagt der Apotheker. „Zweimal am Tag, mit Wasser.“ — „Was kostet das ?“ — „Neun Euro.“ Mia nimmt die Tabletten und trinkt viel Wasser. Am Abend fühlt sie sich besser. Kim sagt: „Gute Besserung und schlaf gut !“",
        questions: [
                            Exercise(id: "de-listen-apotheke-samstag-q1", kind: "choice", prompt: "Was hat Mia ?", options: ["Kopfschmerzen und Fieber", "Husten und Schnupfen", "Nur Müdigkeit", "Bauchschmerzen"], answers: ["Kopfschmerzen und Fieber"], explain: "Mia hat Kopfschmerzen und Fieber."),
                            Exercise(id: "de-listen-apotheke-samstag-q2", kind: "written", prompt: "Wohin gehen die Freundinnen ?", options: [], answers: ["in die apotheke", "zur apotheke", "Apotheke"], explain: "Kim geht mit ihr in die Apotheke."),
                            Exercise(id: "de-listen-apotheke-samstag-q3", kind: "choice", prompt: "Wie oft soll Mia die Tabletten nehmen ?", options: ["Zweimal am Tag", "Dreimal am Tag", "Einmal am Tag", "Nie"], answers: ["Zweimal am Tag"], explain: "Zweimal am Tag, mit Wasser."),
                            Exercise(id: "de-listen-apotheke-samstag-q4", kind: "written", prompt: "Was kostet das ?", options: [], answers: ["neun euro", "9 euro", "9"], explain: "Neun Euro."),
                            Exercise(id: "de-listen-apotheke-samstag-q5", kind: "written", prompt: "Was trinkt Mia ?", options: [], answers: ["wasser", "viel wasser"], explain: "Mia nimmt die Tabletten und trinkt viel Wasser."),
                            Exercise(id: "de-listen-apotheke-samstag-q6", kind: "choice", prompt: "Wie fühlt sich Mia am Abend ?", options: ["Besser", "Schlechter", "Gleich", "Sehr krank"], answers: ["Besser"], explain: "Am Abend fühlt sie sich besser.")], skills: ["listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs"]),
    ListeningText(id: "de-listen-ueberraschungsfest", languageID: "de", title: "Das Überraschungsfest", level: "A1", topic: "essen", unitID: "de-foundations-u16",
        text: "Es ist Freitag. Sascha hat morgen Geburtstag, aber er weiß nichts. Anna ruft im Restaurant Adler an: « Wir möchten einen Tisch für zehn Personen reservieren. » — « Kein Problem », sagt der Kellner. « Was möchten Sie essen ? » — « Zehn Pizzen, bitte. Und was ist in der Pizza Funghi ? » — « Pilze und Käse. » Am Samstag kommen alle um sechs, Sascha um sieben. Alle rufen: « Überraschung ! » Sascha freut sich sehr: « Ihr seid die besten Freunde ! »",
        questions: [
                            Exercise(id: "de-listen-ueberraschungsfest-q1", kind: "choice", prompt: "Wann hat Sascha Geburtstag ?", options: ["Morgen", "Heute", "Am Freitag", "Nächste Woche"], answers: ["Morgen"], explain: "Es ist Freitag, und Sascha hat morgen Geburtstag."),
                            Exercise(id: "de-listen-ueberraschungsfest-q2", kind: "written", prompt: "Wen ruft Anna an ?", options: [], answers: ["im restaurant adler", "restaurant adler", "das restaurant adler"], explain: "Anna ruft im Restaurant Adler an."),
                            Exercise(id: "de-listen-ueberraschungsfest-q3", kind: "written", prompt: "Was möchten sie essen ?", options: [], answers: ["zehn pizzen", "10 pizzen", "zehn pizza"], explain: "« Zehn Pizzen, bitte », sagt Anna."),
                            Exercise(id: "de-listen-ueberraschungsfest-q4", kind: "choice", prompt: "Was ist in der Pizza Funghi ?", options: ["Pilze und Käse", "Schinken und Käse", "Tomaten und Salat", "Nur Käse"], answers: ["Pilze und Käse"], explain: "« Pilze und Käse », sagt der Kellner."),
                            Exercise(id: "de-listen-ueberraschungsfest-q5", kind: "written", prompt: "Wann kommen die Freunde ?", options: [], answers: ["um sechs", "um 6", "um sechs uhr"], explain: "Am Samstag kommen alle um sechs."),
                            Exercise(id: "de-listen-ueberraschungsfest-q6", kind: "choice", prompt: "Wie findet Sascha die Party ?", options: ["Er freut sich sehr", "Er ist müde", "Er möchte zahlen", "Er geht nach Hause"], answers: ["Er freut sich sehr"], explain: "Er freut sich sehr und dankt seinen Freunden.")], skills: ["listening:gist", "listening:detail", "vocab:food", "function:order-food"]),
    ListeningText(id: "de-listen-geburtstagsplan", languageID: "de", title: "Der Geburtstagsplan", level: "A2", topic: "geschenke", unitID: "de-foundations-u17",
        text: "Mia und Paul planen Emmas Geburtstag am Samstag. « Was werden wir ihr schenken ? », fragt Mia. « Ich werde ein Kochbuch kaufen — sie kocht so gern », sagt Paul. « Gute Idee ! Ich bestelle eine Kerze und Ballons. » Dann wird Mia still: « Ich kann leider nicht kommen, weil ich am Samstag arbeiten muss. » « Schade », sagt Paul, « aber am Abend feiern wir in der Pizzeria Sonne. Kommst du danach ? » « Klar, ab acht Uhr bin ich dabei. » Am Ende lachen sie: Emma weiß von nichts.",
        questions: [
                            Exercise(id: "de-listen-geburtstagsplan-q1", kind: "choice", prompt: "Was wird Paul Emma schenken ?", options: ["Ein Kochbuch", "Kerzen und Ballons", "Eine Kette", "Konzertkarten"], answers: ["Ein Kochbuch"], explain: "« Ich werde ein Kochbuch kaufen — sie kocht so gern »."),
                            Exercise(id: "de-listen-geburtstagsplan-q2", kind: "written", prompt: "Was bestellt Mia ?", options: [], answers: ["eine kerze und ballons", "kerze und ballons", "eine kerze, ballons"], explain: "« Ich bestelle eine Kerze und Ballons. »"),
                            Exercise(id: "de-listen-geburtstagsplan-q3", kind: "written", prompt: "Warum kann Mia nicht kommen ?", options: [], answers: ["weil sie arbeiten muss", "sie muss arbeiten", "arbeiten"], explain: "Sie muss am Samstag arbeiten."),
                            Exercise(id: "de-listen-geburtstagsplan-q4", kind: "choice", prompt: "Wo feiern sie am Abend ?", options: ["In der Pizzeria Sonne", "Zu Hause", "Im Restaurant Adler", "Im Park"], answers: ["In der Pizzeria Sonne"], explain: "« … am Abend feiern wir in der Pizzeria Sonne »."),
                            Exercise(id: "de-listen-geburtstagsplan-q5", kind: "written", prompt: "Wann ist Mia dabei ?", options: [], answers: ["ab acht uhr", "ab 8 uhr", "nach acht uhr"], explain: "« Ab acht Uhr bin ich dabei. »"),
                            Exercise(id: "de-listen-geburtstagsplan-q6", kind: "choice", prompt: "Was erfährt Emma noch nicht ?", options: ["Von der Party", "Von dem Kochbuch", "Von der Arbeit", "Von den Ballons"], answers: ["Von der Party"], explain: "Emma weiß von nichts — sie soll überrascht sein.")], skills: ["listening:gist", "listening:inference", "grammar:going-to", "vocab:social-expressions"]),
    ListeningText(id: "de-listen-sommerepisode", languageID: "de", title: "Die Sommerepisode", level: "B1", topic: "erlebnisse", unitID: "de-foundations-u18",
        text: "Kim trifft Tim im Park. « Du wolltest doch was erzählen », sagt Kim. Tim nickt: « Letzten Sommer arbeitete ich in einem Café am See. Einmal bestellte ein Gast elfmal Cappuccino — einen nach dem anderen. » « Nicht zu fassen ! », ruft Kim. « Und dann ? » « Ich brachte alle Tassen hinaus. Plötzlich stand seine ganze Familie auf und verteilte den Kaffee an die Passanten am Weg. » « Was ? Warum ? » « Es stellte sich heraus, dass er seinen siebzigsten Geburtstag feierte und jedem eine Freude machen wollte. Am Ende lachte der ganze See. » Kim schüttelt den Kopf: « Solche Geschichten passieren nur dir. »",
        questions: [
                            Exercise(id: "de-listen-sommerepisode-q1", kind: "choice", prompt: "Wo arbeitete Tim letzten Sommer ?", options: ["In einem Café am See", "In einem Park", "In einer Bäckerei", "Auf einem Boot"], answers: ["In einem Café am See"], explain: "« Letzten Sommer arbeitete ich in einem Café am See »."),
                            Exercise(id: "de-listen-sommerepisode-q2", kind: "written", prompt: "Was bestellte der Gast ?", options: [], answers: ["elfmal cappuccino", "elf cappuccinos", "elfmal cappuccino"], explain: "Einmal bestellte ein Gast elfmal Cappuccino."),
                            Exercise(id: "de-listen-sommerepisode-q3", kind: "choice", prompt: "Wer stand plötzlich auf ?", options: ["Seine ganze Familie", "Die Passanten", "Kim und Tim", "Der Chef des Cafés"], answers: ["Seine ganze Familie"], explain: "« Plötzlich stand seine ganze Familie auf »."),
                            Exercise(id: "de-listen-sommerepisode-q4", kind: "written", prompt: "Warum machte der Gast das ?", options: [], answers: ["geburtstag", "er feierte seinen siebzigsten geburtstag", "siebzigster geburtstag"], explain: "Er feierte seinen siebzigsten Geburtstag und wollte jedem eine Freude machen."),
                            Exercise(id: "de-listen-sommerepisode-q5", kind: "choice", prompt: "Wie endete die Geschichte ?", options: ["Alle lachten", "Die Familie ging wütend", "Tim verlor den Job", "Es begann zu regnen"], answers: ["Alle lachten"], explain: "« Am Ende lachte der ganze See »."),
                            Exercise(id: "de-listen-sommerepisode-q6", kind: "choice", prompt: "Was meint Kim mit ihrem Schluss ?", options: ["Tim erlebt solche Dinge oft", "Tim soll aufhören zu arbeiten", "Tim lügt", "Tim mag keinen Kaffee"], answers: ["Tim erlebt solche Dinge oft"], explain: "« Solche Geschichten passieren nur dir » — scherzhaft: nur Tim erlebt so etwas.")], skills: ["listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors"]),
    ListeningText(id: "de-listen-debatte-takt", languageID: "de", title: "Debatte mit Takt", level: "C1", topic: "debatte", unitID: "de-foundations-u9",
        text: "In der Sendung « Punkt kontra Punkt » streiten Hana Berger und Robert Falk über autofreie Innenstädte. Falk beginnt: « Der Handel wird leiden, das ist doch klar. » Berger bleibt ruhig: « Ich verstehe die Sorge, aber die Zahlen aus anderen Städten widersprechen ihr. » Falk schärft nach: « Das mag stimmen, allerdings handelt es sich um Großstädte. » — « Da bin ich ganz bei Ihnen », sagt Berger, « dennoch war auch Freiburg vor zwanzig Jahren skeptisch. » Der Moderator greift ein: « Sie widersprechen sich höflich — wie geht das ? » Berger lacht: « Erst würdigen, dann kontern. Und nie den Menschen, immer die Position angreifen. » Falk nickt: « Daran könnte ich mich gewöhnen. »",
        questions: [
                            Exercise(id: "de-listen-debatte-takt-q1", kind: "choice", prompt: "Welche Sorge äußert Falk zuerst ?", options: ["Der Handel wird leiden", "Die Luft wird schlechter", "Die Stadt wird lauter", "Die Mieten steigen"], answers: ["Der Handel wird leiden"], explain: "« Der Handel wird leiden, das ist doch klar »."),
                            Exercise(id: "de-listen-debatte-takt-q2", kind: "written", prompt: "Wie beginnt Berger ihren Widerspruch ?", options: [], answers: ["ich verstehe die sorge", "ich verstehe ihre sorge"], explain: "« Ich verstehe die Sorge, aber… » — erst Verständnis, dann Kontra."),
                            Exercise(id: "de-listen-debatte-takt-q3", kind: "choice", prompt: "Was räumt Falk ein und begrenzt er zugleich ?", options: ["Dass die Zahlen stimmen, aber nur für Großstädte", "Dass Freiburg skeptisch war", "Dass der Handel leidet", "Dass Berger recht hat"], answers: ["Dass die Zahlen stimmen, aber nur für Großstädte"], explain: "« Das mag stimmen, allerdings handelt es sich um Großstädte »."),
                            Exercise(id: "de-listen-debatte-takt-q4", kind: "written", prompt: "Welches Beispiel nennt Berger ?", options: [], answers: ["freiburg"], explain: "« Dennoch war auch Freiburg vor zwanzig Jahren skeptisch »."),
                            Exercise(id: "de-listen-debatte-takt-q5", kind: "choice", prompt: "Was empfiehlt Berger für den höflichen Widerspruch ?", options: ["Erst würdigen, dann die Position angreifen", "Immer den Menschen angreifen", "Nie widersprechen", "Lauter werden"], answers: ["Erst würdigen, dann die Position angreifen"], explain: "« Erst würdigen, dann kontern. Und nie den Menschen, immer die Position angreifen »."),
                            Exercise(id: "de-listen-debatte-takt-q6", kind: "written", prompt: "Wie reagiert Falk am Ende ?", options: [], answers: ["daran könnte ich mich gewöhnen", "daran konnte ich mich gewohnen"], explain: "« Daran könnte ich mich gewöhnen » — er erkennt Bergers Takt halb im Scherz an.")], skills: ["listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "de-listen-feier-freitag", languageID: "de", title: "Ein Abend bei Lea", level: "A1", topic: "besuch", unitID: "de-foundations-u19",
        text: "Es ist Freitagabend. Jakob steht vor Leas Tür und klingelt. « Darf ich reinkommen ? » — « Natürlich, komm rein ! Du darfst die Schuhe ausziehen. » Jakob bringt einen Kuchen mit: « Der ist für euch. » Am Tisch fragt Lea: « Möchtest du Tee oder Saft ? » — « Tee, bitte. » Sie essen Kuchen und reden lange. Am Ende sagt Jakob: « Vielen Dank für die Einladung ! » — « Bis zum nächsten Mal ! »",
        questions: [
                            Exercise(id: "de-listen-feier-freitag-q1", kind: "choice", prompt: "Wann kommt Jakob zu Lea ?", options: ["Am Freitagabend", "Am Samstagmorgen", "Am Montag", "Am Sonntag"], answers: ["Am Freitagabend"], explain: "Es ist Freitagabend."),
                            Exercise(id: "de-listen-feier-freitag-q2", kind: "written", prompt: "Was fragt Jakob an der Tür ?", options: [], answers: ["darf ich reinkommen", "darf ich reinkommen ?", "darf ich hereinkommen"], explain: "« Darf ich reinkommen ? », fragt Jakob."),
                            Exercise(id: "de-listen-feier-freitag-q3", kind: "choice", prompt: "Was darf Jakob machen ?", options: ["Die Schuhe ausziehen", "Rauchen", "Kochen", "Fernsehen"], answers: ["Die Schuhe ausziehen"], explain: "« Du darfst die Schuhe ausziehen. »"),
                            Exercise(id: "de-listen-feier-freitag-q4", kind: "written", prompt: "Was bringt Jakob mit ?", options: [], answers: ["einen kuchen", "kuchen", "einen kuchen mit"], explain: "Jakob bringt einen Kuchen mit."),
                            Exercise(id: "de-listen-feier-freitag-q5", kind: "choice", prompt: "Was nimmt Jakob zu trinken ?", options: ["Tee", "Saft", "Wasser", "Kaffee"], answers: ["Tee"], explain: "« Tee, bitte. »"),
                            Exercise(id: "de-listen-feier-freitag-q6", kind: "written", prompt: "Was sagt Jakob am Ende ?", options: [], answers: ["vielen dank für die einladung", "vielen dank fur die einladung", "danke für die einladung"], explain: "« Vielen Dank für die Einladung ! »")], skills: ["listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can"]),
    ListeningText(id: "de-listen-reklamation-rechnung", languageID: "de", title: "Anruf im Laden", level: "A2", topic: "reklamation", unitID: "de-foundations-u20",
        text: "Anna ruft im Laden ElektroPlus an. « Guten Tag, es tut mir leid, aber mein Wasserkocher funktioniert nicht mehr. » — « Das tut mir leid. Wann haben Sie ihn gekauft ? » — « Letzte Woche, am Montag. Ich habe die Rechnung hier. » — « Gut, dann können wir ihn umtauschen. Haben Sie ihn schon mit einer anderen Steckdose ausprobiert ? » — « Ja, zweimal. Er geht einfach nicht an. » — « Verstanden. Bringen Sie ihn und die Rechnung einfach vorbei, dann bekommen Sie ein neues Gerät. » — « Super, vielen Dank ! Bis morgen. »",
        questions: [
                            Exercise(id: "de-listen-reklamation-rechnung-q1", kind: "choice", prompt: "Was funktioniert nicht ?", options: ["Der Wasserkocher", "Die Kaffeemaschine", "Der Fernseher", "Der Drucker"], answers: ["Der Wasserkocher"], explain: "« Mein Wasserkocher funktioniert nicht mehr. »"),
                            Exercise(id: "de-listen-reklamation-rechnung-q2", kind: "choice", prompt: "Wann hat Anna ihn gekauft ?", options: ["Letzte Woche, am Montag", "Gestern", "Im Mai", "Vor einem Monat"], answers: ["Letzte Woche, am Montag"], explain: "« Letzte Woche, am Montag. »"),
                            Exercise(id: "de-listen-reklamation-rechnung-q3", kind: "written", prompt: "Welchen Beleg hat Anna ?", options: [], answers: ["die rechnung", "eine rechnung"], explain: "« Ich habe die Rechnung hier. »"),
                            Exercise(id: "de-listen-reklamation-rechnung-q4", kind: "written", prompt: "Was hat Anna schon ausprobiert ?", options: [], answers: ["eine andere steckdose", "eine andere steckdose, zweimal", "eine andere steckdose zweimal"], explain: "« Haben Sie ihn schon mit einer anderen Steckdose ausprobiert ? » — « Ja, zweimal. »"),
                            Exercise(id: "de-listen-reklamation-rechnung-q5", kind: "choice", prompt: "Was bekommt Anna am Ende ?", options: ["Ein neues Gerät", "Ihr Geld zurück", "Nur eine Reparatur", "Gar nichts"], answers: ["Ein neues Gerät"], explain: "« …dann bekommen Sie ein neues Gerät. »")], skills: ["listening:gist", "listening:detail", "function:solve-problems", "grammar:past-simple-regular"]),
    ListeningText(id: "de-listen-probevorstellung", languageID: "de", title: "Das Gespräch bei Frau Berger", level: "B1", topic: "arbeit", unitID: "de-foundations-u21",
        text: "Frau Berger führt das Gespräch. « Herr Moos, erzählen Sie kurz von Ihrer Erfahrung. » — « Ich habe drei Jahre in einer Marketingagentur gearbeitet, außerdem habe ich dort ein kleines Team geleitet. » — « Und was ist Ihre größte Stärke ? » — « Ich bleibe ruhig, wenn viel los ist. Letztes Jahr liefen zehn Projekte gleichzeitig — das hat gut funktioniert. » — « Warum haben Sie sich bei uns beworben ? » — « Weil Ihre Firma nachhaltig arbeitet. Das überzeugt mich. » Frau Berger nickt. « Wo sehen Sie sich in fünf Jahren ? » — « In einer Führungsrolle, aber zuerst will ich hier viel lernen. » — « Danke, wir melden uns bis Freitag. »",
        questions: [
                            Exercise(id: "de-listen-probevorstellung-q1", kind: "choice", prompt: "Warum hat sich Herr Moos beworben ?", options: ["Weil die Firma nachhaltig arbeitet", "Weil sie viel Geld zahlt", "Weil sie nah an seiner Wohnung liegt", "Weil sein Freund dort arbeitet"], answers: ["Weil die Firma nachhaltig arbeitet"], explain: "« Weil Ihre Firma nachhaltig arbeitet. Das überzeugt mich. »"),
                            Exercise(id: "de-listen-probevorstellung-q2", kind: "written", prompt: "Was hat er in der Agentur geleitet ?", options: [], answers: ["ein kleines team"], explain: "« Außerdem habe ich dort ein kleines Team geleitet. »"),
                            Exercise(id: "de-listen-probevorstellung-q3", kind: "choice", prompt: "Wie reagiert er, wenn viel los ist ?", options: ["Er bleibt ruhig", "Er wird laut", "Er braucht Hilfe", "Er geht früher"], answers: ["Er bleibt ruhig"], explain: "« Ich bleibe ruhig, wenn viel los ist. »"),
                            Exercise(id: "de-listen-probevorstellung-q4", kind: "written", prompt: "Wo sieht er sich in fünf Jahren ?", options: [], answers: ["in einer führungsrolle", "in einer fuehrungsrolle", "in einer führenden rolle"], explain: "« In einer Führungsrolle … »"),
                            Exercise(id: "de-listen-probevorstellung-q5", kind: "choice", prompt: "Was will er zuerst tun ?", options: ["In der Firma viel lernen", "Sofort Chef werden", "Die Firma wieder verlassen", "Ein eigenes Geschäft aufmachen"], answers: ["In der Firma viel lernen"], explain: "« …aber zuerst will ich hier viel lernen. »")], skills: ["listening:inference", "listening:detail", "vocab:work", "function:talk-about-work"]),
    ListeningText(id: "de-listen-ton-podcast", languageID: "de", title: "Podcast: Das passende Verb", level: "C1", topic: "sprache", unitID: "de-foundations-u9",
        text: "Im Podcast « Feines Deutsch » fragt Hörerin Katrin: « Warum klingt « eine Entscheidung machen » falsch ? » Wiebke erklärt: Kollokationen sind Gewohnheiten, keine Regeln — « treffen » gehört zur Entscheidung wie « üben » zur Kritik. Tarek ergänzt: « Wer das falsche Verb nimmt, macht keinen Fehler, der sofort auffällt — aber der Ton stimmt nicht ». Die beiden diskutieren, ob man solche Wendungen auswendig lernen soll. Wiebke hält Lesen für wirksamer: « Im Kontext bleibt die Verbindung hängen ». Am Ende geben sie der Hörerin einen Auftrag: eine Woche lang jede E-Mail auf ein einziges Verb prüfen — das, das man ersetzen könnte. « Genau genommen », lacht Tarek, « ist das die beste Übung für den genauen Ton ».",
        questions: [
                            Exercise(id: "de-listen-ton-podcast-q1", kind: "choice", prompt: "Was sind Kollokationen laut Wiebke ?", options: ["Gewohnheiten, keine Regeln", "Feste Grammatikregeln", "Fremdwörter aus dem Englischen", "Fehler, die auffallen"], answers: ["Gewohnheiten, keine Regeln"], explain: "« Kollokationen sind Gewohnheiten, keine Regeln. »"),
                            Exercise(id: "de-listen-ton-podcast-q2", kind: "written", prompt: "Welches Verb gehört zur Kritik ?", options: [], answers: ["üben", "ueben"], explain: "« …wie « üben » zur Kritik. »"),
                            Exercise(id: "de-listen-ton-podcast-q3", kind: "choice", prompt: "Was meint Tarek mit « der Ton stimmt nicht » ?", options: ["Es klingt nicht muttersprachlich", "Die Grammatik ist falsch", "Die Mail ist zu lang", "Die Musik ist zu laut"], answers: ["Es klingt nicht muttersprachlich"], explain: "« …macht keinen Fehler, der sofort auffällt — aber der Ton stimmt nicht. »"),
                            Exercise(id: "de-listen-ton-podcast-q4", kind: "choice", prompt: "Was hält Wiebke für wirksamer als Auswendiglernen ?", options: ["Lesen im Kontext", "Wortlisten schreiben", "Vokabel-Apps", "Alles übersetzen"], answers: ["Lesen im Kontext"], explain: "« Im Kontext bleibt die Verbindung hängen. »"),
                            Exercise(id: "de-listen-ton-podcast-q5", kind: "written", prompt: "Welchen Auftrag bekommen die Hörer ?", options: [], answers: ["jede e-mail auf ein verb prüfen", "jede email auf ein verb pruefen", "eine woche lang jede e-mail auf ein verb prüfen"], explain: "« …eine Woche lang jede E-Mail auf ein einziges Verb prüfen. »")], skills: ["listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion"]),
    ListeningText(id: "de-listen-ueberraschungsparty", languageID: "de", title: "Die Überraschungsparty", level: "A1", topic: "feste", unitID: "de-foundations-u22",
        text: "Samstag ist Tims Geburtstag. Lea ruft Mira an: « Wir machen eine Überraschungsparty für Tim ! Bist du dabei ? » — « Ja, klar ! Wann beginnt die Party ? » — « Um sieben Uhr, bei mir zu Hause. Tim kommt um halb acht — bitte sei pünktlich ! » — « Was bringe ich mit ? » — « Bring bitte Saft und Kekse mit. Ich mache einen Kuchen. » — « Super ! Ist Paul auch eingeladen ? » — « Ja, er bringt die Musik mit. Und Mira: sag nichts zu Tim ! Es ist eine Überraschung ! » — « Keine Sorge, ich sage nichts. Versprochen ! Bis Samstag ! »",
        questions: [
                            Exercise(id: "de-listen-ueberraschungsparty-q1", kind: "choice", prompt: "Wann ist Tims Geburtstag ?", options: ["Am Samstag", "Am Sonntag", "Am Freitag", "Heute"], answers: ["Am Samstag"], explain: "Samstag ist Tims Geburtstag."),
                            Exercise(id: "de-listen-ueberraschungsparty-q2", kind: "choice", prompt: "Wo ist die Party ?", options: ["Bei Lea zu Hause", "Im Café", "Bei Tim zu Hause", "Im Park"], answers: ["Bei Lea zu Hause"], explain: "Um sieben Uhr, bei mir zu Hause."),
                            Exercise(id: "de-listen-ueberraschungsparty-q3", kind: "written", prompt: "Wann beginnt die Party ?", options: [], answers: ["um sieben uhr", "um 19 uhr", "sieben uhr"], explain: "Um sieben Uhr, bei Lea zu Hause."),
                            Exercise(id: "de-listen-ueberraschungsparty-q4", kind: "written", prompt: "Was bringt Mira mit ?", options: [], answers: ["saft und kekse", "saft und kekse mit"], explain: "Bring bitte Saft und Kekse mit."),
                            Exercise(id: "de-listen-ueberraschungsparty-q5", kind: "choice", prompt: "Was bringt Paul mit ?", options: ["Die Musik", "Den Kuchen", "Saft", "Blumen"], answers: ["Die Musik"], explain: "Er bringt die Musik mit."),
                            Exercise(id: "de-listen-ueberraschungsparty-q6", kind: "choice", prompt: "Was ist mit Tim ?", options: ["Er weiß nichts von der Party", "Er plant die Party", "Er ist auf Reisen", "Er kommt zu spät"], answers: ["Er weiß nichts von der Party"], explain: "« Sag nichts zu Tim ! Es ist eine Überraschung ! »")], skills: ["listening:detail", "grammar:present-simple", "vocab:social-expressions", "vocab:food"]),
    ListeningText(id: "de-listen-umkleidekabine", languageID: "de", title: "In der Umkleidekabine", level: "A1", topic: "einkaufen", unitID: "de-foundations-u23",
        text: "Anna möchte eine Jacke kaufen. Die Verkäuferin fragt: « Welche Größe haben Sie ? » — « Größe M, ich glaube. » — « Hier, probieren Sie die Jacke an. Die Umkleide ist da drüben. » Anna geht in die Umkleide. Nach einer Minute: « Die Jacke ist zu klein. Haben Sie sie auch in Größe L ? » — « Ja, hier bitte. » — Eine Minute später: « Und, passt sie ? » — « Ja, jetzt passt sie gut. Wie viel kostet sie ? » — « 59 Euro. » — « Ich nehme sie. Wo kann ich zahlen ? » — « An der Kasse, dort vorne. Vielen Dank ! »",
        questions: [
                            Exercise(id: "de-listen-umkleidekabine-q1", kind: "choice", prompt: "Was möchte Anna kaufen ?", options: ["Eine Jacke", "Ein T-Shirt", "Eine Hose", "Schuhe"], answers: ["Eine Jacke"], explain: "Anna möchte eine Jacke kaufen."),
                            Exercise(id: "de-listen-umkleidekabine-q2", kind: "written", prompt: "Welche Größe probiert Anna zuerst an ?", options: [], answers: ["m", "größe m", "groesse m", "grosse m"], explain: "« Welche Größe haben Sie ? » — « Größe M. »"),
                            Exercise(id: "de-listen-umkleidekabine-q3", kind: "choice", prompt: "Wie findet Anna die erste Jacke ?", options: ["Zu klein", "Zu groß", "Zu teuer", "Zu eng an den Ärmeln"], answers: ["Zu klein"], explain: "« Die Jacke ist zu klein. »"),
                            Exercise(id: "de-listen-umkleidekabine-q4", kind: "written", prompt: "Wie viel kostet die Jacke ?", options: [], answers: ["59 euro", "neunundfünfzig euro", "neunundfuenfzig euro"], explain: "« 59 Euro. »"),
                            Exercise(id: "de-listen-umkleidekabine-q5", kind: "choice", prompt: "Wo kann Anna zahlen ?", options: ["An der Kasse", "In der Umkleide", "Am Eingang", "Im ersten Stock"], answers: ["An der Kasse"], explain: "« An der Kasse, dort vorne. »")], skills: ["listening:detail", "grammar:can", "vocab:shopping"]),
    ListeningText(id: "de-listen-rueckgabe-laden", languageID: "de", title: "Die Rückgabe im Laden", level: "A2", topic: "einkaufen", unitID: "de-foundations-u24",
        text: "« Guten Tag, ich habe diese Kaffeemaschine letzte Woche gekauft. » — « Was ist damit ? » — « Sie hat nicht funktioniert. Ich habe es zweimal probiert, aber es kommt kein Wasser durch. » — « Haben Sie die Quittung dabei ? » — « Ja, hier. » — « Möchten Sie die Maschine umtauschen oder das Geld zurück ? » — « Ich möchte das Geld zurück, bitte. Ich habe mir schon eine andere Marke bestellt. » — « Kein Problem. Können Sie hier unterschreiben ? Danke. Das Geld ist in drei Tagen auf Ihrem Konto. » — « Sehr gut. Vielen Dank für Ihre Hilfe ! » — « Entschuldigen Sie die Unannehmlichkeiten ! »",
        questions: [
                            Exercise(id: "de-listen-rueckgabe-laden-q1", kind: "choice", prompt: "Was hat die Kundin gekauft ?", options: ["Eine Kaffeemaschine", "Einen Wasserkocher", "Eine Jacke", "Ein Handy"], answers: ["Eine Kaffeemaschine"], explain: "Ich habe diese Kaffeemaschine letzte Woche gekauft."),
                            Exercise(id: "de-listen-rueckgabe-laden-q2", kind: "written", prompt: "Was war das Problem ?", options: [], answers: ["sie hat nicht funktioniert", "das gerät hat nicht funktioniert", "das geraet hat nicht funktioniert", "kein wasser kam durch"], explain: "« Sie hat nicht funktioniert … es kommt kein Wasser durch. »"),
                            Exercise(id: "de-listen-rueckgabe-laden-q3", kind: "choice", prompt: "Was möchte die Kundin ?", options: ["Das Geld zurück", "Die Maschine umtauschen", "Eine Reparatur", "Eine neue Quittung"], answers: ["Das Geld zurück"], explain: "« Ich möchte das Geld zurück, bitte. »"),
                            Exercise(id: "de-listen-rueckgabe-laden-q4", kind: "written", prompt: "Was hat sie sich schon bestellt ?", options: [], answers: ["eine andere marke", "eine kaffeemaschine einer anderen marke", "eine andere kaffeemaschine"], explain: "Ich habe mir schon eine andere Marke bestellt."),
                            Exercise(id: "de-listen-rueckgabe-laden-q5", kind: "choice", prompt: "Wann bekommt sie das Geld ?", options: ["In drei Tagen", "Morgen", "In einer Woche", "Sofort"], answers: ["In drei Tagen"], explain: "Das Geld ist in drei Tagen auf Ihrem Konto."),
                            Exercise(id: "de-listen-rueckgabe-laden-q6", kind: "choice", prompt: "Wann hat sie die Maschine gekauft ?", options: ["Letzte Woche", "Gestern", "Vor einem Monat", "Heute"], answers: ["Letzte Woche"], explain: "Ich habe diese Kaffeemaschine letzte Woche gekauft.")], skills: ["listening:detail", "grammar:past-simple-regular", "vocab:shopping", "function:solve-problems"]),
    ListeningText(id: "de-listen-vortag-abreise", languageID: "de", title: "Der Vortag der Abreise", level: "A2", topic: "reisen", unitID: "de-foundations-u25",
        text: "« Morgen fliegen wir nach Lissabon ! Hast du schon gepackt ? » — « Fast. Ich werde morgen früh die letzten Sachen einpacken. » — « Vergiss den Reisepass nicht ! Wo ist dein Ticket ? » — « Ich habe es gestern ausgedruckt. Und ich werde ein Taxi zum Flughafen bestellen. » — « Gut. Der Flug geht um neun, wir müssen um sieben losfahren. » — « Kein Problem, ich werde um sechs Uhr aufstehen. » — « Und wie wird das Wetter in Lissabon ? » — « Es wird warm. Ich nehme nur leichte Kleidung mit. » — « Perfekt. Dann gute Nacht — und danke, dass ich mitkommen darf ! »",
        questions: [
                            Exercise(id: "de-listen-vortag-abreise-q1", kind: "choice", prompt: "Wohin fliegen sie ?", options: ["Nach Lissabon", "Nach Berlin", "Nach Rom", "Nach Madrid"], answers: ["Nach Lissabon"], explain: "Morgen fliegen wir nach Lissabon."),
                            Exercise(id: "de-listen-vortag-abreise-q2", kind: "choice", prompt: "Wann geht der Flug ?", options: ["Um neun Uhr", "Um sechs Uhr", "Um sieben Uhr", "Um halb neun"], answers: ["Um neun Uhr"], explain: "Der Flug geht um neun."),
                            Exercise(id: "de-listen-vortag-abreise-q3", kind: "written", prompt: "Was wird sie früh am Morgen tun ?", options: [], answers: ["die letzten sachen einpacken", "einpacken", "den koffer fertig packen"], explain: "Ich werde morgen früh die letzten Sachen einpacken."),
                            Exercise(id: "de-listen-vortag-abreise-q4", kind: "written", prompt: "Wann wird sie aufstehen ?", options: [], answers: ["um sechs uhr", "um 6 uhr", "sechs uhr"], explain: "Ich werde um sechs Uhr aufstehen."),
                            Exercise(id: "de-listen-vortag-abreise-q5", kind: "choice", prompt: "Wie wird das Wetter in Lissabon ?", options: ["Warm", "Kalt", "Regnerisch", "Windig"], answers: ["Warm"], explain: "Es wird warm."),
                            Exercise(id: "de-listen-vortag-abreise-q6", kind: "choice", prompt: "Wohin fährt ein Taxi ?", options: ["Zum Flughafen", "Zum Bahnhof", "Zum Hotel", "In die Innenstadt"], answers: ["Zum Flughafen"], explain: "Ich werde ein Taxi zum Flughafen bestellen.")], skills: ["listening:detail", "grammar:going-to", "vocab:travel", "vocab:transport"]),
    ListeningText(id: "de-listen-traumviertel", languageID: "de", title: "Unser Traumviertel", level: "B1", topic: "stadt", unitID: "de-foundations-u26",
        text: "Marla und Jonas reden über ihr Traumviertel. « Ich ziehe bald um — aber welches Viertel soll es sein ? » — « Ich bin der Meinung, dass ein Stadtteil mit vielen Bäumen lebenswerter ist. Einerseits kostet die Miete dort oft mehr, andererseits spare ich mir das Auto. » — « Stimmt, aber öffentliche Verkehrsmittel sind mir wichtiger. Ich schlage das Bahnhofsviertel vor: man ist schnell im Zentrum. » — « Einerseits hast du recht, da ist alles nah. Andererseits ist es dort laut. Ich brauche Grün zum Atmen. » — « Dann vielleicht das Viertel am Fluss ? Es ist ruhig, hat Parks und Radwege. Und die Miete ist günstiger als im Zentrum. » — « Das klingt nach unserem Traumviertel. Sollen wir dort Wohnungen suchen ? »",
        questions: [
                            Exercise(id: "de-listen-traumviertel-q1", kind: "choice", prompt: "Was findet Marla wichtig in einem Viertel ?", options: ["Viele Bäume und Grün", "Nähe zum Bahnhof", "Günstige Parkplätze", "Viele Geschäfte"], answers: ["Viele Bäume und Grün"], explain: "Ein Stadtteil mit vielen Bäumen ist lebenswerter."),
                            Exercise(id: "de-listen-traumviertel-q2", kind: "written", prompt: "Welches Viertel schlägt Jonas zuerst vor ?", options: [], answers: ["das bahnhofsviertel", "bahnhofsviertel"], explain: "« Ich schlage das Bahnhofsviertel vor. »"),
                            Exercise(id: "de-listen-traumviertel-q3", kind: "choice", prompt: "Was ist Marlas Einwand gegen das Bahnhofsviertel ?", options: ["Es ist dort laut", "Die Miete ist zu hoch", "Es gibt keine Parks", "Man braucht ein Auto"], answers: ["Es ist dort laut"], explain: "Andererseits ist es dort laut."),
                            Exercise(id: "de-listen-traumviertel-q4", kind: "choice", prompt: "Wie ist die Miete am Fluss im Vergleich zum Zentrum ?", options: ["Günstiger", "Teurer", "Gleich teuer", "Sie steigt bald"], answers: ["Günstiger"], explain: "Die Miete ist günstiger als im Zentrum."),
                            Exercise(id: "de-listen-traumviertel-q5", kind: "written", prompt: "Was beschließen die beiden am Ende ?", options: [], answers: ["wohnungen suchen", "sie suchen dort wohnungen", "wohnungen am fluss suchen"], explain: "« Sollen wir dort Wohnungen suchen ? »")], skills: ["listening:inference", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "de-listen-besprechung-ende", languageID: "de", title: "Der letzte Punkt der Besprechung", level: "B1", topic: "arbeit", unitID: "de-work-u1",
        text: "« Kommen wir zum letzten Punkt: Wo stehen wir mit dem Projekt ? » — « Die Präsentation ist fertig. Einerseits sind wir im Zeitplan, andererseits fehlt das Budget für die Werbung. » — « Dann schlage ich vor, dass wir das Budget am Freitag klären. Ich schreibe heute eine E-Mail an die Finanzabteilung. » — « Da bin ich anderer Meinung. Wir sollten zuerst die Werbung besprechen, das Budget danach. Sonst verlieren wir Zeit. » — « Guter Punkt. Ich schreibe die E-Mail an die Finanzen, und Sie leiten die Diskussion. » — « Einverstanden. » — « Herr Aziz, fassen Sie die Ergebnisse zusammen. » — « Mach ich. Bis Freitag bekommen alle eine Zusammenfassung. » — « Sehr gut. Danke an alle ! »",
        questions: [
                            Exercise(id: "de-listen-besprechung-ende-q1", kind: "choice", prompt: "Was fehlt noch im Projekt ?", options: ["Das Budget für die Werbung", "Die Präsentation", "Der Zeitplan", "Die Zusammenfassung"], answers: ["Das Budget für die Werbung"], explain: "Einerseits im Zeitplan, andererseits fehlt noch das Budget für die Werbung."),
                            Exercise(id: "de-listen-besprechung-ende-q2", kind: "choice", prompt: "Was schlägt die erste Person vor ?", options: ["Eine E-Mail an die Finanzabteilung", "Eine Pause", "Ein neues Projekt", "Ein Treffen mit Kunden"], answers: ["Eine E-Mail an die Finanzabteilung"], explain: "Ich schreibe heute eine E-Mail an die Finanzabteilung."),
                            Exercise(id: "de-listen-besprechung-ende-q3", kind: "written", prompt: "Warum will sie zuerst über die Werbung sprechen ?", options: [], answers: ["sonst verlieren wir zeit", "sonst verliert man zeit", "wegen der zeit"], explain: "« Sonst verlieren wir Zeit. »"),
                            Exercise(id: "de-listen-besprechung-ende-q4", kind: "written", prompt: "Bis wann bekommt die Gruppe die Zusammenfassung ?", options: [], answers: ["bis freitag", "freitag", "am freitag"], explain: "Bis Freitag bekommen alle eine Zusammenfassung."),
                            Exercise(id: "de-listen-besprechung-ende-q5", kind: "choice", prompt: "Wie endet die Besprechung ?", options: ["Alle sind einverstanden", "Es gibt Streit", "Sie wird verschoben", "Ohne Ergebnis"], answers: ["Alle sind einverstanden"], explain: "« Einverstanden. » — « Sehr gut. Danke an alle ! »"),
                            Exercise(id: "de-listen-besprechung-ende-q6", kind: "choice", prompt: "Was bedeutet « Einverstanden » in dieser Besprechung ?", options: ["Ich stimme zu", "Ich bin dagegen", "Ich bin unsicher", "Ich muss fragen"], answers: ["Ich stimme zu"], explain: "Einverstanden heißt: Ich stimme zu.")], skills: ["listening:inference", "function:express-opinion", "function:talk-about-work", "grammar:connectors"]),
    ListeningText(id: "de-listen-umzugsplan", languageID: "de", title: "Der Umzugsplan", level: "A2", topic: "pläne", unitID: "de-foundations-u28",
        text: "Anna ruft Lena an: « Ich muss nächsten Samstag umziehen — kannst du helfen ? » — « Klar ! Ich leihe den Kistenwagen von meinem Onkel. Wie viele Kartons hast du ? » — « Zwölf, glaube ich. Und einen Transporter zu mieten ist zu teuer. » — « Kein Problem, der Wagen von meinem Onkel kostet nichts. Ich bin um neun bei dir. » — « Super. Ben bringt den Kaffee mit — und ich werde Kuchen backen. » — « Abgemacht ! Dann sehen wir uns am Samstag früh um neun. »",
        questions: [
                            Exercise(id: "de-listen-umzugsplan-q1", kind: "choice", prompt: "Wann muss Anna umziehen ?", options: ["Nächsten Samstag", "Diesen Freitag", "Heute Abend", "In zwei Wochen"], answers: ["Nächsten Samstag"], explain: "« Ich muss nächsten Samstag umziehen. »"),
                            Exercise(id: "de-listen-umzugsplan-q2", kind: "written", prompt: "Was leiht Lena ?", options: [], answers: ["den kistenwagen", "den kistenwagen von ihrem onkel", "den wagen von ihrem onkel"], explain: "« Ich leihe den Kistenwagen von meinem Onkel. »"),
                            Exercise(id: "de-listen-umzugsplan-q3", kind: "choice", prompt: "Warum mietet Anna keinen Transporter ?", options: ["Es ist zu teuer", "Er ist zu klein", "Sie kann nicht fahren", "Es gibt keinen"], answers: ["Es ist zu teuer"], explain: "« Einen Transporter zu mieten ist zu teuer. »"),
                            Exercise(id: "de-listen-umzugsplan-q4", kind: "choice", prompt: "Wann kommt Lena bei Anna an ?", options: ["Um neun", "Um acht", "Um zehn", "Um sieben"], answers: ["Um neun"], explain: "« Ich bin um neun bei dir. »"),
                            Exercise(id: "de-listen-umzugsplan-q5", kind: "written", prompt: "Was wird Anna backen ?", options: [], answers: ["kuchen", "einen kuchen", "sie wird kuchen backen"], explain: "« Ich werde Kuchen backen. »")], skills: ["listening:detail", "grammar:modal-must-have-to", "function:make-future-plans"]),
    ListeningText(id: "de-listen-besichtigung", languageID: "de", title: "Die Besichtigung", level: "A2", topic: "wohnen", unitID: "de-foundations-u28",
        text: "Frau Weber öffnet die Tür: « Guten Tag, kommen Sie rein. Die Wohnung hat zwei Zimmer, Küche und Bad. » — Anna: « Wie hoch sind die Nebenkosten ? » — « 180 Euro, die Heizung ist dabei. » — « Ist die Küche im Preis dabei ? » — « Leider nicht, aber sie ist fast neu. » — Anna schaut sich alles an: « Der Balkon ist schön groß. Passt es Ihnen, wenn ich morgen mit meinem Partner nochmal komme ? » — « Gerne, wie wäre es um 17 Uhr ? » — « Perfekt. Und ab wann kann ich einziehen ? » — « Ab dem 1. Juni. Den Vertrag bekommen Sie per E-Mail. » — « Vielen Dank, bis morgen ! »",
        questions: [
                            Exercise(id: "de-listen-besichtigung-q1", kind: "choice", prompt: "Wie groß ist die Wohnung ?", options: ["Zwei Zimmer", "Drei Zimmer", "Ein Zimmer", "Vier Zimmer"], answers: ["Zwei Zimmer"], explain: "« Die Wohnung hat zwei Zimmer, Küche und Bad. »"),
                            Exercise(id: "de-listen-besichtigung-q2", kind: "written", prompt: "Wie hoch sind die Nebenkosten ?", options: [], answers: ["180 euro", "hundertachtzig euro"], explain: "« 180 Euro, die Heizung ist dabei. »"),
                            Exercise(id: "de-listen-besichtigung-q3", kind: "choice", prompt: "Ist die Küche im Preis dabei ?", options: ["Nein, aber sie ist fast neu", "Ja, ganz neu", "Ja, mit Heizung", "Nein, sie ist kaputt"], answers: ["Nein, aber sie ist fast neu"], explain: "« Leider nicht, aber sie ist fast neu. »"),
                            Exercise(id: "de-listen-besichtigung-q4", kind: "written", prompt: "Wann kommt Anna wieder ?", options: [], answers: ["morgen um 17 uhr", "um 17 uhr"], explain: "« …wenn ich morgen … nochmal komme ? » — « Wie wäre es um 17 Uhr ? »"),
                            Exercise(id: "de-listen-besichtigung-q5", kind: "choice", prompt: "Ab wann kann Anna einziehen ?", options: ["Ab dem 1. Juni", "Ab dem 1. Mai", "Sofort", "Ab dem 15. Juni"], answers: ["Ab dem 1. Juni"], explain: "« Ab dem 1. Juni. Den Vertrag bekommen Sie per E-Mail. »")], skills: ["listening:detail", "vocab:home", "function:ask-simple-questions"]),
    ListeningText(id: "de-listen-rueckblick-wochenende", languageID: "de", title: "Wie war dein Wochenende ?", level: "A2", topic: "vergangenheit", unitID: "de-foundations-u3",
        text: "Ben trifft Lena im Café: « Wie war dein Wochenende ? » — « Toll und etwas verrückt. Am Samstag habe ich einen Ausflug gemacht — und dann hat es geregnet. » — « Was hast du gemacht ? » — « Ich bin ins Museum gegangen. Es war interessant, aber sehr voll. » — « Und am Abend ? » — « Ich habe Pizza gegessen und einen Film gesehen. Am Sonntag habe ich lange geschlafen und bin dann Fahrrad gefahren. » — « Klingt gut ! Und was war verrückt ? » — « Im Museum habe ich meinen alten Lehrer getroffen. » — « Das glaub ich nicht ! » — « Stimmt aber. Es war ein schönes Wiedersehen. »",
        questions: [
                            Exercise(id: "de-listen-rueckblick-wochenende-q1", kind: "written", prompt: "Was hat das Wetter am Samstag gemacht ?", options: [], answers: ["es hat geregnet", "geregnet"], explain: "« …und dann hat es geregnet. »"),
                            Exercise(id: "de-listen-rueckblick-wochenende-q2", kind: "choice", prompt: "Wohin ist sie gegangen ?", options: ["Ins Museum", "Zum See", "In die Berge", "Nach Hause"], answers: ["Ins Museum"], explain: "« Ich bin ins Museum gegangen. »"),
                            Exercise(id: "de-listen-rueckblick-wochenende-q3", kind: "written", prompt: "Was hat sie am Abend gegessen ?", options: [], answers: ["pizza", "sie hat pizza gegessen"], explain: "« Ich habe Pizza gegessen und einen Film gesehen. »"),
                            Exercise(id: "de-listen-rueckblick-wochenende-q4", kind: "choice", prompt: "Was hat sie am Sonntag gemacht ?", options: ["Lange geschlafen und Rad gefahren", "Gearbeitet", "Gekocht", "Gefeiert"], answers: ["Lange geschlafen und Rad gefahren"], explain: "« Am Sonntag habe ich lange geschlafen und bin dann Fahrrad gefahren. »"),
                            Exercise(id: "de-listen-rueckblick-wochenende-q5", kind: "choice", prompt: "Wen hat sie im Museum getroffen ?", options: ["Ihren alten Lehrer", "Ihre Nachbarin", "Ihren Bruder", "Eine alte Freundin"], answers: ["Ihren alten Lehrer"], explain: "« Im Museum habe ich meinen alten Lehrer getroffen. »")], skills: ["listening:detail", "grammar:present-perfect", "function:describe-past-events"]),
    ListeningText(id: "de-listen-zug-verspaetet", languageID: "de", title: "Der verspätete Zug", level: "A2", topic: "probleme", unitID: "de-foundations-u20",
        text: "Am Informationsschalter: « Guten Tag, mein Zug nach Hamburg hat 40 Minuten Verspätung. Ich verpasse meinen Anschluss. » — « Kein Problem. Der nächste Zug fährt um 15:12. » — « Komme ich damit um 17 Uhr in Hamburg an ? » — « Leider erst um 17:35. » — « Das ist zu spät — ich habe um 18 Uhr einen Termin. » — « Moment. Es gibt einen ICE über Hannover, Abfahrt 14:50, Ankunft 16:55. » — « Perfekt ! Muss ich ein neues Ticket kaufen ? » — « Nein, Ihr Ticket gilt auch für diesen Zug. Ich drücke Ihnen den neuen Anschluss aus. » — « Vielen Dank für die Hilfe ! »",
        questions: [
                            Exercise(id: "de-listen-zug-verspaetet-q1", kind: "choice", prompt: "Was ist das Problem ?", options: ["Der Zug hat Verspätung", "Das Ticket ist weg", "Der Zug fällt aus", "Sie ist am falschen Bahnhof"], answers: ["Der Zug hat Verspätung"], explain: "« Mein Zug nach Hamburg hat 40 Minuten Verspätung. »"),
                            Exercise(id: "de-listen-zug-verspaetet-q2", kind: "choice", prompt: "Wann fährt der nächste normale Zug ?", options: ["Um 15:12", "Um 14:50", "Um 16:55", "Um 17:35"], answers: ["Um 15:12"], explain: "« Der nächste Zug fährt um 15:12. »"),
                            Exercise(id: "de-listen-zug-verspaetet-q3", kind: "written", prompt: "Über welche Stadt fährt der schnellere ICE ?", options: [], answers: ["hannover", "über hannover", "ueber hannover"], explain: "« Es gibt einen ICE über Hannover. »"),
                            Exercise(id: "de-listen-zug-verspaetet-q4", kind: "choice", prompt: "Wann kommt sie in Hamburg an ?", options: ["Um 16:55", "Um 17:35", "Um 18 Uhr", "Um 17 Uhr"], answers: ["Um 16:55"], explain: "« Abfahrt 14:50, Ankunft 16:55. »"),
                            Exercise(id: "de-listen-zug-verspaetet-q5", kind: "written", prompt: "Muss sie ein neues Ticket kaufen ?", options: [], answers: ["nein", "nein, das ticket gilt", "nein, ihr ticket gilt auch"], explain: "« Nein, Ihr Ticket gilt auch für diesen Zug. »")], skills: ["listening:detail", "vocab:transport", "function:solve-problems"]),
    ListeningText(id: "de-listen-hotelbuchung", languageID: "de", title: "Der Anruf im Hotel", level: "A2", topic: "reisen", unitID: "de-foundations-u25",
        text: "« Hotel Seeblick, guten Tag. » — « Guten Tag, ich habe für nächste Woche ein Doppelzimmer gebucht. Mein Name ist Nina Keller. » — « Einen Moment … Es tut mir leid: Wir haben Ihr Zimmer leider doppelt vergeben. » — « Wie bitte ? Ich fliege am Montag an ! » — « Bitte bleiben Sie ruhig — wir bezahlen Ihr Taxi und Sie bekommen ein Zimmer im Hotel am Park, zwei Minuten von hier. Gleicher Preis. » — « Ist dort auch Frühstück dabei ? » — « Ja, und wir holen Sie vom Flughafen ab. » — « Na gut, ich bin gespannt. » — « Vielen Dank für Ihr Verständnis, Frau Keller. Bis Montag ! »",
        questions: [
                            Exercise(id: "de-listen-hotelbuchung-q1", kind: "choice", prompt: "Was war das Problem ?", options: ["Das Zimmer war doppelt vergeben", "Das Hotel war voll", "Das Frühstück fehlte", "Der Preis war falsch"], answers: ["Das Zimmer war doppelt vergeben"], explain: "« Wir haben Ihr Zimmer leider doppelt vergeben. »"),
                            Exercise(id: "de-listen-hotelbuchung-q2", kind: "choice", prompt: "Wann kommt Frau Keller an ?", options: ["Am Montag", "Am Wochenende", "Am Dienstag", "Am Freitag"], answers: ["Am Montag"], explain: "« Ich fliege am Montag an ! »"),
                            Exercise(id: "de-listen-hotelbuchung-q3", kind: "written", prompt: "Was bekommt sie im Hotel am Park ?", options: [], answers: ["ein zimmer", "ein zimmer zum gleichen preis", "ein zimmer, gleicher preis"], explain: "« Sie bekommen ein Zimmer im Hotel am Park … Gleicher Preis. »"),
                            Exercise(id: "de-listen-hotelbuchung-q4", kind: "choice", prompt: "Wer zahlt das Taxi ?", options: ["Das Hotel Seeblick", "Frau Keller", "Das Hotel am Park", "Niemand"], answers: ["Das Hotel Seeblick"], explain: "« Wir bezahlen Ihr Taxi. » (Hotel Seeblick)"),
                            Exercise(id: "de-listen-hotelbuchung-q5", kind: "written", prompt: "Wie kommt sie vom Flughafen zum Hotel ?", options: [], answers: ["das hotel holt sie ab", "sie wird abgeholt", "das hotel seeblick holt sie ab"], explain: "« Wir holen Sie vom Flughafen ab. »")], skills: ["listening:detail", "vocab:travel", "function:solve-problems"]),
    ListeningText(id: "de-listen-moebel-raten", languageID: "de", title: "Das Sofa für die neue Wohnung", level: "A2", topic: "einkaufen", unitID: "de-foundations-u24",
        text: "Im Möbelhaus: « Das Sofa gefällt mir. Was kostet es ? » — « 899 Euro. Dieses Modell hier ist billiger: nur 749 Euro. » — « Es ist aber kleiner. Gibt es das große auch in Blau ? » — « In Blau dauert es zwei Wochen. Sie können aber Ratenzahlung nehmen: dann zahlen Sie jeden Monat 75 Euro. » — « Wie lange dauert das ? » — « Zwölf Monate, ohne Zinsen. » — « Und die Lieferung ? » — « Wir liefern kostenlos bis in die Wohnung. Wann passt es Ihnen ? » — « Könnten Sie am Samstagvormittag kommen ? Wir ziehen gerade um. » — « Samstag früh, kein Problem. Herzlichen Glückwunsch zur neuen Wohnung ! »",
        questions: [
                            Exercise(id: "de-listen-moebel-raten-q1", kind: "choice", prompt: "Was kostet das Sofa, das Nina gefällt ?", options: ["899 Euro", "749 Euro", "75 Euro", "12 Euro"], answers: ["899 Euro"], explain: "« Das Sofa gefällt mir. Was kostet es ? » — « 899 Euro. »"),
                            Exercise(id: "de-listen-moebel-raten-q2", kind: "choice", prompt: "Warum dauert die blaue Farbe länger ?", options: ["Es dauert zwei Wochen", "Es gibt nur Rot", "Sie ist ausverkauft", "Der Laden ist geschlossen"], answers: ["Es dauert zwei Wochen"], explain: "« In Blau dauert es zwei Wochen. »"),
                            Exercise(id: "de-listen-moebel-raten-q3", kind: "written", prompt: "Wie viel zahlt sie bei Ratenzahlung pro Monat ?", options: [], answers: ["75 euro", "fünfundsiebzig euro", "fuenfundsiebzig euro"], explain: "« …zahlen Sie jeden Monat 75 Euro. »"),
                            Exercise(id: "de-listen-moebel-raten-q4", kind: "choice", prompt: "Wie lange dauert die Ratenzahlung ?", options: ["Zwölf Monate", "Zwei Wochen", "Sechs Monate", "Sechs Wochen"], answers: ["Zwölf Monate"], explain: "« Zwölf Monate, ohne Zinsen. »"),
                            Exercise(id: "de-listen-moebel-raten-q5", kind: "written", prompt: "Was kostet die Lieferung ?", options: [], answers: ["nichts", "sie ist kostenlos", "die lieferung ist kostenlos"], explain: "« Wir liefern kostenlos bis in die Wohnung. »")], skills: ["listening:detail", "vocab:shopping", "grammar:comparatives", "function:go-shopping"]),
    ListeningText(id: "de-listen-schluessel-panne", languageID: "de", title: "Die Schlüssel-Panne", level: "B1", topic: "erlebnisse", unitID: "de-foundations-u18",
        text: "Paul erzählt: « Letzten Dienstag hatte ich ein Vorstellungsgespräch um 9 Uhr. Um Viertel vor acht war ich fertig angezogen — und dann: der Schlüssel war im Schloss abgebrochen. Von innen ! Ich habe meine Mitbewohnerin angerufen, aber sie war schon im Büro. Also bin ich zum Nachbarn gegangen, Herrn Braun. Der hilft uns schon oft. Er kam mit einer Zange — nach zwanzig Minuten war die Tür offen. » — « Und das Gespräch ? » — « Ich bin mit dreckigen Händen zur U-Bahn gelaufen, aber pünktlich da gewesen. Der Chef hat gelacht und gesagt, wer sich selbst hilft, kommt durch jede Tür. Ich habe den Job ! » — « Unglaublich. Manchmal hilft das Chaos mehr als der Plan. »",
        questions: [
                            Exercise(id: "de-listen-schluessel-panne-q1", kind: "choice", prompt: "Was war um Viertel vor acht passiert ?", options: ["Der Schlüssel war abgebrochen", "Der Zug war weg", "Das Gespräch war verschoben", "Der Nachbar war nicht da"], answers: ["Der Schlüssel war abgebrochen"], explain: "« …der Schlüssel war im Schloss abgebrochen. »"),
                            Exercise(id: "de-listen-schluessel-panne-q2", kind: "written", prompt: "Wer half Paul mit einer Zange ?", options: [], answers: ["herr braun", "der nachbar", "sein nachbar herr braun"], explain: "« Also bin ich zum Nachbarn gegangen, Herrn Braun. Er kam mit einer Zange. »"),
                            Exercise(id: "de-listen-schluessel-panne-q3", kind: "choice", prompt: "Wie kam Paul zum Gespräch ?", options: ["Mit der U-Bahn", "Mit dem Auto", "Zu Fuß bis zum Büro", "Mit dem Taxi"], answers: ["Mit der U-Bahn"], explain: "« Ich bin mit dreckigen Händen zur U-Bahn gelaufen. »"),
                            Exercise(id: "de-listen-schluessel-panne-q4", kind: "written", prompt: "Wann war das Gespräch ?", options: [], answers: ["um 9 uhr", "um neun uhr", "um neun"], explain: "« …ein Vorstellungsgespräch um 9 Uhr. »"),
                            Exercise(id: "de-listen-schluessel-panne-q5", kind: "choice", prompt: "Wie endet die Geschichte ?", options: ["Paul hat den Job bekommen", "Paul kam zu spät", "Der Chef war wütend", "Paul fand den Schlüssel nie"], answers: ["Paul hat den Job bekommen"], explain: "« Ich habe den Job ! »")], skills: ["listening:inference", "function:tell-a-story", "grammar:present-perfect"]),
    ListeningText(id: "de-listen-debatte-homeoffice", languageID: "de", title: "Debatte: Homeoffice — Segen oder Sünde ?", level: "B2", topic: "meinung", unitID: "de-foundations-u7",
        text: "Rundfunk-Debatte mit Dr. Lang und dem Gewerkschafter Kramer. — Dr. Lang: « Ich vertrete den Standpunkt, dass Homeoffice produktiver macht. Einerseits entfällt der Weg zur Arbeit, andererseits lässt sich der Tag besser strukturieren. Die Zahlen meiner Studie sprechen eine klare Sprache: vier Stunden mehr pro Woche. » — Kramer: « Dagegen möchte ich einwenden: Nicht jeder Job passt an den Küchentisch. Zudem leidet das Teamgefühl — wer schon mal per Video diskutiert hat, weiß, wovon ich rede. » — Lang: « Ein berechtigter Einwand, doch die Lösung heißt Mischung: zwei Tage im Büro, drei zu Hause. » — Kramer: « Da stimme ich Ihnen zu — solange die Firma uns die Ausstattung zahlt. » — Moderatorin: « Damit ist die Runde am Ende: Die Mischung macht's. »",
        questions: [
                            Exercise(id: "de-listen-debatte-homeoffice-q1", kind: "choice", prompt: "Was ist Dr. Langs These ?", options: ["Homeoffice macht produktiver", "Homeoffice kostet Jobs", "Homeoffice macht krank", "Homeoffice ist zu teuer"], answers: ["Homeoffice macht produktiver"], explain: "« Ich vertrete den Standpunkt, dass Homeoffice produktiver macht. »"),
                            Exercise(id: "de-listen-debatte-homeoffice-q2", kind: "written", prompt: "Wie viele Stunden mehr pro Woche nennt die Studie ?", options: [], answers: ["vier", "4", "vier stunden"], explain: "« …vier Stunden mehr pro Woche. »"),
                            Exercise(id: "de-listen-debatte-homeoffice-q3", kind: "choice", prompt: "Was wirft Kramer ein ?", options: ["Das Teamgefühl leidet", "Die Zahlen seien falsch", "Homeoffice sei verboten", "Das Büro sei zu laut"], answers: ["Das Teamgefühl leidet"], explain: "« Zudem leidet das Teamgefühl. »"),
                            Exercise(id: "de-listen-debatte-homeoffice-q4", kind: "written", prompt: "Welche Lösung schlägt Dr. Lang vor ?", options: [], answers: ["mischung", "zwei tage im buero, drei zu hause", "zwei tage im büro und drei zu hause", "zwei tage buero, drei zuhause"], explain: "« Die Lösung heißt Mischung: zwei Tage im Büro, drei zu Hause. »"),
                            Exercise(id: "de-listen-debatte-homeoffice-q5", kind: "choice", prompt: "Was fordert Kramer als Bedingung ?", options: ["Die Firma soll die Ausstattung zahlen", "Mehr Gehalt", "Weniger Meetings", "Freie Wahl des Ortes"], answers: ["Die Firma soll die Ausstattung zahlen"], explain: "« …solange die Firma uns die Ausstattung zahlt. »")], skills: ["listening:inference", "function:express-opinion", "grammar:connectors"]),
    ListeningText(id: "de-listen-miete-verhandlung", languageID: "de", title: "Die Mietverhandlung", level: "B2", topic: "verhandeln", unitID: "de-foundations-u7",
        text: "Frau Simon klingelt bei ihrem Vermieter Herrn Krause: « Ich wohne jetzt vier Jahre hier und habe nie eine Miete zu spät gezahlt. Nun erhöhen Sie um 15 Prozent — das finde ich zu viel. » — « Die Kosten steigen überall, Frau Simon. » — « Verstehe. Mein Vorschlag: zehn Prozent, dafür verlängere ich den Vertrag auf drei Jahre. » — « Zwei Jahre, und Sie übernehmen die kleine Garage mit. » — « Nur ohne Aufpreis. Dann erkläre ich mich einverstanden. » — « Also: zehn Prozent, zwei Jahre, die Garage zum alten Preis. Danke für das offene Wort. » — « Ebenso — auf ein faires Wohnen ! »",
        questions: [
                            Exercise(id: "de-listen-miete-verhandlung-q1", kind: "choice", prompt: "Wie viel Prozent wollte der Vermieter zuerst ?", options: ["15", "10", "12", "20"], answers: ["15"], explain: "« Nun erhöhen Sie um 15 Prozent. »"),
                            Exercise(id: "de-listen-miete-verhandlung-q2", kind: "written", prompt: "Wie lange wohnt Frau Simon schon dort ?", options: [], answers: ["vier jahre", "4 jahre"], explain: "« Ich wohne jetzt vier Jahre hier … »"),
                            Exercise(id: "de-listen-miete-verhandlung-q3", kind: "choice", prompt: "Was bietet sie im ersten Vorschlag ?", options: ["Verlängerung auf drei Jahre", "Auszug im Sommer", "Neue Fenster", "Eine sofortige volle Erhöhung"], answers: ["Verlängerung auf drei Jahre"], explain: "« …dafür verlängere ich den Vertrag auf drei Jahre. »"),
                            Exercise(id: "de-listen-miete-verhandlung-q4", kind: "written", prompt: "Was soll sie zusätzlich übernehmen ?", options: [], answers: ["die garage", "die kleine garage"], explain: "« …und Sie übernehmen die kleine Garage mit. »"),
                            Exercise(id: "de-listen-miete-verhandlung-q5", kind: "choice", prompt: "Wie endet die Verhandlung ?", options: ["Zehn Prozent, zwei Jahre, Garage zum alten Preis", "Fünfzehn Prozent, ein Jahr", "Zehn Prozent, drei Jahre", "Der Vermieter verzichtet ganz"], answers: ["Zehn Prozent, zwei Jahre, Garage zum alten Preis"], explain: "« Also: zehn Prozent, zwei Jahre, die Garage zum alten Preis. »")], skills: ["listening:inference", "function:negotiate", "speaking:negotiate"]),
    ListeningText(id: "de-listen-nachricht-streik", languageID: "de", title: "Nachrichten: Warnstreik im Verkehr", level: "B2", topic: "nachrichten", unitID: "de-foundations-u8",
        text: "Von der Nachrichtenzentrale: Der Warnstreik der Bus- und Bahnfahrer hat heute Morgen den Verkehr in der Region lahmgelegt. Wie das Verkehrsunternehmen mitteilte, seien rund 70 Prozent der Fahrten ausgefallen. Die Gewerkschaft begründet den Streik mit den laufenden Tarifverhandlungen: Sie fordert fünf Prozent mehr Lohn und bessere Dienstpläne. Der Vorstand nannte die Forderung verhandlungsfähig, wies aber darauf hin, dass höhere Löhne die Fahrpreise erhöhen würden. Die Gespräche sollen kommende Woche fortgesetzt werden. Ein Sprecher der Gewerkschaft kündigte an, die Streiks würden so lange wiederholt, bis ein akzeptables Angebot vorliege. Reisende wurden gebeten, frühzeitiger als gewöhnlich zu planen. Weitere Nachrichten um halb.",
        questions: [
                            Exercise(id: "de-listen-nachricht-streik-q1", kind: "choice", prompt: "Was ist das Thema der Nachricht ?", options: ["Ein Warnstreik im Verkehr", "Ein Unfall auf der Bahn", "Neue Fahrpreise", "Ein neues Bahnhofsgebäude"], answers: ["Ein Warnstreik im Verkehr"], explain: "« Der Warnstreik … hat heute Morgen den Verkehr in der Region lahmgelegt. »"),
                            Exercise(id: "de-listen-nachricht-streik-q2", kind: "written", prompt: "Wie viele Fahrten sind laut Unternehmen ausgefallen ?", options: [], answers: ["rund 70 prozent", "70 prozent", "siebzig prozent"], explain: "« …seien rund 70 Prozent der Fahrten ausgefallen. »"),
                            Exercise(id: "de-listen-nachricht-streik-q3", kind: "choice", prompt: "Was fordert die Gewerkschaft ?", options: ["Fünf Prozent mehr Lohn", "Kürzere Fahrpreise", "Neue Busse", "Mehr Züge am Abend"], answers: ["Fünf Prozent mehr Lohn"], explain: "« Sie fordert fünf Prozent mehr Lohn und bessere Dienstpläne. »"),
                            Exercise(id: "de-listen-nachricht-streik-q4", kind: "choice", prompt: "Was würde laut Vorstand bei höheren Löhnen passieren ?", options: ["Die Fahrpreise würden erhöht", "Die Bahnen würden stillstehen", "Der Streik würde enden", "Die Pläne würden besser"], answers: ["Die Fahrpreise würden erhöht"], explain: "« …dass höhere Löhne die Fahrpreise erhöhen würden. »"),
                            Exercise(id: "de-listen-nachricht-streik-q5", kind: "written", prompt: "Wie lange sollen die Streiks wiederholt werden ?", options: [], answers: ["bis ein akzeptables angebot vorliegt", "solange, bis ein angebot vorliegt"], explain: "« …bis ein akzeptables Angebot vorliege. »")], skills: ["listening:detail", "grammar:passive-intro", "grammar:reported-speech-basic"]),
    ListeningText(id: "de-listen-medien-podcast", languageID: "de", title: "Kulturteil: Lesen im Alltag", level: "B2", topic: "medien", unitID: "de-foundations-u8",
        text: "Im Kulturteil spricht Moderatorin Rieder mit der Medienwissenschaftlerin Professorin Adeyemi. — « Professorin, viele lesen nur noch Schlagzeilen. Verlieren wir die Tiefe ? » — « Ich würde vorsichtig formulieren: Das Lesen hat sich verschoben, nicht abgeschafft. Menschen lesen viel — nur anders: schnell und quer. » — « Was heißt das für die Nachrichten ? » — « Wer nur Headlines scannt, verbindet die Fakten nicht mehr. Deshalb raten wir zu einem langen Artikel pro Tag — die Tiefe kommt von der Zeit, die wir uns nehmen. » — « Und die sozialen Netzwerke ? » — « Sie sind Werkzeuge. Ob sie uns dumm machen, entscheidet der Gebrauch — ein Hammer kann bauen oder zerstören. » — « Danke für das klare Bild. »",
        questions: [
                            Exercise(id: "de-listen-medien-podcast-q1", kind: "choice", prompt: "Wie nennt Professorin Adeyemi die Entwicklung des Lesens ?", options: ["Verschoben, nicht abgeschafft", "Beendet", "Unverändert", "Gefährlich"], answers: ["Verschoben, nicht abgeschafft"], explain: "« Das Lesen hat sich verschoben, nicht abgeschafft. »"),
                            Exercise(id: "de-listen-medien-podcast-q2", kind: "written", prompt: "Was raten die Forscher für jeden Tag ?", options: [], answers: ["einen langen artikel", "einen langen artikel pro tag", "ein langer artikel"], explain: "« Deshalb raten wir zu einem langen Artikel pro Tag. »"),
                            Exercise(id: "de-listen-medien-podcast-q3", kind: "choice", prompt: "Wovor warnt sie bei Headlines ?", options: ["Man verbindet die Fakten nicht mehr", "Man liest zu langsam", "Man kauft zu viele Zeitungen", "Man vergisst Termine"], answers: ["Man verbindet die Fakten nicht mehr"], explain: "« Wer nur Headlines scannt, verbindet die Fakten nicht mehr. »"),
                            Exercise(id: "de-listen-medien-podcast-q4", kind: "choice", prompt: "Womit vergleicht sie soziale Netzwerke ?", options: ["Mit einem Hammer", "Mit einem Buch", "Mit einer Brücke", "Mit einem Spiegel"], answers: ["Mit einem Hammer"], explain: "« Ein Hammer kann bauen oder zerstören. »"),
                            Exercise(id: "de-listen-medien-podcast-q5", kind: "written", prompt: "Wovon kommt laut ihr die Tiefe ?", options: [], answers: ["von der zeit", "von der zeit, die wir uns nehmen", "von der zeit, die man sich nimmt"], explain: "« Die Tiefe kommt von der Zeit, die wir uns nehmen. »")], skills: ["listening:inference", "grammar:reported-speech-basic", "function:express-opinion"]),
    ListeningText(id: "de-listen-gehalt-verhandlung", languageID: "de", title: "Die Gehaltsverhandlung", level: "B2", topic: "verhandeln", unitID: "de-foundations-u7",
        text: "Frau Berger von der Personalabteilung empfängt Anna: « Sie haben die Probezeit überzeugt. Wie stellen Sie sich Ihr Gehalt vor ? » — « Aufgrund meiner Verantwortung wünsche ich 52 000 Euro im Jahr. » — « Das übersteigt unser Budget. Ich kann 47 000 anbieten. » — « Verstehe. Ich bringe die Kundenkontakte aus meiner alten Firma mit — zwei Großkunden sind schon angefragt. Was wäre, wenn wir 50 000 sagen und ich die Betreuung übernehme ? » — « Interessant. 48 500, dafür eine Gehaltsprüfung nach sechs Monaten. » — « Einverstanden — und bitte eine schriftliche Zusage. » — « Selbstverständlich. Willkommen im Team ! »",
        questions: [
                            Exercise(id: "de-listen-gehalt-verhandlung-q1", kind: "choice", prompt: "Was hat Anna abgeschlossen ?", options: ["Die Probezeit", "Die Ausbildung", "Das Studium", "Den Vertrag nicht"], answers: ["Die Probezeit"], explain: "« Sie haben die Probezeit überzeugt. »"),
                            Exercise(id: "de-listen-gehalt-verhandlung-q2", kind: "written", prompt: "Wie viel Gehalt wünscht sich Anna ?", options: [], answers: ["52 000 euro", "52000 euro", "52.000 euro", "zweiundfünfzigtausend euro"], explain: "« …wünsche ich 52 000 Euro im Jahr. »"),
                            Exercise(id: "de-listen-gehalt-verhandlung-q3", kind: "choice", prompt: "Was bietet Anna zusätzlich an ?", options: ["Kundenkontakte aus der alten Firma", "Einen Umzug", "Mehrarbeit ohne Lohn", "Ein eigenes Büro"], answers: ["Kundenkontakte aus der alten Firma"], explain: "« Ich bringe die Kundenkontakte aus meiner alten Firma mit. »"),
                            Exercise(id: "de-listen-gehalt-verhandlung-q4", kind: "choice", prompt: "Was ist die letzte Zusage ?", options: ["48 500 Euro mit Gehaltsprüfung", "52 000 Euro sofort", "47 000 Euro ohne Prüfung", "50 000 Euro ohne Prüfung"], answers: ["48 500 Euro mit Gehaltsprüfung"], explain: "« 48 500, dafür eine Gehaltsprüfung nach sechs Monaten. »"),
                            Exercise(id: "de-listen-gehalt-verhandlung-q5", kind: "written", prompt: "Was verlangt Anna am Ende zusätzlich ?", options: [], answers: ["eine schriftliche zusage", "eine schriftliche bestätigung"], explain: "« Einverstanden — und bitte eine schriftliche Zusage. »")], skills: ["listening:inference", "function:negotiate", "function:talk-about-work"]),
    ListeningText(id: "en-listen-language-cafe", languageID: "en", title: "The language café", level: "A1", topic: "introductions", unitID: "en-foundations-u1",
        text: "Every Wednesday evening, a small café in the city centre is a language café. Students from many countries sit together at big tables. Lucas is twenty-five years old, and he is from Brazil. His Portuguese and Spanish are excellent, and his English is quite good now. At his table there is a woman from Japan and two men from Italy. They ask simple questions: Where are you from? What do you do? Lucas is a nurse, and he is happy to answer. At ten o'clock the café closes, but the new friends are not tired. They are only happy to talk.",
        questions: [
                            Exercise(id: "en-listen-language-cafe-q1", kind: "choice", prompt: "Where is the language café?", options: ["In a small café in the city centre", "In a school", "In a park", "In a hotel"], answers: ["In a small café in the city centre"], explain: "Every Wednesday evening, a small café in the city centre is a language café."),
                            Exercise(id: "en-listen-language-cafe-q2", kind: "choice", prompt: "Where is Lucas from?", options: ["Brazil", "Japan", "Italy", "Portugal"], answers: ["Brazil"], explain: "Lucas is from Brazil."),
                            Exercise(id: "en-listen-language-cafe-q3", kind: "written", prompt: "How old is Lucas?", options: [], answers: ["twenty-five", "25", "he is twenty-five"], explain: "Lucas is twenty-five years old."),
                            Exercise(id: "en-listen-language-cafe-q4", kind: "choice", prompt: "What is his job?", options: ["He is a nurse", "He is a teacher", "He is a waiter", "He is a student"], answers: ["He is a nurse"], explain: "Lucas is a nurse, and he is happy to answer."),
                            Exercise(id: "en-listen-language-cafe-q5", kind: "choice", prompt: "Who sits at his table?", options: ["A woman from Japan and two men from Italy", "Two women from Brazil", "A man from Japan", "Four students from Spain"], answers: ["A woman from Japan and two men from Italy"], explain: "At his table there is a woman from Japan and two men from Italy."),
                            Exercise(id: "en-listen-language-cafe-q6", kind: "written", prompt: "What time does the café close?", options: [], answers: ["at ten o'clock", "ten o'clock", "ten"], explain: "At ten o'clock the café closes.")], skills: ["listening:gist", "listening:detail", "vocab:introductions", "function:introduce-yourself"]),
    ListeningText(id: "en-listen-new-neighbour", languageID: "en", title: "The new neighbour", level: "A1", topic: "people", unitID: "en-foundations-u1",
        text: "There is a new neighbour in the building. Her name is Amélie, and she is from France. She is not a student; she is a photographer. She doesn't work in an office — she works at home, and she travels a lot. The people in the building are curious, but they are also shy, so they don't talk to her. Then one morning, Ben meets her at the door. \"Are you the new neighbour?\" he asks. \"Yes, I am,\" she says, \"and I am happy to be here.\" Now they are friends, and she isn't alone in the building.",
        questions: [
                            Exercise(id: "en-listen-new-neighbour-q1", kind: "choice", prompt: "Where is Amélie from?", options: ["France", "Italy", "Japan", "Brazil"], answers: ["France"], explain: "Amélie is from France."),
                            Exercise(id: "en-listen-new-neighbour-q2", kind: "choice", prompt: "What is her job?", options: ["She is a photographer", "She is a student", "She works in an office", "She is a teacher"], answers: ["She is a photographer"], explain: "She is not a student; she is a photographer."),
                            Exercise(id: "en-listen-new-neighbour-q3", kind: "choice", prompt: "Does she work in an office?", options: ["No, she works at home", "Yes, every day", "Only in summer", "She doesn't say"], answers: ["No, she works at home"], explain: "She doesn't work in an office — she works at home."),
                            Exercise(id: "en-listen-new-neighbour-q4", kind: "written", prompt: "Why don't the people talk to her?", options: [], answers: ["they are shy", "because they are shy", "shy"], explain: "They are curious, but they are also shy."),
                            Exercise(id: "en-listen-new-neighbour-q5", kind: "choice", prompt: "Where does Ben meet her?", options: ["At the door", "In the lift", "In the street", "At the café"], answers: ["At the door"], explain: "One morning, Ben meets her at the door."),
                            Exercise(id: "en-listen-new-neighbour-q6", kind: "written", prompt: "How does Amélie feel at the end?", options: [], answers: ["happy", "she is happy", "happy to be here"], explain: "She says she is happy to be here.")], skills: ["listening:gist", "listening:detail", "function:describe-people"]),
    ListeningText(id: "en-listen-lost-umbrella", languageID: "en", title: "The blue umbrella", level: "A1", topic: "things", unitID: "en-foundations-u2",
        text: "It is a rainy Monday, and the classroom is full of umbrellas. \"Whose umbrella is this?\" the teacher asks. It is a big blue umbrella, and it is next to my chair. \"It isn't mine,\" says Marta. \"My umbrella is green.\" \"Is it yours, Pedro?\" \"No, it isn't. My things are in my bag.\" Then Daniel comes in, wet and tired. He looks at the blue umbrella and laughs. \"That's my umbrella! It's my father's umbrella, and he needs it today.\" The class laughs too. Daniel takes his umbrella, and the teacher writes on the board: your, my, his, her.",
        questions: [
                            Exercise(id: "en-listen-lost-umbrella-q1", kind: "choice", prompt: "What is the weather like?", options: ["Rainy", "Sunny", "Snowy", "Windy and dry"], answers: ["Rainy"], explain: "It is a rainy Monday."),
                            Exercise(id: "en-listen-lost-umbrella-q2", kind: "choice", prompt: "What colour is the umbrella next to the chair?", options: ["Blue", "Green", "Black", "Red"], answers: ["Blue"], explain: "It is a big blue umbrella."),
                            Exercise(id: "en-listen-lost-umbrella-q3", kind: "written", prompt: "What colour is Marta's umbrella?", options: [], answers: ["green", "it is green", "her umbrella is green"], explain: "Marta's umbrella is green."),
                            Exercise(id: "en-listen-lost-umbrella-q4", kind: "choice", prompt: "Whose umbrella is the blue one?", options: ["Daniel's", "Marta's", "Pedro's", "The teacher's"], answers: ["Daniel's"], explain: "Daniel says it is his umbrella — his father's umbrella."),
                            Exercise(id: "en-listen-lost-umbrella-q5", kind: "choice", prompt: "Where are Pedro's things?", options: ["In his bag", "At home", "In his car", "Under the chair"], answers: ["In his bag"], explain: "Pedro says his things are in his bag."),
                            Exercise(id: "en-listen-lost-umbrella-q6", kind: "choice", prompt: "Why does Daniel need the umbrella today?", options: ["His father needs it", "It is a gift for Marta", "It is for the teacher", "He wants to sell it"], answers: ["His father needs it"], explain: "It is his father's umbrella, and his father needs it today.")], skills: ["listening:detail", "grammar:demonstratives", "vocab:social-expressions"]),
    ListeningText(id: "en-listen-new-flatmate", languageID: "en", title: "A new flatmate", level: "A1", topic: "home", unitID: "en-foundations-u2",
        text: "Tom has got a new flatmate. His name is Leo and he is twenty-three years old. Leo comes from a small town in the north, but he works in the city now. He has got two boxes, a guitar and a bicycle. The flat has got two bedrooms and a sunny kitchen. Tom hopes Leo likes cooking, because Tom hates it.",
        questions: [
                            Exercise(id: "en-listen-new-flatmate-q1", kind: "choice", prompt: "How old is Leo?", options: ["Twenty-three", "Thirty-two", "Twenty", "Thirty"], answers: ["Twenty-three"], explain: "Leo is twenty-three years old."),
                            Exercise(id: "en-listen-new-flatmate-q2", kind: "choice", prompt: "What has Leo NOT got?", options: ["A television", "Two boxes", "A guitar", "A bicycle"], answers: ["A television"], explain: "He has two boxes, a guitar and a bicycle — no television."),
                            Exercise(id: "en-listen-new-flatmate-q3", kind: "written", prompt: "What does Tom hate doing?", options: [], answers: ["cooking", "he hates cooking", "tom hates cooking"], explain: "Tom hates cooking."),
                            Exercise(id: "en-listen-new-flatmate-q4", kind: "choice", prompt: "What does the flat have?", options: ["Two bedrooms and a sunny kitchen", "One bedroom and a balcony", "A garden", "Two bathrooms"], answers: ["Two bedrooms and a sunny kitchen"], explain: "The flat has got two bedrooms and a sunny kitchen."),
                            Exercise(id: "en-listen-new-flatmate-q5", kind: "choice", prompt: "Where does Leo work now?", options: ["In the city", "In a small town", "In the north", "He doesn't work"], answers: ["In the city"], explain: "He comes from a small town, but he works in the city now."),
                            Exercise(id: "en-listen-new-flatmate-q6", kind: "written", prompt: "Which instrument has Leo got?", options: [], answers: ["a guitar", "guitar", "he has got a guitar"], explain: "Leo has got a guitar.")], skills: ["listening:gist", "listening:detail", "grammar:have-got", "vocab:home"]),
    ListeningText(id: "en-listen-coffee-morning", languageID: "en", title: "A coffee before work", level: "A1", topic: "routine", unitID: "en-foundations-u3",
        text: "Every morning, Marta walks to a small café near her flat. The waiter knows her name, so she never has to order. Today she sits by the window with a coffee and a croissant. Her bus leaves at half past eight, but she is not worried. The café is very quiet at this hour. She drinks her coffee slowly and watches the city wake up.",
        questions: [
                            Exercise(id: "en-listen-coffee-morning-q1", kind: "choice", prompt: "Where does Marta go every morning?", options: ["To a small café", "To her office", "To the bus station", "To a park"], answers: ["To a small café"], explain: "She walks to a small café near her flat."),
                            Exercise(id: "en-listen-coffee-morning-q2", kind: "choice", prompt: "What does she have for breakfast today?", options: ["Tea and toast", "A coffee and a croissant", "Orange juice", "Nothing"], answers: ["A coffee and a croissant"], explain: "She sits by the window with a coffee and a croissant."),
                            Exercise(id: "en-listen-coffee-morning-q3", kind: "written", prompt: "What time does her bus leave?", options: [], answers: ["at half past eight", "half past eight", "8:30"], explain: "Her bus leaves at half past eight."),
                            Exercise(id: "en-listen-coffee-morning-q4", kind: "choice", prompt: "How does she feel about the time?", options: ["She is not worried", "She is very late", "She is angry", "She is sleepy"], answers: ["She is not worried"], explain: "The text says she is not worried."),
                            Exercise(id: "en-listen-coffee-morning-q5", kind: "choice", prompt: "Who knows Marta's name?", options: ["The waiter", "The bus driver", "Her boss", "A neighbour"], answers: ["The waiter"], explain: "The waiter knows her name, so she never has to order."),
                            Exercise(id: "en-listen-coffee-morning-q6", kind: "written", prompt: "Where does she sit today?", options: [], answers: ["by the window", "next to the window", "at the window"], explain: "Today she sits by the window.")], skills: ["listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine"]),
    ListeningText(id: "en-listen-night-shift", languageID: "en", title: "The night shift", level: "A1", topic: "work", unitID: "en-foundations-u3",
        text: "Paolo is a baker, and he works at night. His shift starts at eleven o'clock in the evening, and it finishes at seven in the morning. First, he makes the bread; then he makes the cakes. He never works alone — his cousin works with him, and they talk while they work. Paolo usually sleeps from nine in the morning to three in the afternoon. On Sundays he doesn't work, and he has lunch with his family. His neighbours sometimes ask him: \"Do you like your job?\" \"Yes,\" he says, \"the city is quiet, the bread smells wonderful, and my mornings are free.\"",
        questions: [
                            Exercise(id: "en-listen-night-shift-q1", kind: "choice", prompt: "When does Paolo's shift start?", options: ["At eleven in the evening", "At seven in the morning", "At nine in the morning", "At three in the afternoon"], answers: ["At eleven in the evening"], explain: "His shift starts at eleven o'clock in the evening."),
                            Exercise(id: "en-listen-night-shift-q2", kind: "written", prompt: "What does he make first?", options: [], answers: ["bread", "the bread", "he makes the bread"], explain: "First, he makes the bread; then the cakes."),
                            Exercise(id: "en-listen-night-shift-q3", kind: "choice", prompt: "Who works with him?", options: ["His cousin", "His brother", "His wife", "A friend from school"], answers: ["His cousin"], explain: "He never works alone — his cousin works with him."),
                            Exercise(id: "en-listen-night-shift-q4", kind: "written", prompt: "When does Paolo usually sleep?", options: [], answers: ["from nine to three", "from nine in the morning to three in the afternoon", "nine to three"], explain: "He usually sleeps from nine in the morning to three in the afternoon."),
                            Exercise(id: "en-listen-night-shift-q5", kind: "choice", prompt: "What does he do on Sundays?", options: ["He has lunch with his family", "He sleeps all day", "He works alone", "He bakes cakes at home"], answers: ["He has lunch with his family"], explain: "On Sundays he doesn't work, and he has lunch with his family."),
                            Exercise(id: "en-listen-night-shift-q6", kind: "choice", prompt: "Why does Paolo like his job?", options: ["The city is quiet and the bread smells wonderful", "It is very well paid", "He meets a lot of people", "The nights are long"], answers: ["The city is quiet and the bread smells wonderful"], explain: "He says the city is quiet, the bread smells wonderful and his mornings are free.")], skills: ["listening:number-time", "listening:detail", "grammar:third-person-s", "grammar:frequency-adverbs", "vocab:work"]),
    ListeningText(id: "en-listen-city-walk", languageID: "en", title: "A walk in the new city", level: "A1", topic: "directions", unitID: "en-foundations-u4",
        text: "Nadia is new in town, and today she explores on foot. In her street there is a small supermarket, a bakery and a bookshop — everything is very close, so she doesn't need the bus. She walks to the river and turns left. There, she can see the old bridge and a big park. In the park there are children, dogs and a lot of green space. She can't visit the museum because it is closed on Mondays, but she can sit in the sun. A man with a dog gives her directions to the market: \"Go straight, cross the bridge, and the market is on your right.\" She thanks him and walks on.",
        questions: [
                            Exercise(id: "en-listen-city-walk-q1", kind: "choice", prompt: "How does Nadia explore the city?", options: ["On foot", "By bus", "By bike", "By tram"], answers: ["On foot"], explain: "Today she explores on foot."),
                            Exercise(id: "en-listen-city-walk-q2", kind: "choice", prompt: "What is in her street?", options: ["A supermarket, a bakery and a bookshop", "A cinema and a café", "A school", "A hospital"], answers: ["A supermarket, a bakery and a bookshop"], explain: "In her street there is a small supermarket, a bakery and a bookshop."),
                            Exercise(id: "en-listen-city-walk-q3", kind: "choice", prompt: "What can she see from the river?", options: ["The old bridge and a big park", "A castle", "The museum", "A shopping centre"], answers: ["The old bridge and a big park"], explain: "From the river she can see the old bridge and a big park."),
                            Exercise(id: "en-listen-city-walk-q4", kind: "choice", prompt: "Why can't she visit the museum?", options: ["It is closed on Mondays", "She doesn't have time", "It is too expensive", "She can't find it"], answers: ["It is closed on Mondays"], explain: "The museum is closed on Mondays."),
                            Exercise(id: "en-listen-city-walk-q5", kind: "written", prompt: "Where is the market?", options: [], answers: ["on your right", "on the right", "on her right"], explain: "Cross the bridge, and the market is on your right."),
                            Exercise(id: "en-listen-city-walk-q6", kind: "written", prompt: "Who gives her directions?", options: [], answers: ["a man with a dog", "a man", "the man with the dog"], explain: "A man with a dog gives her directions.")], skills: ["listening:detail", "function:ask-for-directions", "vocab:directions", "grammar:imperatives"]),
    ListeningText(id: "en-listen-bus-stop-chat", languageID: "en", title: "The bus stop chat", level: "A1", topic: "people", unitID: "en-foundations-out",
        text: "It's cold at the bus stop, and Ben doesn't like silence. 'Cold today, isn't it?' he says to the woman next to him. 'Freezing,' she says. 'Any plans for the weekend?' Ben asks. 'Nothing much — you?' 'My sister is visiting, so we'll walk by the river if it doesn't rain.' The woman smiles. 'Sounds nice. My plans are tea and a book!' The bus arrives — late, of course. 'Have a good one!' Ben says as she gets on. 'You too!' And that's it: a complete conversation with a stranger, sixty seconds long.",
        questions: [
                            Exercise(id: "en-listen-bus-stop-chat-q1", kind: "choice", prompt: "How does Ben open the conversation?", options: ["About the cold", "About the bus", "About the river", "About tea"], answers: ["About the cold"], explain: "'Cold today, isn't it?' — the weather opener."),
                            Exercise(id: "en-listen-bus-stop-chat-q2", kind: "written", prompt: "What are the woman's plans for the weekend?", options: [], answers: ["tea and a book", "tea", "a book"], explain: "Her plans are tea and a book."),
                            Exercise(id: "en-listen-bus-stop-chat-q3", kind: "choice", prompt: "Who is visiting Ben?", options: ["His sister", "His mother", "A neighbour", "Nobody"], answers: ["His sister"], explain: "His sister is visiting, so they'll walk by the river."),
                            Exercise(id: "en-listen-bus-stop-chat-q4", kind: "written", prompt: "Where will they walk if it doesn't rain?", options: [], answers: ["by the river", "the river"], explain: "By the river."),
                            Exercise(id: "en-listen-bus-stop-chat-q5", kind: "choice", prompt: "How does the bus arrive?", options: ["Late, of course", "Early", "Full", "It never arrives"], answers: ["Late, of course"], explain: "The bus arrives — late, of course."),
                            Exercise(id: "en-listen-bus-stop-chat-q6", kind: "written", prompt: "How does Ben say goodbye?", options: [], answers: ["have a good one", "have a good one!"], explain: "'Have a good one!' as she gets on.")], skills: ["vocab:social-expressions", "grammar:present-continuous", "function:talk-about-weather"]),
    ListeningText(id: "en-listen-saturday-list", languageID: "en", title: "The Saturday list", level: "A1", topic: "shopping", unitID: "en-foundations-out",
        text: "Saturday morning, and Marta is at the supermarket with a long list. She needs bread, milk, eggs and tomatoes, but she can't find the tomatoes. A shop assistant is stacking apples nearby. 'Excuse me, where are the tomatoes?' Marta asks. 'Aisle three, next to the juice,' the assistant says. Marta finds them, checks the price — two euros fifty — and goes to the checkout. 'Anything else?' the cashier asks. 'No, that's all, thanks!' At home, she unpacks the bag and finds one thing missing: the bread. It's still on the kitchen table, next to her keys.",
        questions: [
                            Exercise(id: "en-listen-saturday-list-q1", kind: "choice", prompt: "What is NOT on Marta's list?", options: ["Tomatoes", "Bread", "Milk", "Apples"], answers: ["Apples"], explain: "The apples belong to the shop assistant, not the list."),
                            Exercise(id: "en-listen-saturday-list-q2", kind: "written", prompt: "Where are the tomatoes?", options: [], answers: ["aisle three", "in aisle three", "aisle 3"], explain: "Aisle three, next to the juice."),
                            Exercise(id: "en-listen-saturday-list-q3", kind: "choice", prompt: "How much are the tomatoes?", options: ["Two euros fifty", "Three euros", "Two euros", "Fifty cents"], answers: ["Two euros fifty"], explain: "She checks the price: two euros fifty."),
                            Exercise(id: "en-listen-saturday-list-q4", kind: "written", prompt: "What does the cashier ask?", options: [], answers: ["anything else", "anything else?"], explain: "'Anything else?' — the cashier's question."),
                            Exercise(id: "en-listen-saturday-list-q5", kind: "choice", prompt: "What is missing at home?", options: ["The bread", "The milk", "The eggs", "The tomatoes"], answers: ["The bread"], explain: "The bread is still on the kitchen table."),
                            Exercise(id: "en-listen-saturday-list-q6", kind: "written", prompt: "What else is on the kitchen table?", options: [], answers: ["her keys", "the keys", "keys"], explain: "Her keys are next to the bread.")], skills: ["vocab:food", "grammar:there-is-are", "grammar:present-simple", "function:go-shopping"]),
    ListeningText(id: "en-listen-sunday-market", languageID: "en", title: "The Sunday market", level: "A1", topic: "shopping", unitID: "en-foundations-u4",
        text: "On Sundays there is a market in the town square. Anna and her father go there at nine o'clock, before it gets busy. They buy fruit, bread and flowers. Anna wants some strawberries, but her father says they are too expensive this week. In the end they take home a big bag of oranges and some white roses for the kitchen table.",
        questions: [
                            Exercise(id: "en-listen-sunday-market-q1", kind: "choice", prompt: "When do Anna and her father go to the market?", options: ["At nine o'clock", "At noon", "In the afternoon", "At half past six"], answers: ["At nine o'clock"], explain: "They go at nine o'clock, before it gets busy."),
                            Exercise(id: "en-listen-sunday-market-q2", kind: "written", prompt: "Why doesn't Anna get the strawberries?", options: [], answers: ["they are too expensive", "too expensive", "because they are too expensive"], explain: "Her father says they are too expensive this week."),
                            Exercise(id: "en-listen-sunday-market-q3", kind: "choice", prompt: "What do they take home?", options: ["Oranges and roses", "Strawberries and bread", "Apples and tulips", "Bread and cheese"], answers: ["Oranges and roses"], explain: "They take home oranges and white roses."),
                            Exercise(id: "en-listen-sunday-market-q4", kind: "choice", prompt: "Where is the market?", options: ["In the town square", "Near the river", "At the station", "In a supermarket"], answers: ["In the town square"], explain: "There is a market in the town square on Sundays."),
                            Exercise(id: "en-listen-sunday-market-q5", kind: "choice", prompt: "What do they buy?", options: ["Fruit, bread and flowers", "Fish and vegetables", "Cheese and meat", "Only flowers"], answers: ["Fruit, bread and flowers"], explain: "They buy fruit, bread and flowers."),
                            Exercise(id: "en-listen-sunday-market-q6", kind: "written", prompt: "What does Anna want?", options: [], answers: ["strawberries", "some strawberries", "she wants strawberries"], explain: "Anna wants some strawberries.")], skills: ["listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping"]),
    ListeningText(id: "en-listen-new-neighbourhood", languageID: "en", title: "The new neighbourhood", level: "A1", topic: "town", unitID: "en-foundations-town",
        text: "Sofia just moved to Maple Street, and her new neighbour Tom is telling her everything. 'There's a bakery on the corner — the bread is fantastic. There are two schools, a park and a small library. There isn't a cinema, I'm afraid; the nearest one is two bus stops away.' Sofia asks about the park: 'Is there a chemist's near the park?' 'Yes, right next to it,' Tom says. 'And the people?' Sofia wants to know. 'They're friendly and very quiet,' Tom laughs, 'except on Saturdays, when the football starts.'",
        questions: [
                            Exercise(id: "en-listen-new-neighbourhood-q1", kind: "choice", prompt: "What is on the corner?", options: ["A bakery", "A park", "A library", "A cinema"], answers: ["A bakery"], explain: "There's a bakery on the corner — fantastic bread."),
                            Exercise(id: "en-listen-new-neighbourhood-q2", kind: "written", prompt: "What is there two of?", options: [], answers: ["schools", "two schools"], explain: "There are two schools."),
                            Exercise(id: "en-listen-new-neighbourhood-q3", kind: "choice", prompt: "What is missing in the neighbourhood?", options: ["A cinema", "A library", "A bakery", "A park"], answers: ["A cinema"], explain: "There isn't a cinema — the nearest is two bus stops away."),
                            Exercise(id: "en-listen-new-neighbourhood-q4", kind: "written", prompt: "Where is the chemist's?", options: [], answers: ["next to the park", "near the park", "right next to the park"], explain: "Right next to the park."),
                            Exercise(id: "en-listen-new-neighbourhood-q5", kind: "choice", prompt: "What are the people like?", options: ["Friendly and quiet", "Loud", "Unfriendly", "Always at football"], answers: ["Friendly and quiet"], explain: "Friendly and very quiet — except on Saturdays."),
                            Exercise(id: "en-listen-new-neighbourhood-q6", kind: "written", prompt: "What starts on Saturdays?", options: [], answers: ["the football", "football"], explain: "The football starts on Saturdays.")], skills: ["vocab:town", "grammar:there-is-are", "function:ask-simple-questions"]),
    ListeningText(id: "en-listen-rainy-day", languageID: "en", title: "A rainy Saturday", level: "A1", topic: "weather", unitID: "en-foundations-now",
        text: "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Outside, the neighbours are running to their cars with umbrellas. The cat is sleeping in its favourite chair, and the dog is watching the rain too. Anna is not bored — she is drawing the grey sky in her notebook. Her mother is making tea, and the kitchen smells wonderful. 'What are you doing?' Ben asks. 'I'm drawing the weather,' Anna says, 'because today the weather is interesting!'",
        questions: [
                            Exercise(id: "en-listen-rainy-day-q1", kind: "choice", prompt: "What is the weather doing?", options: ["It's raining", "It's snowing", "It's sunny", "It's windy"], answers: ["It's raining"], explain: "It is raining in Maple Street."),
                            Exercise(id: "en-listen-rainy-day-q2", kind: "choice", prompt: "What is Ben doing?", options: ["He's playing a video game", "He's drawing", "He's making tea", "He's sleeping"], answers: ["He's playing a video game"], explain: "Her brother Ben is playing a video game."),
                            Exercise(id: "en-listen-rainy-day-q3", kind: "written", prompt: "What is Anna drawing?", options: [], answers: ["the grey sky", "the sky", "the weather"], explain: "She is drawing the grey sky in her notebook."),
                            Exercise(id: "en-listen-rainy-day-q4", kind: "choice", prompt: "Where is the cat?", options: ["In its favourite chair", "Under the table", "Outside in the rain", "On Anna's bed"], answers: ["In its favourite chair"], explain: "The cat is sleeping in its favourite chair."),
                            Exercise(id: "en-listen-rainy-day-q5", kind: "written", prompt: "What is the mother making?", options: [], answers: ["tea", "making tea", "she is making tea"], explain: "Her mother is making tea."),
                            Exercise(id: "en-listen-rainy-day-q6", kind: "choice", prompt: "How does Anna feel about the day?", options: ["She is not bored", "She is sad", "She is angry", "She is tired"], answers: ["She is not bored"], explain: "Anna is not bored — for her the weather is interesting.")], skills: ["listening:detail", "grammar:present-continuous", "vocab:weather"]),
    ListeningText(id: "en-listen-busy-kitchen", languageID: "en", title: "Sunday in the kitchen", level: "A1", topic: "family", unitID: "en-foundations-now",
        text: "It is Sunday morning, and the whole family is in the kitchen. Grandma is cutting bread, and Grandpa is making coffee — his coffee is always too strong. Anna's father is singing while he is cooking eggs, and her mother is setting the table. The twins are helping, but they are eating more strawberries than they are putting in the bowl. Even the dog is working: he is waiting under the table for pieces of cheese. 'Is anyone NOT eating in this kitchen?' Grandpa laughs. Everyone is smiling. Sunday breakfast is the family's favourite moment of the week.",
        questions: [
                            Exercise(id: "en-listen-busy-kitchen-q1", kind: "choice", prompt: "Where is the whole family?", options: ["In the kitchen", "In the garden", "In the car", "At a café"], answers: ["In the kitchen"], explain: "The whole family is in the kitchen on Sunday morning."),
                            Exercise(id: "en-listen-busy-kitchen-q2", kind: "written", prompt: "What is Grandma doing?", options: [], answers: ["cutting bread", "she is cutting bread", "she's cutting bread"], explain: "Grandma is cutting bread."),
                            Exercise(id: "en-listen-busy-kitchen-q3", kind: "choice", prompt: "What is Grandpa's coffee like?", options: ["Always too strong", "Cold", "Perfect", "Without sugar"], answers: ["Always too strong"], explain: "His coffee is always too strong."),
                            Exercise(id: "en-listen-busy-kitchen-q4", kind: "written", prompt: "What is the father doing while he cooks?", options: [], answers: ["singing", "he is singing", "he's singing"], explain: "He is singing while he is cooking eggs."),
                            Exercise(id: "en-listen-busy-kitchen-q5", kind: "choice", prompt: "What are the twins really doing with the strawberries?", options: ["Eating them", "Washing them", "Selling them", "Cutting them"], answers: ["Eating them"], explain: "They are eating more strawberries than they are putting in the bowl."),
                            Exercise(id: "en-listen-busy-kitchen-q6", kind: "written", prompt: "What is the dog waiting for?", options: [], answers: ["pieces of cheese", "cheese", "some cheese"], explain: "He is waiting under the table for pieces of cheese.")], skills: ["listening:gist", "grammar:present-continuous", "vocab:family"]),
    ListeningText(id: "en-listen-birthday-week", languageID: "en", title: "The birthday week", level: "A1", topic: "dates", unitID: "en-foundations-days",
        text: "This is a special week for Leo. His birthday is on Friday, 12 September, and his family is planning three small parties. On Monday, his colleagues are taking him to a café after work. On Wednesday, his friends are coming to his flat for a film night — his sister is making her famous chocolate cake on Thursday, so the flat smells of chocolate for two days. The family party is on Saturday at three o'clock, at his grandparents' house. Leo's favourite day? 'Sunday,' he laughs, 'because then I can finally rest — my birthday week is wonderful but very busy!'",
        questions: [
                            Exercise(id: "en-listen-birthday-week-q1", kind: "written", prompt: "When is Leo's birthday?", options: [], answers: ["on friday 12 september", "friday 12 september", "12 september", "friday 12th september"], explain: "His birthday is on Friday, 12 September."),
                            Exercise(id: "en-listen-birthday-week-q2", kind: "choice", prompt: "What are his colleagues doing on Monday?", options: ["Taking him to a café", "Cooking a cake", "Coming to his flat", "Resting"], answers: ["Taking him to a café"], explain: "On Monday, his colleagues are taking him to a café after work."),
                            Exercise(id: "en-listen-birthday-week-q3", kind: "choice", prompt: "When is the family party?", options: ["On Saturday at three o'clock", "On Wednesday evening", "On Friday at work", "On Monday morning"], answers: ["On Saturday at three o'clock"], explain: "The family party is on Saturday at three o'clock."),
                            Exercise(id: "en-listen-birthday-week-q4", kind: "written", prompt: "What is his sister making, and when?", options: [], answers: ["chocolate cake on thursday", "a chocolate cake on thursday", "chocolate cake, on thursday"], explain: "She is making her famous chocolate cake on Thursday."),
                            Exercise(id: "en-listen-birthday-week-q5", kind: "choice", prompt: "Where is the family party?", options: ["At his grandparents' house", "At a café", "At his flat", "At work"], answers: ["At his grandparents' house"], explain: "It is at his grandparents' house."),
                            Exercise(id: "en-listen-birthday-week-q6", kind: "written", prompt: "What is Leo's favourite day of the week? Why? (one word for the day)", options: [], answers: ["sunday", "on sunday", "sunday because he can rest"], explain: "Sunday — because then he can finally rest.")], skills: ["listening:number-time", "grammar:time-expressions", "function:tell-time"], exposureSkills: ["grammar:present-continuous"]),
    ListeningText(id: "en-listen-not-feeling-well", languageID: "en", title: "Not feeling well", level: "A1", topic: "health", unitID: "en-foundations-days",
        text: "Daniel doesn't feel well this morning. He has got a headache and a sore throat, and his whole body is tired. At work, his colleague Sofia notices immediately. 'What's wrong?' she asks. 'I've got a cold, I think,' Daniel says. 'My throat hurts, and I can't stop sneezing.' Sofia is worried. 'Go home and rest! Drink hot tea with honey — my grandmother's recipe.' Daniel takes her advice. In the afternoon, he is in bed with a big cup of tea. His cat is sleeping next to him. On Friday he is back at work, and his colleagues say he looks great.",
        questions: [
                            Exercise(id: "en-listen-not-feeling-well-q1", kind: "choice", prompt: "How does Daniel feel this morning?", options: ["He doesn't feel well", "He feels great", "He is angry", "He is hungry"], answers: ["He doesn't feel well"], explain: "Daniel doesn't feel well this morning."),
                            Exercise(id: "en-listen-not-feeling-well-q2", kind: "written", prompt: "What has Daniel got?", options: [], answers: ["a cold", "he has got a cold", "he's got a cold", "a headache and a cold"], explain: "He thinks he has got a cold."),
                            Exercise(id: "en-listen-not-feeling-well-q3", kind: "choice", prompt: "Who notices first?", options: ["His colleague Sofia", "His mother", "His cat", "His boss"], answers: ["His colleague Sofia"], explain: "His colleague Sofia notices immediately."),
                            Exercise(id: "en-listen-not-feeling-well-q4", kind: "written", prompt: "What does Sofia recommend?", options: [], answers: ["hot tea with honey", "tea with honey", "go home and rest"], explain: "Hot tea with honey — her grandmother's recipe."),
                            Exercise(id: "en-listen-not-feeling-well-q5", kind: "choice", prompt: "Where is Daniel in the afternoon?", options: ["In bed with a cup of tea", "At the pharmacy", "At work", "At Sofia's house"], answers: ["In bed with a cup of tea"], explain: "He is in bed with a big cup of tea."),
                            Exercise(id: "en-listen-not-feeling-well-q6", kind: "choice", prompt: "When is he back at work?", options: ["On Friday", "On Monday", "The same afternoon", "On Wednesday"], answers: ["On Friday"], explain: "On Friday he is back at work and looks great.")], skills: ["listening:detail", "vocab:health", "grammar:have-got", "grammar:can"]),
    ListeningText(id: "en-listen-language-exchange", languageID: "en", title: "The language-exchange evening", level: "A2", topic: "languages", unitID: "en-foundations-u5",
        text: "Last Thursday, Ines went to a language exchange at a bar in the old town. She wanted to practise her English, so she sat with a group from Manchester. At first she could only smile and nod. But after half an hour the words started to come. They talked about films, football and the differences between Spanish and English breakfasts. She didn't leave until eleven, and she wrote down fifteen new expressions on the tram home.",
        questions: [
                            Exercise(id: "en-listen-language-exchange-q1", kind: "choice", prompt: "Why did Ines go to the exchange?", options: ["To practise her English", "To watch football", "To eat breakfast", "To teach maths"], answers: ["To practise her English"], explain: "She wanted to practise her English."),
                            Exercise(id: "en-listen-language-exchange-q2", kind: "written", prompt: "What could she do at first?", options: [], answers: ["she could only smile and nod", "smile and nod", "only smile and nod"], explain: "At first she could only smile and nod."),
                            Exercise(id: "en-listen-language-exchange-q3", kind: "choice", prompt: "What did they NOT talk about?", options: ["Their jobs", "Films", "Football", "Breakfasts"], answers: ["Their jobs"], explain: "They talked about films, football and breakfasts — not jobs."),
                            Exercise(id: "en-listen-language-exchange-q4", kind: "written", prompt: "What did she do on the tram home?", options: [], answers: ["she wrote down fifteen new expressions", "she wrote down new expressions", "wrote down fifteen expressions"], explain: "She wrote down fifteen new expressions."),
                            Exercise(id: "en-listen-language-exchange-q5", kind: "choice", prompt: "Where did the exchange take place?", options: ["In a bar in the old town", "In a school", "In a library", "In a park"], answers: ["In a bar in the old town"], explain: "It was at a bar in the old town."),
                            Exercise(id: "en-listen-language-exchange-q6", kind: "written", prompt: "What time did she leave?", options: [], answers: ["at eleven", "eleven", "at 11"], explain: "She didn't leave until eleven.")], skills: ["listening:gist", "listening:inference", "vocab:social-expressions"], exposureSkills: ["grammar:past-simple-regular"]),
    ListeningText(id: "en-listen-rainy-picnic", languageID: "en", title: "The rainy picnic", level: "A2", topic: "weather", unitID: "en-foundations-u5",
        text: "We were so excited about the picnic on Saturday. The weather was warm on Friday, so we didn't check the forecast. On Saturday morning it started to rain and it didn't stop all day. We moved everything into the kitchen and ate on the floor. Honestly, it was one of the best afternoons of the summer. Sometimes the plans that go wrong are the ones you remember.",
        questions: [
                            Exercise(id: "en-listen-rainy-picnic-q1", kind: "choice", prompt: "Why didn't they check the forecast?", options: ["The weather was warm on Friday", "They don't have a phone", "They were in a hurry", "They forgot"], answers: ["The weather was warm on Friday"], explain: "The weather was warm on Friday, so they didn't check."),
                            Exercise(id: "en-listen-rainy-picnic-q2", kind: "written", prompt: "Where did they eat?", options: [], answers: ["in the kitchen", "on the kitchen floor", "on the floor in the kitchen"], explain: "They moved everything into the kitchen and ate on the floor."),
                            Exercise(id: "en-listen-rainy-picnic-q3", kind: "choice", prompt: "How did they feel about the day in the end?", options: ["It was one of the best afternoons", "It was a disaster", "They were bored", "They were angry"], answers: ["It was one of the best afternoons"], explain: "It was one of the best afternoons of the summer."),
                            Exercise(id: "en-listen-rainy-picnic-q4", kind: "choice", prompt: "What was the weather like on Saturday?", options: ["It rained all day", "Sunny", "Cloudy but dry", "Snowy"], answers: ["It rained all day"], explain: "It started to rain and didn't stop all day."),
                            Exercise(id: "en-listen-rainy-picnic-q5", kind: "choice", prompt: "Which day was the picnic planned for?", options: ["Saturday", "Friday", "Sunday", "Monday"], answers: ["Saturday"], explain: "They were excited about the picnic on Saturday."),
                            Exercise(id: "en-listen-rainy-picnic-q6", kind: "written", prompt: "What was the weather like on Friday?", options: [], answers: ["warm", "it was warm", "the weather was warm"], explain: "The weather was warm on Friday.")], skills: ["listening:inference", "listening:detail", "vocab:weather"], exposureSkills: ["grammar:past-was-were", "grammar:past-simple-regular"]),
    ListeningText(id: "en-listen-first-day", languageID: "en", title: "Sofia's first day", level: "A2", topic: "jobs", unitID: "en-foundations-u6",
        text: "Yesterday was Sofia's first day at her new job. She woke up at six, took the tram and arrived early. The office was smaller than she expected, but everyone was friendly. Her manager gave her a laptop and a long list of things to read. At lunchtime she ate with two colleagues in the park next to the office. On the way home she felt tired but happy, and she called her mother to tell her everything.",
        questions: [
                            Exercise(id: "en-listen-first-day-q1", kind: "choice", prompt: "When did Sofia arrive at the office?", options: ["Early", "Late", "At noon", "She doesn't say"], answers: ["Early"], explain: "She woke up at six and arrived early."),
                            Exercise(id: "en-listen-first-day-q2", kind: "written", prompt: "What did her manager give her?", options: [], answers: ["a laptop and a long list", "a laptop and a list of things to read", "a laptop"], explain: "He gave her a laptop and a long list of things to read."),
                            Exercise(id: "en-listen-first-day-q3", kind: "choice", prompt: "Where did she eat lunch?", options: ["In the park", "At her desk", "In a café", "At home"], answers: ["In the park"], explain: "She ate with two colleagues in the park next to the office."),
                            Exercise(id: "en-listen-first-day-q4", kind: "choice", prompt: "How did she feel on the way home?", options: ["Tired but happy", "Angry", "Sad and lonely", "Nervous"], answers: ["Tired but happy"], explain: "She felt tired but happy."),
                            Exercise(id: "en-listen-first-day-q5", kind: "choice", prompt: "How did she go to work?", options: ["By tram", "By bus", "On foot", "By car"], answers: ["By tram"], explain: "She took the tram."),
                            Exercise(id: "en-listen-first-day-q6", kind: "written", prompt: "Who did she call on the way home?", options: [], answers: ["her mother", "she called her mother", "mother"], explain: "She called her mother to tell her everything.")], skills: ["listening:detail", "grammar:past-simple-regular", "vocab:work"]),
    ListeningText(id: "en-listen-small-accident", languageID: "en", title: "A small accident", level: "A2", topic: "pets", unitID: "en-foundations-u6",
        text: "While Carlos was cooking dinner on Sunday, he heard a crash from the living room. His cat, Luna, had jumped onto the bookshelf and knocked down his favourite cup. The cup was in pieces on the floor. Luna sat next to the broken pieces, completely calm, as if nothing had happened. Carlos cleaned everything up carefully. The cup was from a trip to Lisbon five years ago, but he didn't shout. It was, after all, only a cup.",
        questions: [
                            Exercise(id: "en-listen-small-accident-q1", kind: "choice", prompt: "What was Carlos doing when he heard the crash?", options: ["Cooking dinner", "Cleaning the floor", "Reading", "Sleeping"], answers: ["Cooking dinner"], explain: "He was cooking dinner on Sunday."),
                            Exercise(id: "en-listen-small-accident-q2", kind: "written", prompt: "Who broke the cup?", options: [], answers: ["his cat luna", "luna", "the cat", "his cat"], explain: "Luna the cat jumped onto the bookshelf and knocked it down."),
                            Exercise(id: "en-listen-small-accident-q3", kind: "choice", prompt: "Where was the cup from?", options: ["A trip to Lisbon", "A birthday", "His grandmother", "A market"], answers: ["A trip to Lisbon"], explain: "The cup was from a trip to Lisbon five years ago."),
                            Exercise(id: "en-listen-small-accident-q4", kind: "choice", prompt: "How did Carlos react?", options: ["He didn't shout", "He shouted at Luna", "He cried", "He called his friend"], answers: ["He didn't shout"], explain: "He cleaned up carefully and didn't shout."),
                            Exercise(id: "en-listen-small-accident-q5", kind: "choice", prompt: "Where was the bookshelf?", options: ["In the living room", "In the kitchen", "In the bedroom", "In the hall"], answers: ["In the living room"], explain: "He heard the crash from the living room, where the bookshelf was."),
                            Exercise(id: "en-listen-small-accident-q6", kind: "written", prompt: "How old is the cup?", options: [], answers: ["five years old", "five years", "five"], explain: "The cup was from a trip to Lisbon five years ago.")], skills: ["listening:detail", "grammar:past-simple-regular"], exposureSkills: ["grammar:past-continuous"]),
    ListeningText(id: "en-listen-two-cities", languageID: "en", title: "Two cities, one decision", level: "A2", topic: "travel", unitID: "en-foundations-compare",
        text: "'So, Lisbon or Porto?' Marta asks. Her sister Lena is moving next month, and the decision is harder than she expected. 'Porto is smaller and cheaper,' Lena says, 'but Lisbon has more job opportunities.' Marta nods. 'And the weather? Lisbon is warmer in winter.' 'True, but Porto is greener — I love the rain on the river.' They compare the flats they found online: the Lisbon flat is more modern but noisier; the Porto flat is older but much bigger, and the rent is lower than in Lisbon. 'Which one do you prefer?' Marta asks. Lena smiles. 'Honestly, the people make the city. My best friend is in Porto — that's the most important thing.'",
        questions: [
                            Exercise(id: "en-listen-two-cities-q1", kind: "choice", prompt: "What is Lena's decision about?", options: ["Moving to Lisbon or Porto", "Two jobs", "Two flats in the same city", "A holiday"], answers: ["Moving to Lisbon or Porto"], explain: "She is moving next month and must choose between the two cities."),
                            Exercise(id: "en-listen-two-cities-q2", kind: "written", prompt: "According to Lena, what does Lisbon have more of?", options: [], answers: ["job opportunities", "more job opportunities", "jobs"], explain: "Lisbon has more job opportunities."),
                            Exercise(id: "en-listen-two-cities-q3", kind: "choice", prompt: "How does Lena describe the Porto flat?", options: ["Older but much bigger", "More modern but noisier", "Cheaper but smaller", "Newer and greener"], answers: ["Older but much bigger"], explain: "The Porto flat is older but much bigger, and the rent is lower."),
                            Exercise(id: "en-listen-two-cities-q4", kind: "written", prompt: "Which city is warmer in winter?", options: [], answers: ["lisbon", "lisboa"], explain: "Marta says Lisbon is warmer in winter."),
                            Exercise(id: "en-listen-two-cities-q5", kind: "choice", prompt: "What does Lena say is the most important thing?", options: ["Her best friend is in Porto", "The weather", "The rent", "The modern flat"], answers: ["Her best friend is in Porto"], explain: "For her, the people make the city."),
                            Exercise(id: "en-listen-two-cities-q6", kind: "choice", prompt: "How hard was the decision?", options: ["Harder than she expected", "Easy", "Impossible", "She doesn't say"], answers: ["Harder than she expected"], explain: "The decision is harder than she expected.")], skills: ["listening:inference", "grammar:comparatives", "grammar:superlatives", "vocab:travel"]),
    ListeningText(id: "en-listen-quiet-hotel", languageID: "en", title: "The quiet hotel problem", level: "A2", topic: "travel", unitID: "en-foundations-compare",
        text: "Tom booked a quiet hotel for his holiday, but on the first night a group arrived for a wedding. The music played until three in the morning, and Tom couldn't sleep. In the morning he went to reception. 'I booked a quiet room,' he said calmly. 'Last night I heard every song of the party.' The manager apologised. 'You're right — we shouldn't have given you room twelve. We're moving you to the garden side, and breakfast is on us today.' Tom thanked her. 'That's fair.' The new room was quieter than a library, and by the pool Tom finally started to enjoy his holiday.",
        questions: [
                            Exercise(id: "en-listen-quiet-hotel-q1", kind: "choice", prompt: "Why couldn't Tom sleep?", options: ["There was a wedding party", "The bed was uncomfortable", "It was too cold", "The street was noisy"], answers: ["There was a wedding party"], explain: "A wedding group arrived and the music played until three."),
                            Exercise(id: "en-listen-quiet-hotel-q2", kind: "written", prompt: "What had Tom booked?", options: [], answers: ["a quiet hotel", "a quiet room", "a quiet hotel room"], explain: "He booked a quiet hotel for his holiday."),
                            Exercise(id: "en-listen-quiet-hotel-q3", kind: "choice", prompt: "How did Tom complain?", options: ["Calmly at reception", "He shouted at the manager", "He wrote a bad review", "He called the police"], answers: ["Calmly at reception"], explain: "He went to reception and spoke calmly."),
                            Exercise(id: "en-listen-quiet-hotel-q4", kind: "written", prompt: "What did the manager offer?", options: [], answers: ["a room on the garden side", "a quieter room", "a room on the garden side and free breakfast", "a new room and free breakfast"], explain: "A room on the garden side, and breakfast on the house."),
                            Exercise(id: "en-listen-quiet-hotel-q5", kind: "choice", prompt: "How was the new room?", options: ["Quieter than a library", "Still noisy", "Bigger but expensive", "Next to the pool"], answers: ["Quieter than a library"], explain: "The new room was quieter than a library."),
                            Exercise(id: "en-listen-quiet-hotel-q6", kind: "written", prompt: "What was Tom's reaction to the solution?", options: [], answers: ["that's fair", "he thanked her", "he said that's fair"], explain: "He thanked her and said that was fair.")], skills: ["listening:detail", "function:solve-problems", "grammar:comparatives", "vocab:travel"], exposureSkills: ["grammar:past-continuous"]),
    ListeningText(id: "en-listen-weekend-plans", languageID: "en", title: "The weekend plan", level: "A2", topic: "free time", unitID: "en-foundations-plans",
        text: "'What are you going to do this weekend?' Sara asks her flatmate Diego. 'Nothing special,' he says, 'I'm going to clean the flat and maybe watch a film.' Sara has a better idea. 'The weather is going to be sunny on Saturday — some friends are going to cycle to the lake. Are you going to come?' Diego thinks. 'I haven't got a bike.' 'You can rent one — it's only eight euros for the whole day. We're going to leave at nine, have lunch by the water and come back before six.' 'And if it rains?' 'We're going to take the train back — problem solved!' Diego laughs. 'OK, I'm in. But I'm not going to cycle uphill!'",
        questions: [
                            Exercise(id: "en-listen-weekend-plans-q1", kind: "choice", prompt: "What was Diego going to do this weekend?", options: ["Clean the flat and watch a film", "Cycle to the lake", "Visit Sara's friends", "Work"], answers: ["Clean the flat and watch a film"], explain: "He was going to clean the flat and maybe watch a film."),
                            Exercise(id: "en-listen-weekend-plans-q2", kind: "written", prompt: "What is the weather going to be like on Saturday?", options: [], answers: ["sunny", "it's going to be sunny", "sunny on saturday"], explain: "The weather is going to be sunny."),
                            Exercise(id: "en-listen-weekend-plans-q3", kind: "choice", prompt: "What are Sara and her friends going to do?", options: ["Cycle to the lake", "Go to the cinema", "Visit a museum", "Have a picnic in the park"], answers: ["Cycle to the lake"], explain: "Some friends are going to cycle to the lake."),
                            Exercise(id: "en-listen-weekend-plans-q4", kind: "written", prompt: "How much does renting a bike cost?", options: [], answers: ["eight euros", "8 euros", "8€"], explain: "It's only eight euros for the whole day."),
                            Exercise(id: "en-listen-weekend-plans-q5", kind: "choice", prompt: "What time are they going to leave?", options: ["At nine", "At six", "At noon", "At eight"], answers: ["At nine"], explain: "They're going to leave at nine and come back before six."),
                            Exercise(id: "en-listen-weekend-plans-q6", kind: "written", prompt: "What is Diego NOT going to do?", options: [], answers: ["cycle uphill", "go uphill", "cycle up hill"], explain: "He's in — but he's not going to cycle uphill!")], skills: ["listening:gist", "grammar:going-to", "function:make-future-plans", "vocab:hobbies"]),
    ListeningText(id: "en-listen-office-rules", languageID: "en", title: "The office rules", level: "A2", topic: "work", unitID: "en-foundations-plans",
        text: "It's Nerea's first day, and Pablo is showing her around. 'A few rules,' he smiles. 'Everyone has to wear the badge — security is strict about that. You don't have to arrive at eight exactly, but meetings start at nine sharp, so don't be late for those.' 'Should I bring my own laptop?' Nerea asks. 'No — the company gives you one, and you mustn't install outside software on it. Lunch is at one; you can eat in the canteen or go out. On Fridays we don't have to wear formal clothes.' 'And coffee?' 'The machine is free — but you should try the bar next door. Their coffee is much better!'",
        questions: [
                            Exercise(id: "en-listen-office-rules-q1", kind: "choice", prompt: "What does everyone have to wear?", options: ["A badge", "A uniform", "Formal clothes", "A helmet"], answers: ["A badge"], explain: "Everyone has to wear the badge — security is strict."),
                            Exercise(id: "en-listen-office-rules-q2", kind: "written", prompt: "What time do meetings start?", options: [], answers: ["at nine", "nine", "9"], explain: "Meetings start at nine sharp."),
                            Exercise(id: "en-listen-office-rules-q3", kind: "choice", prompt: "What mustn't Nerea do with the work laptop?", options: ["Install outside software", "Take it home", "Use it for email", "Charge it at night"], answers: ["Install outside software"], explain: "You mustn't install outside software on it."),
                            Exercise(id: "en-listen-office-rules-q4", kind: "written", prompt: "What is different on Fridays?", options: [], answers: ["no formal clothes", "you don't have to wear formal clothes", "informal clothes", "casual clothes"], explain: "On Fridays they don't have to wear formal clothes."),
                            Exercise(id: "en-listen-office-rules-q5", kind: "choice", prompt: "What does Pablo recommend for coffee?", options: ["The bar next door", "The office machine", "Making it at home", "The canteen"], answers: ["The bar next door"], explain: "You should try the bar next door — much better coffee."),
                            Exercise(id: "en-listen-office-rules-q6", kind: "choice", prompt: "Where can Nerea eat lunch?", options: ["In the canteen or out", "Only at her desk", "Only in the canteen", "At the bar next door"], answers: ["In the canteen or out"], explain: "Lunch is at one — canteen or out.")], skills: ["listening:detail", "grammar:modal-must-have-to", "grammar:modal-should", "vocab:work"], exposureSkills: ["grammar:going-to"]),
    ListeningText(id: "en-listen-never-been", languageID: "en", title: "Things I've never done", level: "B1", topic: "travel", unitID: "en-foundations-experiences",
        text: "At a hostel kitchen table, three travellers compare lives. Jonas has visited twenty countries, but he's never learned to swim — 'I know, it's ridiculous.' Amara has swum with dolphins twice, yet she's never left Africa until this trip. And Coco, who has been on the road for six years, has never flown: she crosses oceans on ships and borders on buses. 'Never?' Jonas asks. 'Never. The fear is older than I am.' They laugh about the things they haven't done, and Coco says something that stays with them: 'You don't need to have done everything. You just need to still want to.'",
        questions: [
                            Exercise(id: "en-listen-never-been-q1", kind: "choice", prompt: "What has Jonas never done?", options: ["Learned to swim", "Visited twenty countries", "Flown on a plane", "Crossed a border"], answers: ["Learned to swim"], explain: "He has visited twenty countries but has never learned to swim."),
                            Exercise(id: "en-listen-never-been-q2", kind: "written", prompt: "How many times has Amara swum with dolphins?", options: [], answers: ["twice", "2 times", "two times"], explain: "She has swum with dolphins twice."),
                            Exercise(id: "en-listen-never-been-q3", kind: "choice", prompt: "How does Coco travel across oceans?", options: ["On ships", "On buses", "By plane", "She doesn't cross them"], answers: ["On ships"], explain: "She crosses oceans on ships and borders on buses."),
                            Exercise(id: "en-listen-never-been-q4", kind: "written", prompt: "How long has Coco been travelling?", options: [], answers: ["six years", "6 years"], explain: "She has been on the road for six years."),
                            Exercise(id: "en-listen-never-been-q5", kind: "choice", prompt: "Why has Coco never flown?", options: ["Her fear is older than she is", "She can't afford it", "She prefers trains", "She has never wanted to"], answers: ["Her fear is older than she is"], explain: "She says the fear is older than she is."),
                            Exercise(id: "en-listen-never-been-q6", kind: "choice", prompt: "What does Coco say at the end?", options: ["You just need to still want to", "Everyone should fly once", "Travel is overrated", "Ships are better"], answers: ["You just need to still want to"], explain: "You don't need to have done everything — just to still want to.")], skills: ["listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"], exposureSkills: ["grammar:relative-clauses"]),
    ListeningText(id: "en-listen-traffic-tale", languageID: "en", title: "The day of the parade", level: "B1", topic: "stories", unitID: "en-foundations-experiences",
        text: "It was a quiet Sunday morning and Elena was cycling to work, as she always did. The streets were almost empty; a few runners were crossing the bridge, and a baker was setting out trays of bread. She was crossing the main square when she heard drums. Suddenly, the road ahead filled with people — a parade she had completely forgotten about. Dancers were spinning, children were waving flags, and a brass band was playing behind them. Elena stopped, one foot on the ground, and just watched. She was twenty minutes late for work, but her boss, who had also been stuck in the crowd, only laughed. 'Some mornings,' he said, 'you're exactly where you should be.'",
        questions: [
                            Exercise(id: "en-listen-traffic-tale-q1", kind: "choice", prompt: "What was Elena doing when she heard the drums?", options: ["She was crossing the main square", "She was working", "She was setting out bread", "She was at home"], answers: ["She was crossing the main square"], explain: "She was crossing the main square when she heard drums."),
                            Exercise(id: "en-listen-traffic-tale-q2", kind: "written", prompt: "What were the runners doing on the bridge?", options: [], answers: ["crossing it", "crossing the bridge", "running"], explain: "A few runners were crossing the bridge."),
                            Exercise(id: "en-listen-traffic-tale-q3", kind: "choice", prompt: "What filled the road?", options: ["A parade", "Traffic", "Rain", "Runners"], answers: ["A parade"], explain: "Suddenly, the road filled with people — a forgotten parade."),
                            Exercise(id: "en-listen-traffic-tale-q4", kind: "written", prompt: "What was the brass band doing?", options: [], answers: ["playing", "playing behind the dancers", "playing music"], explain: "A brass band was playing behind the dancers."),
                            Exercise(id: "en-listen-traffic-tale-q5", kind: "choice", prompt: "How late was Elena for work?", options: ["Twenty minutes", "Ten minutes", "An hour", "She never arrived"], answers: ["Twenty minutes"], explain: "She was twenty minutes late."),
                            Exercise(id: "en-listen-traffic-tale-q6", kind: "choice", prompt: "Why did her boss only laugh?", options: ["He had also been stuck in the crowd", "It was a holiday", "She never told him", "He loves parades"], answers: ["He had also been stuck in the crowd"], explain: "Her boss had also been stuck — some mornings you're exactly where you should be.")], skills: ["listening:detail", "grammar:past-continuous", "grammar:past-simple-irregular", "function:tell-a-story"], exposureSkills: ["grammar:past-continuous"]),
    ListeningText(id: "en-listen-if-it-rains", languageID: "en", title: "If it rains", level: "B1", topic: "plans", unitID: "en-foundations-connections",
        text: "'So what's the plan if it rains?' Sam asks, looking at the grey sky. Priya has thought about everything. 'If it rains before ten, we'll move the picnic into the greenhouse — my aunt said we can use it. If it starts while we're out, we'll walk fifteen minutes to the station and take the train back.' 'And if the trains stop?' 'They won't — but if they do, we'll call my brother; he loves an excuse to drive at night.' Sam laughs. 'And if the sun shines all day?' 'Then we'll have the best picnic of the year, and you'll owe me an apology for doubting my planning.'",
        questions: [
                            Exercise(id: "en-listen-if-it-rains-q1", kind: "choice", prompt: "Where will they go if it rains before ten?", options: ["To the greenhouse", "Home", "To the station", "To Sam's flat"], answers: ["To the greenhouse"], explain: "They'll move the picnic into the greenhouse."),
                            Exercise(id: "en-listen-if-it-rains-q2", kind: "written", prompt: "What will they do if rain starts while they're out?", options: [], answers: ["take the train back", "walk to the station and take the train", "walk to the station"], explain: "Walk to the station and take the train back."),
                            Exercise(id: "en-listen-if-it-rains-q3", kind: "choice", prompt: "Who will pick them up if the trains stop?", options: ["Priya's brother", "Sam's sister", "Priya's aunt", "Nobody"], answers: ["Priya's brother"], explain: "Her brother loves an excuse to drive at night."),
                            Exercise(id: "en-listen-if-it-rains-q4", kind: "written", prompt: "What does Priya say will happen if the sun shines all day?", options: [], answers: ["the best picnic of the year", "they'll have the best picnic of the year", "it will be the best picnic of the year"], explain: "Then they'll have the best picnic of the year."),
                            Exercise(id: "en-listen-if-it-rains-q5", kind: "choice", prompt: "Why does Sam owe an apology?", options: ["For doubting Priya's planning", "For being late", "For eating the food", "For losing the map"], answers: ["For doubting Priya's planning"], explain: "Priya says he'll owe an apology for doubting her planning."),
                            Exercise(id: "en-listen-if-it-rains-q6", kind: "choice", prompt: "How does Priya seem about her plan?", options: ["She has thought about everything", "She is nervous", "She hasn't prepared", "She wants to cancel"], answers: ["She has thought about everything"], explain: "Priya has an answer for every condition.")], skills: ["listening:detail", "grammar:first-conditional", "function:make-future-plans"]),
    ListeningText(id: "en-listen-job-change", languageID: "en", title: "Before the change", level: "B1", topic: "work", unitID: "en-foundations-connections",
        text: "Rosa remembers her office life the way you remember an old coat: familiar, slightly tight. She used to commute ninety minutes each way. She used to eat lunch at her desk and answer emails at midnight. 'I used to think that was normal,' she says. 'Everyone around me did the same.' Two years ago she moved to a small town and opened a bookshop. At first, the silence was unbearable — she didn't use to have quiet, and it felt like something was wrong. Now she closes at six and reads in the evenings. 'People ask if I miss the city. Although I loved parts of it, I don't miss the person I was becoming there.'",
        questions: [
                            Exercise(id: "en-listen-job-change-q1", kind: "written", prompt: "How long did Rosa use to commute each way?", options: [], answers: ["ninety minutes", "90 minutes", "an hour and a half"], explain: "She used to commute ninety minutes each way."),
                            Exercise(id: "en-listen-job-change-q2", kind: "choice", prompt: "What did she use to do at midnight?", options: ["Answer emails", "Sleep", "Read", "Cook"], answers: ["Answer emails"], explain: "She used to answer emails at midnight."),
                            Exercise(id: "en-listen-job-change-q3", kind: "written", prompt: "What did she open in the small town?", options: [], answers: ["a bookshop", "a book shop", "a bookstore"], explain: "She opened a bookshop."),
                            Exercise(id: "en-listen-job-change-q4", kind: "choice", prompt: "How did the silence feel at first?", options: ["Unbearable", "Wonderful", "Normal", "Exciting"], answers: ["Unbearable"], explain: "She didn't use to have quiet, and it felt like something was wrong."),
                            Exercise(id: "en-listen-job-change-q5", kind: "written", prompt: "What does she do in the evenings now?", options: [], answers: ["she reads", "reads"], explain: "Now she closes at six and reads in the evenings."),
                            Exercise(id: "en-listen-job-change-q6", kind: "choice", prompt: "What doesn't she miss about the city?", options: ["The person she was becoming", "Her colleagues", "The food", "The salary"], answers: ["The person she was becoming"], explain: "Although she loved parts of it, she doesn't miss who she was becoming.")], skills: ["listening:inference", "grammar:used-to", "grammar:connectors", "vocab:work"]),
    ListeningText(id: "en-listen-monday-predictions", languageID: "en", title: "The Monday pool", level: "B1", topic: "work", unitID: "en-foundations-change",
        text: "Every Monday, the design team runs a small prediction pool. 'Ten euros says the client changes the brief by Wednesday,' says Jonas. Petra shakes her head. 'The brief will survive — but the printer will break. It always does.' Newcomer Ana smiles nervously. 'I'll just predict something safe: we'll all complain about the coffee.' Everyone writes their bets on the whiteboard, and the week starts. By Wednesday, the client has indeed changed the brief, twice. Jonas collects his ten euros without a word. The printer, loyal to tradition, jams on Thursday morning — Petra's turn to smile. And on Friday, Ana looks at her line on the board, at the empty coffee machine, and says what everyone is thinking: 'Will anyone else complain, or is it just me?'",
        questions: [
                            Exercise(id: "en-listen-monday-predictions-q1", kind: "choice", prompt: "What does Jonas predict on Monday?", options: ["The client will change the brief", "The printer will break", "The coffee will run out", "Ana will win"], answers: ["The client will change the brief"], explain: "'Ten euros says the client changes the brief by Wednesday.'"),
                            Exercise(id: "en-listen-monday-predictions-q2", kind: "written", prompt: "What is Petra's prediction?", options: [], answers: ["the printer will break", "the printer breaks", "printer will break"], explain: "The brief will survive, but the printer will break."),
                            Exercise(id: "en-listen-monday-predictions-q3", kind: "written", prompt: "What does newcomer Ana predict?", options: [], answers: ["they will all complain about the coffee", "everyone will complain about the coffee", "they'll complain about the coffee"], explain: "A safe prediction: everyone complains about the coffee."),
                            Exercise(id: "en-listen-monday-predictions-q4", kind: "choice", prompt: "What happened by Wednesday?", options: ["The client changed the brief twice", "The printer broke", "The coffee machine died", "Nothing"], answers: ["The client changed the brief twice"], explain: "The client changed the brief, twice — Jonas wins his bet."),
                            Exercise(id: "en-listen-monday-predictions-q5", kind: "choice", prompt: "When did the printer jam?", options: ["Thursday morning", "Wednesday", "Monday", "It didn't"], answers: ["Thursday morning"], explain: "Loyal to tradition, it jammed on Thursday morning."),
                            Exercise(id: "en-listen-monday-predictions-q6", kind: "choice", prompt: "How did Jonas collect his winnings?", options: ["Without a word", "With a speech", "He never did", "He bought coffee"], answers: ["Without a word"], explain: "He collected his ten euros without a word — the quiet winner.")], skills: ["listening:inference", "grammar:future-forms", "function:make-future-plans"]),
    ListeningText(id: "en-listen-office-rumours", languageID: "en", title: "The rumour mill", level: "B1", topic: "work", unitID: "en-foundations-change",
        text: "Carmen came back from one day off and the office had invented three futures. 'Marco said the company was moving to Lisbon,' whispered Diego. 'Lena told me they were hiring twenty people,' said Carmen. 'And Priya swears she heard we were all getting new laptops.' Carmen put down her bag and applied the office rule: trace every rumour to its source. The Lisbon story started with a photo Marco took of a moving van — which was moving his neighbour's piano. The twenty hires were real, but Lena had read 'over the next five years' and skipped that part. And the laptops were true: an email had gone out at seven that morning. One truth, one exaggeration, one piano.",
        questions: [
                            Exercise(id: "en-listen-office-rumours-q1", kind: "choice", prompt: "How many futures had the office invented?", options: ["Three", "Two", "Five", "One"], answers: ["Three"], explain: "The office had invented three futures in one day."),
                            Exercise(id: "en-listen-office-rumours-q2", kind: "written", prompt: "What did Marco say, according to Diego?", options: [], answers: ["the company was moving to lisbon", "they were moving to lisbon", "the company was moving"], explain: "Marco said the company was moving to Lisbon."),
                            Exercise(id: "en-listen-office-rumours-q3", kind: "choice", prompt: "What was the moving van actually moving?", options: ["A piano", "Office furniture", "Twenty laptops", "Files"], answers: ["A piano"], explain: "Marco's photo showed his neighbour's piano being moved."),
                            Exercise(id: "en-listen-office-rumours-q4", kind: "written", prompt: "What was true about the twenty hires?", options: [], answers: ["over the next five years", "they were real but over five years", "over five years"], explain: "Real — but 'over the next five years', which Lena skipped."),
                            Exercise(id: "en-listen-office-rumours-q5", kind: "choice", prompt: "Which rumour was completely true?", options: ["The new laptops", "Lisbon", "Twenty hires immediately", "None"], answers: ["The new laptops"], explain: "An email had gone out at seven that morning."),
                            Exercise(id: "en-listen-office-rumours-q6", kind: "choice", prompt: "What is the office rule Carmen applies?", options: ["Trace every rumour to its source", "Never believe Lena", "Ignore all emails", "Trust Diego"], answers: ["Trace every rumour to its source"], explain: "Her rule: trace every rumour to its source.")], skills: ["listening:inference", "grammar:reported-speech-basic", "grammar:future-forms", "vocab:work"]),
    ListeningText(id: "en-listen-news-swap", languageID: "en", title: "The news swap", level: "B1", topic: "people", unitID: "en-foundations-telling",
        text: "Café table, two old friends, forty-eight hours of accumulated news. 'You first,' says Ines. 'OK — I got the promotion!' 'No way! Congratulations! When do you start?' 'Monday. And the office is ten minutes from my flat.' 'That IS great news.' Then Ines takes a breath. 'Mine isn't all good. I crashed my bike — I'm fine, but the bike is gone.' 'Oh no, I'm so sorry. Are you OK though? Really?' 'Honestly, yes. Just angry about the bike.' Ines nods, then smiles. 'But there's more: I'm going to Italy in June.' 'Stop it! You're kidding!' 'I'm not. Two weeks, Tuscany, and you're coming with me.'",
        questions: [
                            Exercise(id: "en-listen-news-swap-q1", kind: "choice", prompt: "What is Ines's good news at the end?", options: ["A trip to Italy", "A new bike", "A promotion", "A new job"], answers: ["A trip to Italy"], explain: "Two weeks in Tuscany in June."),
                            Exercise(id: "en-listen-news-swap-q2", kind: "written", prompt: "What is the friend's good news?", options: [], answers: ["a promotion", "she got the promotion", "the promotion"], explain: "She got the promotion — starting Monday."),
                            Exercise(id: "en-listen-news-swap-q3", kind: "choice", prompt: "What happened to the bike?", options: ["It's gone after a crash", "It was stolen", "It needs repair", "She sold it"], answers: ["It's gone after a crash"], explain: "Ines crashed her bike; she's fine, but the bike is gone."),
                            Exercise(id: "en-listen-news-swap-q4", kind: "written", prompt: "What is the friend's reaction to the crash?", options: [], answers: ["im so sorry", "oh no im so sorry"], explain: "'Oh no, I'm so sorry' — then the care question."),
                            Exercise(id: "en-listen-news-swap-q5", kind: "choice", prompt: "How does the friend react to the promotion?", options: ["'No way! Congratulations!'", "'That's awful.'", "'Really? Are you OK?'", "'Good luck.'"], answers: ["'No way! Congratulations!'"], explain: "React + congratulate."),
                            Exercise(id: "en-listen-news-swap-q6", kind: "choice", prompt: "What does Ines invite her friend to do?", options: ["Come to Tuscany", "Buy a new bike", "Visit the new office", "Start in June"], answers: ["Come to Tuscany"], explain: "'You're coming with me.'")], skills: ["vocab:social-expressions", "function:express-opinion", "grammar:future-forms"]),
    ListeningText(id: "en-listen-flat-renovation", languageID: "en", title: "The flat renovation", level: "B1", topic: "home", unitID: "en-foundations-done",
        text: "Flat 4C was finally being renovated, and Marta had one week to organise it. 'I'm having the kitchen repainted on Monday,' she told her brother Leo, 'and I'm getting the plumber to look at the shower on Tuesday.' 'Are you doing any of it yourself?' Leo laughed. 'I'm paying professionals to do it — that's the point,' Marta said. 'I've been putting this off for a year.' The painters finished on Wednesday, but the plumber arrived, set up his tools and disappeared. Marta followed up with three phone calls and an online form, and finally got him to come back on Thursday. 'Did he carry out the full inspection?' Leo asked on Friday. 'The whole flat — pipes, boiler, taps. And tomorrow the cleaners are coming, so I don't have to do anything at all.' 'You mean you don't have to do anything yourself,' Leo said. 'Exactly,' said Marta. 'That's what money is for.'",
        questions: [
                            Exercise(id: "en-listen-flat-renovation-q1", kind: "choice", prompt: "What is Marta doing this week?", options: ["Organising her flat's renovation", "Moving to a new flat", "Working as a plumber", "Helping her brother paint"], answers: ["Organising her flat's renovation"], explain: "Flat 4C was finally being renovated, and Marta had one week to organise it."),
                            Exercise(id: "en-listen-flat-renovation-q2", kind: "written", prompt: "Who is painting the kitchen?", options: [], answers: ["professional painters", "painters", "professionals"], explain: "'I'm having the kitchen repainted' — professionals do it, not Marta."),
                            Exercise(id: "en-listen-flat-renovation-q3", kind: "choice", prompt: "What had Marta been putting off for a year?", options: ["The renovation", "A holiday", "An online form", "The full inspection"], answers: ["The renovation"], explain: "'I've been putting this off for a year' — the whole renovation."),
                            Exercise(id: "en-listen-flat-renovation-q4", kind: "written", prompt: "How did Marta finally get the plumber to come back?", options: [], answers: ["three phone calls and an online form", "three calls and an online form", "by calling three times and filling in an online form"], explain: "She followed up with three phone calls and an online form."),
                            Exercise(id: "en-listen-flat-renovation-q5", kind: "choice", prompt: "What did the full inspection cover?", options: ["Pipes, boiler and taps", "Only the shower", "The kitchen paint", "The windows"], answers: ["Pipes, boiler and taps"], explain: "'The whole flat — pipes, boiler, taps.'"),
                            Exercise(id: "en-listen-flat-renovation-q6", kind: "choice", prompt: "What does Marta mean by 'That's what money is for'?", options: ["Paying others so she doesn't do the work herself", "Saving for the future", "Buying new furniture", "Tip the workers well"], answers: ["Paying others so she doesn't do the work herself"], explain: "She pays professionals so she doesn't have to do anything herself.")], skills: ["listening:inference", "grammar:causative-have", "grammar:phrasal-verbs", "vocab:work"]),
    ListeningText(id: "en-listen-wrong-platform", languageID: "en", title: "The wrong platform", level: "B1", topic: "travel", unitID: "en-foundations-problems",
        text: "'You look exhausted,' said Tom. 'I am,' said Ana. 'I wish I had checked the platform board. I took the 6:12 to the north station instead of the south one.' 'No! So you missed the warm-up.' 'If I had looked up, I would have seen the notice — the southbound train was leaving from platform 2, not 9. I only realised when we crossed the river.' 'What did you do then?' 'I got off at the next stop and took a taxi. If the traffic had been normal, I'd have arrived before eight. But there was a football match, so I walked in at half past nine, hot and furious.' 'At least you made it for the main act.' 'True. And honestly, if I hadn't taken the wrong train, I wouldn't have seen the river at sunset. If only every mistake came with a view.' Tom laughed. 'So the lesson is: check the board, but keep a little curiosity.'",
        questions: [
                            Exercise(id: "en-listen-wrong-platform-q1", kind: "choice", prompt: "What went wrong for Ana?", options: ["She took the wrong train", "She missed the last train", "She lost her ticket", "The concert was cancelled"], answers: ["She took the wrong train"], explain: "She took the 6:12 to the north station instead of the south one."),
                            Exercise(id: "en-listen-wrong-platform-q2", kind: "written", prompt: "What does Ana wish she had checked?", options: [], answers: ["the platform board", "the board", "the platform display"], explain: "'I wish I had checked the platform board.'"),
                            Exercise(id: "en-listen-wrong-platform-q3", kind: "choice", prompt: "Why was she late even after taking a taxi?", options: ["A football match made the traffic terrible", "The taxi broke down", "The driver didn't know the venue", "It started to rain heavily"], answers: ["A football match made the traffic terrible"], explain: "There was a football match, so the taxi didn't help enough."),
                            Exercise(id: "en-listen-wrong-platform-q4", kind: "choice", prompt: "When did Ana finally arrive?", options: ["At half past nine", "Before eight", "At 6:12", "At midnight"], answers: ["At half past nine"], explain: "She walked in at half past nine, hot and furious."),
                            Exercise(id: "en-listen-wrong-platform-q5", kind: "written", prompt: "What good thing came out of the mistake?", options: [], answers: ["she saw the river at sunset", "the river at sunset", "seeing the river at sunset"], explain: "'If I hadn't taken the wrong train, I wouldn't have seen the river at sunset.'"),
                            Exercise(id: "en-listen-wrong-platform-q6", kind: "choice", prompt: "What lesson does Tom draw?", options: ["Check the board, but stay curious", "Never take taxis", "Always arrive an hour early", "Concerts aren't worth it"], answers: ["Check the board, but stay curious"], explain: "'Check the board, but keep a little curiosity.'")], skills: ["listening:inference", "grammar:wish-clauses", "grammar:third-conditional", "vocab:feelings"]),
    ListeningText(id: "en-listen-grandpas-garden", languageID: "en", title: "Grandpa's garden", level: "A2", topic: "family",
        text: "When Pablo was a child, he spent every summer at his grandpa's house. The garden was enormous, full of tomato plants and lemon trees. Every morning they watered the plants together and every afternoon they played cards under the big tree. His grandpa didn't talk much, but he laughed easily. Pablo didn't like vegetables then. Now he grows his own tomatoes and understands why his grandpa smiled at them.",
        questions: [
                            Exercise(id: "en-listen-grandpas-garden-q1", kind: "choice", prompt: "What was in grandpa's garden?", options: ["Tomato plants and lemon trees", "Only flowers", "Vegetable soup", "Apple trees"], answers: ["Tomato plants and lemon trees"], explain: "It was full of tomato plants and lemon trees."),
                            Exercise(id: "en-listen-grandpas-garden-q2", kind: "written", prompt: "What did they do every afternoon?", options: [], answers: ["they played cards", "played cards under the big tree", "they played cards under the big tree"], explain: "They played cards under the big tree."),
                            Exercise(id: "en-listen-grandpas-garden-q3", kind: "choice", prompt: "What was grandpa like?", options: ["Quiet but quick to laugh", "Loud and serious", "He never smiled", "He talked all day"], answers: ["Quiet but quick to laugh"], explain: "He didn't talk much, but he laughed easily."),
                            Exercise(id: "en-listen-grandpas-garden-q4", kind: "written", prompt: "What does Pablo grow now?", options: [], answers: ["tomatoes", "his own tomatoes", "he grows tomatoes"], explain: "Now he grows his own tomatoes."),
                            Exercise(id: "en-listen-grandpas-garden-q5", kind: "choice", prompt: "What did they do every morning?", options: ["They watered the plants", "They played cards", "They cooked lunch", "They went shopping"], answers: ["They watered the plants"], explain: "Every morning they watered the plants together."),
                            Exercise(id: "en-listen-grandpas-garden-q6", kind: "written", prompt: "What didn't Pablo like as a child?", options: [], answers: ["vegetables", "he didn't like vegetables"], explain: "Pablo didn't like vegetables then.")], skills: ["listening:inference", "grammar:past-simple-irregular", "vocab:family"]),
    ListeningText(id: "en-listen-lost-jacket", languageID: "en", title: "The lost jacket", level: "A2", topic: "clothes",
        text: "Last week Daniel lost his favourite jacket. He left it on the number twelve bus on Friday evening. He called the lost property office on Monday, but nobody had seen it. Two days later a neighbour knocked on his door and gave him the jacket. She found it on the bus seat with his name and address inside the pocket. Daniel was amazed and invited her in for a cup of tea.",
        questions: [
                            Exercise(id: "en-listen-lost-jacket-q1", kind: "written", prompt: "Where did Daniel leave his jacket?", options: [], answers: ["on the number twelve bus", "on the bus", "on the 12 bus"], explain: "He left it on the number twelve bus."),
                            Exercise(id: "en-listen-lost-jacket-q2", kind: "choice", prompt: "When did he call the lost property office?", options: ["On Monday", "On Friday", "Two days later", "The same evening"], answers: ["On Monday"], explain: "He called on Monday, but nobody had seen it."),
                            Exercise(id: "en-listen-lost-jacket-q3", kind: "choice", prompt: "Who found the jacket?", options: ["A neighbour", "A bus driver", "His mother", "A colleague"], answers: ["A neighbour"], explain: "A neighbour knocked on his door and gave him the jacket."),
                            Exercise(id: "en-listen-lost-jacket-q4", kind: "written", prompt: "How did the neighbour know it was Daniel's jacket?", options: [], answers: ["his name and address were inside the pocket", "there was a name and address in the pocket", "his name and address in the pocket"], explain: "His name and address were inside the pocket."),
                            Exercise(id: "en-listen-lost-jacket-q5", kind: "choice", prompt: "How did Daniel feel when he got the jacket back?", options: ["Amazed", "Angry", "Sad", "Sleepy"], answers: ["Amazed"], explain: "Daniel was amazed."),
                            Exercise(id: "en-listen-lost-jacket-q6", kind: "written", prompt: "What did he invite the neighbour for?", options: [], answers: ["a cup of tea", "cup of tea", "tea"], explain: "He invited her in for a cup of tea.")], skills: ["listening:detail", "grammar:past-simple-regular", "vocab:transport"]),
    ListeningText(id: "en-listen-night-train", languageID: "en", title: "The night train", level: "A2", topic: "travel",
        text: "Ella took the night train to the coast because the morning tickets were too expensive. She shared a small compartment with a woman who worked as a nurse and a student who talked for hours about football. Ella couldn't sleep, but she didn't mind. The train arrived at five in the morning, before the sun came up. She walked out of the station, smelled the sea and knew the trip was worth it.",
        questions: [
                            Exercise(id: "en-listen-night-train-q1", kind: "written", prompt: "Why did Ella take the night train?", options: [], answers: ["the morning tickets were too expensive", "because the morning tickets were too expensive", "morning tickets were too expensive"], explain: "The morning tickets were too expensive."),
                            Exercise(id: "en-listen-night-train-q2", kind: "choice", prompt: "What did the student talk about?", options: ["Football", "Nursing", "The coast", "Music"], answers: ["Football"], explain: "The student talked for hours about football."),
                            Exercise(id: "en-listen-night-train-q3", kind: "choice", prompt: "When did the train arrive?", options: ["At five in the morning", "At five in the evening", "At sunrise", "At midnight"], answers: ["At five in the morning"], explain: "It arrived at five, before the sun came up."),
                            Exercise(id: "en-listen-night-train-q4", kind: "written", prompt: "How did Ella know the trip was worth it when she arrived?", options: [], answers: ["she smelled the sea", "she smelled the sea and knew the trip was worth it", "because she smelled the sea"], explain: "She walked out and smelled the sea."),
                            Exercise(id: "en-listen-night-train-q5", kind: "choice", prompt: "What was the woman in the compartment?", options: ["A nurse", "A teacher", "A doctor", "A driver"], answers: ["A nurse"], explain: "She worked as a nurse."),
                            Exercise(id: "en-listen-night-train-q6", kind: "choice", prompt: "Did Ella sleep on the train?", options: ["No, but she didn't mind", "Yes, all night", "Yes, for two hours", "She doesn't say"], answers: ["No, but she didn't mind"], explain: "She couldn't sleep, but she didn't mind.")], skills: ["listening:inference", "grammar:past-simple-irregular", "vocab:travel"]),
    ListeningText(id: "en-listen-doctor-call", languageID: "en", title: "The doctor's phone call", level: "A2", topic: "health", unitID: "en-foundations-health",
        text: "The receptionist answers on the second ring. 'Good morning, Riverside Clinic.' 'Hello, I'd like to make an appointment. It's not an emergency, but I've had back pain for two weeks and it's getting worse.' The receptionist types. 'Dr Lee has a slot today at 16:40. Is that OK?' 'Perfect.' 'Just so I know you've got it: today, 16:40, Dr Lee. Bring your ID and your medication list. And drink water — it helps everything.' The caller laughs. 'Thank you very much.' 'See you this afternoon. Take care!'",
        questions: [
                            Exercise(id: "en-listen-doctor-call-q1", kind: "choice", prompt: "What does the caller want?", options: ["To make an appointment", "A prescription now", "To cancel", "To speak to Dr Lee"], answers: ["To make an appointment"], explain: "I'd like to make an appointment."),
                            Exercise(id: "en-listen-doctor-call-q2", kind: "written", prompt: "How long has the back pain lasted?", options: [], answers: ["two weeks", "for two weeks"], explain: "For two weeks — and getting worse."),
                            Exercise(id: "en-listen-doctor-call-q3", kind: "choice", prompt: "When is the appointment?", options: ["Today at 16:40", "Tomorrow morning", "This evening", "Next week"], answers: ["Today at 16:40"], explain: "Dr Lee has a slot today at 16:40."),
                            Exercise(id: "en-listen-doctor-call-q4", kind: "written", prompt: "What should the caller bring?", options: [], answers: ["id and medication list", "her id and medication list", "id and a medication list"], explain: "ID and the medication list."),
                            Exercise(id: "en-listen-doctor-call-q5", kind: "choice", prompt: "What does the receptionist recommend for everything?", options: ["Drinking water", "Resting", "Painkillers", "Walking"], answers: ["Drinking water"], explain: "Drink water — it helps everything (she's joking, half)."),
                            Exercise(id: "en-listen-doctor-call-q6", kind: "written", prompt: "How does the receptionist close the call?", options: [], answers: ["see you this afternoon take care", "take care"], explain: "'See you this afternoon. Take care!'")], skills: ["function:talk-about-health", "grammar:present-perfect", "vocab:health"]),
    ListeningText(id: "en-listen-four-day-week", languageID: "en", title: "The four-day week", level: "B2", topic: "work", unitID: "en-foundations-viewpoints",
        text: "At the town-hall debate, both speakers agreed on the problem — burnout — and disagreed on nearly everything else. The union representative argued that a four-day week was the obvious fix: trials in Iceland, she said, had been judged a success by almost every measure, and productivity had been maintained with happier staff. The chamber-of-commerce speaker pushed back. Those trials, he replied, were small and self-selected; forcing the change on small businesses could raise costs and reduce service hours. An audience member proposed the middle path nobody had mentioned: keep five contract days but cut meetings by half. Both speakers, perhaps unexpectedly, said they could live with that — which is usually the sign of a good compromise.",
        questions: [
                            Exercise(id: "en-listen-four-day-week-q1", kind: "choice", prompt: "What did both speakers agree on?", options: ["The problem: burnout", "The solution", "The costs", "Nothing"], answers: ["The problem: burnout"], explain: "They agreed on the problem and disagreed on nearly everything else."),
                            Exercise(id: "en-listen-four-day-week-q2", kind: "written", prompt: "Which country's trials did the union representative mention?", options: [], answers: ["iceland", "trials in iceland"], explain: "Trials in Iceland had been judged a success."),
                            Exercise(id: "en-listen-four-day-week-q3", kind: "choice", prompt: "What was the counter-argument?", options: ["The trials were small and self-selected", "Workers don't want it", "It is illegal", "Productivity would double"], answers: ["The trials were small and self-selected"], explain: "He replied the trials were small and self-selected."),
                            Exercise(id: "en-listen-four-day-week-q4", kind: "written", prompt: "What middle path did an audience member propose?", options: [], answers: ["keep five days but cut meetings by half", "cut meetings by half", "five days with half the meetings"], explain: "Keep five contract days but cut meetings by half."),
                            Exercise(id: "en-listen-four-day-week-q5", kind: "choice", prompt: "How did the speakers react to the compromise?", options: ["They said they could live with it", "They rejected it", "They laughed", "They left"], answers: ["They said they could live with it"], explain: "Both said they could live with it — a good compromise."),
                            Exercise(id: "en-listen-four-day-week-q6", kind: "choice", prompt: "What does the passive voice of the report emphasise?", options: ["The trials and their judgement, not who judged them", "The speaker's anger", "The costs", "The audience"], answers: ["The trials and their judgement, not who judged them"], explain: "Had been judged a success — the doer doesn't matter.")], skills: ["listening:inference", "grammar:connectors", "function:express-opinion", "grammar:passive-intro"]),
    ListeningText(id: "en-listen-negotiation-standoff", languageID: "en", title: "The salary standoff", level: "B2", topic: "work", unitID: "en-foundations-viewpoints",
        text: "'Let's start with the number you want, and I'll tell you honestly if it's possible,' said the manager. Nadia appreciated the directness. 'Forty-eight thousand — that's the market rate for this role, and I can show you three listings that prove it.' The manager didn't flinch. 'I believe you. If I approved that today, I'd have to rewrite three other salaries, and I don't have the budget for that this quarter.' 'What if we phased it?' Nadia offered. 'Forty-four now, a review in March with clear targets, and forty-eight if I hit them.' The manager was quiet for a moment. 'If you put those targets in writing and hit them, I'll defend that raise upstairs. Shall we say we have a deal?' Nadia smiled. 'We have a deal — in writing.'",
        questions: [
                            Exercise(id: "en-listen-negotiation-standoff-q1", kind: "written", prompt: "What salary did Nadia ask for?", options: [], answers: ["forty-eight thousand", "48.000", "48000", "forty-eight thousand euros"], explain: "Forty-eight thousand — the market rate, she said."),
                            Exercise(id: "en-listen-negotiation-standoff-q2", kind: "choice", prompt: "Why couldn't the manager approve it today?", options: ["He'd have to rewrite three other salaries", "She didn't deserve it", "It's illegal", "The company is closing"], answers: ["He'd have to rewrite three other salaries"], explain: "Approving it would force three rewrites — and there's no budget this quarter."),
                            Exercise(id: "en-listen-negotiation-standoff-q3", kind: "written", prompt: "What was Nadia's phased proposal?", options: [], answers: ["44 now and 48 in march with targets", "forty-four now a review in march and forty-eight if she hit targets", "44 now 48 later"], explain: "Forty-four now, review in March, forty-eight if she hits the targets."),
                            Exercise(id: "en-listen-negotiation-standoff-q4", kind: "choice", prompt: "What condition did the manager add?", options: ["The targets in writing", "A six-month wait", "No review at all", "A different role"], answers: ["The targets in writing"], explain: "If the targets are in writing and hit, he'll defend the raise."),
                            Exercise(id: "en-listen-negotiation-standoff-q5", kind: "choice", prompt: "Which negotiation move is 'What if we phased it?'", options: ["Offering a middle path", "Rejecting the deal", "Buying time", "Closing"], answers: ["Offering a middle path"], explain: "What if… proposes the middle path between the two positions."),
                            Exercise(id: "en-listen-negotiation-standoff-q6", kind: "choice", prompt: "How did Nadia make sure the deal would hold?", options: ["She asked for it in writing", "She shook hands", "She lowered her ask", "She threatened to leave"], answers: ["She asked for it in writing"], explain: "'We have a deal — in writing.'")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:first-conditional"]),
    ListeningText(id: "en-listen-news-desk", languageID: "en", title: "At the news desk", level: "B2", topic: "work", unitID: "en-foundations-media",
        text: "The 18:00 bulletin is being assembled at the news desk. The editor reads the running order aloud: 'Lead story: the city council has announced a new flood-prevention plan — measures are expected to cost four million euros, according to documents seen by our reporters. Second: the bridge is believed to be safe after emergency inspections; it is thought that traffic will return to normal by Monday. And the sports close: the match was postponed because the pitch was flooded — the third postponement this season.' A young reporter raises her hand. 'Should we say who saw the documents?' The editor shakes his head. 'We protect sources. The documents exist; the audience can decide what they mean.'",
        questions: [
                            Exercise(id: "en-listen-news-desk-q1", kind: "written", prompt: "What has the city council announced?", options: [], answers: ["a new flood-prevention plan", "a flood-prevention plan"], explain: "A new flood-prevention plan."),
                            Exercise(id: "en-listen-news-desk-q2", kind: "choice", prompt: "How is the cost being reported?", options: ["According to documents seen by reporters", "The council said it", "It is a rumour", "It is not mentioned"], answers: ["According to documents seen by reporters"], explain: "According to documents seen by our reporters."),
                            Exercise(id: "en-listen-news-desk-q3", kind: "written", prompt: "What is believed about the bridge?", options: [], answers: ["that it is safe", "it is believed to be safe", "it is safe"], explain: "It is believed to be safe after inspections."),
                            Exercise(id: "en-listen-news-desk-q4", kind: "choice", prompt: "Why was the match postponed?", options: ["The pitch was flooded", "The teams were tired", "The bridge closed", "It wasn't"], answers: ["The pitch was flooded"], explain: "Postponed because the pitch was flooded."),
                            Exercise(id: "en-listen-news-desk-q5", kind: "choice", prompt: "Why does the editor protect the source?", options: ["The audience can decide what the documents mean", "The documents are fake", "It is illegal", "He doesn't know the source"], answers: ["The audience can decide what the documents mean"], explain: "The documents exist; the audience decides."),
                            Exercise(id: "en-listen-news-desk-q6", kind: "written", prompt: "How many postponements has the season had?", options: [], answers: ["three", "3"], explain: "The third postponement this season.")], skills: ["grammar:passive-intro", "grammar:present-perfect", "function:talk-about-work"]),
    ListeningText(id: "en-listen-bridge-news", languageID: "en", title: "The morning news: bridge reopened", level: "B2", topic: "town", unitID: "en-foundations-viewpoints",
        text: "Good morning. The Millbrook bridge, which was closed in March after cracks were discovered in two support beams, was reopened to traffic shortly after six this morning — three weeks ahead of schedule. Repair work, which was carried out by a local firm, was funded jointly by the council and the regional government, though the exact split has not been disclosed. Drivers are being asked to observe the fifty-kilometre limit for the first fortnight while the surface settles. Bus route nine, which was diverted via the ring road, returns to its original route today. And in a surprise twist, the ferry that was launched as a temporary replacement — will keep running until September, after commuters, apparently, fell in love with it.",
        questions: [
                            Exercise(id: "en-listen-bridge-news-q1", kind: "written", prompt: "When was the bridge reopened?", options: [], answers: ["shortly after six this morning", "after six this morning", "this morning at six"], explain: "Reopened shortly after six this morning."),
                            Exercise(id: "en-listen-bridge-news-q2", kind: "choice", prompt: "Why had it been closed?", options: ["Cracks were found in support beams", "A flood", "It was repainted", "An accident"], answers: ["Cracks were found in support beams"], explain: "Closed in March after cracks were discovered in two beams."),
                            Exercise(id: "en-listen-bridge-news-q3", kind: "choice", prompt: "Who carried out the repairs?", options: ["A local firm", "The council itself", "The regional government", "It doesn't say"], answers: ["A local firm"], explain: "Carried out by a local firm — the passive keeps focus on the work."),
                            Exercise(id: "en-listen-bridge-news-q4", kind: "written", prompt: "What are drivers asked to do for the first fortnight?", options: [], answers: ["observe the fifty kilometre limit", "observe the 50 km limit", "drive at fifty"], explain: "Observe the 50 km/h limit while the surface settles."),
                            Exercise(id: "en-listen-bridge-news-q5", kind: "choice", prompt: "What happens to the temporary ferry?", options: ["It keeps running until September", "It stops today", "It was cancelled", "It becomes permanent"], answers: ["It keeps running until September"], explain: "Commuters apparently fell in love with it."),
                            Exercise(id: "en-listen-bridge-news-q6", kind: "choice", prompt: "Why does this report rely so heavily on the passive?", options: ["The doers matter less than the facts", "The doers are famous", "It is an error", "To hide the costs"], answers: ["The doers matter less than the facts"], explain: "News reports the event: was closed, was reopened, was carried out.")], skills: ["listening:connected-speech", "listening:detail", "grammar:passive-intro", "grammar:relative-clauses"]),
    ListeningText(id: "en-listen-podcast-habits", languageID: "en", title: "Podcast: the habits episode", level: "B2", topic: "free time", unitID: "en-foundations-viewpoints",
        text: "HOST: Welcome back. Today, habits — the ones that stick and the ones that don't. With me, Dr Amaia Ruiz, who has spent a decade researching behaviour. Amaia, quick version: why do most New Year's resolutions fail? DR RUIZ: Because they're ambitions, not systems. People say 'I'll get fit' — that's a wish. A system is 'I run on Tuesdays with Sam.' HOST: So the friend is part of the system? DR RUIZ: The friend is the system. Accountability beats motivation roughly nine times out of ten in our data. HOST: Nine out of ten! And the two-minute rule everyone quotes? DR RUIZ: Useful, slightly overrated. Starting small matters less than starting at the same time. The clock does the remembering for you. HOST: One habit you'd recommend to everyone? DR RUIZ: A ten-minute walk after lunch. Boring, free, and — according to everything we know — the closest thing to a miracle we've measured.",
        questions: [
                            Exercise(id: "en-listen-podcast-habits-q1", kind: "choice", prompt: "Why do most resolutions fail, according to Dr Ruiz?", options: ["They're ambitions, not systems", "January is too cold", "People are lazy", "Gyms are expensive"], answers: ["They're ambitions, not systems"], explain: "'I'll get fit' is a wish; a system is 'I run on Tuesdays with Sam.'"),
                            Exercise(id: "en-listen-podcast-habits-q2", kind: "written", prompt: "What beats motivation in her data?", options: [], answers: ["accountability", "the friend", "accountability beats motivation"], explain: "Accountability beats motivation nine times out of ten."),
                            Exercise(id: "en-listen-podcast-habits-q3", kind: "choice", prompt: "What does she think of the two-minute rule?", options: ["Useful, slightly overrated", "Completely wrong", "The best idea", "Dangerous"], answers: ["Useful, slightly overrated"], explain: "Starting small matters less than starting at the same time."),
                            Exercise(id: "en-listen-podcast-habits-q4", kind: "written", prompt: "What does the clock do, according to Dr Ruiz?", options: [], answers: ["the remembering for you", "does the remembering", "remembers for you"], explain: "The clock does the remembering for you."),
                            Exercise(id: "en-listen-podcast-habits-q5", kind: "choice", prompt: "What habit does she recommend to everyone?", options: ["A ten-minute walk after lunch", "Running on Tuesdays", "Going to the gym", "Journaling"], answers: ["A ten-minute walk after lunch"], explain: "Boring, free, and the closest thing to a miracle they've measured."),
                            Exercise(id: "en-listen-podcast-habits-q6", kind: "choice", prompt: "What makes this sound like a podcast rather than an essay?", options: ["The host's interruptions and quick exchanges", "The long sentences", "The passive voice", "The statistics only"], answers: ["The host's interruptions and quick exchanges"], explain: "Turn-taking, reactions and short questions are the podcast register.")], skills: ["listening:connected-speech", "listening:inference", "grammar:first-conditional", "function:talk-about-routines"]),
    ListeningText(id: "en-listen-keynote", languageID: "en", title: "The keynote", level: "C1", topic: "work", unitID: "en-foundations-nuance",
        text: "Good afternoon. I'd like to begin with a confession: everything I believed about attention five years ago has aged badly. The research I'll present today — conducted across four countries, with the caveats that such breadth demands — suggests something uncomfortable: our capacity for sustained focus hasn't declined so much as our tolerance for discomfort has collapsed. Now, I appreciate that's a strong claim. The evidence runs like this. In conditions where devices were removed — not silenced, removed — reading comprehension recovered to pre-smartphone baselines within nine days. What participants reported, however, was not relief but a kind of withdrawal, which raises the question I'd like to leave you with: if a tool has rewritten our baseline for what feels bearable, is it a tool any more? I'll let you sit with that. Thank you.",
        questions: [
                            Exercise(id: "en-listen-keynote-q1", kind: "choice", prompt: "How does the speaker open the keynote?", options: ["With a confession", "With a joke", "With data", "With thanks"], answers: ["With a confession"], explain: "Everything I believed five years ago has aged badly — a confession opener."),
                            Exercise(id: "en-listen-keynote-q2", kind: "written", prompt: "What has collapsed, according to the research?", options: [], answers: ["Our tolerance for discomfort"], explain: "Not our focus — our tolerance for discomfort has collapsed."),
                            Exercise(id: "en-listen-keynote-q3", kind: "choice", prompt: "How does she flag the strength of her claim?", options: ["Now, I appreciate that's a strong claim", "Obviously", "Everyone knows", "She doesn't"], answers: ["Now, I appreciate that's a strong claim"], explain: "Naming the claim's strength is the C1 move: hedge before you hit."),
                            Exercise(id: "en-listen-keynote-q4", kind: "written", prompt: "What recovered within nine days when devices were removed?", options: [], answers: ["reading comprehension", "comprehension recovered to pre-smartphone baselines", "reading"], explain: "Reading comprehension recovered to pre-smartphone baselines."),
                            Exercise(id: "en-listen-keynote-q5", kind: "choice", prompt: "What did participants report feeling?", options: ["A kind of withdrawal", "Relief", "Nothing", "Happiness"], answers: ["A kind of withdrawal"], explain: "Not relief — a kind of withdrawal."),
                            Exercise(id: "en-listen-keynote-q6", kind: "choice", prompt: "What is the closing question really about?", options: ["Whether a tool that rewrites our baseline is still a tool", "Device batteries", "Reading speed", "Four countries"], answers: ["Whether a tool that rewrites our baseline is still a tool"], explain: "She leaves the redefinition question with the audience.")], skills: ["listening:connected-speech", "listening:inference", "function:express-opinion", "grammar:connectors"]),
    ListeningText(id: "en-listen-radio-debate", languageID: "en", title: "The radio debate", level: "C1", topic: "work", unitID: "en-foundations-nuance",
        text: "Radio phone-in, two guests, one question: should cities ban cars from their centres? The urbanist goes first: 'The evidence tends to support it. Air quality improves, shops report more foot traffic. I wouldn't say it solves everything — admittedly, delivery logistics need rethinking — but the direction is clear.' The taxi representative is unimpressed: 'That's a very comfortable position for someone with a parking space. It is often claimed that everyone supports these bans. My members do not.' The host steps in: 'Let me bring you both together. If — and at this stage it's an if — the city invested in night deliveries, would that change your position?' A long pause. 'It would certainly change mine,' the taxi man admits. The urbanist laughs: 'Then we have something to build on.'",
        questions: [
                            Exercise(id: "en-listen-radio-debate-q1", kind: "choice", prompt: "What is the urbanist's position?", options: ["The evidence tends to support the ban", "The ban solves everything", "The ban is tyranny", "She has no position"], answers: ["The evidence tends to support the ban"], explain: "Hedged: tends to support, not solves everything."),
                            Exercise(id: "en-listen-radio-debate-q2", kind: "written", prompt: "What does the urbanist concede?", options: [], answers: ["delivery logistics need rethinking", "deliveries are a problem"], explain: "Admittedly, delivery logistics need rethinking."),
                            Exercise(id: "en-listen-radio-debate-q3", kind: "choice", prompt: "What does 'It is often claimed that everyone supports these bans' imply?", options: ["The claim is exaggerated", "Everyone supports them", "It is a fact", "Nobody supports them"], answers: ["The claim is exaggerated"], explain: "The passive + often claims distance the speaker from the claim."),
                            Exercise(id: "en-listen-radio-debate-q4", kind: "written", prompt: "What is the host's conditional question?", options: [], answers: ["if the city invested in night deliveries", "whether the city invested in night deliveries"], explain: "If the city invested in night deliveries, would positions change?"),
                            Exercise(id: "en-listen-radio-debate-q5", kind: "choice", prompt: "How does the taxi man respond at the end?", options: ["It would certainly change mine", "Never", "He leaves", "He agrees fully"], answers: ["It would certainly change mine"], explain: "A conditional concession — something to build on."),
                            Exercise(id: "en-listen-radio-debate-q6", kind: "choice", prompt: "What does the urbanist's laugh suggest?", options: ["A starting point for agreement", "She is mocking him", "She disagrees", "She is nervous"], answers: ["A starting point for agreement"], explain: "'Then we have something to build on.'")], skills: ["grammar:second-conditional", "function:negotiate", "grammar:connectors", "function:express-opinion"], exposureSkills: ["grammar:first-conditional"]),
    ListeningText(id: "en-listen-viewpoint-interview", languageID: "en", title: "The viewpoint interview", level: "B2", topic: "work", unitID: "en-foundations-viewpoints",
        text: "Interviewer: 'You've argued that the five-day office week is obsolete. But many CEOs disagree.' Marta: 'They do, and I understand why. Commercial leases are expensive. Middle managers built careers on supervision. But the data — and I'd point to the Stanford study of sixteen thousand workers — shows remote workers are 13% more productive.' Interviewer: 'What about young employees who need mentorship?' Marta: 'Fair point. My answer is structured onboarding, not forced presence. You can mentor on Tuesday and Thursday without watching someone's desk on Monday.' Interviewer: 'If you were CEO of a Fortune 500, what would you do first?' Marta: 'I'd scrap the office policy entirely and rebuild it around outcomes, not hours.'",
        questions: [
                            Exercise(id: "en-listen-viewpoint-interview-q1", kind: "choice", prompt: "What does Marta argue?", options: ["The five-day office week is obsolete", "CEOs are always right", "Remote work is perfect", "Ban all offices"], answers: ["The five-day office week is obsolete"], explain: "She argues the five-day office week is obsolete."),
                            Exercise(id: "en-listen-viewpoint-interview-q2", kind: "written", prompt: "What study does Marta cite?", options: [], answers: ["the stanford study", "stanford"], explain: "The Stanford study of 16,000 workers."),
                            Exercise(id: "en-listen-viewpoint-interview-q3", kind: "choice", prompt: "What does Marta propose instead of forced presence?", options: ["Structured onboarding", "More offices", "Higher salaries", "Fewer meetings"], answers: ["Structured onboarding"], explain: "Her answer is structured onboarding, not forced presence."),
                            Exercise(id: "en-listen-viewpoint-interview-q4", kind: "written", prompt: "What would Marta do first as CEO?", options: [], answers: ["scrap the office policy"], explain: "Scrap the office policy and rebuild around outcomes."),
                            Exercise(id: "en-listen-viewpoint-interview-q5", kind: "choice", prompt: "What does Marta concede about young employees?", options: ["They need mentorship", "They are less productive", "They prefer offices", "They need more money"], answers: ["They need mentorship"], explain: "Fair point: young employees need mentorship."),
                            Exercise(id: "en-listen-viewpoint-interview-q6", kind: "choice", prompt: "How does Marta handle the CEO hypothetical?", options: ["She gives a direct answer", "She refuses", "She laughs", "She changes topic"], answers: ["She gives a direct answer"], explain: "If I were CEO, I'd scrap the office policy — direct and structured.")], skills: ["grammar:second-conditional", "function:express-opinion", "grammar:connectors", "vocab:work"], exposureSkills: ["grammar:passive-intro"]),
    ListeningText(id: "en-listen-hospital-stories", languageID: "en", title: "Stories from the ward", level: "B2", topic: "health", unitID: "en-foundations-viewpoints",
        text: "Nurse Rosa has worked the night shift for twelve years, and she's collected stories the way other people collect stamps. There was the man who sang opera to his IV drip — he said it was Puccini or nothing. And the woman who refused to sleep until she'd taught every nurse on the ward to make paella. 'It took three nights,' Rosa remembers. 'But the paella was excellent.' The hardest stories, she says, are the quiet ones — the patients who ask the same question over and over because they're more afraid of the answer than the illness. 'You answer it every time. That's the job. You answer, and you stay.'",
        questions: [
                            Exercise(id: "en-listen-hospital-stories-q1", kind: "choice", prompt: "How long has Rosa worked nights?", options: ["Twelve years", "Two years", "Twenty years", "Ten years"], answers: ["Twelve years"], explain: "Twelve years on the night shift."),
                            Exercise(id: "en-listen-hospital-stories-q2", kind: "written", prompt: "What did the opera man sing to his IV drip?", options: [], answers: ["puccini", "opera"], explain: "Puccini — or nothing."),
                            Exercise(id: "en-listen-hospital-stories-q3", kind: "choice", prompt: "How many nights did the paella lesson take?", options: ["Three", "One", "Two", "Five"], answers: ["Three"], explain: "Three nights — but the paella was excellent."),
                            Exercise(id: "en-listen-hospital-stories-q4", kind: "choice", prompt: "What are the hardest stories?", options: ["The quiet ones — patients afraid of the answer", "The loud ones", "The opera singers", "The long shifts"], answers: ["The quiet ones — patients afraid of the answer"], explain: "Patients afraid of the answer than the illness."),
                            Exercise(id: "en-listen-hospital-stories-q5", kind: "written", prompt: "What is the job, according to Rosa?", options: [], answers: ["answer and stay"], explain: "You answer, and you stay."),
                            Exercise(id: "en-listen-hospital-stories-q6", kind: "choice", prompt: "What does Rosa collect?", options: ["Stories", "Stamps", "IV drips", "Recipes"], answers: ["Stories"], explain: "Stories, like others collect stamps.")], skills: ["listening:inference", "grammar:past-continuous", "function:talk-about-health", "vocab:health"], exposureSkills: ["grammar:used-to"]),
    ListeningText(id: "en-listen-pitch-night", languageID: "en", title: "After the pitch night", level: "B2", topic: "work", unitID: "en-foundations-innovation",
        text: "'Did you catch the pitch night?' asked Priya. 'Three start-ups, ninety seconds each.' 'I saw the first two,' said Jonas. 'The one everyone is talking about is Corner — it is believed to have signed two hospital chains already.' 'That rumour again. It's said that the founders met at a robotics lab, but nobody can confirm it, and no deal has been officially announced.' 'Even so, they're bound to attract offers after that demo. A pill dispenser that calls the pharmacy itself? That's likely to reshape the whole care market.' 'Likely, perhaps — but the third presenter worried me. If the numbers can't be checked, the valuation can't be trusted either. It is widely assumed that they doubled their users last year, but their chart had no scale on it.' 'So who are you backing?' 'Corner, cautiously. The technology works and the team is credible. As for the rest, it is expected that the truth will come out in the due diligence.'",
        questions: [
                            Exercise(id: "en-listen-pitch-night-q1", kind: "choice", prompt: "What event are Priya and Jonas discussing?", options: ["A start-up pitch night", "A hospital conference", "A robotics competition", "A product recall"], answers: ["A start-up pitch night"], explain: "Three start-ups, ninety seconds each — the pitch night."),
                            Exercise(id: "en-listen-pitch-night-q2", kind: "written", prompt: "What is Corner believed to have signed?", options: [], answers: ["two hospital chains", "deals with two hospital chains", "hospital chains"], explain: "'It is believed to have signed two hospital chains already.'"),
                            Exercise(id: "en-listen-pitch-night-q3", kind: "choice", prompt: "What has not been officially announced?", options: ["The deal", "The demo", "Where the founders met", "The user numbers"], answers: ["The deal"], explain: "Nobody can confirm the rumour; no deal has been officially announced."),
                            Exercise(id: "en-listen-pitch-night-q4", kind: "choice", prompt: "Why does Priya distrust the third presenter?", options: ["The chart had no scale, so the numbers can't be checked", "The presenter spoke too fast", "The product didn't work", "The team is too young"], answers: ["The chart had no scale, so the numbers can't be checked"], explain: "If the numbers can't be checked, the valuation can't be trusted either."),
                            Exercise(id: "en-listen-pitch-night-q5", kind: "written", prompt: "What does the pill dispenser do, according to Jonas?", options: [], answers: ["it calls the pharmacy itself", "calls the pharmacy itself", "calls the pharmacy"], explain: "'A pill dispenser that calls the pharmacy itself.'"),
                            Exercise(id: "en-listen-pitch-night-q6", kind: "choice", prompt: "What does 'they're bound to attract offers' express?", options: ["A high degree of certainty", "A rumour", "A doubt about the demo", "A warning against investing"], answers: ["A high degree of certainty"], explain: "Bound to = Jonas considers it almost certain.")], skills: ["listening:inference", "grammar:passive-reporting", "grammar:speculation", "vocab:work"]),
    ListeningText(id: "en-listen-podcast-nuance", languageID: "en", title: "The nuance episode", level: "C1", topic: "work", unitID: "en-foundations-nuance",
        text: "HOST: You've written that 'nuance is the first casualty of urgency.' That's a great line — but what does it mean? AUTHOR: It means that when we're in a hurry, we flatten complex positions into for-and-against. And most interesting problems are neither. HOST: Give me an example. AUTHOR: Take remote work. The productive question isn't 'is it good or bad?' — it's 'which parts of which jobs benefit from which conditions?' That's a harder question, and the answer is boring: it depends. HOST: So nuance is just… saying it depends? AUTHOR: [laughs] No — it depends is where nuance starts, not where it ends. The next step is specifying: depends on what, for whom, under what conditions. HOST: And that's the book? AUTHOR: That's the book.",
        questions: [
                            Exercise(id: "en-listen-podcast-nuance-q1", kind: "choice", prompt: "What is the first casualty of urgency?", options: ["Nuance", "Data", "Humour", "Time"], answers: ["Nuance"], explain: "Nuance is the first casualty of urgency."),
                            Exercise(id: "en-listen-podcast-nuance-q2", kind: "written", prompt: "What does urgency do to complex positions?", options: [], answers: ["flattens them into for-and-against"], explain: "It flattens complex positions into for-and-against."),
                            Exercise(id: "en-listen-podcast-nuance-q3", kind: "choice", prompt: "What's the productive question about remote work?", options: ["Which parts benefit from which conditions", "Is it good or bad", "Should everyone be remote", "Why do people hate it"], answers: ["Which parts benefit from which conditions"], explain: "Not good-or-bad, but which parts of which jobs benefit from which conditions."),
                            Exercise(id: "en-listen-podcast-nuance-q4", kind: "written", prompt: "What's the boring answer?", options: [], answers: ["it depends"], explain: "The answer is boring: it depends."),
                            Exercise(id: "en-listen-podcast-nuance-q5", kind: "choice", prompt: "Where does nuance start and end?", options: ["Starts at it depends, ends with specification", "Starts with data", "Starts and ends with it depends", "Never starts"], answers: ["Starts at it depends, ends with specification"], explain: "It depends is where nuance starts; specifying conditions is where it goes."),
                            Exercise(id: "en-listen-podcast-nuance-q6", kind: "choice", prompt: "What's the book about?", options: ["Specifying what nuance depends on", "Remote work", "Urgency", "Podcasts"], answers: ["Specifying what nuance depends on"], explain: "Depends on what, for whom, under what conditions.")], skills: ["listening:inference", "grammar:connectors", "function:express-opinion", "vocab:collocations"]),
    ListeningText(id: "es-listen-cafe-morning", languageID: "es", title: "Un café antes del trabajo", level: "A1", topic: "rutina", unitID: "es-foundations-u1",
        text: "Cada mañana, Marta camina hasta una cafetería pequeña cerca de su piso. El camarero sabe su nombre, así que nunca tiene que pedir. Hoy se sienta junto a la ventana con un café y un croissant. Su autobús sale a las ocho y media, pero no está preocupada. La cafetería es muy tranquila a esta hora. Bebe su café despacio y mira cómo la ciudad despierta.",
        questions: [
                            Exercise(id: "es-listen-cafe-morning-q1", kind: "choice", prompt: "¿Adónde va Marta cada mañana?", options: ["A una cafetería pequeña", "A su oficina", "A la estación de autobuses", "A un parque"], answers: ["A una cafetería pequeña"], explain: "Camina hasta una cafetería pequeña cerca de su piso."),
                            Exercise(id: "es-listen-cafe-morning-q2", kind: "choice", prompt: "¿Qué desayuna hoy?", options: ["Un café y un croissant", "Té y tostadas", "Zumo de naranja", "Nada"], answers: ["Un café y un croissant"], explain: "Se sienta junto a la ventana con un café y un croissant."),
                            Exercise(id: "es-listen-cafe-morning-q3", kind: "written", prompt: "¿A qué hora sale su autobús?", options: [], answers: ["a las ocho y media", "las ocho y media", "ocho y media"], explain: "Su autobús sale a las ocho y media."),
                            Exercise(id: "es-listen-cafe-morning-q4", kind: "choice", prompt: "¿Cómo se siente con el tiempo?", options: ["No está preocupada", "Está muy tarde", "Está enfadada", "Tiene sueño"], answers: ["No está preocupada"], explain: "El texto dice que no está preocupada."),
                            Exercise(id: "es-listen-cafe-morning-q5", kind: "choice", prompt: "¿Quién sabe su nombre?", options: ["El camarero", "El conductor del autobús", "Su jefe", "Un vecino"], answers: ["El camarero"], explain: "El camarero sabe su nombre, así que nunca tiene que pedir."),
                            Exercise(id: "es-listen-cafe-morning-q6", kind: "written", prompt: "¿Dónde se sienta hoy?", options: [], answers: ["junto a la ventana", "al lado de la ventana", "en la ventana"], explain: "Hoy se sienta junto a la ventana.")], skills: ["listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine"]),
    ListeningText(id: "es-listen-language-class", languageID: "es", title: "La clase de idiomas", level: "A1", topic: "presentaciones", unitID: "es-foundations-u1",
        text: "Marta asiste a su primera clase de portugués en un instituto pequeño. En la clase hay seis personas y todas quieren hablar. La profesora pide presentaciones. «Me llamo Marta y soy de Bolivia», dice una señora. «Yo soy Andrés, soy de Perú y trabajo en un restaurante», dice un chico joven. Marta también se presenta: «Soy Marta, soy de Argentina y soy enfermera». La profesora es de Madrid y enseña con mucho humor. Al final de la clase, los estudiantes intercambian números de teléfono. No son amigos todavía, pero la próxima semana van a tomar un café juntos y practicar.",
        questions: [
                            Exercise(id: "es-listen-language-class-q1", kind: "choice", prompt: "¿Cuántas personas hay en la clase?", options: ["Seis", "Tres", "Diez", "Catorce"], answers: ["Seis"], explain: "En la clase hay seis personas."),
                            Exercise(id: "es-listen-language-class-q2", kind: "choice", prompt: "¿De dónde es Andrés?", options: ["De Perú", "De Bolivia", "De Argentina", "De México"], answers: ["De Perú"], explain: "Andrés es de Perú y trabaja en un restaurante."),
                            Exercise(id: "es-listen-language-class-q3", kind: "choice", prompt: "¿Cuál es el trabajo de Marta?", options: ["Enfermera", "Profesora", "Camarera", "Estudiante"], answers: ["Enfermera"], explain: "Marta es de Argentina y es enfermera."),
                            Exercise(id: "es-listen-language-class-q4", kind: "written", prompt: "¿De dónde es la profesora?", options: [], answers: ["madrid", "de madrid", "es de madrid"], explain: "La profesora es de Madrid."),
                            Exercise(id: "es-listen-language-class-q5", kind: "choice", prompt: "¿Qué hacen al final de la clase?", options: ["Intercambian números de teléfono", "Vuelven a casa solos", "Hacen un examen", "Cenan en un restaurante"], answers: ["Intercambian números de teléfono"], explain: "Los estudiantes intercambian números de teléfono."),
                            Exercise(id: "es-listen-language-class-q6", kind: "written", prompt: "¿Qué van a hacer la próxima semana?", options: [], answers: ["tomar un café", "van a tomar un café", "tomar un café juntos"], explain: "La próxima semana van a tomar un café juntos y practicar.")], skills: ["listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself"]),
    ListeningText(id: "es-listen-little-sister", languageID: "es", title: "Mi hermana pequeña", level: "A1", topic: "familia", unitID: "es-foundations-u1",
        text: "Mi hermana pequeña se llama Carla y tiene nueve años. Es muy simpática y muy habladora. Carla no es callada: habla con todo el mundo, con los vecinos, con los profesores y con los perros del parque. Es rubia, como nuestra madre, y tiene los ojos marrones como mi padre. No es alta para su edad, pero es muy rápida y le encanta el fútbol. Su equipo no es muy bueno, pero a ella no le importa. «Yo no soy profesional», dice ella, «yo solo soy feliz con la pelota». Mi hermana es pequeña, pero su alegría es enorme.",
        questions: [
                            Exercise(id: "es-listen-little-sister-q1", kind: "choice", prompt: "¿Cuántos años tiene Carla?", options: ["Nueve", "Diecinueve", "Siete", "Diez"], answers: ["Nueve"], explain: "Carla tiene nueve años."),
                            Exercise(id: "es-listen-little-sister-q2", kind: "choice", prompt: "¿Cómo es Carla?", options: ["Simpática y habladora", "Tímida y callada", "Seria", "Triste"], answers: ["Simpática y habladora"], explain: "Es muy simpática y muy habladora."),
                            Exercise(id: "es-listen-little-sister-q3", kind: "written", prompt: "¿De qué color son sus ojos?", options: [], answers: ["marrones", "marrón", "los ojos marrones"], explain: "Tiene los ojos marrones como su padre."),
                            Exercise(id: "es-listen-little-sister-q4", kind: "choice", prompt: "¿Cómo es su pelo?", options: ["Rubio, como su madre", "Moreno, como su padre", "Pelirrojo", "Corto y negro"], answers: ["Rubio, como su madre"], explain: "Es rubia, como nuestra madre."),
                            Exercise(id: "es-listen-little-sister-q5", kind: "choice", prompt: "¿Qué le encanta?", options: ["El fútbol", "La natación", "La música", "Los videojuegos"], answers: ["El fútbol"], explain: "Es muy rápida y le encanta el fútbol."),
                            Exercise(id: "es-listen-little-sister-q6", kind: "written", prompt: "¿Cómo es su alegría?", options: [], answers: ["enorme", "muy grande", "grande"], explain: "Su alegría es enorme.")], skills: ["listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family"]),
    ListeningText(id: "es-listen-new-flatmate", languageID: "es", title: "Un nuevo compañero de piso", level: "A1", topic: "casa", unitID: "es-foundations-u1",
        text: "Tom tiene un compañero de piso nuevo. Se llama Leo y tiene veintitrés años. Leo viene de un pueblo pequeño del norte, pero ahora trabaja en la ciudad. Tiene dos cajas, una guitarra y una bicicleta. El piso tiene dos habitaciones y una cocina luminosa. Tom espera que a Leo le guste cocinar, porque a Tom no le gusta nada.",
        questions: [
                            Exercise(id: "es-listen-new-flatmate-q1", kind: "choice", prompt: "¿Cuántos años tiene Leo?", options: ["Veintitrés", "Treinta y dos", "Veinte", "Treinta"], answers: ["Veintitrés"], explain: "Leo tiene veintitrés años."),
                            Exercise(id: "es-listen-new-flatmate-q2", kind: "choice", prompt: "¿Qué NO tiene Leo?", options: ["Un televisor", "Dos cajas", "Una guitarra", "Una bicicleta"], answers: ["Un televisor"], explain: "Tiene dos cajas, una guitarra y una bicicleta — sin televisor."),
                            Exercise(id: "es-listen-new-flatmate-q3", kind: "written", prompt: "¿Qué odia hacer Tom?", options: [], answers: ["cocinar", "odia cocinar", "tom odia cocinar"], explain: "A Tom no le gusta nada cocinar."),
                            Exercise(id: "es-listen-new-flatmate-q4", kind: "choice", prompt: "¿Cómo es el piso?", options: ["Dos habitaciones y una cocina luminosa", "Un dormitorio y un balcón", "Un jardín", "Dos baños"], answers: ["Dos habitaciones y una cocina luminosa"], explain: "El piso tiene dos habitaciones y una cocina luminosa."),
                            Exercise(id: "es-listen-new-flatmate-q5", kind: "choice", prompt: "¿Dónde trabaja Leo ahora?", options: ["En la ciudad", "En un pueblo", "En el norte", "No trabaja"], answers: ["En la ciudad"], explain: "Viene de un pueblo pequeño, pero ahora trabaja en la ciudad."),
                            Exercise(id: "es-listen-new-flatmate-q6", kind: "written", prompt: "¿Qué instrumento tiene Leo?", options: [], answers: ["una guitarra", "la guitarra", "guitarra"], explain: "Leo tiene una guitarra.")], skills: ["listening:gist", "listening:detail", "grammar:have-got", "vocab:home"]),
    ListeningText(id: "es-listen-new-neighbour", languageID: "es", title: "La vecina nueva", level: "A1", topic: "gente", unitID: "es-foundations-u1",
        text: "En el edificio hay una vecina nueva. Se llama Amélie y es de Francia. No es estudiante; es fotógrafa. No trabaja en una oficina: trabaja en casa y viaja mucho. Los vecinos son curiosos, pero también son tímidos, así que no le hablan. Entonces, una mañana, Ben la encuentra en la puerta. «¿Eres tú la vecina nueva?», pregunta él. «Sí, soy yo», contesta ella, «y estoy contenta de estar aquí». Ahora son amigos, y ella ya no está sola en el edificio.",
        questions: [
                            Exercise(id: "es-listen-new-neighbour-q1", kind: "choice", prompt: "¿De dónde es Amélie?", options: ["De Francia", "De Italia", "De Japón", "De Brasil"], answers: ["De Francia"], explain: "Amélie es de Francia."),
                            Exercise(id: "es-listen-new-neighbour-q2", kind: "choice", prompt: "¿Cuál es su trabajo?", options: ["Es fotógrafa", "Es estudiante", "Trabaja en una oficina", "Es profesora"], answers: ["Es fotógrafa"], explain: "No es estudiante; es fotógrafa."),
                            Exercise(id: "es-listen-new-neighbour-q3", kind: "choice", prompt: "¿Trabaja en una oficina?", options: ["No, trabaja en casa", "Sí, todos los días", "Solo en verano", "No lo dice"], answers: ["No, trabaja en casa"], explain: "No trabaja en una oficina: trabaja en casa."),
                            Exercise(id: "es-listen-new-neighbour-q4", kind: "written", prompt: "¿Por qué no le hablan los vecinos?", options: [], answers: ["son tímidos", "porque son tímidos", "tímidos"], explain: "Son curiosos, pero también son tímidos."),
                            Exercise(id: "es-listen-new-neighbour-q5", kind: "choice", prompt: "¿Dónde la encuentra Ben?", options: ["En la puerta", "En el ascensor", "En la calle", "En la cafetería"], answers: ["En la puerta"], explain: "Una mañana, Ben la encuentra en la puerta."),
                            Exercise(id: "es-listen-new-neighbour-q6", kind: "written", prompt: "¿Cómo se siente Amélie al final?", options: [], answers: ["contenta", "feliz", "está contenta"], explain: "Dice que está contenta de estar aquí.")], skills: ["listening:gist", "listening:detail", "function:describe-people"]),
    ListeningText(id: "es-listen-sunday-market", languageID: "es", title: "El mercado del domingo", level: "A1", topic: "compras", unitID: "es-foundations-u1",
        text: "Los domingos hay un mercado en la plaza del pueblo. Ana y su padre van allí a las nueve, antes de que se llene. Compran fruta, pan y flores. Ana quiere unas fresas, pero su padre dice que esta semana son muy caras. Al final se llevan una bolsa grande de naranjas y unas rosas blancas para la mesa de la cocina.",
        questions: [
                            Exercise(id: "es-listen-sunday-market-q1", kind: "choice", prompt: "¿Cuándo van Ana y su padre al mercado?", options: ["A las nueve", "Al mediodía", "Por la tarde", "A las seis y media"], answers: ["A las nueve"], explain: "Van a las nueve, antes de que se llene."),
                            Exercise(id: "es-listen-sunday-market-q2", kind: "written", prompt: "¿Por qué no compra Ana las fresas?", options: [], answers: ["son muy caras", "muy caras", "porque son muy caras"], explain: "Su padre dice que son muy caras esta semana."),
                            Exercise(id: "es-listen-sunday-market-q3", kind: "choice", prompt: "¿Qué se llevan a casa?", options: ["Naranjas y rosas", "Fresas y pan", "Manzanas y tulipanes", "Pan y queso"], answers: ["Naranjas y rosas"], explain: "Se llevan naranjas y rosas blancas."),
                            Exercise(id: "es-listen-sunday-market-q4", kind: "choice", prompt: "¿Dónde está el mercado?", options: ["En la plaza del pueblo", "Junto al río", "En la estación", "En un supermercado"], answers: ["En la plaza del pueblo"], explain: "Hay un mercado en la plaza del pueblo los domingos."),
                            Exercise(id: "es-listen-sunday-market-q5", kind: "choice", prompt: "¿Qué compran?", options: ["Fruta, pan y flores", "Pescado y verduras", "Queso y carne", "Solo flores"], answers: ["Fruta, pan y flores"], explain: "Compran fruta, pan y flores."),
                            Exercise(id: "es-listen-sunday-market-q6", kind: "written", prompt: "¿Qué quiere Ana?", options: [], answers: ["fresas", "unas fresas", "quiere fresas"], explain: "Ana quiere unas fresas.")], skills: ["listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping"]),
    ListeningText(id: "es-listen-piso-elegido", languageID: "es", title: "El piso elegido", level: "A2", topic: "pisos", unitID: "es-foundations-u7",
        text: "Lucía y Pablo buscan piso en la app. El primero es más barato, pero está peor situado: a cuarenta minutos del centro. El segundo cuesta cien euros más al mes, pero es más luminoso y tiene balcón. Lucía opina que la luz es lo más importante, porque trabaja desde casa. Al final deciden pedir visita al segundo: es más caro, pero es el mejor de los dos para ellos.",
        questions: [
                            Exercise(id: "es-listen-piso-elegido-q1", kind: "choice", prompt: "¿Cuántos pisos comparan?", options: ["Dos", "Tres", "Cuatro"], answers: ["Dos"], explain: "Comparan dos pisos en la app."),
                            Exercise(id: "es-listen-piso-elegido-q2", kind: "choice", prompt: "¿Qué problema tiene el más barato?", options: ["Está lejos del centro", "No tiene balcón", "Es muy caro", "Es pequeño"], answers: ["Está lejos del centro"], explain: "A cuarenta minutos del centro."),
                            Exercise(id: "es-listen-piso-elegido-q3", kind: "written", prompt: "¿Cuánto cuesta más el segundo al mes?", options: [], answers: ["cien euros", "100 euros"], explain: "Cuesta cien euros más al mes."),
                            Exercise(id: "es-listen-piso-elegido-q4", kind: "choice", prompt: "¿Qué es lo más importante para Lucía?", options: ["La luz", "El precio", "El balcón", "La cocina"], answers: ["La luz"], explain: "Trabaja desde casa y la luz es lo más importante."),
                            Exercise(id: "es-listen-piso-elegido-q5", kind: "choice", prompt: "¿Qué deciden al final?", options: ["Pedir visita al segundo", "Quedarse con el primero", "Seguir buscando", "Pedir descuento"], answers: ["Pedir visita al segundo"], explain: "Deciden pedir visita al segundo."),
                            Exercise(id: "es-listen-piso-elegido-q6", kind: "written", prompt: "¿Para quién es el mejor?", options: [], answers: ["para ellos"], explain: "Es el mejor de los dos para ellos.")], skills: ["listening:gist", "listening:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ListeningText(id: "es-listen-plan-sabado", languageID: "es", title: "El sábado, organizado", level: "A2", topic: "planes", unitID: "es-foundations-u7",
        text: "Elena llama a su hermano para organizar el sábado. Él propone ir a la montaña, pero va a llover, así que Elena sugiere el museo nuevo. Van a quedar a las diez en la entrada principal y van a comer en el mercado de al lado, que es más barato que los restaurantes del centro. Por la noche no tienen plan: van a decidir sobre la marcha, cuando sepan qué tiempo hace.",
        questions: [
                            Exercise(id: "es-listen-plan-sabado-q1", kind: "choice", prompt: "¿Quién propone la montaña?", options: ["El hermano", "Elena", "Su madre", "Un amigo"], answers: ["El hermano"], explain: "Su hermano propone ir a la montaña."),
                            Exercise(id: "es-listen-plan-sabado-q2", kind: "choice", prompt: "¿Por qué no van a la montaña?", options: ["Va a llover", "Están cansados", "El museo es gratis", "La montaña está lejos"], answers: ["Va a llover"], explain: "Va a llover, así que van al museo."),
                            Exercise(id: "es-listen-plan-sabado-q3", kind: "written", prompt: "¿A qué hora van a quedar?", options: [], answers: ["a las diez", "las diez"], explain: "Van a quedar a las diez."),
                            Exercise(id: "es-listen-plan-sabado-q4", kind: "choice", prompt: "¿Dónde van a comer?", options: ["En el mercado de al lado", "En un restaurante del centro", "En casa", "En el museo"], answers: ["En el mercado de al lado"], explain: "Es más barato que los restaurantes del centro."),
                            Exercise(id: "es-listen-plan-sabado-q5", kind: "choice", prompt: "¿Qué van a hacer por la noche?", options: ["Decidir sobre la marcha", "Ir al cine", "Volver temprano", "Quedar con amigos"], answers: ["Decidir sobre la marcha"], explain: "Van a decidir cuando sepan el tiempo.")], skills: ["listening:gist", "listening:detail", "grammar:going-to"], exposureSkills: ["grammar:future-forms"]),
    ListeningText(id: "es-listen-primera-vez", languageID: "es", title: "Cosas que no he hecho", level: "B1", topic: "viajes", unitID: "es-foundations-u5",
        text: "En la cocina de un hostal, tres viajeros comparan vidas. Diego ha visitado veinte países, pero nunca ha aprendido a nadar: «Lo sé, es ridículo». Valeria ha buceado dos veces con tortugas, pero no ha salido de América Latina hasta este viaje. Y Marta, que lleva seis años en la carretera, nunca ha volado: cruza los océanos en barco y las fronteras en autobús. «¿Nunca?», pregunta Diego. «Nunca. El miedo es más viejo que yo.» Se ríen de lo que no han hecho, y Marta dice algo que se quedan todos: «No hace falta haberlo hecho todo. Basta con seguir queriendo».",
        questions: [
                            Exercise(id: "es-listen-primera-vez-q1", kind: "choice", prompt: "¿Qué no ha hecho nunca Diego?", options: ["Aprender a nadar", "Visitar veinte países", "Cruzar en barco", "Salir de América"], answers: ["Aprender a nadar"], explain: "Ha visitado veinte países, pero nunca ha aprendido a nadar."),
                            Exercise(id: "es-listen-primera-vez-q2", kind: "written", prompt: "¿Cuántas veces ha buceado Valeria?", options: [], answers: ["dos veces", "2 veces", "dos"], explain: "Valeria ha buceado dos veces con tortugas."),
                            Exercise(id: "es-listen-primera-vez-q3", kind: "choice", prompt: "¿Cómo cruza Marta los océanos?", options: ["En barco", "En avión", "En autobús", "A pie"], answers: ["En barco"], explain: "Cruza los océanos en barco y las fronteras en autobús."),
                            Exercise(id: "es-listen-primera-vez-q4", kind: "choice", prompt: "¿Qué dice Marta sobre el miedo?", options: ["Es más viejo que ella", "Es más joven que ella", "Es ridículo", "Se ha ido"], answers: ["Es más viejo que ella"], explain: "El miedo es más viejo que yo."),
                            Exercise(id: "es-listen-primera-vez-q5", kind: "written", prompt: "¿Qué basta, según Marta?", options: [], answers: ["seguir queriendo", "con seguir queriendo"], explain: "Basta con seguir queriendo."),
                            Exercise(id: "es-listen-primera-vez-q6", kind: "choice", prompt: "¿Cómo reaccionan los tres?", options: ["Se ríen", "Se enfadan", "Se van", "Lloran"], answers: ["Se ríen"], explain: "Se ríen de lo que no han hecho.")], skills: ["listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"], exposureSkills: ["grammar:relative-clauses"]),
    ListeningText(id: "es-listen-cambio-pueblo", languageID: "es", title: "De la ciudad al pueblo", level: "B1", topic: "cambios", unitID: "es-foundations-u5",
        text: "Nacho explica por qué dejó Madrid. Antes vivía en un piso pequeño y trabajaba once horas al día: «Ganaba bien, pero no tenía vida». Un invierno se puso enfermo, y entonces entendió que algo tenía que cambiar. Ahora vive en un pueblo de mil habitantes, trabaja desde casa por las mañanas y cultiva un huerto por las tardes. «Gano menos, pero me sobra tiempo.» Al principio sus padres no lo entendían; ahora vienen cada mes. «¿Te arrepientes de algo?», le pregunta su amiga. «De no haberlo hecho antes».",
        questions: [
                            Exercise(id: "es-listen-cambio-pueblo-q1", kind: "choice", prompt: "¿Dónde vivía Nacho antes?", options: ["En Madrid", "En un pueblo", "En Barcelona", "En un hostal"], answers: ["En Madrid"], explain: "Nacho explica por qué dejó Madrid."),
                            Exercise(id: "es-listen-cambio-pueblo-q2", kind: "written", prompt: "¿Cuántas horas trabajaba al día?", options: [], answers: ["once horas", "11 horas", "once"], explain: "Trabajaba once horas al día."),
                            Exercise(id: "es-listen-cambio-pueblo-q3", kind: "choice", prompt: "¿Qué le hizo cambiar?", options: ["Se puso enfermo", "Perdió el trabajo", "Ganó la lotería", "Conoció a alguien"], answers: ["Se puso enfermo"], explain: "Un invierno se puso enfermo, y entonces entendió que tenía que cambiar."),
                            Exercise(id: "es-listen-cambio-pueblo-q4", kind: "choice", prompt: "¿Qué hace por las tardes ahora?", options: ["Cultiva un huerto", "Trabaja más horas", "Viaja cada mes", "Estudia"], answers: ["Cultiva un huerto"], explain: "Trabaja desde casa por las mañanas y cultiva un huerto por las tardes."),
                            Exercise(id: "es-listen-cambio-pueblo-q5", kind: "written", prompt: "¿Qué se arrepiente Nacho?", options: [], answers: ["de no haberlo hecho antes", "no haberlo hecho antes"], explain: "«De no haberlo hecho antes».")], skills: ["listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions"]),
    ListeningText(id: "es-listen-regateo-mesa", languageID: "es", title: "El regateo de la mesa", level: "B2", topic: "negocios", unitID: "es-foundations-u8",
        text: "En una app de segunda mano, Clara quiere una mesa de madera que cuesta 80 euros. « ¿Y si nos viéramos en 60 ? », propone ella. El vendedor no acepta: « Solo si te la llevas hoy ». Clara lo piensa: « Te daría 65 si incluyes la silla ». « Imposible », ríe él, « pero te dejaría la mesa en 70 y te la subiría al piso ». Clara no lo duda: « ¿La subirías tú sola ? ». « Tengo un carro », responde. « Trato hecho », dice ella, y añade: « Si me gusta tanto como en la foto, te dejo una reseña de cinco estrellas ».",
        questions: [
                            Exercise(id: "es-listen-regateo-mesa-q1", kind: "choice", prompt: "¿Cuánto pide el vendedor por la mesa ?", options: ["80 euros", "60 euros", "70 euros", "65 euros"], answers: ["80 euros"], explain: "La mesa cuesta 80 euros."),
                            Exercise(id: "es-listen-regateo-mesa-q2", kind: "written", prompt: "¿Qué propone Clara primero ?", options: [], answers: ["60 euros", "sesenta euros", "nos vieramos en 60", "nos viéramos en 60"], explain: "« ¿Y si nos viéramos en 60 ? »."),
                            Exercise(id: "es-listen-regateo-mesa-q3", kind: "choice", prompt: "¿Qué condición pone el vendedor ?", options: ["Llevarla hoy", "Pagar en efectivo", "Añadir una reseña", "Volver mañana"], answers: ["Llevarla hoy"], explain: "« Solo si te la llevas hoy »."),
                            Exercise(id: "es-listen-regateo-mesa-q4", kind: "choice", prompt: "¿Qué ofrece el vendedor por 70 ?", options: ["Subirle la mesa al piso", "Añadir la silla", "Bajar a 60", "Darle un carro"], answers: ["Subirle la mesa al piso"], explain: "« Te la subiría al piso »."),
                            Exercise(id: "es-listen-regateo-mesa-q5", kind: "written", prompt: "¿Qué promete Clara si le gusta ?", options: [], answers: ["una resena de cinco estrellas", "una reseña de cinco estrellas", "resena cinco estrellas"], explain: "Una reseña de cinco estrellas.")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "es-listen-noticia-barrio", languageID: "es", title: "La noticia del barrio", level: "B2", topic: "noticias", unitID: "es-foundations-u9",
        text: "En el mercado, Ana y Luis comentan lo que se dice. « Se dice que van a peatonalizar la calle Mayor », cuenta Ana. « ¿Otra vez ? », se ríe Luis. « La noticia que leí dice que empiezan en primavera ». Según el ayuntamiento, serían solo los sábados, pero los comerciantes, cuyo negocio dependería del turismo, ya se han manifestado. « Es cierto que bajaría el ruido », reconoce Luis, « pero, ¿y el aparcamiento ? ». Ana defiende la medida: « Por un lado, más gente caminaría; por otro, los autobuses llegarían a la puerta ». Se quedan sin resolverlo, pero prometen volver a hablarlo cuando se publique el plan.",
        questions: [
                            Exercise(id: "es-listen-noticia-barrio-q1", kind: "choice", prompt: "¿Qué se dice de la calle Mayor ?", options: ["Que la peatonalizarán", "Que la ampliarán", "Que la cerrarán", "Que cambiará de nombre"], answers: ["Que la peatonalizarán"], explain: "« Se dice que van a peatonalizar la calle Mayor »."),
                            Exercise(id: "es-listen-noticia-barrio-q2", kind: "written", prompt: "¿Cuándo empezarían ?", options: [], answers: ["en primavera", "primavera"], explain: "« La noticia que leí dice que empiezan en primavera »."),
                            Exercise(id: "es-listen-noticia-barrio-q3", kind: "choice", prompt: "¿Qué dice el ayuntamiento ?", options: ["Solo los sábados", "Todos los días", "Solo en verano", "Los festivos"], answers: ["Solo los sábados"], explain: "Según el ayuntamiento, serían solo los sábados."),
                            Exercise(id: "es-listen-noticia-barrio-q4", kind: "choice", prompt: "¿Quién se ha manifestado ?", options: ["Los comerciantes", "Los vecinos", "Los taxistas", "El ayuntamiento"], answers: ["Los comerciantes"], explain: "Los comerciantes ya se han manifestado."),
                            Exercise(id: "es-listen-noticia-barrio-q5", kind: "written", prompt: "¿Qué prometen Ana y Luis ?", options: [], answers: ["volver a hablarlo", "hablarlo otra vez", "volverlo a hablar"], explain: "Prometen volver a hablarlo cuando se publique el plan.")], skills: ["listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors"]),
    ListeningText(id: "es-listen-debate-radio", languageID: "es", title: "Tertulia: el teletrabajo", level: "C1", topic: "debate", unitID: "es-foundations-u10",
        text: "En « Punto de vista », la tertulia de la emisora, la presentadora abre el debate sobre el teletrabajo. « Para empezar, un dato: la productividad sube, según el ministerio », dice. Un contertulio relativiza la cifra: « En cierto modo, sí; pero, desde mi punto de vista, ese dato mide otra cosa ». Una editorial, en cambio, defiende volver a la oficina: « A esto se añade que el equipo necesita verse ». « No obstante », apostilla la presentadora, « hay quien trabaja a cien kilómetros de la sede ». La tertulia se encrespa: por otra parte, nadie menciona los costes del transporte. « En resumen », cierra la presentadora, « el debate sigue abierto: por así decirlo, ni blanco ni negro ».",
        questions: [
                            Exercise(id: "es-listen-debate-radio-q1", kind: "choice", prompt: "¿Qué tema abre la tertulia ?", options: ["El teletrabajo", "El precio del transporte", "Los indicadores del ministerio", "Una editorial del día"], answers: ["El teletrabajo"], explain: "La presentadora abre el debate sobre el teletrabajo."),
                            Exercise(id: "es-listen-debate-radio-q2", kind: "written", prompt: "¿Qué dato da la presentadora para empezar ?", options: [], answers: ["sube la productividad", "la productividad sube", "que sube la productividad"], explain: "« Un dato: la productividad sube »."),
                            Exercise(id: "es-listen-debate-radio-q3", kind: "choice", prompt: "¿Qué opina el contertulio de ese dato ?", options: ["Que mide otra cosa", "Que es falso", "Que lo firma el ministerio", "Que es definitivo"], answers: ["Que mide otra cosa"], explain: "« En cierto modo, sí; pero… ese dato mide otra cosa »."),
                            Exercise(id: "es-listen-debate-radio-q4", kind: "choice", prompt: "¿Qué añade la editorial al debate ?", options: ["Que el equipo necesita verse", "Que la oficina es cara", "Que sube la productividad", "Que nadie usa el metro"], answers: ["Que el equipo necesita verse"], explain: "« A esto se añade que el equipo necesita verse »."),
                            Exercise(id: "es-listen-debate-radio-q5", kind: "written", prompt: "¿Cómo cierra la presentadora el programa ?", options: [], answers: ["el debate sigue abierto", "sigue abierto", "ni blanco ni negro"], explain: "« En resumen… el debate sigue abierto ».")], skills: ["listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "es-listen-charla-claves", languageID: "es", title: "Tres claves para presentar", level: "C1", topic: "comunicación", unitID: "es-foundations-u10",
        text: "Gracias por venir. Hoy quiero compartir con ustedes tres claves para presentar ideas con claridad. La primera: abrir con un mapa. « Para empezar » y « en primer lugar » no son adornos: le dicen al oyente por dónde vamos. La segunda: encadenar, no saltar. Cada argumento debe venir tomado de la mano del anterior — por otra parte, a esto se añade que… —; si saltamos de piedra en piedra, el público se baja del tren. Y la tercera: cerrar con una sola idea. « En resumen » significa elegir: si su conclusión tiene tres frases, no es una conclusión, es un resumen mal entendido. Desde mi punto de vista, quien domina estos conectores no improvisa: simplemente se deja leer. Pasemos ahora a practicar con un caso real de consulta.",
        questions: [
                            Exercise(id: "es-listen-charla-claves-q1", kind: "choice", prompt: "¿Cuál es el propósito principal de la charla ?", options: ["Explicar cómo presentar ideas", "Vender un libro de estilo", "Critica las reuniones de trabajo", "Contar la carrera de la ponente"], answers: ["Explicar cómo presentar ideas"], explain: "Toda la charla gira alrededor de presentar ideas con claridad."),
                            Exercise(id: "es-listen-charla-claves-q2", kind: "choice", prompt: "¿Cuántas claves presenta la ponente ?", options: ["Tres", "Dos", "Cuatro", "Cinco"], answers: ["Tres"], explain: "« Hoy quiero compartir con ustedes tres claves »."),
                            Exercise(id: "es-listen-charla-claves-q3", kind: "written", prompt: "Según la charla, ¿qué significa cerrar con « en resumen » ?", options: [], answers: ["elegir", "elegir una sola idea", "una sola idea"], explain: "« En resumen significa elegir »: una sola idea final."),
                            Exercise(id: "es-listen-charla-claves-q4", kind: "choice", prompt: "¿Cómo deben encadenarse los argumentos ?", options: ["Tomados de la mano del anterior", "Cada uno por su lado", "Del más fuerte al más débil", "Por orden de llegada"], answers: ["Tomados de la mano del anterior"], explain: "Cada argumento viene tomado de la mano del anterior; si saltas, el público se baja del tren."),
                            Exercise(id: "es-listen-charla-claves-q5", kind: "written", prompt: "¿Qué dice la ponente de quien domina los conectores ?", options: [], answers: ["no improvisa", "que no improvisa", "se deja leer"], explain: "« No improvisa: simplemente se deja leer ».")], skills: ["listening:gist", "listening:detail", "grammar:connectors", "vocab:work"]),
    ListeningText(id: "es-listen-podcast-matices", languageID: "es", title: "En defensa del matiz", level: "C1", topic: "lenguaje", unitID: "es-foundations-u10",
        text: "En « Se dice así », Marta y Diego discuten sobre la manía de matizar. « Hoy en cierto modo todo el mundo matiza », observa Marta. « ¿Moda ? Yo diría que es pereza: decimos \"más o menos\" para no mojarnos », rebate Diego. « No obstante, matizar no es cobardía; por así decirlo, es dejar la puerta abierta », responde ella. « Desde tu punto de vista, claro: tú jamás das un sí rotundo », se burla él. « Tampoco hace falta: en una reunión, un matiz a tiempo te ahorra una discusión ». « Bueno, ahí te doy la razón: mejor un \"hasta cierto punto\" honesto que un \"sí\" que luego te pesa ». « Trato hecho: matices bien entendidos ».",
        questions: [
                            Exercise(id: "es-listen-podcast-matices-q1", kind: "choice", prompt: "¿Qué piensa Diego de la moda de matizar ?", options: ["Que a veces es pereza", "Que es obligatoria en las reuniones", "Que es muy reciente", "Que la defiende sin reservas"], answers: ["Que a veces es pereza"], explain: "« Yo diría que es pereza: decimos más o menos para no mojarnos »."),
                            Exercise(id: "es-listen-podcast-matices-q2", kind: "written", prompt: "Según Marta, ¿qué consigue un matiz a tiempo ?", options: [], answers: ["te ahorra una discusion", "te ahorra una discusión", "ahorra una discusión"], explain: "« Un matiz a tiempo te ahorra una discusión »."),
                            Exercise(id: "es-listen-podcast-matices-q3", kind: "choice", prompt: "¿En qué punto cede Diego ?", options: ["Mejor un matiz honesto que un sí que pesa", "Que Marta nunca da un sí rotundo", "Que los matices son pereza", "Que hay que mojarse siempre"], answers: ["Mejor un matiz honesto que un sí que pesa"], explain: "« Mejor un 'hasta cierto punto' honesto que un 'sí' que luego te pesa »."),
                            Exercise(id: "es-listen-podcast-matices-q4", kind: "written", prompt: "¿Cómo defiende Marta el hecho de matizar ?", options: [], answers: ["dejar la puerta abierta", "no es cobardia", "no es cobardía"], explain: "« Matizar no es cobardía; es dejar la puerta abierta »."),
                            Exercise(id: "es-listen-podcast-matices-q5", kind: "choice", prompt: "¿Qué tono tiene la conversación al final ?", options: ["Cordial", "Enfrentado", "Indiferente", "Fríamente profesional"], answers: ["Cordial"], explain: "Se dan la razón en parte y cierran en buen término.")], skills: ["listening:inference", "listening:connected-speech", "function:express-opinion", "vocab:social-expressions"]),
    ListeningText(id: "es-listen-piso-nuevo", languageID: "es", title: "Un piso nuevo", level: "A1", topic: "casa", unitID: "es-foundations-u11",
        text: "Leo tiene un piso nuevo en el centro. El piso tiene dos habitaciones y un salón grande. En el salón hay un sofá azul y una mesa junto a la ventana. La cocina es pequeña, pero hay una mesa para desayunar. Su compañero de piso se llama Martín. Su habitación está limpia y sus libros están encima de la mesa. No hay lavavajillas, así que lavan los platos a mano. A Leo le gusta el piso porque está cerca de un parque.",
        questions: [
                            Exercise(id: "es-listen-piso-nuevo-q1", kind: "choice", prompt: "¿Cuántas habitaciones tiene el piso?", options: ["Dos", "Tres", "Cuatro", "Una"], answers: ["Dos"], explain: "El piso tiene dos habitaciones y un salón grande."),
                            Exercise(id: "es-listen-piso-nuevo-q2", kind: "choice", prompt: "¿Dónde está la mesa del salón?", options: ["Junto a la ventana", "En la cocina", "Debajo del sofá", "En el pasillo"], answers: ["Junto a la ventana"], explain: "Hay una mesa junto a la ventana."),
                            Exercise(id: "es-listen-piso-nuevo-q3", kind: "written", prompt: "¿Cómo se llama su compañero de piso?", options: [], answers: ["Martin", "Martín"], explain: "Su compañero de piso se llama Martín."),
                            Exercise(id: "es-listen-piso-nuevo-q4", kind: "choice", prompt: "¿Dónde están los libros de Martín?", options: ["Encima de la mesa", "Debajo de la cama", "En el salón", "En una caja"], answers: ["Encima de la mesa"], explain: "Sus libros están encima de la mesa."),
                            Exercise(id: "es-listen-piso-nuevo-q5", kind: "written", prompt: "¿Por qué le gusta el piso a Leo?", options: [], answers: ["esta cerca de un parque", "está cerca de un parque", "porque está cerca de un parque"], explain: "Está cerca de un parque."),
                            Exercise(id: "es-listen-piso-nuevo-q6", kind: "choice", prompt: "¿Cómo es la cocina?", options: ["Pequeña", "Grande", "Nueva", "Moderna"], answers: ["Pequeña"], explain: "La cocina es pequeña, pero hay una mesa para desayunar.")], skills: ["listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home"]),
    ListeningText(id: "es-listen-paseo-barrio", languageID: "es", title: "Un paseo por el barrio", level: "A1", topic: "barrio", unitID: "es-foundations-u12",
        text: "Hoy soy nuevo en el barrio. Pregunto a una señora: «Perdone, ¿hay un supermercado por aquí?». «Sí, hay uno en la esquina», dice ella. «¿Y una farmacia?». «Siga recto y gire a la izquierda; está a tres minutos». Camino y veo el supermercado, pero no veo la farmacia. Una chica me ayuda: «Está detrás del supermercado, muy cerca». Al final compro agua y pan. El barrio es tranquilo y la gente es muy amable.",
        questions: [
                            Exercise(id: "es-listen-paseo-barrio-q1", kind: "choice", prompt: "¿Dónde está el supermercado?", options: ["En la esquina", "En la plaza", "Detrás de la farmacia", "Muy lejos"], answers: ["En la esquina"], explain: "La señora dice: hay uno en la esquina."),
                            Exercise(id: "es-listen-paseo-barrio-q2", kind: "choice", prompt: "¿Qué hay que hacer para llegar a la farmacia?", options: ["Siga recto y gire a la izquierda", "Gire a la derecha", "Tome el autobús", "Vuelva a casa"], answers: ["Siga recto y gire a la izquierda"], explain: "Siga recto y gire a la izquierda."),
                            Exercise(id: "es-listen-paseo-barrio-q3", kind: "written", prompt: "¿Dónde está la farmacia?", options: [], answers: ["detras del supermercado", "detrás del supermercado", "muy cerca"], explain: "Está detrás del supermercado."),
                            Exercise(id: "es-listen-paseo-barrio-q4", kind: "choice", prompt: "¿Qué compra al final?", options: ["Agua y pan", "Fruta", "Leche y café", "Nada"], answers: ["Agua y pan"], explain: "Al final compra agua y pan."),
                            Exercise(id: "es-listen-paseo-barrio-q5", kind: "choice", prompt: "¿Cómo es el barrio?", options: ["Tranquilo", "Ruidoso", "Grande", "Feo"], answers: ["Tranquilo"], explain: "El barrio es tranquilo."),
                            Exercise(id: "es-listen-paseo-barrio-q6", kind: "written", prompt: "¿Cómo es la gente del barrio?", options: [], answers: ["muy amable", "es muy amable", "amable"], explain: "La gente es muy amable.")], skills: ["listening:gist", "listening:detail", "grammar:there-is-are", "vocab:town", "function:ask-for-directions"]),
    ListeningText(id: "es-listen-llamada-abuela", languageID: "es", title: "Una llamada a la abuela", level: "A1", topic: "familia", unitID: "es-foundations-u13",
        text: "Hablo con mi abuela por teléfono. «¡Hola, abuela! ¿Está el abuelo?». «No está ahora; está en el mercado. ¿Todo bien?». «Sí, abuela. Mi hermana siempre estudia por la noche y a veces cena con nosotros. Nunca tenemos tiempo los viernes». «¿Y tu madre?». «Trabaja mucho, pero llamamos los domingos». «Vale, cariño. Dile al abuelo que llamo más tarde». «Vale, abuela. Un beso».",
        questions: [
                            Exercise(id: "es-listen-llamada-abuela-q1", kind: "choice", prompt: "¿Con quién habla?", options: ["Con su abuela", "Con su tío", "Con su madre", "Con su hermana"], answers: ["Con su abuela"], explain: "Hablo con mi abuela por teléfono."),
                            Exercise(id: "es-listen-llamada-abuela-q2", kind: "choice", prompt: "¿Dónde está el abuelo?", options: ["En el mercado", "En casa", "En el trabajo", "En la calle"], answers: ["En el mercado"], explain: "No está ahora; está en el mercado."),
                            Exercise(id: "es-listen-llamada-abuela-q3", kind: "choice", prompt: "¿Qué hace siempre la hermana?", options: ["Estudia por la noche", "Cena fuera", "Llama a la abuela", "Trabaja mucho"], answers: ["Estudia por la noche"], explain: "Mi hermana siempre estudia por la noche."),
                            Exercise(id: "es-listen-llamada-abuela-q4", kind: "written", prompt: "¿Qué hace a veces la hermana?", options: [], answers: ["Cena con nosotros", "cena con nosotros", "a veces cena con nosotros"], explain: "A veces cena con nosotros."),
                            Exercise(id: "es-listen-llamada-abuela-q5", kind: "choice", prompt: "¿Cuándo llaman a la madre?", options: ["Los domingos", "Los viernes", "Los sábados", "Los lunes"], answers: ["Los domingos"], explain: "Llamamos los domingos."),
                            Exercise(id: "es-listen-llamada-abuela-q6", kind: "written", prompt: "¿Qué va a hacer la abuela con el abuelo?", options: [], answers: ["Llamar más tarde", "llamar mas tarde", "llamar más tarde"], explain: "Dile al abuelo que llamo más tarde.")], skills: ["listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ListeningText(id: "es-listen-finde-lluvioso", languageID: "es", title: "Un sábado de lluvia", level: "A1", topic: "clima", unitID: "es-foundations-u14",
        text: "Hoy es sábado y llueve mucho. Nunca salgo los días de lluvia. Por la mañana veo una serie y a veces leo un libro. Mi hermano siempre juega al fútbol, pero hoy no puede: hace frío y llueve. Por la tarde vamos al cine con nuestros amigos. En esta ciudad llueve mucho en otoño, pero en verano hace sol todos los días. Me gusta el otoño, pero no me gusta la lluvia.",
        questions: [
                            Exercise(id: "es-listen-finde-lluvioso-q1", kind: "choice", prompt: "¿Qué tiempo hace hoy?", options: ["Llueve", "Nieva", "Hace sol", "Hace viento"], answers: ["Llueve"], explain: "Hoy es sábado y llueve mucho."),
                            Exercise(id: "es-listen-finde-lluvioso-q2", kind: "choice", prompt: "¿Qué hace el narrador por la mañana?", options: ["Ve una serie y a veces lee", "Juega al fútbol", "Va al cine", "Sale con amigos"], answers: ["Ve una serie y a veces lee"], explain: "Por la mañana veo una serie y a veces leo un libro."),
                            Exercise(id: "es-listen-finde-lluvioso-q3", kind: "written", prompt: "¿Por qué no puede jugar al fútbol el hermano?", options: [], answers: ["Porque llueve", "porque hace frío", "porque hace frio", "porque llueve y hace frío"], explain: "Hace frío y llueve."),
                            Exercise(id: "es-listen-finde-lluvioso-q4", kind: "choice", prompt: "¿Adónde van por la tarde?", options: ["Al cine", "A la piscina", "Al mercado", "A la montaña"], answers: ["Al cine"], explain: "Por la tarde vamos al cine."),
                            Exercise(id: "es-listen-finde-lluvioso-q5", kind: "choice", prompt: "¿Cómo es el verano en esta ciudad?", options: ["Hace sol todos los días", "Llueve todos los días", "Nieva mucho", "Hace frío"], answers: ["Hace sol todos los días"], explain: "En verano hace sol todos los días."),
                            Exercise(id: "es-listen-finde-lluvioso-q6", kind: "written", prompt: "¿Qué estación le gusta?", options: [], answers: ["El otoño", "el otoño", "el otono"], explain: "Me gusta el otoño.")], skills: ["listening:gist", "listening:detail", "vocab:weather", "function:talk-about-weather", "grammar:frequency-adverbs"]),
    ListeningText(id: "es-listen-metro-perdido", languageID: "es", title: "Perdido en el metro", level: "A1", topic: "transporte", unitID: "es-foundations-u15",
        text: "Estoy en el centro y quiero ir al museo. No conozco la ciudad y estoy perdido. Pregunto a una señora: «¿Dónde está la estación de metro, por favor?». La señora dice: «Está en la plaza, al lado del banco». Tomo la línea cuatro y bajo en la parada del museo. El metro pasa cada cinco minutos y el viaje dura diez. Llego al museo a las once y cuarto. Los billetes cuestan dos euros y cincuenta.",
        questions: [
                            Exercise(id: "es-listen-metro-perdido-q1", kind: "choice", prompt: "¿Adónde quiere ir el narrador?", options: ["Al museo", "A la estación", "Al banco", "A la plaza"], answers: ["Al museo"], explain: "Estoy en el centro y quiero ir al museo."),
                            Exercise(id: "es-listen-metro-perdido-q2", kind: "choice", prompt: "¿Dónde está la estación de metro?", options: ["En la plaza, al lado del banco", "Dentro del museo", "En la parada del bus", "Al final de la calle"], answers: ["En la plaza, al lado del banco"], explain: "La señora dice: «Está en la plaza, al lado del banco»."),
                            Exercise(id: "es-listen-metro-perdido-q3", kind: "written", prompt: "¿Qué línea toma el narrador?", options: [], answers: ["La línea cuatro", "la linea cuatro", "la cuatro"], explain: "Tomo la línea cuatro."),
                            Exercise(id: "es-listen-metro-perdido-q4", kind: "choice", prompt: "¿Cada cuánto pasa el metro?", options: ["Cada cinco minutos", "Cada diez minutos", "Cada quince minutos", "Cada media hora"], answers: ["Cada cinco minutos"], explain: "El metro pasa cada cinco minutos."),
                            Exercise(id: "es-listen-metro-perdido-q5", kind: "written", prompt: "¿A qué hora llega al museo?", options: [], answers: ["A las once y cuarto", "a las once y cuarto", "las once y cuarto"], explain: "Llego al museo a las once y cuarto."),
                            Exercise(id: "es-listen-metro-perdido-q6", kind: "written", prompt: "¿Cuánto cuesta el billete?", options: [], answers: ["Dos euros y cincuenta", "dos euros con cincuenta", "2,50 euros"], explain: "Los billetes cuestan dos euros y cincuenta.")], skills: ["listening:gist", "listening:detail", "vocab:transport", "function:tell-time"]),
    ListeningText(id: "es-listen-farmacia-sabado", languageID: "es", title: "Sábado en la farmacia", level: "A1", topic: "salud", unitID: "es-foundations-u16",
        text: "Es sábado y no me siento bien. Me duele la garganta y tengo tos, pero no tengo fiebre. Voy a la farmacia de mi barrio y pregunto por un jarabe para la tos. El farmacéutico pregunta: «¿Para quién es?». Es para mí. Compro también unas pastillas para la garganta: cuestan tres euros. La pastilla es una cada ocho horas y el jarabe, tres veces al día. Por la tarde descanso en casa y bebo mucha agua. Nunca tomo medicamentos sin preguntar primero.",
        questions: [
                            Exercise(id: "es-listen-farmacia-sabado-q1", kind: "choice", prompt: "¿Qué le duele?", options: ["La garganta", "La cabeza", "El estómago", "La espalda"], answers: ["La garganta"], explain: "Me duele la garganta."),
                            Exercise(id: "es-listen-farmacia-sabado-q2", kind: "choice", prompt: "¿Qué tiene y qué no tiene?", options: ["Tos, pero no fiebre", "Fiebre, pero no tos", "Fiebre y tos", "Ni tos ni fiebre"], answers: ["Tos, pero no fiebre"], explain: "Tengo tos, pero no tengo fiebre."),
                            Exercise(id: "es-listen-farmacia-sabado-q3", kind: "choice", prompt: "¿Qué compra para la garganta?", options: ["Pastillas", "Jarabe", "Agua", "Nada"], answers: ["Pastillas"], explain: "Compro también unas pastillas para la garganta."),
                            Exercise(id: "es-listen-farmacia-sabado-q4", kind: "written", prompt: "¿Cuánto cuestan las pastillas?", options: [], answers: ["Tres euros", "tres euros", "3 euros"], explain: "Las pastillas cuestan tres euros."),
                            Exercise(id: "es-listen-farmacia-sabado-q5", kind: "written", prompt: "¿Cada cuántas horas toma la pastilla?", options: [], answers: ["Cada ocho horas", "cada ocho horas", "cada 8 horas"], explain: "La pastilla es una cada ocho horas."),
                            Exercise(id: "es-listen-farmacia-sabado-q6", kind: "choice", prompt: "¿Qué hace por la tarde?", options: ["Descansa en casa y bebe agua", "Trabaja en la farmacia", "Sale con amigos", "Juega al fútbol"], answers: ["Descansa en casa y bebe agua"], explain: "Por la tarde descanso en casa y bebo mucha agua.")], skills: ["listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs"]),
    ListeningText(id: "es-listen-cena-sorpresa", languageID: "es", title: "Una cena de sorpresa", level: "A1", topic: "restaurantes", unitID: "es-foundations-u17",
        text: "Es el cumpleaños de Marta. Sus amigos organizan una cena de sorpresa en un restaurante del centro. La carta tiene paella, gazpacho y tortilla. Los amigos piden tres menús y dos jarras de agua. Marta no sabe nada: cree que es una cena normal con su amiga Laura. A las nueve, Marta entra en el restaurante y todos cantan: «¡Sorpresa!». El camarero trae un pastel con velas y dice: «El pastel es de la casa». Marta llora de alegría.",
        questions: [
                            Exercise(id: "es-listen-cena-sorpresa-q1", kind: "choice", prompt: "¿Quién organiza la cena?", options: ["Sus amigos", "Su familia", "Laura", "El camarero"], answers: ["Sus amigos"], explain: "Sus amigos organizan una cena de sorpresa."),
                            Exercise(id: "es-listen-cena-sorpresa-q2", kind: "choice", prompt: "¿Qué hay en la carta?", options: ["Paella, gazpacho y tortilla", "Sopa y ensalada", "Pasta y pizza", "Solo postres"], answers: ["Paella, gazpacho y tortilla"], explain: "La carta tiene paella, gazpacho y tortilla."),
                            Exercise(id: "es-listen-cena-sorpresa-q3", kind: "written", prompt: "¿Qué piden para beber?", options: [], answers: ["dos jarras de agua", "jarras de agua", "agua"], explain: "Piden dos jarras de agua."),
                            Exercise(id: "es-listen-cena-sorpresa-q4", kind: "choice", prompt: "¿Qué cree Marta al principio?", options: ["Que es una cena normal", "Que es su cumpleaños", "Que Laura no viene", "Que el restaurante está cerrado"], answers: ["Que es una cena normal"], explain: "Cree que es una cena normal con su amiga Laura."),
                            Exercise(id: "es-listen-cena-sorpresa-q5", kind: "written", prompt: "¿A qué hora entra Marta?", options: [], answers: ["a las nueve", "las nueve", "nueve"], explain: "A las nueve, Marta entra en el restaurante."),
                            Exercise(id: "es-listen-cena-sorpresa-q6", kind: "choice", prompt: "¿Quién trae el pastel?", options: ["El camarero", "Laura", "Un amigo", "La madre de Marta"], answers: ["El camarero"], explain: "El camarero trae un pastel con velas.")], skills: ["listening:gist", "listening:detail", "vocab:food", "function:order-food"]),
    ListeningText(id: "es-listen-plan-cumpleanos", languageID: "es", title: "El plan del cumpleaños", level: "A2", topic: "planes", unitID: "es-foundations-u18",
        text: "Marta llama a Daniel para organizar el cumpleaños de su amiga Vega, que es el jueves. Marta va a reservar una mesa en un restaurante mexicano, pero prefiere preguntar primero si Vega puede ese día. Daniel se va a encargar del regalo: va a comprarle unos libros, porque Vega lee muchísimo. Van a quedar a las nueve en la puerta del restaurante, y Daniel va a llegar un poco antes con el regalo escondido en la mochila. Marta se ríe: si Vega pregunta por qué van al restaurante, van a decirle que es porque sí.",
        questions: [
                            Exercise(id: "es-listen-plan-cumpleanos-q1", kind: "choice", prompt: "¿De quién es el cumpleaños?", options: ["De Vega", "De Marta", "De Daniel", "De la madre de Marta"], answers: ["De Vega"], explain: "Es el cumpleaños de Vega, la amiga de Marta."),
                            Exercise(id: "es-listen-plan-cumpleanos-q2", kind: "written", prompt: "¿Qué va a hacer Marta primero?", options: [], answers: ["reservar una mesa", "reservar mesa", "va a reservar una mesa"], explain: "Marta va a reservar una mesa en un restaurante mexicano."),
                            Exercise(id: "es-listen-plan-cumpleanos-q3", kind: "choice", prompt: "¿Qué va a comprarle Daniel?", options: ["Unos libros", "Una mochila", "Una mesa", "Un pastel"], answers: ["Unos libros"], explain: "Va a comprarle unos libros, porque Vega lee muchísimo."),
                            Exercise(id: "es-listen-plan-cumpleanos-q4", kind: "choice", prompt: "¿Por qué elige Daniel libros?", options: ["Porque Vega lee muchísimo", "Porque son baratos", "Porque no hay tiendas", "Porque Vega lo pide"], answers: ["Porque Vega lee muchísimo"], explain: "«…porque Vega lee muchísimo»."),
                            Exercise(id: "es-listen-plan-cumpleanos-q5", kind: "written", prompt: "¿A qué hora van a quedar?", options: [], answers: ["a las nueve", "las nueve", "nueve"], explain: "Van a quedar a las nueve en la puerta del restaurante."),
                            Exercise(id: "es-listen-plan-cumpleanos-q6", kind: "choice", prompt: "¿Dónde va a esconder Daniel el regalo?", options: ["En la mochila", "En el coche", "En el restaurante", "En casa de Marta"], answers: ["En la mochila"], explain: "Con el regalo escondido en la mochila.")], skills: ["listening:gist", "listening:detail", "grammar:going-to", "vocab:social-expressions"]),
    ListeningText(id: "es-listen-anecdota-verano", languageID: "es", title: "La anécdota del concierto", level: "B1", topic: "anécdotas", unitID: "es-foundations-u19",
        text: "Marcos cuenta su anécdota del verano. «Pues mira, fui a un concierto en Valencia con mi prima. Llegamos con mucha antelación y comimos en un bar cerca. De repente, mi prima gritó: ¡el ticket! Lo dejó en el bar, así que volvió corriendo mientras yo guardaba el sitio en la cola. Resultó que un camarero encontró el ticket y me lo trajo hasta el recinto. Al final, mi prima entró justo a tiempo y la banda estrenó su canción favorita. Cuando se lo conté a mi madre, no me creyó: dijo que esas cosas solo me pasan a mí».",
        questions: [
                            Exercise(id: "es-listen-anecdota-verano-q1", kind: "choice", prompt: "¿Dónde pasó la anécdota?", options: ["En Valencia", "En el bar", "En casa de su madre", "En un pueblo"], answers: ["En Valencia"], explain: "«Fui a un concierto en Valencia con mi prima»."),
                            Exercise(id: "es-listen-anecdota-verano-q2", kind: "written", prompt: "¿Qué se dejó la prima en el bar?", options: [], answers: ["el ticket", "El ticket", "la entrada"], explain: "«¡El ticket! Lo dejó en el bar»."),
                            Exercise(id: "es-listen-anecdota-verano-q3", kind: "choice", prompt: "¿Quién encontró el ticket?", options: ["Un camarero", "La madre de Marcos", "Un guardia", "La prima"], answers: ["Un camarero"], explain: "«Resultó que un camarero encontró el ticket»."),
                            Exercise(id: "es-listen-anecdota-verano-q4", kind: "choice", prompt: "¿Qué hizo Marcos mientras su prima volvía?", options: ["Guardó el sitio en la cola", "Volvió al bar", "Compró otro ticket", "Entró sin ticket"], answers: ["Guardó el sitio en la cola"], explain: "«Volvió corriendo mientras yo guardaba el sitio en la cola»."),
                            Exercise(id: "es-listen-anecdota-verano-q5", kind: "written", prompt: "¿Qué canción sonó al final?", options: [], answers: ["su canción favorita", "la canción favorita", "canción favorita"], explain: "«La banda estrenó su canción favorita»."),
                            Exercise(id: "es-listen-anecdota-verano-q6", kind: "choice", prompt: "¿Cómo reaccionó la madre?", options: ["No le creyó", "Se enfadó", "Lloró", "Fue al concierto"], answers: ["No le creyó"], explain: "«No me creyó: esas cosas solo me pasan a mí».")], skills: ["listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors"]),
    ListeningText(id: "es-listen-debate-tacto", languageID: "es", title: "Discrepar sin romper", level: "C1", topic: "debate", unitID: "es-foundations-u10",
        text: "En el programa «Contrapunto», dos invitados debaten sobre prohibir los coches en el centro. «Creo que la medida es necesaria; la contaminación se ha doblado», arranca Elena. «Entiendo tu punto, pero la gente vive en el centro de paso: primero el transporte público», responde Juan. «Es discutible —matiza ella—, precisamente porque el bus ya duplica su frecuencia». El moderador interviene: «Veo por dónde van ambos: de acuerdo en el fondo, no en el calendario». Juan sonríe: «No lo veo así, pero prometo no volver a aparcar en la plaza». Elena remata: «Y yo prometo no dar nunca más por cerrado un debate a las diez de la noche».",
        questions: [
                            Exercise(id: "es-listen-debate-tacto-q1", kind: "choice", prompt: "¿Qué se debate?", options: ["Prohibir los coches en el centro", "El precio del bus", "La contaminación de la playa", "El calendario escolar"], answers: ["Prohibir los coches en el centro"], explain: "Debaten sobre prohibir los coches en el centro."),
                            Exercise(id: "es-listen-debate-tacto-q2", kind: "choice", prompt: "¿Cuál es la postura de Elena?", options: ["La medida es necesaria", "Primero el transporte público", "No hay contaminación", "Es discutible"], answers: ["La medida es necesaria"], explain: "«La medida es necesaria; la contaminación se ha doblado»."),
                            Exercise(id: "es-listen-debate-tacto-q3", kind: "choice", prompt: "¿Cómo responde Juan a Elena?", options: ["«Entiendo tu punto, pero…»", "«No me interesa tu opinión»", "«Estás equivocada por completo»", "«Cambiemos de tema»"], answers: ["«Entiendo tu punto, pero…»"], explain: "«Entiendo tu punto, pero la gente vive en el centro de paso»."),
                            Exercise(id: "es-listen-debate-tacto-q4", kind: "written", prompt: "¿Por qué dice Elena que es discutible?", options: [], answers: ["porque el bus ya duplica su frecuencia", "el bus ya duplica su frecuencia", "porque el bus duplica su frecuencia"], explain: "«Es discutible, precisamente porque el bus ya duplica su frecuencia»."),
                            Exercise(id: "es-listen-debate-tacto-q5", kind: "choice", prompt: "¿En qué están de acuerdo ambos, según el moderador?", options: ["En el fondo, no en el calendario", "En nada", "En el precio del transporte", "En prohibir todo"], answers: ["En el fondo, no en el calendario"], explain: "«De acuerdo en el fondo, no en el calendario»."),
                            Exercise(id: "es-listen-debate-tacto-q6", kind: "choice", prompt: "¿Qué tono tiene el debate al final?", options: ["Cordial, con humor", "Enfrentado", "Triste", "Indiferente"], answers: ["Cordial, con humor"], explain: "Las promesas con humor cierran el debate en tono cordial.")], skills: ["listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "es-listen-tertulia-viernes", languageID: "es", title: "La tertulia del viernes", level: "A1", topic: "visitas", unitID: "es-foundations-u20",
        text: "Los viernes, Paula visita a su vecina Carmen. Llama a la puerta y dice: «¿Puedo pasar?». Carmen responde: «¡Pasa, pasa!». Paula siempre trae un detalle: hoy trae unas magdalenas. Carmen pregunta: «¿Un café?». Paula dice que sí. Las dos hablan en el salón, junto a la ventana. A las nueve, Paula se despide: «Gracias por todo, Carmen. Hasta la próxima». Carmen le da un beso y contesta: «De nada. Nos vemos el viernes».",
        questions: [
                            Exercise(id: "es-listen-tertulia-viernes-q1", kind: "choice", prompt: "¿Quién visita a Carmen?", options: ["Paula", "Su vecina", "El hijo de Carmen", "Un camarero"], answers: ["Paula"], explain: "Los viernes, Paula visita a su vecina Carmen."),
                            Exercise(id: "es-listen-tertulia-viernes-q2", kind: "choice", prompt: "¿Qué dice Paula en la puerta?", options: ["¿Puedo pasar?", "¿Dónde está el baño?", "Hasta la próxima", "¿Un café?"], answers: ["¿Puedo pasar?"], explain: "Llama a la puerta y dice: «¿Puedo pasar?»."),
                            Exercise(id: "es-listen-tertulia-viernes-q3", kind: "written", prompt: "¿Qué trae Paula hoy?", options: [], answers: ["unas magdalenas", "magdalenas", "magdalenas para Carmen"], explain: "Paula siempre trae un detalle: hoy trae unas magdalenas."),
                            Exercise(id: "es-listen-tertulia-viernes-q4", kind: "choice", prompt: "¿Qué acepta Paula?", options: ["Un café", "Un té", "Un agua", "Un pastel"], answers: ["Un café"], explain: "Carmen pregunta: «¿Un café?». Paula dice que sí."),
                            Exercise(id: "es-listen-tertulia-viernes-q5", kind: "written", prompt: "¿A qué hora se despide Paula?", options: [], answers: ["a las nueve", "las nueve", "nueve"], explain: "A las nueve, Paula se despide."),
                            Exercise(id: "es-listen-tertulia-viernes-q6", kind: "choice", prompt: "¿Qué contesta Carmen al final?", options: ["De nada. Nos vemos el viernes", "Hasta mañana", "Hoy no puedo", "El café es para Paula"], answers: ["De nada. Nos vemos el viernes"], explain: "Carmen contesta: «De nada. Nos vemos el viernes».")], skills: ["listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can"]),
    ListeningText(id: "es-listen-reclamo-factura", languageID: "es", title: "El reclamo de la factura", level: "A2", topic: "reclamos", unitID: "es-foundations-u21",
        text: "Ayer Laura compró una lámpara nueva por internet. El pedido llegó el jueves, pero la factura venía con un error: cobraban dos lámparas y ella solo compró una. Laura decidió reclamar. Buscó el teléfono de la tienda y llamó por la mañana. «Buenas tardes, quiero reclamar una factura», dijo con calma. La dependienta le pidió el número de pedido y revisó los datos. «Tiene razón, es nuestro error», respondió. Le mandó una factura correcta por email y la tienda devolvió la diferencia al día siguiente. Laura colgó contenta: el problema se arregló en diez minutos.",
        questions: [
                            Exercise(id: "es-listen-reclamo-factura-q1", kind: "choice", prompt: "¿Qué compró Laura ayer?", options: ["Una lámpara", "Dos facturas", "Un teléfono", "Una mesa"], answers: ["Una lámpara"], explain: "Ayer Laura compró una lámpara nueva por internet."),
                            Exercise(id: "es-listen-reclamo-factura-q2", kind: "choice", prompt: "¿Cuál era el error de la factura?", options: ["Cobraban dos lámparas", "No llegó el pedido", "El precio era más bajo", "Faltaba la dirección"], answers: ["Cobraban dos lámparas"], explain: "La factura venía con un error: cobraban dos lámparas y ella solo compró una."),
                            Exercise(id: "es-listen-reclamo-factura-q3", kind: "written", prompt: "¿Cuándo llamó Laura a la tienda?", options: [], answers: ["por la mañana", "la mañana", "por la manana"], explain: "Buscó el teléfono de la tienda y llamó por la mañana."),
                            Exercise(id: "es-listen-reclamo-factura-q4", kind: "written", prompt: "¿Qué le pidió la dependienta?", options: [], answers: ["el número de pedido", "el numero de pedido", "número de pedido"], explain: "La dependienta le pidió el número de pedido y revisó los datos."),
                            Exercise(id: "es-listen-reclamo-factura-q5", kind: "choice", prompt: "¿Qué hizo la tienda con la diferencia?", options: ["La devolvió al día siguiente", "La guardó para otra compra", "No hizo nada", "Se la cobró a Laura"], answers: ["La devolvió al día siguiente"], explain: "La tienda devolvió la diferencia al día siguiente."),
                            Exercise(id: "es-listen-reclamo-factura-q6", kind: "choice", prompt: "¿Cómo terminó el problema?", options: ["Se arregló en diez minutos", "Se arregló un mes después", "Laura volvió a la tienda", "Quedó sin solución"], answers: ["Se arregló en diez minutos"], explain: "Laura colgó contenta: el problema se arregló en diez minutos.")], skills: ["listening:gist", "listening:detail", "function:solve-problems", "grammar:past-simple-regular"]),
    ListeningText(id: "es-listen-entrevista-practica", languageID: "es", title: "La entrevista de práctica", level: "B1", topic: "entrevistas", unitID: "es-foundations-u22",
        text: "Nora prepara una entrevista con su amigo Sergio, que trabaja en recursos humanos. «Cuéntame tu experiencia», pide él. «He trabajado cinco años en una agencia; llevo dos proyectos grandes a mis espaldas», responde Nora. «¿Y tu punto fuerte?». «Destaco en el trabajo en equipo; además, me queda mucho por aprender, y eso me gusta». Sergio sonríe: «Eso último suena honesto, no lo dejes fuera». «¿Por eso te contrataron a ti?», pregunta ella. «Yo llegué aquí por exactamente esa frase», contesta él. Al despedirse, Sergio le da un consejo: «Buscan a alguien con experiencia, pero sobre todo a alguien con ganas».",
        questions: [
                            Exercise(id: "es-listen-entrevista-practica-q1", kind: "choice", prompt: "¿A qué se dedica Sergio?", options: ["Trabaja en recursos humanos", "Es candidato a un puesto", "Trabaja en una agencia", "Es el jefe de Nora"], answers: ["Trabaja en recursos humanos"], explain: "Sergio es su amigo y trabaja en recursos humanos."),
                            Exercise(id: "es-listen-entrevista-practica-q2", kind: "written", prompt: "¿Cuántos años trabajó Nora en la agencia?", options: [], answers: ["cinco años", "5 años", "cinco"], explain: "«He trabajado cinco años en una agencia»."),
                            Exercise(id: "es-listen-entrevista-practica-q3", kind: "choice", prompt: "¿Cuál es el punto fuerte de Nora?", options: ["El trabajo en equipo", "Los idiomas", "La experiencia en ventas", "Hablar en público"], answers: ["El trabajo en equipo"], explain: "«Destaco en el trabajo en equipo»."),
                            Exercise(id: "es-listen-entrevista-practica-q4", kind: "choice", prompt: "¿Qué le aconseja Sergio sobre admitir que le queda mucho por aprender?", options: ["Que suena honesto y no lo quite", "Que lo esconda en la entrevista", "Que lo cambie por idiomas", "Que lo repita varias veces"], answers: ["Que suena honesto y no lo quite"], explain: "«Eso último suena honesto, no lo dejes fuera»."),
                            Exercise(id: "es-listen-entrevista-practica-q5", kind: "written", prompt: "Según Sergio, ¿por qué le contrataron a él?", options: [], answers: ["por exactamente esa frase", "por esa frase", "porque dijo esa frase"], explain: "«Yo llegué aquí por exactamente esa frase»."),
                            Exercise(id: "es-listen-entrevista-practica-q6", kind: "choice", prompt: "¿Qué buscan más las empresas, según el consejo de Sergio?", options: ["Experiencia y, sobre todo, ganas", "Solo experiencia", "Solo títulos e idiomas", "Candidatos con contactos"], answers: ["Experiencia y, sobre todo, ganas"], explain: "«Buscan a alguien con experiencia, pero sobre todo a alguien con ganas».")], skills: ["listening:inference", "listening:detail", "vocab:work", "function:talk-about-work"]),
    ListeningText(id: "es-listen-tono-podcast", languageID: "es", title: "Cuestión de tono", level: "C1", topic: "lenguaje", unitID: "es-foundations-u10",
        text: "En «Dicho y hecho», Marta y Diego debaten sobre las palabras que eligen los hablantes. «Hoy he oído \"extraño muchísimo mi pueblo\" en un anuncio y me ha sonado a postal», dice Marta. «¿Qué tendría que decir?», pregunta Diego. «Pues \"echo de menos\", que ya es decirlo con el cuerpo». «Yo diría que son equivalentes; una collocation no lleva pasaporte». «No obstante, fíjate: \"tomar una decisión\" pesa más que \"decidir\"; la fórmula larga ya avisa de que lo has pensado». «De acuerdo en parte: la lengua pinta tonos, pero el hablante elige el pincel». «Precisamente por eso insisto: no digas \"hacer una decisión\"». «Eso sí, ahí te doy toda la razón: esa sí que es un crimen».",
        questions: [
                            Exercise(id: "es-listen-tono-podcast-q1", kind: "choice", prompt: "¿Por qué el anuncio le suena «a postal» a Marta?", options: ["Por el uso de extrañar", "Porque es demasiado largo", "Porque dice echo de menos", "Porque no se entiende"], answers: ["Por el uso de extrañar"], explain: "«He oído extraño muchísimo mi pueblo… y me ha sonado a postal»."),
                            Exercise(id: "es-listen-tono-podcast-q2", kind: "choice", prompt: "¿Qué piensa Diego de las dos formas de echar en falta?", options: ["Que son equivalentes", "Que extrañar es un error", "Que hay que usarlas juntas", "Que ninguna suena natural"], answers: ["Que son equivalentes"], explain: "«Yo diría que son equivalentes; una collocation no lleva pasaporte»."),
                            Exercise(id: "es-listen-tono-podcast-q3", kind: "written", prompt: "Según Marta, ¿qué avisa ya la fórmula «tomar una decisión»?", options: [], answers: ["que lo has pensado", "que lo has meditado", "avisa de que lo has pensado"], explain: "«La fórmula larga ya avisa de que lo has pensado»."),
                            Exercise(id: "es-listen-tono-podcast-q4", kind: "written", prompt: "¿Qué expresión rechaza Marta y llama crimen?", options: [], answers: ["hacer una decisión", "hacer una decision", "hacer una decisión "], explain: "«Precisamente por eso insisto: no digas hacer una decisión»."),
                            Exercise(id: "es-listen-tono-podcast-q5", kind: "choice", prompt: "¿Cómo se cierra la conversación?", options: ["En acuerdo total sobre un punto", "En desacuerdo total", "Sin ninguna conclusión", "Con una discusión nueva"], answers: ["En acuerdo total sobre un punto"], explain: "«Eso sí, ahí te doy toda la razón: esa sí que es un crimen»."),
                            Exercise(id: "es-listen-tono-podcast-q6", kind: "choice", prompt: "¿Cuál es la postura final de Diego sobre las collocations?", options: ["La lengua pinta tonos, pero elige el hablante", "La lengua decide siempre", "Las collocations no pintan nada", "Solo importan los diccionarios"], answers: ["La lengua pinta tonos, pero elige el hablante"], explain: "«La lengua pinta tonos, pero el hablante elige el pincel».")], skills: ["listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion"]),
    ListeningText(id: "es-listen-cumple-sorpresa", languageID: "es", title: "La fiesta sorpresa de Pablo", level: "A1", topic: "cumpleaños", unitID: "es-foundations-u23",
        text: "Hoy es el cumpleaños de Pablo y preparamos una fiesta sorpresa en casa de Lucía. Yo llevo el pastel y Lucía pone los globos y las velas. Los invitados llegan a las ocho: traen regalos y música. Pablo llega a las ocho y media y abrimos la puerta: «¡Sorpresa!». Pablo está muy contento y abre los regalos: un libro de cocina y una bufanda. Después cantamos, comemos pastel y bebemos limonada. ¡Qué fiesta tan buena!",
        questions: [
                            Exercise(id: "es-listen-cumple-sorpresa-q1", kind: "choice", prompt: "¿De quién es el cumpleaños?", options: ["De Pablo", "De Lucía", "Del narrador", "De la madre"], answers: ["De Pablo"], explain: "Hoy es el cumpleaños de Pablo y preparamos una fiesta sorpresa."),
                            Exercise(id: "es-listen-cumple-sorpresa-q2", kind: "choice", prompt: "¿Qué lleva el narrador a la fiesta?", options: ["El pastel", "Los globos", "La música", "Los regalos"], answers: ["El pastel"], explain: "Yo llevo el pastel y Lucía pone los globos y las velas."),
                            Exercise(id: "es-listen-cumple-sorpresa-q3", kind: "written", prompt: "¿A qué hora llega Pablo?", options: [], answers: ["a las ocho y media", "ocho y media", "a las 8 y media"], explain: "Pablo llega a las ocho y media y abrimos la puerta."),
                            Exercise(id: "es-listen-cumple-sorpresa-q4", kind: "choice", prompt: "¿Qué regalos recibe Pablo?", options: ["Un libro de cocina y una bufanda", "Un pastel y unos globos", "Una bufanda y música", "Un libro y unas velas"], answers: ["Un libro de cocina y una bufanda"], explain: "Abre los regalos: un libro de cocina y una bufanda."),
                            Exercise(id: "es-listen-cumple-sorpresa-q5", kind: "written", prompt: "¿Qué beben en la fiesta?", options: [], answers: ["limonada"], explain: "Comemos pastel y bebemos limonada."),
                            Exercise(id: "es-listen-cumple-sorpresa-q6", kind: "choice", prompt: "¿Cómo está Pablo con la sorpresa?", options: ["Muy contento", "Triste", "Enfadado", "Cansado"], answers: ["Muy contento"], explain: "Pablo está muy contento y abre los regalos.")], skills: ["listening:gist", "listening:detail", "vocab:social-expressions", "grammar:present-simple"]),
    ListeningText(id: "es-listen-probador", languageID: "es", title: "La camiseta del probador", level: "A1", topic: "tiendas de ropa", unitID: "es-foundations-u24",
        text: "Ana entra en una tienda de ropa y busca una camiseta azul. «Buenas tardes, ¿tiene esta camiseta en talla M?», pregunta. «Sí, aquí tiene. ¿La quiere en azul o en negro?», responde el dependiente. «La quiero en azul, gracias». Ana va al probador: la camiseta le queda un poco grande. «¿Me da una talla más pequeña, por favor?», pide. El dependiente trae la talla S y ahora queda perfecta. «¿Cuánto es?», pregunta Ana. «Son quince euros», responde él. «Aquí tiene. Pago en efectivo».",
        questions: [
                            Exercise(id: "es-listen-probador-q1", kind: "choice", prompt: "¿Qué busca Ana?", options: ["Una camiseta azul", "Un pantalón negro", "Una falda verde", "Un jersey blanco"], answers: ["Una camiseta azul"], explain: "Ana entra en una tienda de ropa y busca una camiseta azul."),
                            Exercise(id: "es-listen-probador-q2", kind: "written", prompt: "¿Qué talla pide Ana primero?", options: [], answers: ["la talla m", "talla m", "la m"], explain: "«Buenas tardes, ¿tiene esta camiseta en talla M?», pregunta."),
                            Exercise(id: "es-listen-probador-q3", kind: "choice", prompt: "¿Cómo le queda la talla M?", options: ["Un poco grande", "Un poco pequeña", "Perfecta", "Muy corta"], answers: ["Un poco grande"], explain: "La camiseta le queda un poco grande."),
                            Exercise(id: "es-listen-probador-q4", kind: "written", prompt: "¿Qué talla trae el dependiente al final?", options: [], answers: ["la talla s", "la s", "talla s"], explain: "El dependiente trae la talla S y ahora queda perfecta."),
                            Exercise(id: "es-listen-probador-q5", kind: "choice", prompt: "¿Cuánto cuesta la camiseta?", options: ["Quince euros", "Cincuenta euros", "Cinco euros", "Veinticinco euros"], answers: ["Quince euros"], explain: "«Son quince euros», responde él."),
                            Exercise(id: "es-listen-probador-q6", kind: "choice", prompt: "¿Cómo paga Ana?", options: ["En efectivo", "Con tarjeta", "Con un cheque", "A plazos"], answers: ["En efectivo"], explain: "«Aquí tiene. Pago en efectivo».")], skills: ["listening:gist", "listening:detail", "function:go-shopping", "vocab:shopping"]),
    ListeningText(id: "es-listen-devolucion", languageID: "es", title: "La devolución de la cafetera", level: "A2", topic: "compras", unitID: "es-foundations-u25",
        text: "El martes, Sergio compró una cafetera nueva en la tienda ElectroSur. La usó por la mañana, pero el agua no calentaba. Entonces volvió a la tienda con el recibo. «Buenos días, compré esta cafetera ayer, pero no funciona. Quiero devolverla», explicó. La dependienta revisó el recibo y preguntó: «¿Prefiere el dinero o un cambio?». «Prefiero el dinero, gracias», contestó Sergio. La dependienta devolvió los cuarenta y cinco euros a su tarjeta. «En dos o tres días, el banco lo devuelve a su cuenta», avisó. Sergio salió tranquilo: el problema se solucionó en diez minutos.",
        questions: [
                            Exercise(id: "es-listen-devolucion-q1", kind: "choice", prompt: "¿Qué compró Sergio el martes?", options: ["Una cafetera", "Una lámpara", "Un portátil", "Una tostadora"], answers: ["Una cafetera"], explain: "El martes, Sergio compró una cafetera nueva en la tienda ElectroSur."),
                            Exercise(id: "es-listen-devolucion-q2", kind: "choice", prompt: "¿Cuál era el problema?", options: ["El agua no calentaba", "La jarra se rompió", "No llegó el recibo", "Era muy cara"], answers: ["El agua no calentaba"], explain: "La usó por la mañana, pero el agua no calentaba."),
                            Exercise(id: "es-listen-devolucion-q3", kind: "written", prompt: "¿Qué pidió Sergio en la tienda?", options: [], answers: ["devolverla", "quiero devolverla", "la devolución"], explain: "Compré esta cafetera ayer, pero no funciona. Quiero devolverla."),
                            Exercise(id: "es-listen-devolucion-q4", kind: "choice", prompt: "¿Qué prefirió Sergio?", options: ["El dinero", "Un cambio", "Otra cafetera", "Un vale"], answers: ["El dinero"], explain: "«¿Prefiere el dinero o un cambio?». «Prefiero el dinero, gracias»."),
                            Exercise(id: "es-listen-devolucion-q5", kind: "written", prompt: "¿Cuánto devolvieron a su tarjeta?", options: [], answers: ["cuarenta y cinco euros", "45 euros", "cuarenta y cinco"], explain: "La dependienta devolvió los cuarenta y cinco euros a su tarjeta."),
                            Exercise(id: "es-listen-devolucion-q6", kind: "choice", prompt: "¿Cuándo verá Sergio el dinero en su cuenta?", options: ["En dos o tres días", "Al día siguiente", "En diez minutos", "En un mes"], answers: ["En dos o tres días"], explain: "«En dos o tres días, el banco lo devuelve a su cuenta», avisó.")], skills: ["listening:detail", "listening:gist", "function:solve-problems", "grammar:past-simple-regular"]),
    ListeningText(id: "es-listen-maleta-vispera", languageID: "es", title: "La víspera del viaje", level: "A2", topic: "viajes", unitID: "es-foundations-u26",
        text: "Mañana Elena y su familia van a viajar a Roma, y hoy es la víspera. Por la tarde, Elena va a preparar la maleta: lleva ropa ligera, dos libros y el cargador. Su hijo va a revisar los documentos: los pasaportes y las tarjetas de embarque. «No olvides el adaptador», le dice ella. Después de cenar, el vecino va a venir a por las llaves para regar las plantas. Todos madrugan, porque el vuelo sale a las siete y media. «Ya está todo listo», dice Elena. «Solo falta dormir».",
        questions: [
                            Exercise(id: "es-listen-maleta-vispera-q1", kind: "choice", prompt: "¿A dónde van a viajar?", options: ["A Roma", "A Lisboa", "A París", "A Londres"], answers: ["A Roma"], explain: "Mañana Elena y su familia van a viajar a Roma."),
                            Exercise(id: "es-listen-maleta-vispera-q2", kind: "written", prompt: "¿Quién va a revisar los documentos?", options: [], answers: ["su hijo", "el hijo", "hijo"], explain: "Su hijo va a revisar los documentos: los pasaportes y las tarjetas de embarque."),
                            Exercise(id: "es-listen-maleta-vispera-q3", kind: "choice", prompt: "¿Qué no debe olvidar Elena?", options: ["El adaptador", "El pasaporte", "Los libros", "Las llaves"], answers: ["El adaptador"], explain: "«No olvides el adaptador», le dice ella."),
                            Exercise(id: "es-listen-maleta-vispera-q4", kind: "written", prompt: "¿Para qué viene el vecino a por las llaves?", options: [], answers: ["para regar las plantas", "regar las plantas"], explain: "El vecino va a venir a por las llaves para regar las plantas."),
                            Exercise(id: "es-listen-maleta-vispera-q5", kind: "choice", prompt: "¿A qué hora sale el vuelo?", options: ["A las siete y media", "A las siete", "A las ocho y media", "A las seis y media"], answers: ["A las siete y media"], explain: "Todos madrugan, porque el vuelo sale a las siete y media."),
                            Exercise(id: "es-listen-maleta-vispera-q6", kind: "choice", prompt: "¿Por qué madrugan todos?", options: ["Porque el vuelo sale temprano", "Porque el vecino llega pronto", "Porque quieren desayunar", "Porque la maleta está pesada"], answers: ["Porque el vuelo sale temprano"], explain: "Todos madrugan, porque el vuelo sale a las siete y media.")], skills: ["listening:gist", "listening:detail", "grammar:going-to", "vocab:travel"]),
    ListeningText(id: "es-listen-barrio-que-quiero", languageID: "es", title: "El barrio que queremos", level: "B1", topic: "barrio", unitID: "es-foundations-u27",
        text: "—¿Has visto la nueva plaza del barrio? ¿Qué te parece?\n—En mi opinión, ha mejorado mucho. Por un lado, hay más zonas verdes; por otro, apenas hay bancos para sentarse.\n—Estoy de acuerdo. Además, el tráfico de la avenida sigue siendo un problema: lo que más me molesta es el ruido por la noche.\n—Por eso propongo escribir al ayuntamiento: pedimos carriles bici y más árboles.\n—Buena idea. Y yo añado un mercado de segunda mano el sábado: así consumimos menos y compramos más barato.\n—Me parece perfecta. ¿La firmamos con los vecinos?\n—Claro. Si somos muchos, creo que nos van a escuchar.",
        questions: [
                            Exercise(id: "es-listen-barrio-que-quiero-q1", kind: "choice", prompt: "¿Qué opina el primer hablante de la plaza?", options: ["Ha mejorado mucho", "Ha empeorado", "No ha cambiado", "Le da igual"], answers: ["Ha mejorado mucho"], explain: "En mi opinión, ha mejorado mucho."),
                            Exercise(id: "es-listen-barrio-que-quiero-q2", kind: "choice", prompt: "¿Qué falta en la plaza?", options: ["Bancos para sentarse", "Zonas verdes", "Árboles", "Luz"], answers: ["Bancos para sentarse"], explain: "Por otro, apenas hay bancos para sentarse."),
                            Exercise(id: "es-listen-barrio-que-quiero-q3", kind: "written", prompt: "¿Qué es lo que más molesta al segundo hablante?", options: [], answers: ["el ruido por la noche", "el ruido", "ruido por la noche"], explain: "Lo que más me molesta es el ruido por la noche."),
                            Exercise(id: "es-listen-barrio-que-quiero-q4", kind: "choice", prompt: "¿Qué piden al ayuntamiento?", options: ["Carriles bici y más árboles", "Un mercado nuevo", "Más bancos", "Menos ruido"], answers: ["Carriles bici y más árboles"], explain: "Pedimos carriles bici y más árboles."),
                            Exercise(id: "es-listen-barrio-que-quiero-q5", kind: "written", prompt: "¿Qué proponen para el sábado?", options: [], answers: ["un mercado de segunda mano", "mercado de segunda mano"], explain: "Y yo añado un mercado de segunda mano el sábado."),
                            Exercise(id: "es-listen-barrio-que-quiero-q6", kind: "choice", prompt: "¿Por qué creen que el ayuntamiento les va a escuchar?", options: ["Porque serán muchos firmantes", "Porque son famosos", "Porque pagan una tasa", "Porque el alcalde es vecino"], answers: ["Porque serán muchos firmantes"], explain: "Si somos muchos, creo que nos van a escuchar.")], skills: ["listening:inference", "listening:detail", "function:express-opinion", "grammar:connectors"]),
    ListeningText(id: "es-listen-reunion-practica", languageID: "es", title: "La reunión del horario", level: "B1", topic: "reuniones", unitID: "es-work-u1",
        text: "—Buenos días a todos. Hoy tenemos que decidir el nuevo horario del equipo. Marta, ¿tú qué opinas?\n—En mi opinión, entrar a las nueve y salir a las cinco funciona mejor. He hablado con los clientes y no hay problema.\n—Yo estoy de acuerdo, pero propongo una semana de prueba antes. Así vemos los resultados reales.\n—Por un lado, la prueba lleva tiempo; por otro, es lo más prudente. ¿Qué os parece si la empezamos el lunes?\n—A mí me parece bien. ¿Quién prepara el resumen para la dirección?\n—Me encargo yo. Les escribo esta tarde y adjunto los datos de la encuesta.\n—Perfecto. Entonces, votamos el viernes y cerramos la decisión.",
        questions: [
                            Exercise(id: "es-listen-reunion-practica-q1", kind: "choice", prompt: "¿Qué decisión deben tomar en la reunión?", options: ["El nuevo horario", "El nuevo jefe", "Las vacaciones", "El presupuesto"], answers: ["El nuevo horario"], explain: "Hoy tenemos que decidir el nuevo horario del equipo."),
                            Exercise(id: "es-listen-reunion-practica-q2", kind: "choice", prompt: "¿Qué horario propone Marta?", options: ["Entrar a las nueve", "Entrar a las ocho", "Trabajar desde casa", "Horario a turnos"], answers: ["Entrar a las nueve"], explain: "En mi opinión, entrar a las nueve y salir a las cinco funciona mejor."),
                            Exercise(id: "es-listen-reunion-practica-q3", kind: "written", prompt: "¿Qué propone el segundo hablante antes de decidir?", options: [], answers: ["una semana de prueba", "una prueba", "semana de prueba"], explain: "Yo estoy de acuerdo, pero propongo una semana de prueba antes."),
                            Exercise(id: "es-listen-reunion-practica-q4", kind: "choice", prompt: "¿Cuándo empezaría la prueba?", options: ["El lunes", "El martes", "El jueves", "El viernes"], answers: ["El lunes"], explain: "¿Qué os parece si la empezamos el lunes?"),
                            Exercise(id: "es-listen-reunion-practica-q5", kind: "written", prompt: "¿Qué enviará a la dirección y cuándo?", options: [], answers: ["los datos de la encuesta esta tarde", "los datos esta tarde", "los datos de la encuesta"], explain: "Les escribo esta tarde y adjunto los datos de la encuesta."),
                            Exercise(id: "es-listen-reunion-practica-q6", kind: "choice", prompt: "¿Cuándo cierran la decisión?", options: ["El viernes", "El lunes", "Esta tarde", "El miércoles"], answers: ["El viernes"], explain: "Entonces, votamos el viernes y cerramos la decisión.")], skills: ["listening:detail", "listening:inference", "function:talk-about-work", "grammar:connectors"]),
    ListeningText(id: "es-listen-picnic-lluvia", languageID: "es", title: "El picnic de la lluvia", level: "A2", topic: "planes", unitID: "es-foundations-u18",
        text: "El sábado, Pablo y Lucía organizaron un picnic en el parque, pero por la mañana llovió muchísimo. Pablo llamó a Lucía: «Qué pena, hoy no podemos hacer el picnic». Lucía pensó una solución: «¿Por qué no lo dejamos para mañana? Por la tarde estoy libre, así que podemos ir sobre las dos». Pablo va a preparar las empanadas y Lucía va a llevar el batido y la manta. Van a quedar a las dos en la entrada del parque. Y si mañana también llueve, van a comer el picnic en casa de Pablo, que tiene un salón muy grande.",
        questions: [
                            Exercise(id: "es-listen-picnic-lluvia-q1", kind: "choice", prompt: "¿Qué organizaron Pablo y Lucía el sábado?", options: ["Un picnic", "Una fiesta", "Una excursión", "Una cena"], answers: ["Un picnic"], explain: "Organizaron un picnic en el parque."),
                            Exercise(id: "es-listen-picnic-lluvia-q2", kind: "written", prompt: "¿Por qué no pudieron hacer el picnic el sábado?", options: [], answers: ["porque llovió muchísimo", "llovió muchísimo", "por la lluvia"], explain: "Por la mañana llovió muchísimo."),
                            Exercise(id: "es-listen-picnic-lluvia-q3", kind: "choice", prompt: "¿Para cuándo dejan el picnic?", options: ["Para mañana", "Para la noche", "Para la semana que viene", "No lo dejan"], answers: ["Para mañana"], explain: "«¿Por qué no lo dejamos para mañana?»."),
                            Exercise(id: "es-listen-picnic-lluvia-q4", kind: "choice", prompt: "¿Qué va a llevar Lucía?", options: ["El batido y la manta", "Las empanadas", "La música", "Los vasos"], answers: ["El batido y la manta"], explain: "Lucía va a llevar el batido y la manta."),
                            Exercise(id: "es-listen-picnic-lluvia-q5", kind: "written", prompt: "¿A qué hora van a quedar?", options: [], answers: ["a las dos", "las dos", "a las 2"], explain: "Van a quedar a las dos en la entrada del parque."),
                            Exercise(id: "es-listen-picnic-lluvia-q6", kind: "choice", prompt: "¿Qué van a hacer si mañana también llueve?", options: ["Comer en casa de Pablo", "Ir al cine", "Quedarse en el parque", "Cancelar todo"], answers: ["Comer en casa de Pablo"], explain: "Van a comer el picnic en casa de Pablo.")], skills: ["listening:gist", "listening:detail", "grammar:past-simple-regular", "grammar:going-to"]),
    ListeningText(id: "es-listen-reserva-hostal", languageID: "es", title: "La reserva del hostal", level: "A2", topic: "viajes", unitID: "es-foundations-u26",
        text: "Elena va a viajar a Lisboa el mes que viene, así que llamó a un hostal para confirmar su reserva. «Buenas tardes, tengo una reserva para dos noches, a nombre de Elena Ríos». El recepcionista la buscó en el ordenador: «Sí, aquí está: habitación doble con baño, desde el jueves hasta el sábado». Elena preguntó por el desayuno: está incluido desde las siete de la mañana. Pero hay un problema: su vuelo llega muy tarde, casi a la medianoche. El recepcionista la tranquilizó: «No se preocupe, la guardamos la habitación toda la noche. ¿Nos confirma su número de móvil?».",
        questions: [
                            Exercise(id: "es-listen-reserva-hostal-q1", kind: "choice", prompt: "¿A dónde va a viajar Elena?", options: ["A Lisboa", "A Madrid", "A Sevilla", "A Oporto"], answers: ["A Lisboa"], explain: "Elena va a viajar a Lisboa el mes que viene."),
                            Exercise(id: "es-listen-reserva-hostal-q2", kind: "written", prompt: "¿Para cuántas noches es la reserva?", options: [], answers: ["dos noches", "2 noches", "dos"], explain: "Tiene una reserva para dos noches."),
                            Exercise(id: "es-listen-reserva-hostal-q3", kind: "choice", prompt: "¿Qué habitación reservó Elena?", options: ["Doble con baño", "Individual", "Doble sin baño", "Familiar"], answers: ["Doble con baño"], explain: "Aquí está: habitación doble con baño."),
                            Exercise(id: "es-listen-reserva-hostal-q4", kind: "written", prompt: "¿Desde qué hora está incluido el desayuno?", options: [], answers: ["desde las siete", "las siete", "desde las 7"], explain: "El desayuno está incluido desde las siete."),
                            Exercise(id: "es-listen-reserva-hostal-q5", kind: "choice", prompt: "¿Cuál es el problema de Elena?", options: ["Va a llegar muy tarde", "No tiene reserva", "El hostal cierra el jueves", "El desayuno no está incluido"], answers: ["Va a llegar muy tarde"], explain: "Su vuelo llega muy tarde, casi a la medianoche."),
                            Exercise(id: "es-listen-reserva-hostal-q6", kind: "choice", prompt: "¿Qué le pide el recepcionista al final?", options: ["Su número de móvil", "Su pasaporte", "Una tarjeta de crédito", "Un email"], answers: ["Su número de móvil"], explain: "«¿Nos confirma su número de móvil?».")], skills: ["listening:detail", "listening:gist", "vocab:travel", "grammar:going-to"]),
    ListeningText(id: "es-listen-tren-retrasado", languageID: "es", title: "El tren con retraso", level: "A2", topic: "viajes", unitID: "es-foundations-u26",
        text: "Hoy Andrés va a viajar en tren a Valencia para ver a su hermana. Llegó a la estación con tiempo, pero en el panel apareció una mala noticia: el tren de las ocho va con cuarenta minutos de retraso. Andrés fue a la ventanilla: «Buenos días, mi tren va con retraso y a las once tengo una cita importante. ¿Hay otro tren antes?». La empleada le respondió: «El de las nueve llega antes, pero está lleno; puedo darle un asiento en el de las nueve y media». Andrés aceptó y compró un café para esperar: así llega a las doce, justo para comer con su hermana.",
        questions: [
                            Exercise(id: "es-listen-tren-retrasado-q1", kind: "choice", prompt: "¿A dónde va a viajar Andrés?", options: ["A Valencia", "A Sevilla", "A Bilbao", "A Málaga"], answers: ["A Valencia"], explain: "Andrés va a viajar en tren a Valencia para ver a su hermana."),
                            Exercise(id: "es-listen-tren-retrasado-q2", kind: "written", prompt: "¿Cuánto retraso tiene su tren?", options: [], answers: ["cuarenta minutos", "40 minutos", "cuarenta"], explain: "El tren de las ocho va con cuarenta minutos de retraso."),
                            Exercise(id: "es-listen-tren-retrasado-q3", kind: "choice", prompt: "¿Por qué necesita llegar antes de las once?", options: ["Tiene una cita importante", "Su hermana está enferma", "El hotel cierra a las once", "El tren desaparece"], answers: ["Tiene una cita importante"], explain: "«A las once tengo una cita importante»."),
                            Exercise(id: "es-listen-tren-retrasado-q4", kind: "choice", prompt: "¿Qué le ofrece la empleada?", options: ["Un asiento en el tren de las nueve y media", "Un billete gratis", "Un taxi a la estación", "La devolución del dinero"], answers: ["Un asiento en el tren de las nueve y media"], explain: "Puedo darle un asiento en el de las nueve y media."),
                            Exercise(id: "es-listen-tren-retrasado-q5", kind: "written", prompt: "¿Para qué compra Andrés un café?", options: [], answers: ["para esperar", "esperar"], explain: "Andrés compró un café para esperar."),
                            Exercise(id: "es-listen-tren-retrasado-q6", kind: "choice", prompt: "¿A qué hora va a llegar a Valencia?", options: ["A las doce", "A las once", "A las nueve y media", "A las dos"], answers: ["A las doce"], explain: "Así llega a las doce, justo para comer con su hermana.")], skills: ["listening:detail", "function:solve-problems", "vocab:transport", "grammar:going-to"]),
    ListeningText(id: "es-listen-averia-lavadora", languageID: "es", title: "La lavadora rota", level: "A2", topic: "problemas", unitID: "es-foundations-u21",
        text: "Anoche la lavadora de Carmen hizo un ruido muy raro y después se paró. Esta mañana llamó al servicio técnico. «Buenos días, mi lavadora no funciona. Tiene tres años, ¿entra en garantía?». El dependiente revisó los datos: «Sí, tiene garantía de cinco años, así que la revisión es gratis. Tenemos cita para mañana por la tarde, de cuatro a seis. ¿Le va bien?». Carmen va a salir del trabajo temprano para estar en casa. Antes de colgar, pidió un consejo: «¿La uso hoy?». «Mejor que no», respondió, «y deje las toallas viejas fuera de la máquina: a veces bloquean el filtro».",
        questions: [
                            Exercise(id: "es-listen-averia-lavadora-q1", kind: "choice", prompt: "¿Qué se averió en casa de Carmen?", options: ["La lavadora", "La nevera", "El horno", "La tele"], answers: ["La lavadora"], explain: "Anoche la lavadora de Carmen hizo un ruido raro y se paró."),
                            Exercise(id: "es-listen-averia-lavadora-q2", kind: "written", prompt: "¿Cuántos años tiene la lavadora?", options: [], answers: ["tres", "3", "tres años"], explain: "«Tiene tres años, ¿entra en garantía?»."),
                            Exercise(id: "es-listen-averia-lavadora-q3", kind: "choice", prompt: "¿Cuánto cuesta la revisión?", options: ["Es gratis, por la garantía", "Cuesta cincuenta euros", "Cuesta el doble", "Carmen debe pagar la máquina"], answers: ["Es gratis, por la garantía"], explain: "Tiene garantía de cinco años, así que la revisión es gratis."),
                            Exercise(id: "es-listen-averia-lavadora-q4", kind: "written", prompt: "¿Cuándo es la cita del técnico?", options: [], answers: ["mañana por la tarde", "manana por la tarde", "de cuatro a seis"], explain: "Tenemos cita para mañana por la tarde, de cuatro a seis."),
                            Exercise(id: "es-listen-averia-lavadora-q5", kind: "choice", prompt: "¿Qué consejo le dan a Carmen?", options: ["No usar hoy la lavadora", "Lavar con agua caliente", "Comprar otra máquina", "Quitar el filtro"], answers: ["No usar hoy la lavadora"], explain: "«Mejor que no», respondió, «y deje las toallas viejas fuera».")], skills: ["listening:detail", "function:solve-problems", "grammar:past-simple-regular", "vocab:home"]),
    ListeningText(id: "es-listen-mudanza-finde", languageID: "es", title: "La mudanza del sábado", level: "A2", topic: "planes", unitID: "es-foundations-u7",
        text: "El hermano de Nora encontró un piso en el centro y se va a mudar el sábado. Nora le llamó para ayudar: «¿Qué necesitas?». «Pues una furgoneta: mis muebles no caben en el coche». Nora va a reservar una furgoneta pequeña para la mañana, y su compañero Diego va a llevar las cajas grandes. El problema es la hora: la furgoneta hay que devolverla antes de las seis, así que van a empezar a las ocho de la mañana. Después, todos van a comer pizza en el piso nuevo para celebrarlo. Nora ya sabe qué regalo va a hacerle a su hermano: una planta para el salón.",
        questions: [
                            Exercise(id: "es-listen-mudanza-finde-q1", kind: "choice", prompt: "¿Qué va a hacer el hermano de Nora el sábado?", options: ["Mudarse", "Comprar un coche", "Viajar al centro", "Cambiar de trabajo"], answers: ["Mudarse"], explain: "Encontró un piso en el centro y se va a mudar el sábado."),
                            Exercise(id: "es-listen-mudanza-finde-q2", kind: "written", prompt: "¿Qué necesita para llevar los muebles?", options: [], answers: ["una furgoneta", "furgoneta"], explain: "«Pues una furgoneta: mis muebles no caben en el coche»."),
                            Exercise(id: "es-listen-mudanza-finde-q3", kind: "choice", prompt: "¿Qué va a reservar Nora?", options: ["Una furgoneta pequeña", "Un camión grande", "Un taxi", "Una moto"], answers: ["Una furgoneta pequeña"], explain: "Nora va a reservar una furgoneta pequeña para la mañana."),
                            Exercise(id: "es-listen-mudanza-finde-q4", kind: "choice", prompt: "¿Por qué van a empezar a las ocho?", options: ["Hay que devolver la furgoneta antes de las seis", "Nora trabaja por la tarde", "El piso está muy lejos", "Hace calor al mediodía"], answers: ["Hay que devolver la furgoneta antes de las seis"], explain: "La furgoneta hay que devolverla antes de las seis."),
                            Exercise(id: "es-listen-mudanza-finde-q5", kind: "written", prompt: "¿Qué van a comer después de la mudanza?", options: [], answers: ["pizza", "una pizza"], explain: "Van a comer pizza en el piso nuevo para celebrarlo."),
                            Exercise(id: "es-listen-mudanza-finde-q6", kind: "choice", prompt: "¿Qué regalo va a hacerle Nora a su hermano?", options: ["Una planta para el salón", "Un cuadro", "Unas sillas", "Una lámpara"], answers: ["Una planta para el salón"], explain: "Nora va a hacerle una planta para el salón.")], skills: ["listening:gist", "grammar:going-to", "vocab:home", "function:make-future-plans"]),
    ListeningText(id: "es-listen-cambio-zapatillas", languageID: "es", title: "El cambio de zapatillas", level: "A2", topic: "compras", unitID: "es-foundations-u25",
        text: "El martes, Rubén compró unas zapatillas por internet, pero al probarlas se equivocó de talla: le quedaban grandes. Fue a la tienda del centro con la caja y el recibo. «Buenas tardes, quiero cambiar unas zapatillas, es que son muy grandes». La dependienta las miró: «¿Quiere la misma en una talla menor?». «Sí, la cuarenta y dos, por favor». No había en la tienda, así que la dependienta las va a pedir al almacén: «Llegan el jueves; le mandamos un mensaje cuando estén». Rubén prefirió esperar: el jueves pasa por la tienda después del trabajo.",
        questions: [
                            Exercise(id: "es-listen-cambio-zapatillas-q1", kind: "choice", prompt: "¿Qué compró Rubén el martes?", options: ["Unas zapatillas", "Una chaqueta", "Unos vaqueros", "Una mochila"], answers: ["Unas zapatillas"], explain: "El martes, Rubén compró unas zapatillas por internet."),
                            Exercise(id: "es-listen-cambio-zapatillas-q2", kind: "written", prompt: "¿Cuál fue el problema con las zapatillas?", options: [], answers: ["le quedaban grandes", "son muy grandes", "quedaban grandes"], explain: "Al probarlas se equivocó de talla: le quedaban grandes."),
                            Exercise(id: "es-listen-cambio-zapatillas-q3", kind: "choice", prompt: "¿Qué talla necesita Rubén?", options: ["La cuarenta y dos", "La cuarenta", "La cuarenta y cuatro", "La treinta y ocho"], answers: ["La cuarenta y dos"], explain: "«Sí, la cuarenta y dos, por favor»."),
                            Exercise(id: "es-listen-cambio-zapatillas-q4", kind: "choice", prompt: "¿Qué va a hacer la tienda?", options: ["Pedirlas al almacén", "Devolverle el dinero", "Arreglárselas", "Regalarle calcetines"], answers: ["Pedirlas al almacén"], explain: "La dependienta las va a pedir al almacén."),
                            Exercise(id: "es-listen-cambio-zapatillas-q5", kind: "written", prompt: "¿Cuándo van a llegar las zapatillas a la tienda?", options: [], answers: ["el jueves", "jueves"], explain: "«Llegan el jueves; le mandamos un mensaje cuando estén»."),
                            Exercise(id: "es-listen-cambio-zapatillas-q6", kind: "choice", prompt: "¿Cuándo pasa Rubén por la tienda?", options: ["El jueves, después del trabajo", "El martes por la mañana", "El fin de semana", "No va a volver"], answers: ["El jueves, después del trabajo"], explain: "El jueves pasa por la tienda después del trabajo.")], skills: ["listening:detail", "function:solve-problems", "grammar:past-simple-regular", "vocab:shopping"]),
    ListeningText(id: "es-listen-carnet-tercera", languageID: "es", title: "El carnet, a la tercera", level: "B1", topic: "anécdotas", unitID: "es-foundations-u19",
        text: "Te cuento una anécdota: el carnet de conducir me ha costado más de lo que esperaba. La primera vez lo suspendí porque me puse muy nervioso en el examen práctico: se me olvidó mirar los espejos. La segunda vez, el coche del examen se averió a mitad de la prueba, así que tuvimos que repetirla entera. Cuando por fin me presenté a la tercera, ya no esperaba nada: llevaba meses practicando y había dado cientos de vueltas al polígono. Y aquella vez, que menos lo buscaba, aprobé. Mi instructor se rió: «Ya ves, a la tercera va la vencida». Desde entonces, conducir es mi momento tranquilo del día.",
        questions: [
                            Exercise(id: "es-listen-carnet-tercera-q1", kind: "written", prompt: "¿Qué le ha costado más de lo que esperaba?", options: [], answers: ["el carnet de conducir", "el carnet", "el carné de conducir"], explain: "El carnet de conducir me ha costado más de lo que esperaba."),
                            Exercise(id: "es-listen-carnet-tercera-q2", kind: "choice", prompt: "¿Por qué suspendió la primera vez?", options: ["Se puso nervioso y olvidó mirar los espejos", "Hacía mucho sol", "El coche no arrancaba", "Se equivocó de ruta"], answers: ["Se puso nervioso y olvidó mirar los espejos"], explain: "Me puse muy nervioso: se me olvidó mirar los espejos."),
                            Exercise(id: "es-listen-carnet-tercera-q3", kind: "choice", prompt: "¿Qué pasó en el segundo examen?", options: ["El coche se averió a mitad de la prueba", "Llegó tarde al examen", "Confundió una señal", "Suspendió por los espejos"], answers: ["El coche se averió a mitad de la prueba"], explain: "El coche del examen se averió a mitad de la prueba."),
                            Exercise(id: "es-listen-carnet-tercera-q4", kind: "written", prompt: "¿Cuántas vueltas había dado al polígono?", options: [], answers: ["cientos", "cientos de vueltas", "muchas vueltas"], explain: "Había dado cientos de vueltas al polígono."),
                            Exercise(id: "es-listen-carnet-tercera-q5", kind: "choice", prompt: "¿Qué le dice el instructor al final?", options: ["«A la tercera va la vencida»", "«Lo siento, suspende»", "«Todavía falta poco»", "«Cambia de autoescuela»"], answers: ["«A la tercera va la vencida»"], explain: "«Ya ves, a la tercera va la vencida».")], skills: ["listening:gist", "listening:inference", "function:tell-a-story", "grammar:present-perfect"]),
    ListeningText(id: "es-listen-debate-redes", languageID: "es", title: "Debate: redes y bulos", level: "B2", topic: "redes", unitID: "es-foundations-u9",
        text: "En «La Tarde», debate sobre redes sociales. La periodista Marta Roca abre: «Las noticias que circularon ayer por las redes fueron compartidas miles de veces sin verificar. Si fuéramos más pacientes, el bulo no se extendería tanto». El tecnólogo Iván Puig matiza: «No demonizaría las plataformas: el problema es el modelo, que premia la velocidad frente al rigor. Si los ingresos no dependieran de los clics, los medios publicarían mejor». Marta añade que la educación mediática debería enseñarse en el instituto: «Un adolescente que sabe contrastar fuentes es inmune a la mitad de los engaños». Iván cierra con una propuesta concreta: etiquetar con claridad los contenidos sin verificar. Los oyentes pueden votar a favor y en contra en la web del programa.",
        questions: [
                            Exercise(id: "es-listen-debate-redes-q1", kind: "choice", prompt: "¿Cuál es el problema que plantea Marta?", options: ["Noticias compartidas sin verificar", "El precio de los móviles", "Los anuncios en redes", "La lentitud de la web"], answers: ["Noticias compartidas sin verificar"], explain: "Las noticias que circularon ayer fueron compartidas miles de veces sin verificar."),
                            Exercise(id: "es-listen-debate-redes-q2", kind: "written", prompt: "¿Qué premia el modelo actual, según Iván?", options: [], answers: ["la velocidad", "velocidad", "la velocidad frente al rigor"], explain: "El problema es el modelo, que premia la velocidad frente al rigor."),
                            Exercise(id: "es-listen-debate-redes-q3", kind: "choice", prompt: "Según Iván, ¿de qué no deberían depender los ingresos?", options: ["De los clics", "De los suscriptores", "Del Estado", "De la radio"], answers: ["De los clics"], explain: "Si los ingresos no dependieran de los clics, los medios publicarían mejor."),
                            Exercise(id: "es-listen-debate-redes-q4", kind: "written", prompt: "¿Dónde debería enseñarse la educación mediática, según Marta?", options: [], answers: ["en el instituto", "el instituto", "en los institutos"], explain: "La educación mediática debería enseñarse en el instituto."),
                            Exercise(id: "es-listen-debate-redes-q5", kind: "choice", prompt: "¿Qué propone Iván al final?", options: ["Etiquetar los contenidos sin verificar", "Cerrar las redes", "Multar a los usuarios", "Prohibir los bulos"], answers: ["Etiquetar los contenidos sin verificar"], explain: "Iván cierra con una propuesta: etiquetar los contenidos sin verificar."),
                            Exercise(id: "es-listen-debate-redes-q6", kind: "choice", prompt: "¿Quiénes pueden participar con su voto?", options: ["Los oyentes, en la web", "Solo los invitados", "Los periodistas del programa", "Nadie"], answers: ["Los oyentes, en la web"], explain: "Los oyentes pueden votar en la web del programa.")], skills: ["listening:inference", "function:express-opinion", "grammar:second-conditional", "grammar:relative-clauses"]),
    ListeningText(id: "es-listen-sueldo-negociado", languageID: "es", title: "El aumento negociado", level: "B2", topic: "negociación",
        text: "Carla preparó la conversación de su aumento como quien prepara un examen. Primero se documentó: averiguó cuánto se paga en puestos parecidos al suyo y anotó los proyectos que ella había liderado aquel año. En la reunión no pidió un favor; presentó datos: «Si el presupuesto lo permitiera, propondría una revisión salarial acorde al mercado». Su jefa no dijo que no, sino que pidió tiempo: la decisión se tomaría después del cierre trimestral. Carla lo aceptó, pero dejó una condición: volver a hablarlo en marzo, con cifras sobre la mesa. La subida llegó: no fue todo lo que soñaba, pero la conversación le enseñó lo esencial: lo que no se negocia, no se consigue.",
        questions: [
                            Exercise(id: "es-listen-sueldo-negociado-q1", kind: "choice", prompt: "¿Qué averiguó Carla antes de la reunión?", options: ["Cuánto se paga en puestos parecidos", "El sueldo de su jefa", "Las vacaciones de sus compañeros", "El precio del parking"], answers: ["Cuánto se paga en puestos parecidos"], explain: "Averiguó cuánto se paga en puestos parecidos al suyo."),
                            Exercise(id: "es-listen-sueldo-negociado-q2", kind: "written", prompt: "¿Qué anotó Carla?", options: [], answers: ["los proyectos que había liderado", "los proyectos", "los proyectos liderados"], explain: "Anotó los proyectos que ella había liderado aquel año."),
                            Exercise(id: "es-listen-sueldo-negociado-q3", kind: "choice", prompt: "¿Cuándo se tomará la decisión?", options: ["Tras el cierre trimestral", "Esa misma tarde", "En enero", "No se tomará nunca"], answers: ["Tras el cierre trimestral"], explain: "La decisión se tomaría después del cierre trimestral."),
                            Exercise(id: "es-listen-sueldo-negociado-q4", kind: "choice", prompt: "¿Qué condición puso Carla?", options: ["Volver a hablarlo en marzo", "Cambiar de departamento", "Trabajar desde casa", "Firmar ya el contrato"], answers: ["Volver a hablarlo en marzo"], explain: "Dejó una condición: volver a hablarlo en marzo, con cifras sobre la mesa."),
                            Exercise(id: "es-listen-sueldo-negociado-q5", kind: "choice", prompt: "¿Qué le enseñó la conversación?", options: ["Lo que no se negocia, no se consigue", "Los jefes nunca dicen sí", "Conviene pedir poco", "Los datos sobran"], answers: ["Lo que no se negocia, no se consigue"], explain: "Le enseñó lo esencial: lo que no se negocia, no se consigue.")], skills: ["listening:inference", "function:negotiate", "grammar:passive-intro", "grammar:second-conditional"]),
    ListeningText(id: "es-listen-tertulia-ia", languageID: "es", title: "Tertulia: IA y empleo", level: "B2", topic: "actualidad", unitID: "es-foundations-u9",
        text: "Tertulia de medianoche: inteligencia artificial y empleo. La economista Nerea Ortiz arranca: «Muchas tareas rutinarias serán sustituidas por sistemas automáticos; eso ya está ocurriendo». El escritor Leo Manso discrepa del pesimismo: «Cada revolución técnica destruyó oficios, pero creó otros que nadie imaginaba. Yo no prohibiría la herramienta: la regularía». Nerea responde con cautela: «Regular, sí, pero rápido, porque el ritmo del cambio no espera a las leyes. Y habría que formar a la gente cuyo trabajo cambie, no solo avisarla». El moderador cierra: los expertos coinciden en algo — el reto no es la máquina, sino repartir sus beneficios —, aunque discrepan en casi todo lo demás.",
        questions: [
                            Exercise(id: "es-listen-tertulia-ia-q1", kind: "choice", prompt: "¿Cuál es el tema de la tertulia?", options: ["La IA y el empleo", "Los coches eléctricos", "La reforma laboral", "Las pensiones"], answers: ["La IA y el empleo"], explain: "La tertulia trata sobre inteligencia artificial y empleo."),
                            Exercise(id: "es-listen-tertulia-ia-q2", kind: "written", prompt: "¿Qué tareas serán sustituidas, según Nerea?", options: [], answers: ["las rutinarias", "tareas rutinarias", "las tareas rutinarias"], explain: "«Muchas tareas rutinarias serán sustituidas por sistemas automáticos»."),
                            Exercise(id: "es-listen-tertulia-ia-q3", kind: "choice", prompt: "¿Qué haría Leo con la herramienta?", options: ["La regularía", "La prohibiría", "La vendería", "La ignoraría"], answers: ["La regularía"], explain: "«Yo no prohibiría la herramienta: la regularía»."),
                            Exercise(id: "es-listen-tertulia-ia-q4", kind: "choice", prompt: "¿A quién habría que formar, según Nerea?", options: ["A la gente cuyo trabajo cambie", "Solo a los jóvenes", "A los ingenieros", "A los profesores"], answers: ["A la gente cuyo trabajo cambie"], explain: "Habría que formar a la gente cuyo trabajo cambie."),
                            Exercise(id: "es-listen-tertulia-ia-q5", kind: "choice", prompt: "¿En qué coinciden los expertos?", options: ["El reto es repartir los beneficios", "Hay que prohibir la IA", "El cambio no existe", "Las leyes sobran"], answers: ["El reto es repartir los beneficios"], explain: "Coinciden: el reto no es la máquina, sino repartir sus beneficios.")], skills: ["listening:inference", "function:express-opinion", "grammar:passive-intro", "grammar:second-conditional"]),
    ListeningText(id: "es-listen-mediacion-ruido", languageID: "es", title: "Mediación: ruido en el edificio", level: "B2", topic: "negociación",
        text: "En el centro cívico, una mediación vecinal. Don Ernesto, del tercer piso, se queja: «Desde que abrió el local, los fines de semana no duermo; el ruido atraviesa la pared como si no existiera». La dueña del local, Bea, responde: «Entiendo su cansancio, pero el bar es mi único ingreso; si cerrara a las doce, echaría a perder el negocio». La mediadora propone un acuerdo por partes: insonorizar la sala que da al patio, mover los conciertos al viernes y crear un canal directo de avisos. «Si el ruido bajara esta misma semana, retiraría la denuncia», concede don Ernesto. Bea firma: se compromete a insonorizar para el mes que viene y a invitar a los vecinos a una cena para estrenar el silencio.",
        questions: [
                            Exercise(id: "es-listen-mediacion-ruido-q1", kind: "written", prompt: "¿De qué se queja don Ernesto?", options: [], answers: ["del ruido", "el ruido", "del ruido del local"], explain: "Desde que abrió el local, el ruido no le deja dormir."),
                            Exercise(id: "es-listen-mediacion-ruido-q2", kind: "choice", prompt: "¿Qué significa el bar para Bea?", options: ["Su único ingreso", "Un pasatiempo", "Un negocio familiar", "Una pérdida de tiempo"], answers: ["Su único ingreso"], explain: "«El bar es mi único ingreso»."),
                            Exercise(id: "es-listen-mediacion-ruido-q3", kind: "choice", prompt: "¿Qué propone la mediadora?", options: ["Insonorizar, mover conciertos y crear un canal de avisos", "Cerrar el bar para siempre", "Multar a Bea cada fin de semana", "Cambiar a don Ernesto de piso"], answers: ["Insonorizar, mover conciertos y crear un canal de avisos"], explain: "Propone insonorizar, mover los conciertos al viernes y crear un canal de avisos."),
                            Exercise(id: "es-listen-mediacion-ruido-q4", kind: "written", prompt: "¿Qué retiraría don Ernesto si baja el ruido?", options: [], answers: ["la denuncia", "denuncia"], explain: "«Si el ruido bajara esta misma semana, retiraría la denuncia»."),
                            Exercise(id: "es-listen-mediacion-ruido-q5", kind: "choice", prompt: "¿Cuándo se compromete Bea a insonorizar?", options: ["Para el mes que viene", "Para el verano", "Nunca", "Cuando cierre el bar"], answers: ["Para el mes que viene"], explain: "Se compromete a insonorizar para el mes que viene.")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "vocab:social-expressions"]),
    ListeningText(id: "es-listen-turismo-masas", languageID: "es", title: "Puntos de vista: turismo y barrios", level: "B2", topic: "opinión", unitID: "es-foundations-u8",
        text: "Programa «Puntos de vista»: turismo y ciudades que se llenan. La guionista Sara Pons es clara: «Los barrios que visitan los turistas se están quedando sin vecinos; los pisos se convierten en apartamentos de alquiler y la tienda de toda la vida cierra». El hotelero Marc Vidal responde: «Sin turismo, esta ciudad no comería: uno de cada cinco empleos depende de él. Lo que hay que discutir no es si turistas, sino cuántos y dónde». Sara propone límites: «Yo limitaría las licencias de alquiler turístico y ampliaría el transporte público hacia los barrios que nadie visita». Marc sonríe: «Al menos estamos de acuerdo en algo: el problema no son los visitantes, sino la falta de plan».",
        questions: [
                            Exercise(id: "es-listen-turismo-masas-q1", kind: "written", prompt: "¿Qué están perdiendo los barrios turísticos?", options: [], answers: ["vecinos", "los vecinos", "sus vecinos"], explain: "Los barrios que visitan los turistas se están quedando sin vecinos."),
                            Exercise(id: "es-listen-turismo-masas-q2", kind: "choice", prompt: "¿Cuántos empleos dependen del turismo, según Marc?", options: ["Uno de cada cinco", "Uno de cada dos", "Uno de cada diez", "Ninguno"], answers: ["Uno de cada cinco"], explain: "«Uno de cada cinco empleos depende de él»."),
                            Exercise(id: "es-listen-turismo-masas-q3", kind: "written", prompt: "¿Qué limitaría Sara?", options: [], answers: ["las licencias de alquiler turístico", "las licencias", "licencias turísticas"], explain: "«Yo limitaría las licencias de alquiler turístico»."),
                            Exercise(id: "es-listen-turismo-masas-q4", kind: "choice", prompt: "¿Qué propone Sara para el transporte público?", options: ["Ampliarlo hacia los barrios que nadie visita", "Prohibir el autobús turístico", "Subir el precio del billete", "Quitar el metro"], answers: ["Ampliarlo hacia los barrios que nadie visita"], explain: "Ampliaría el transporte público hacia los barrios que nadie visita."),
                            Exercise(id: "es-listen-turismo-masas-q5", kind: "choice", prompt: "¿En qué están de acuerdo Sara y Marc?", options: ["El problema es la falta de plan", "Hay que prohibir el turismo", "El ayuntamiento miente", "Los hoteles sobran"], answers: ["El problema es la falta de plan"], explain: "Están de acuerdo: el problema es la falta de plan.")], skills: ["listening:inference", "function:express-opinion", "grammar:second-conditional", "grammar:passive-intro"]),
    ListeningText(id: "fr-listen-cafe-morning", languageID: "fr", title: "Un café avant le travail", level: "A1", topic: "routine", unitID: "fr-foundations-u1",
        text: "Chaque matin, Marta marche jusqu'à un petit café près de chez elle. Le serveur connaît son nom, alors elle n'a jamais besoin de commander. Aujourd'hui, elle s'assoit près de la fenêtre avec un café et un croissant. Son bus part à huit heures et demie, mais elle ne s'inquiète pas. Le café est très calme à cette heure-là. Elle boit son café lentement et regarde la ville se réveiller.",
        questions: [
                            Exercise(id: "fr-listen-cafe-morning-q1", kind: "choice", prompt: "Où Marta va-t-elle chaque matin ?", options: ["Dans un petit café", "À son bureau", "À la gare routière", "Dans un parc"], answers: ["Dans un petit café"], explain: "Elle marche jusqu'à un petit café près de chez elle."),
                            Exercise(id: "fr-listen-cafe-morning-q2", kind: "choice", prompt: "Qu'est-ce qu'elle prend ce matin ?", options: ["Un café et un croissant", "Un thé et des toasts", "Du jus d'orange", "Rien"], answers: ["Un café et un croissant"], explain: "Elle s'assoit avec un café et un croissant."),
                            Exercise(id: "fr-listen-cafe-morning-q3", kind: "written", prompt: "À quelle heure part son bus ?", options: [], answers: ["à huit heures et demie", "huit heures et demie", "huit heures et demi"], explain: "Son bus part à huit heures et demie."),
                            Exercise(id: "fr-listen-cafe-morning-q4", kind: "choice", prompt: "Comment se sent-elle par rapport à l'heure ?", options: ["Elle ne s'inquiète pas", "Elle est très en retard", "Elle est fâchée", "Elle a sommeil"], answers: ["Elle ne s'inquiète pas"], explain: "Le texte dit qu'elle ne s'inquiète pas."),
                            Exercise(id: "fr-listen-cafe-morning-q5", kind: "choice", prompt: "Qui connaît son nom ?", options: ["Le serveur", "Le conducteur du bus", "Son patron", "Un voisin"], answers: ["Le serveur"], explain: "Le serveur connaît son nom, alors elle n'a jamais besoin de commander."),
                            Exercise(id: "fr-listen-cafe-morning-q6", kind: "written", prompt: "Où s'assoit-elle aujourd'hui ?", options: [], answers: ["près de la fenêtre", "à côté de la fenêtre", "vers la fenêtre"], explain: "Aujourd'hui, elle s'assoit près de la fenêtre.")], skills: ["listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine"]),
    ListeningText(id: "fr-listen-language-class", languageID: "fr", title: "Le cours de langue", level: "A1", topic: "présentations", unitID: "fr-foundations-u1",
        text: "Marta assiste à son premier cours de portugais dans un petit institut. Dans la classe, il y a six personnes et tout le monde veut parler. La professeure demande les présentations. « Je m'appelle Marta et je suis de Bolivie », dit une dame. « Moi, c'est Andrés, je suis du Pérou et je travaille dans un restaurant », dit un jeune homme. Marta se présente aussi : « Je suis Marta, je suis argentine et je suis infirmière. » La professeure est de Madrid et elle enseigne avec beaucoup d'humour. À la fin du cours, les étudiants échangent leurs numéros de téléphone. Ils ne sont pas encore amis, mais la semaine prochaine, ils vont prendre un café ensemble et pratiquer.",
        questions: [
                            Exercise(id: "fr-listen-language-class-q1", kind: "choice", prompt: "Combien de personnes y a-t-il dans la classe ?", options: ["Six", "Trois", "Dix", "Quatorze"], answers: ["Six"], explain: "Dans la classe, il y a six personnes."),
                            Exercise(id: "fr-listen-language-class-q2", kind: "choice", prompt: "D'où vient Andrés ?", options: ["Du Pérou", "De Bolivie", "D'Argentine", "Du Mexique"], answers: ["Du Pérou"], explain: "Andrés vient du Pérou et il travaille dans un restaurant."),
                            Exercise(id: "fr-listen-language-class-q3", kind: "choice", prompt: "Quel est le métier de Marta ?", options: ["Infirmière", "Professeure", "Serveuse", "Étudiante"], answers: ["Infirmière"], explain: "Marta est argentine et elle est infirmière."),
                            Exercise(id: "fr-listen-language-class-q4", kind: "written", prompt: "De quelle ville est la professeure ?", options: [], answers: ["madrid", "de madrid", "elle est de madrid"], explain: "La professeure est de Madrid."),
                            Exercise(id: "fr-listen-language-class-q5", kind: "choice", prompt: "Que font-ils à la fin du cours ?", options: ["Ils échangent leurs numéros de téléphone", "Ils rentrent seuls", "Ils font un examen", "Ils dînent au restaurant"], answers: ["Ils échangent leurs numéros de téléphone"], explain: "Les étudiants échangent leurs numéros de téléphone."),
                            Exercise(id: "fr-listen-language-class-q6", kind: "written", prompt: "Que vont-ils faire la semaine prochaine ?", options: [], answers: ["prendre un café", "ils vont prendre un café", "prendre un café ensemble"], explain: "La semaine prochaine, ils vont prendre un café ensemble et pratiquer.")], skills: ["listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself"]),
    ListeningText(id: "fr-listen-little-sister", languageID: "fr", title: "Ma petite sœur", level: "A1", topic: "famille", unitID: "fr-foundations-u1",
        text: "Ma petite sœur s'appelle Carla et elle a neuf ans. Elle est très gentille et très bavarde. Carla n'est pas discrète : elle parle avec tout le monde, avec les voisins, avec les professeurs et avec les chiens du parc. Elle est blonde, comme notre mère, et elle a les yeux marron comme mon père. Elle n'est pas grande pour son âge, mais elle est très rapide et elle adore le football. Son équipe n'est pas très bonne, mais cela ne la dérange pas. « Je ne suis pas professionnelle », dit-elle, « moi, je suis juste heureuse avec le ballon ». Ma sœur est petite, mais sa joie est énorme.",
        questions: [
                            Exercise(id: "fr-listen-little-sister-q1", kind: "choice", prompt: "Quel âge a Carla ?", options: ["Neuf ans", "Dix-neuf ans", "Sept ans", "Dix ans"], answers: ["Neuf ans"], explain: "Carla a neuf ans."),
                            Exercise(id: "fr-listen-little-sister-q2", kind: "choice", prompt: "Comment est Carla ?", options: ["Gentille et bavarde", "Timide et discrète", "Sérieuse", "Triste"], answers: ["Gentille et bavarde"], explain: "Elle est très gentille et très bavarde."),
                            Exercise(id: "fr-listen-little-sister-q3", kind: "written", prompt: "De quelle couleur sont ses yeux ?", options: [], answers: ["marron", "les yeux marron", "marron comme son père"], explain: "Elle a les yeux marron comme son père."),
                            Exercise(id: "fr-listen-little-sister-q4", kind: "choice", prompt: "Comment sont ses cheveux ?", options: ["Blonds, comme sa mère", "Bruns, comme son père", "Roux", "Courts et noirs"], answers: ["Blonds, comme sa mère"], explain: "Elle est blonde, comme notre mère."),
                            Exercise(id: "fr-listen-little-sister-q5", kind: "choice", prompt: "Qu'est-ce qu'elle adore ?", options: ["Le football", "La natation", "La musique", "Les jeux vidéo"], answers: ["Le football"], explain: "Elle est très rapide et elle adore le football."),
                            Exercise(id: "fr-listen-little-sister-q6", kind: "written", prompt: "Comment est sa joie ?", options: [], answers: ["énorme", "très grande", "grande"], explain: "Sa joie est énorme.")], skills: ["listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family"]),
    ListeningText(id: "fr-listen-new-flatmate", languageID: "fr", title: "Un nouveau colocataire", level: "A1", topic: "maison", unitID: "fr-foundations-u1",
        text: "Tom a un nouveau colocataire. Il s'appelle Léo et il a vingt-trois ans. Léo vient d'une petite ville du nord, mais il travaille maintenant en ville. Il a deux cartons, une guitare et un vélo. L'appartement a deux chambres et une cuisine très lumineuse. Tom espère que Léo aime cuisiner, parce que Tom, lui, déteste ça.",
        questions: [
                            Exercise(id: "fr-listen-new-flatmate-q1", kind: "choice", prompt: "Quel âge a Léo ?", options: ["Vingt-trois ans", "Trente-deux ans", "Vingt ans", "Trente ans"], answers: ["Vingt-trois ans"], explain: "Léo a vingt-trois ans."),
                            Exercise(id: "fr-listen-new-flatmate-q2", kind: "choice", prompt: "Qu'est-ce que Léo n'a PAS ?", options: ["Une télévision", "Deux cartons", "Une guitare", "Un vélo"], answers: ["Une télévision"], explain: "Il a deux cartons, une guitare et un vélo — pas de télévision."),
                            Exercise(id: "fr-listen-new-flatmate-q3", kind: "written", prompt: "Qu'est-ce que Tom déteste faire ?", options: [], answers: ["cuisiner", "il déteste cuisiner", "tom déteste cuisiner"], explain: "Tom déteste cuisiner."),
                            Exercise(id: "fr-listen-new-flatmate-q4", kind: "choice", prompt: "Comment est l'appartement ?", options: ["Deux chambres et une cuisine lumineuse", "Une chambre et un balcon", "Un jardin", "Deux salles de bain"], answers: ["Deux chambres et une cuisine lumineuse"], explain: "L'appartement a deux chambres et une cuisine très lumineuse."),
                            Exercise(id: "fr-listen-new-flatmate-q5", kind: "choice", prompt: "Où Léo travaille-t-il maintenant ?", options: ["En ville", "Dans un petit village", "Dans le nord", "Il ne travaille pas"], answers: ["En ville"], explain: "Il vient d'une petite ville du nord, mais il travaille maintenant en ville."),
                            Exercise(id: "fr-listen-new-flatmate-q6", kind: "written", prompt: "Quel instrument Léo a-t-il ?", options: [], answers: ["une guitare", "la guitare", "guitare"], explain: "Léo a une guitare.")], skills: ["listening:gist", "listening:detail", "grammar:have-got", "vocab:home"]),
    ListeningText(id: "fr-listen-new-neighbour", languageID: "fr", title: "La nouvelle voisine", level: "A1", topic: "gens", unitID: "fr-foundations-u1",
        text: "Dans l'immeuble, il y a une nouvelle voisine. Elle s'appelle Amélie et elle est de France. Elle n'est pas étudiante ; elle est photographe. Elle ne travaille pas dans un bureau : elle travaille chez elle et elle voyage beaucoup. Les voisins sont curieux, mais ils sont aussi timides, alors ils ne lui parlent pas. Puis, un matin, Ben la rencontre à la porte. « C'est vous, la nouvelle voisine ? », demande-t-il. « Oui, c'est moi », répond-elle, « et je suis contente d'être ici. » Maintenant, ils sont amis, et elle n'est plus seule dans l'immeuble.",
        questions: [
                            Exercise(id: "fr-listen-new-neighbour-q1", kind: "choice", prompt: "D'où vient Amélie ?", options: ["De France", "D'Italie", "Du Japon", "Du Brésil"], answers: ["De France"], explain: "Amélie est de France."),
                            Exercise(id: "fr-listen-new-neighbour-q2", kind: "choice", prompt: "Quel est son métier ?", options: ["Photographe", "Étudiante", "Employée de bureau", "Professeure"], answers: ["Photographe"], explain: "Elle n'est pas étudiante ; elle est photographe."),
                            Exercise(id: "fr-listen-new-neighbour-q3", kind: "choice", prompt: "Travaille-t-elle dans un bureau ?", options: ["Non, elle travaille chez elle", "Oui, tous les jours", "Seulement en été", "Elle ne le dit pas"], answers: ["Non, elle travaille chez elle"], explain: "Elle ne travaille pas dans un bureau : elle travaille chez elle."),
                            Exercise(id: "fr-listen-new-neighbour-q4", kind: "written", prompt: "Pourquoi les voisins ne lui parlent-ils pas ?", options: [], answers: ["ils sont timides", "parce qu'ils sont timides", "timides"], explain: "Ils sont curieux, mais ils sont aussi timides."),
                            Exercise(id: "fr-listen-new-neighbour-q5", kind: "choice", prompt: "Où Ben la rencontre-t-il ?", options: ["À la porte", "Dans l'ascenseur", "Dans la rue", "Au café"], answers: ["À la porte"], explain: "Un matin, Ben la rencontre à la porte."),
                            Exercise(id: "fr-listen-new-neighbour-q6", kind: "written", prompt: "Comment Amélie se sent-elle à la fin ?", options: [], answers: ["contente", "heureuse", "elle est contente"], explain: "Elle dit qu'elle est contente d'être ici.")], skills: ["listening:gist", "listening:detail", "function:describe-people"]),
    ListeningText(id: "fr-listen-sunday-market", languageID: "fr", title: "Le marché du dimanche", level: "A1", topic: "achats", unitID: "fr-foundations-u1",
        text: "Le dimanche, il y a un marché sur la place du village. Anna et son père y vont à neuf heures, avant que ce soit trop bondé. Ils achètent des fruits, du pain et des fleurs. Anna veut des fraises, mais son père dit qu'elles sont trop chères cette semaine. À la fin, ils rentrent avec un grand sac d'oranges et des roses blanches pour la table de la cuisine.",
        questions: [
                            Exercise(id: "fr-listen-sunday-market-q1", kind: "choice", prompt: "Quand Anna et son père vont-ils au marché ?", options: ["À neuf heures", "À midi", "Dans l'après-midi", "À six heures et demie"], answers: ["À neuf heures"], explain: "Ils y vont à neuf heures, avant que ce soit trop bondé."),
                            Exercise(id: "fr-listen-sunday-market-q2", kind: "written", prompt: "Pourquoi Anna n'a-t-elle pas de fraises ?", options: [], answers: ["elles sont trop chères", "trop chères", "parce qu'elles sont trop chères"], explain: "Son père dit qu'elles sont trop chères cette semaine."),
                            Exercise(id: "fr-listen-sunday-market-q3", kind: "choice", prompt: "Qu'est-ce qu'ils ramènent à la maison ?", options: ["Des oranges et des roses", "Des fraises et du pain", "Des pommes et des tulipes", "Du pain et du fromage"], answers: ["Des oranges et des roses"], explain: "Ils rentrent avec des oranges et des roses blanches."),
                            Exercise(id: "fr-listen-sunday-market-q4", kind: "choice", prompt: "Où est le marché ?", options: ["Sur la place du village", "Près de la rivière", "À la gare", "Dans un supermarché"], answers: ["Sur la place du village"], explain: "Il y a un marché sur la place du village le dimanche."),
                            Exercise(id: "fr-listen-sunday-market-q5", kind: "choice", prompt: "Qu'est-ce qu'ils achètent ?", options: ["Des fruits, du pain et des fleurs", "Du poisson et des légumes", "Du fromage et de la viande", "Uniquement des fleurs"], answers: ["Des fruits, du pain et des fleurs"], explain: "Ils achètent des fruits, du pain et des fleurs."),
                            Exercise(id: "fr-listen-sunday-market-q6", kind: "written", prompt: "Qu'est-ce qu'Anna veut ?", options: [], answers: ["des fraises", "les fraises", "elle veut des fraises"], explain: "Anna veut des fraises.")], skills: ["listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping"]),
    ListeningText(id: "fr-listen-appart-choisi", languageID: "fr", title: "L'appartement choisi", level: "A2", topic: "appartements", unitID: "fr-foundations-u4",
        text: "Camille et Théo cherchent un appartement. Le premier est moins cher, mais il est plus loin de la gare : quarante minutes à pied. Le second coûte cent euros de plus, mais il est plus lumineux et il a un balcon. Pour Camille, la lumière est le plus important, parce qu'elle travaille à la maison. Ils décident de demander une visite du second : il est plus cher, mais c'est le meilleur des deux pour eux.",
        questions: [
                            Exercise(id: "fr-listen-appart-choisi-q1", kind: "choice", prompt: "Combien d'appartements comparent-ils ?", options: ["Deux", "Trois", "Quatre"], answers: ["Deux"], explain: "Ils comparent deux appartements."),
                            Exercise(id: "fr-listen-appart-choisi-q2", kind: "choice", prompt: "Quel est le problème du moins cher ?", options: ["Il est loin de la gare", "Il n'a pas de balcon", "Il est très cher", "Il est petit"], answers: ["Il est loin de la gare"], explain: "Quarante minutes à pied de la gare."),
                            Exercise(id: "fr-listen-appart-choisi-q3", kind: "written", prompt: "Combien coûte le second en plus par mois ?", options: [], answers: ["cent euros", "100 euros"], explain: "Cent euros de plus par mois."),
                            Exercise(id: "fr-listen-appart-choisi-q4", kind: "choice", prompt: "Qu'est-ce qui est le plus important pour Camille ?", options: ["La lumière", "Le prix", "Le balcon", "La cuisine"], answers: ["La lumière"], explain: "Elle travaille à la maison."),
                            Exercise(id: "fr-listen-appart-choisi-q5", kind: "choice", prompt: "Que décident-ils ?", options: ["Demander une visite du second", "Garder le premier", "Continuer à chercher", "Demander une réduction"], answers: ["Demander une visite du second"], explain: "C'est le meilleur des deux pour eux.")], skills: ["listening:gist", "listening:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ListeningText(id: "fr-listen-samedi-organise", languageID: "fr", title: "Le samedi organisé", level: "A2", topic: "projets", unitID: "fr-foundations-u4",
        text: "Léa appelle son frère pour organiser samedi. Il propose la montagne, mais il va pleuvoir, alors Léa suggère le nouveau musée. Ils vont se retrouver à dix heures à l'entrée principale et déjeuner au marché à côté, qui est moins cher que les restaurants du centre. Le soir, ils n'ont pas de projet : ils vont décider sur place, quand ils connaîtront la météo.",
        questions: [
                            Exercise(id: "fr-listen-samedi-organise-q1", kind: "choice", prompt: "Qui propose la montagne ?", options: ["Le frère", "Léa", "Leur mère", "Un ami"], answers: ["Le frère"], explain: "Son frère propose la montagne."),
                            Exercise(id: "fr-listen-samedi-organise-q2", kind: "choice", prompt: "Pourquoi pas la montagne ?", options: ["Il va pleuvoir", "Ils sont fatigués", "Le musée est gratuit", "La montagne est loin"], answers: ["Il va pleuvoir"], explain: "Il va pleuvoir, alors ils vont au musée."),
                            Exercise(id: "fr-listen-samedi-organise-q3", kind: "written", prompt: "À quelle heure vont-ils se retrouver ?", options: [], answers: ["a dix heures", "à dix heures", "dix heures"], explain: "À dix heures à l'entrée principale."),
                            Exercise(id: "fr-listen-samedi-organise-q4", kind: "choice", prompt: "Où vont-ils déjeuner ?", options: ["Au marché à côté", "Dans un restaurant du centre", "Chez eux", "Au musée"], answers: ["Au marché à côté"], explain: "Moins cher que les restaurants du centre."),
                            Exercise(id: "fr-listen-samedi-organise-q5", kind: "choice", prompt: "Que vont-ils faire le soir ?", options: ["Décider sur place", "Aller au cinéma", "Rentrer tôt", "Voir des amis"], answers: ["Décider sur place"], explain: "Ils vont décider selon la météo.")], skills: ["listening:gist", "listening:detail", "grammar:going-to"], exposureSkills: ["grammar:future-forms"]),
    ListeningText(id: "fr-listen-jamais-fait", languageID: "fr", title: "Ce que je n'ai jamais fait", level: "B1", topic: "voyages", unitID: "fr-foundations-u6",
        text: "Dans la cuisine d'une auberge, trois voyageurs comparent leurs vies. Théo a visité vingt pays, mais il n'a jamais appris à nager : « Je sais, c'est ridicule ». Aïcha a déjà plongé deux fois avec des tortues, mais elle n'a jamais quitté l'Afrique avant ce voyage. Et Léa, qui est sur la route depuis six ans, n'a jamais pris l'avion : elle traverse les océans en bateau et les frontières en bus. « Jamais ? » demande Théo. « Jamais. La peur est plus vieille que moi. » Ils rient de ce qu'ils n'ont pas fait, et Léa dit quelque chose qui reste : « Il ne faut pas avoir tout fait. Il suffit de vouloir encore ».",
        questions: [
                            Exercise(id: "fr-listen-jamais-fait-q1", kind: "choice", prompt: "Qu'est-ce que Théo n'a jamais fait ?", options: ["Apprendre à nager", "Visiter vingt pays", "Traverser en bateau", "Quitter l'Afrique"], answers: ["Apprendre à nager"], explain: "Il a visité vingt pays, mais il n'a jamais appris à nager."),
                            Exercise(id: "fr-listen-jamais-fait-q2", kind: "written", prompt: "Combien de fois Aïcha a-t-elle plongé ?", options: [], answers: ["deux fois", "2 fois", "deux"], explain: "Aïcha a déjà plongé deux fois avec des tortues."),
                            Exercise(id: "fr-listen-jamais-fait-q3", kind: "choice", prompt: "Comment Léa traverse-t-elle les océans ?", options: ["En bateau", "En avion", "En bus", "À pied"], answers: ["En bateau"], explain: "Elle traverse les océans en bateau et les frontières en bus."),
                            Exercise(id: "fr-listen-jamais-fait-q4", kind: "choice", prompt: "Que dit Léa sur la peur ?", options: ["Elle est plus vieille qu'elle", "Elle est plus jeune", "C'est ridicule", "Elle est partie"], answers: ["Elle est plus vieille qu'elle"], explain: "La peur est plus vieille que moi."),
                            Exercise(id: "fr-listen-jamais-fait-q5", kind: "written", prompt: "Qu'est-ce qui suffit, selon Léa ?", options: [], answers: ["vouloir encore", "de vouloir encore"], explain: "Il suffit de vouloir encore.")], skills: ["listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"], exposureSkills: ["grammar:relative-clauses"]),
    ListeningText(id: "fr-listen-ville-village", languageID: "fr", title: "De la ville au village", level: "B1", topic: "changements", unitID: "fr-foundations-u6",
        text: "Nicolas explique pourquoi il a quitté Paris. Avant, il vivait dans un petit appartement et travaillait onze heures par jour : « Je gagnais bien, mais je n'avais pas de vie ». Un hiver, il est tombé malade, et là il a compris qu'il fallait changer. Maintenant il habite dans un village de mille habitants, il travaille de chez lui le matin et cultive un potager l'après-midi. « Je gagne moins, mais j'ai du temps. » Au début, ses parents ne comprenaient pas ; maintenant ils viennent chaque mois. « Tu regrettes quelque chose ? » demande son amie. « De ne pas l'avoir fait plus tôt ».",
        questions: [
                            Exercise(id: "fr-listen-ville-village-q1", kind: "choice", prompt: "Où habitait Nicolas avant ?", options: ["À Paris", "Dans un village", "À Lyon", "Dans une auberge"], answers: ["À Paris"], explain: "Nicolas explique pourquoi il a quitté Paris."),
                            Exercise(id: "fr-listen-ville-village-q2", kind: "written", prompt: "Combien d'heures travaillait-il par jour ?", options: [], answers: ["onze heures", "11 heures", "onze"], explain: "Il travaillait onze heures par jour."),
                            Exercise(id: "fr-listen-ville-village-q3", kind: "choice", prompt: "Qu'est-ce qui l'a fait changer ?", options: ["Il est tombé malade", "Il a perdu son travail", "Il a gagné à la loterie", "Il a rencontré quelqu'un"], answers: ["Il est tombé malade"], explain: "Un hiver, il est tombé malade, et là il a compris."),
                            Exercise(id: "fr-listen-ville-village-q4", kind: "choice", prompt: "Que fait-il l'après-midi maintenant ?", options: ["Il cultive un potager", "Il travaille plus d'heures", "Il voyage chaque mois", "Il étudie"], answers: ["Il cultive un potager"], explain: "Il travaille le matin et cultive un potager l'après-midi."),
                            Exercise(id: "fr-listen-ville-village-q5", kind: "written", prompt: "Que regrette Nicolas ?", options: [], answers: ["de ne pas l'avoir fait plus tot", "de ne pas l'avoir fait plus tôt", "ne pas l'avoir fait plus tôt"], explain: "« De ne pas l'avoir fait plus tôt ».")], skills: ["listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions"]),
    ListeningText(id: "fr-listen-marche-table", languageID: "fr", title: "Le marchandage de la table", level: "B2", topic: "négociation", unitID: "fr-foundations-u7",
        text: "Sur une app d'occasion, Camille veut une table en bois à 80 euros. « Et si on se retrouvait à 60 ? », propose-t-elle. Le vendeur refuse : « Seulement si vous la prenez aujourd'hui ». Camille réfléchit : « Je vous donnerais 65 si vous ajoutez la chaise ». « Impossible », rit-il, « mais je vous laisserais la table à 70 et je vous la monterais à l'étage ». Camille n'hésite pas : « Vous la monteriez tout seul ? ». « J'ai un diable », répond-il. « Marché conclu », dit-elle, et elle ajoute : « Si elle est aussi belle que sur la photo, je laisse cinq étoiles ».",
        questions: [
                            Exercise(id: "fr-listen-marche-table-q1", kind: "choice", prompt: "Combien le vendeur demande-t-il ?", options: ["80 euros", "60 euros", "70 euros", "65 euros"], answers: ["80 euros"], explain: "La table coûte 80 euros."),
                            Exercise(id: "fr-listen-marche-table-q2", kind: "written", prompt: "Que propose Camille d'abord ?", options: [], answers: ["60 euros", "soixante euros", "se retrouver a 60", "se retrouver à 60"], explain: "« Et si on se retrouvait à 60 ? »."),
                            Exercise(id: "fr-listen-marche-table-q3", kind: "choice", prompt: "Quelle condition le vendeur pose-t-il ?", options: ["La prendre aujourd'hui", "Payer en espèces", "Laisser cinq étoiles", "Revenir demain"], answers: ["La prendre aujourd'hui"], explain: "« Seulement si vous la prenez aujourd'hui »."),
                            Exercise(id: "fr-listen-marche-table-q4", kind: "choice", prompt: "Qu'offre le vendeur pour 70 ?", options: ["Monter la table à l'étage", "Ajouter la chaise", "Descendre à 60", "Prêter un diable"], answers: ["Monter la table à l'étage"], explain: "« Je vous la monterais à l'étage »."),
                            Exercise(id: "fr-listen-marche-table-q5", kind: "written", prompt: "Que promet Camille si la table plaît ?", options: [], answers: ["cinq etoiles", "cinq étoiles", "une note de cinq etoiles"], explain: "Cinq étoiles.")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "fr-listen-info-quartier", languageID: "fr", title: "L'info du quartier", level: "B2", topic: "actualité", unitID: "fr-foundations-u8",
        text: "Au marché, Anaïs et Marc commentent ce qu'on dit. « On dit qu'ils vont piétonniser la rue principale », raconte Anaïs. « Encore ? », rit Marc. « La nouvelle que j'ai lue dit que ça commence au printemps ». D'après la mairie, ce serait seulement le samedi, mais les commerçants, dont le chiffre d'affaires dépendrait du tourisme, ont déjà manifesté. « C'est vrai que le bruit baisserait », concède Marc, « mais, et le parking ? ». Anaïs défend la mesure : « D'un côté, plus de gens marcheraient ; de l'autre, les bus s'arrêteraient à la porte ». Ils ne trancheent pas, mais promettent d'en reparler quand le plan sera publié.",
        questions: [
                            Exercise(id: "fr-listen-info-quartier-q1", kind: "choice", prompt: "Que dit-on de la rue principale ?", options: ["Qu'on la piétonnisera", "Qu'on l'élargira", "Qu'on la fermera", "Qu'on la rebaptisera"], answers: ["Qu'on la piétonnisera"], explain: "« On dit qu'ils vont piétonniser la rue principale »."),
                            Exercise(id: "fr-listen-info-quartier-q2", kind: "written", prompt: "Quand est-ce que ça commencerait ?", options: [], answers: ["au printemps", "printemps"], explain: "« La nouvelle que j'ai lue dit que ça commence au printemps »."),
                            Exercise(id: "fr-listen-info-quartier-q3", kind: "choice", prompt: "Que dit la mairie ?", options: ["Seulement le samedi", "Tous les jours", "Seulement en été", "Les jours fériés"], answers: ["Seulement le samedi"], explain: "D'après la mairie, ce serait seulement le samedi."),
                            Exercise(id: "fr-listen-info-quartier-q4", kind: "choice", prompt: "Qui a manifesté ?", options: ["Les commerçants", "Les habitants", "Les taxi", "La mairie"], answers: ["Les commerçants"], explain: "Les commerçants ont déjà manifesté."),
                            Exercise(id: "fr-listen-info-quartier-q5", kind: "written", prompt: "Que promettent Anaïs et Marc ?", options: [], answers: ["d'en reparler", "en reparler", "reparler du plan"], explain: "Ils promettent d'en reparler quand le plan sera publié.")], skills: ["listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors"]),
    ListeningText(id: "fr-listen-debat-radio", languageID: "fr", title: "Débat à la radio", level: "C1", topic: "débats", unitID: "fr-foundations-u9",
        text: "« Bienvenue dans notre débat du soir : le télétravail a-t-il tué le bureau ? » Diane, consultante : « En quelque sorte, oui. D'une certaine manière, les open spaces ont perdu leur raison d'être : nos clients exigent désormais des résultats, pas une présence. » Marc, dirigeant d'une PME : « À mon sens, c'est plus subtil. Nous avons toutefois constaté une baisse de la créativité : les idées circulent moins bien en visioconférence. » Diane concède : « C'est un argument, néanmoins les salariés ne reviendront pas à plein temps. » Le présentateur reformule : « Autrement dit, le bureau deviendrait un lieu de rencontre plutôt qu'un lieu de production ? » Tous deux l'admettent, moyennant des locaux repensés. Le débat continue, mais l'essentiel est dit : la nuance a gagné la partie.",
        questions: [
                            Exercise(id: "fr-listen-debat-radio-q1", kind: "choice", prompt: "Quel est le sujet du débat ?", options: ["Le télétravail et le bureau", "La baisse des résultats", "Le prix des open spaces", "La visioconférence seule"], answers: ["Le télétravail et le bureau"], explain: "Dès l'ouverture : « le télétravail a-t-il tué le bureau ? »."),
                            Exercise(id: "fr-listen-debat-radio-q2", kind: "written", prompt: "Quelle formule nuancée Diane utilise-t-elle en premier ?", options: [], answers: ["en quelque sorte oui", "en quelque sorte, oui", "oui en quelque sorte"], explain: "« En quelque sorte, oui » : l'accord nuancé ouvre son intervention."),
                            Exercise(id: "fr-listen-debat-radio-q3", kind: "choice", prompt: "Que constate Marc ?", options: ["Une baisse de la créativité", "Une hausse des résultats", "Une baisse de la présence", "Une hausse des loyers"], answers: ["Une baisse de la créativité"], explain: "« Nous avons toutefois constaté une baisse de la créativité »."),
                            Exercise(id: "fr-listen-debat-radio-q4", kind: "choice", prompt: "Quelle formule le présentateur utilise-t-il pour reformuler ?", options: ["Autrement dit", "Par ailleurs", "Pour commencer", "En fait"], answers: ["Autrement dit"], explain: "« Autrement dit » annonce la reformulation."),
                            Exercise(id: "fr-listen-debat-radio-q5", kind: "written", prompt: "Que demandent les deux invités à la fin ?", options: [], answers: ["des locaux repenses", "des locaux repensés", "repenser les locaux"], explain: "Ils l'admettent « moyennant des locaux repensés ».")], skills: ["listening:inference", "function:express-opinion", "grammar:connectors", "vocab:collocations"]),
    ListeningText(id: "fr-listen-conference-cles", languageID: "fr", title: "Conférence : les trois clés", level: "C1", topic: "travail", unitID: "fr-foundations-u9",
        text: "« Mesdames et messieurs, permettez-moi de conclure par trois clés. Pour commencer, la clarté : une équipe sans objectifs précis confond activité et avancement. J'en viens ensuite à la confiance ; autrement dit, déléguer, c'est accepter que le travail soit fait autrement. Enfin, le feedback : dans nos enquêtes, les salariés qui reçoivent un retour chaque semaine se déclarent nettement plus engagés. En résumé, ni la surveillance ni la bienveillance aveugle ne suffisent ; à mon sens, la performance naît de la combinaison des trois clés. Si vous ne retenez qu'une phrase de cette conférence, retenez celle-ci : on ne gère pas des gens, on crée les conditions pour qu'ils réussissent. Je vous remercie de votre attention et je réponds à vos questions.",
        questions: [
                            Exercise(id: "fr-listen-conference-cles-q1", kind: "choice", prompt: "Combien de clés l'orateur présente-t-il ?", options: ["Trois", "Deux", "Quatre", "Cinq"], answers: ["Trois"], explain: "« Permettez-moi de conclure par trois clés »."),
                            Exercise(id: "fr-listen-conference-cles-q2", kind: "choice", prompt: "Quelle est la première clé ?", options: ["La clarté", "La confiance", "Le feedback", "La rapidité"], answers: ["La clarté"], explain: "« Pour commencer, la clarté »."),
                            Exercise(id: "fr-listen-conference-cles-q3", kind: "written", prompt: "D'après l'orateur, déléguer signifie quoi ?", options: [], answers: ["accepter que le travail soit fait autrement", "accepter que ce soit fait autrement", "que le travail soit fait autrement"], explain: "« Déléguer, c'est accepter que le travail soit fait autrement »."),
                            Exercise(id: "fr-listen-conference-cles-q4", kind: "choice", prompt: "Qu'est-ce qui rend les salariés plus engagés, selon les enquêtes ?", options: ["Un retour chaque semaine", "Une réunion chaque jour", "Un salaire plus élevé", "Des objectifs flous"], answers: ["Un retour chaque semaine"], explain: "Les salariés « qui reçoivent un retour chaque semaine se déclarent nettement plus engagés »."),
                            Exercise(id: "fr-listen-conference-cles-q5", kind: "written", prompt: "Quel mot complète la phrase finale : « On ne gère pas des ___ , on crée les conditions pour qu'ils réussissent. »", options: [], answers: ["gens", "personnes", "des gens"], explain: "« On ne gère pas des gens » : la phrase à retenir.")], skills: ["listening:connected-speech", "listening:detail", "vocab:work", "grammar:connectors"]),
    ListeningText(id: "fr-listen-podcast-nuances", languageID: "fr", title: "Podcast : l'art de nuancer", level: "C1", topic: "langue", unitID: "fr-foundations-u9",
        text: "Dans ce podcast, Léa reçoit M. Roussel, linguiste. Léa : « Est-ce vraiment poli de répondre seulement : j'ai bien reçu votre mail ? » M. Roussel : « C'est correct, mais neutre. À l'écrit professionnel, on préférera : je vous confirme la bonne réception de votre message. Le verbe confirmer élève le registre. » Léa : « Et à l'oral ? » M. Roussel : « À l'oral, le ton fait la moitié du travail ; néanmoins, certaines tournures restent marquées : je vous prie de bien vouloir sonne formel, voire guindé entre collègues proches. » Léa : « Donc tout est une question de contexte ? » M. Roussel : « En quelque sorte : nuancer, c'est choisir la bonne distance. Celui qui module gagne la confiance de son auditoire ; celui qui parle tout cru l'épuise. »",
        questions: [
                            Exercise(id: "fr-listen-podcast-nuances-q1", kind: "choice", prompt: "Quel est le thème du podcast ?", options: ["Le registre de langue au travail", "L'orthographe des e-mails", "L'histoire du français", "Les réunions à distance"], answers: ["Le registre de langue au travail"], explain: "Le dialogue porte sur les registres à l'écrit et à l'oral professionnel."),
                            Exercise(id: "fr-listen-podcast-nuances-q2", kind: "choice", prompt: "Quelle tournure M. Roussel juge-t-elle guindée entre proches ?", options: ["Je vous prie de bien vouloir", "J'ai bien reçu votre mail", "Je vous confirme la réception", "Le verbe confirmer"], answers: ["Je vous prie de bien vouloir"], explain: "« Je vous prie de bien vouloir sonne formel, voire guindé entre collègues proches »."),
                            Exercise(id: "fr-listen-podcast-nuances-q3", kind: "written", prompt: "Comment M. Roussel définit-il la nuance ?", options: [], answers: ["choisir la bonne distance", "c'est choisir la bonne distance", "choisir la distance"], explain: "« Nuancer, c'est choisir la bonne distance »."),
                            Exercise(id: "fr-listen-podcast-nuances-q4", kind: "choice", prompt: "Qu'est-ce qui fait la moitié du travail à l'oral ?", options: ["Le ton", "L'orthographe", "La longueur", "Le silence"], answers: ["Le ton"], explain: "« À l'oral, le ton fait la moitié du travail »."),
                            Exercise(id: "fr-listen-podcast-nuances-q5", kind: "choice", prompt: "Que veut dire « celui qui module gagne la confiance » ?", options: ["Nuancer rend crédible", "Parler fort convainc", "Écrire court suffit", "Tout dire rassure"], answers: ["Nuancer rend crédible"], explain: "À opposer à « celui qui parle tout cru l'épuise » : la modulation crédibilise.")], skills: ["listening:inference", "listening:gist", "vocab:social-expressions"]),
    ListeningText(id: "fr-listen-nouvel-appart", languageID: "fr", title: "Un nouvel appart pour Léa", level: "A1", topic: "maison", unitID: "fr-foundations-u10",
        text: "Léa visite un nouvel appartement dans le quartier. Dans l'entrée, il y a un miroir. La cuisine est petite, mais il y a une fenêtre. Le salon donne sur la rue : il y a un canapé bleu et deux fauteuils. La chambre est à côté du salon ; le lit est sous la fenêtre. Il n'y a pas de garage, mais il y a un balcon. Le propriétaire dit : « C'est à dix minutes à pied de la gare. » Léa est contente : elle prend l'appartement.",
        questions: [
                            Exercise(id: "fr-listen-nouvel-appart-q1", kind: "choice", prompt: "Où est le lit ?", options: ["Sous la fenêtre", "Sur le balcon", "Dans l'entrée", "À côté de la cuisine"], answers: ["Sous la fenêtre"], explain: "Le lit est sous la fenêtre."),
                            Exercise(id: "fr-listen-nouvel-appart-q2", kind: "choice", prompt: "Qu'est-ce qu'il y a dans le salon ?", options: ["Un canapé bleu et deux fauteuils", "Une grande table avec des chaises", "Un miroir et un balcon", "Un lit sous la fenêtre"], answers: ["Un canapé bleu et deux fauteuils"], explain: "Il y a un canapé bleu et deux fauteuils."),
                            Exercise(id: "fr-listen-nouvel-appart-q3", kind: "written", prompt: "Qu'est-ce qu'il n'y a pas dans l'appartement ?", options: [], answers: ["il n'y a pas de garage", "pas de garage"], explain: "Il n'y a pas de garage, mais il y a un balcon."),
                            Exercise(id: "fr-listen-nouvel-appart-q4", kind: "choice", prompt: "À quelle distance est la gare ?", options: ["À dix minutes à pied", "À dix minutes en bus", "Tout près du salon", "Loin du quartier"], answers: ["À dix minutes à pied"], explain: "C'est à dix minutes à pied de la gare."),
                            Exercise(id: "fr-listen-nouvel-appart-q5", kind: "written", prompt: "Qu'est-ce qu'il y a à côté du salon ?", options: [], answers: ["la chambre", "c'est la chambre"], explain: "La chambre est à côté du salon."),
                            Exercise(id: "fr-listen-nouvel-appart-q6", kind: "choice", prompt: "Comment est Léa à la fin ?", options: ["Contente", "Triste", "Fatiguée", "Fâchée"], answers: ["Contente"], explain: "Léa est contente : elle prend l'appartement.")], skills: ["listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home"]),
    ListeningText(id: "fr-listen-balade-quartier", languageID: "fr", title: "Une balade dans le quartier", level: "A1", topic: "quartier", unitID: "fr-foundations-u11",
        text: "Karim est nouveau dans le quartier. Il demande à une voisine : « Pardon, est-ce qu'il y a une boulangerie près d'ici ? » La voisine répond : « Allez tout droit, tournez à gauche au feu ; c'est tout près. La boulangerie est à côté de la pharmacie. » Karim marche cinq minutes. Ensuite, il traverse le parc : il y a un marché. Le samedi, le marché vend des fruits : pommes, fraises et tomates. Karim achète un kilo de pommes. Il adore son quartier.",
        questions: [
                            Exercise(id: "fr-listen-balade-quartier-q1", kind: "choice", prompt: "Que cherche Karim ?", options: ["Une boulangerie", "Une pharmacie", "La gare", "Un marché"], answers: ["Une boulangerie"], explain: "Il demande s'il y a une boulangerie près d'ici."),
                            Exercise(id: "fr-listen-balade-quartier-q2", kind: "choice", prompt: "Quelle est la direction ?", options: ["Tournez à gauche au feu", "Tournez à droite au feu", "Allez à gauche tout de suite", "Traversez le quartier"], answers: ["Tournez à gauche au feu"], explain: "Allez tout droit, tournez à gauche au feu."),
                            Exercise(id: "fr-listen-balade-quartier-q3", kind: "written", prompt: "Où est la boulangerie ?", options: [], answers: ["à côté de la pharmacie", "a cote de la pharmacie", "près de la pharmacie"], explain: "La boulangerie est à côté de la pharmacie."),
                            Exercise(id: "fr-listen-balade-quartier-q4", kind: "choice", prompt: "Qu'est-ce qu'il y a dans le parc ?", options: ["Un marché", "Des voitures", "Une école", "Un cinéma"], answers: ["Un marché"], explain: "Il traverse le parc : il y a un marché."),
                            Exercise(id: "fr-listen-balade-quartier-q5", kind: "written", prompt: "Qu'est-ce que Karim achète ?", options: [], answers: ["un kilo de pommes", "1 kilo de pommes", "des pommes"], explain: "Karim achète un kilo de pommes."),
                            Exercise(id: "fr-listen-balade-quartier-q6", kind: "choice", prompt: "Comment trouve-t-il le quartier ?", options: ["Il adore", "Il déteste", "Il oublie", "Il cherche"], answers: ["Il adore"], explain: "Il adore son quartier.")], skills: ["listening:gist", "listening:detail", "grammar:there-is-are", "function:ask-for-directions", "vocab:town"]),
    ListeningText(id: "fr-listen-appel-mamie", languageID: "fr", title: "Un appel à mamie", level: "A1", topic: "famille", unitID: "fr-foundations-u12",
        text: "Allô, mamie ? C'est Léa. Tu es là ? Oui, ma chérie ! Comment va la famille ? Très bien ! Maman est au travail, elle revient à six heures. Papa prépare le dîner : il cuisine toujours le samedi. Mon petit frère regarde la télé. Et mon oncle Paul ? Il arrive dimanche avec sa fille. Très bien ! Je rappelle plus tard, papa m'appelle pour le dîner. Gros bisous, mamie !",
        questions: [
                            Exercise(id: "fr-listen-appel-mamie-q1", kind: "choice", prompt: "Qui appelle Léa ?", options: ["Sa mamie", "Son papa", "Sa sœur", "Son oncle"], answers: ["Sa mamie"], explain: "Elle dit : Allô, mamie ? C'est Léa."),
                            Exercise(id: "fr-listen-appel-mamie-q2", kind: "choice", prompt: "Où est maman ?", options: ["Au travail", "À la maison", "Au parc", "Au marché"], answers: ["Au travail"], explain: "Maman est au travail, elle revient à six heures."),
                            Exercise(id: "fr-listen-appel-mamie-q3", kind: "choice", prompt: "Qui cuisine toujours le samedi ?", options: ["Papa", "Maman", "Léa", "Le petit frère"], answers: ["Papa"], explain: "Papa prépare le dîner : il cuisine toujours le samedi."),
                            Exercise(id: "fr-listen-appel-mamie-q4", kind: "written", prompt: "Qui arrive dimanche ?", options: [], answers: ["mon oncle Paul", "son oncle", "mon oncle paul"], explain: "Mon oncle Paul arrive dimanche avec sa fille."),
                            Exercise(id: "fr-listen-appel-mamie-q5", kind: "choice", prompt: "Que fait le petit frère ?", options: ["Il regarde la télé", "Il cuisine", "Il travaille", "Il lit"], answers: ["Il regarde la télé"], explain: "Mon petit frère regarde la télé."),
                            Exercise(id: "fr-listen-appel-mamie-q6", kind: "choice", prompt: "Que fait Léa à la fin ?", options: ["Elle rappelle plus tard", "Elle cuisine le dîner", "Elle va au travail", "Elle regarde la télé"], answers: ["Elle rappelle plus tard"], explain: "Je rappelle plus tard, dit Léa.")], skills: ["listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine"]),
    ListeningText(id: "fr-listen-weekend-pluvieux", languageID: "fr", title: "Un week-end pluvieux", level: "A1", topic: "météo", unitID: "fr-foundations-u13",
        text: "Quel temps ! Il pleut sur Toulouse. Léa appelle son ami Karim : On va au parc ? Non, il pleut. Et il y a du vent. Le parc est désert ! Bon, je reste à la maison. Je lis toujours le samedi après-midi. En hiver, je ne sors jamais. Moi, j'aime la pluie. Je bois un chocolat chaud et je regarde un film. Alors, à demain ! Demain, il fait beau.",
        questions: [
                            Exercise(id: "fr-listen-weekend-pluvieux-q1", kind: "choice", prompt: "Quel temps fait-il ?", options: ["Il pleut", "Il neige", "Il fait beau", "Il fait chaud"], answers: ["Il pleut"], explain: "Il pleut sur Toulouse."),
                            Exercise(id: "fr-listen-weekend-pluvieux-q2", kind: "choice", prompt: "Pourquoi Karim ne va pas au parc ?", options: ["Il pleut", "Il travaille", "Il est fatigué", "Il lit"], answers: ["Il pleut"], explain: "Non, il pleut. Et il y a du vent."),
                            Exercise(id: "fr-listen-weekend-pluvieux-q3", kind: "choice", prompt: "Qu'est-ce que Léa fait toujours le samedi après-midi ?", options: ["Elle lit", "Elle cuisine", "Elle nage", "Elle dort"], answers: ["Elle lit"], explain: "Je lis toujours le samedi après-midi, dit Léa."),
                            Exercise(id: "fr-listen-weekend-pluvieux-q4", kind: "written", prompt: "Qu'est-ce que Karim boit ?", options: [], answers: ["un chocolat chaud", "du chocolat chaud"], explain: "Je bois un chocolat chaud, dit Karim."),
                            Exercise(id: "fr-listen-weekend-pluvieux-q5", kind: "choice", prompt: "En hiver, quand est-ce que Karim sort ?", options: ["Jamais", "Toujours", "Souvent", "Parfois"], answers: ["Jamais"], explain: "En hiver, je ne sors jamais."),
                            Exercise(id: "fr-listen-weekend-pluvieux-q6", kind: "choice", prompt: "Où est Léa ?", options: ["À la maison", "Au parc", "Au travail", "À la piscine"], answers: ["À la maison"], explain: "Bon, je reste à la maison, dit Léa.")], skills: ["listening:gist", "listening:detail", "vocab:weather", "vocab:daily-routine", "grammar:frequency-adverbs", "function:talk-about-weather"]),
    ListeningText(id: "fr-listen-metro-perdu", languageID: "fr", title: "Perdue dans le métro", level: "A1", topic: "transports", unitID: "fr-foundations-u14",
        text: "Léa est à Paris pour la première fois. Elle prend le métro tous les jours, mais aujourd'hui, elle est perdue. Elle demande à un agent : « Pardon, le train part à quelle heure ? » « À huit heures et quart. » « Et je prends quelle ligne ? » « La ligne 4. Le métro arrive à huit heures et demie à la gare. » « Merci ! D'habitude, je prends toujours le bus, mais le métro, c'est rapide ! » Elle est contente : à Paris, on va partout en métro.",
        questions: [
                            Exercise(id: "fr-listen-metro-perdu-q1", kind: "choice", prompt: "Pourquoi Léa demande de l'aide ?", options: ["Elle est perdue", "Elle est malade", "Elle est fatiguée", "Elle est en retard"], answers: ["Elle est perdue"], explain: "Aujourd'hui, elle est perdue dans le métro."),
                            Exercise(id: "fr-listen-metro-perdu-q2", kind: "choice", prompt: "Le train part à quelle heure ?", options: ["À huit heures et quart", "À huit heures et demie", "À sept heures et quart", "À neuf heures"], answers: ["À huit heures et quart"], explain: "À huit heures et quart, dit l'agent."),
                            Exercise(id: "fr-listen-metro-perdu-q3", kind: "choice", prompt: "Le métro arrive à quelle heure à la gare ?", options: ["À huit heures et demie", "À huit heures et quart", "À neuf heures et demie", "À sept heures"], answers: ["À huit heures et demie"], explain: "Le métro arrive à huit heures et demie à la gare."),
                            Exercise(id: "fr-listen-metro-perdu-q4", kind: "written", prompt: "Quelle ligne est-ce que Léa prend ?", options: [], answers: ["la ligne 4", "ligne 4", "la 4"], explain: "La ligne 4, dit l'agent."),
                            Exercise(id: "fr-listen-metro-perdu-q5", kind: "choice", prompt: "Quel transport est-ce que Léa prend d'habitude ?", options: ["Le bus", "Le train", "Le vélo", "À pied"], answers: ["Le bus"], explain: "D'habitude, je prends toujours le bus."),
                            Exercise(id: "fr-listen-metro-perdu-q6", kind: "choice", prompt: "Le métro, c'est comment, pour Léa ?", options: ["Rapide", "Cher", "Long", "Difficile"], answers: ["Rapide"], explain: "Le métro, c'est rapide, dit Léa.")], skills: ["listening:gist", "listening:detail", "vocab:transport", "function:tell-time"]),
    ListeningText(id: "fr-listen-pharmacie-samedi", languageID: "fr", title: "À la pharmacie, samedi", level: "A1", topic: "santé", unitID: "fr-foundations-u15",
        text: "Samedi matin, Hugo est malade. Il a mal à la tête et il a de la fièvre. Il va à la pharmacie. « Bonjour, je voudrais quelque chose pour la tête, s'il vous plaît. » « Vous avez une ordonnance ? » « Non, je n'ai pas d'ordonnance. » « Alors, voici des comprimés : deux fois par jour, matin et soir. Buvez toujours beaucoup d'eau ! » « Ça coûte combien ? » « Quatre euros. » Merci, bonne journée ! Hugo rentre : avec les comprimés et l'eau, il va être en forme.",
        questions: [
                            Exercise(id: "fr-listen-pharmacie-samedi-q1", kind: "choice", prompt: "Quel jour Hugo va à la pharmacie ?", options: ["Samedi", "Dimanche", "Lundi", "Vendredi"], answers: ["Samedi"], explain: "Samedi matin, Hugo est malade."),
                            Exercise(id: "fr-listen-pharmacie-samedi-q2", kind: "choice", prompt: "Hugo a mal à… ?", options: ["À la tête", "Au ventre", "À la gorge", "Au dos"], answers: ["À la tête"], explain: "Il a mal à la tête et il a de la fièvre."),
                            Exercise(id: "fr-listen-pharmacie-samedi-q3", kind: "written", prompt: "Qu'est-ce qu'Hugo demande à la pharmacie ?", options: [], answers: ["quelque chose pour la tête", "quelque chose pour la tete", "il demande quelque chose pour la tête"], explain: "Je voudrais quelque chose pour la tête, dit Hugo."),
                            Exercise(id: "fr-listen-pharmacie-samedi-q4", kind: "choice", prompt: "Hugo a une ordonnance ?", options: ["Non", "Oui", "Deux", "Peut-être"], answers: ["Non"], explain: "Non, je n'ai pas d'ordonnance, dit Hugo."),
                            Exercise(id: "fr-listen-pharmacie-samedi-q5", kind: "choice", prompt: "Combien de fois par jour est-ce qu'il prend les comprimés ?", options: ["Deux fois", "Une fois", "Trois fois", "Jamais"], answers: ["Deux fois"], explain: "Deux fois par jour, matin et soir."),
                            Exercise(id: "fr-listen-pharmacie-samedi-q6", kind: "choice", prompt: "Ça coûte combien ?", options: ["Quatre euros", "Six euros", "Quatorze euros", "Deux euros"], answers: ["Quatre euros"], explain: "Quatre euros, dit le pharmacien."),
                            Exercise(id: "fr-listen-pharmacie-samedi-q7", kind: "choice", prompt: "Qu'est-ce qu'Hugo boit toujours ?", options: ["Beaucoup d'eau", "Du café", "Du jus", "Du lait"], answers: ["Beaucoup d'eau"], explain: "Buvez toujours beaucoup d'eau !")], skills: ["listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs"]),
    ListeningText(id: "fr-listen-diner-surprise", languageID: "fr", title: "Le dîner surprise", level: "A1", topic: "restaurant", unitID: "fr-foundations-u16",
        text: "C'est samedi. Karim invite Léa au restaurant, c'est une surprise. Ils prennent une table pour deux en terrasse. Léa veut une pizza, mais il n'y a pas de pizza : elle prend une quiche. Karim commande le poulet avec des frites. Comme boisson, ils prennent une carafe d'eau et un jus d'orange. Après le repas, Karim demande l'addition. Léa veut payer, mais c'est Karim qui paye : c'est son cadeau d'anniversaire. Léa est très contente.",
        questions: [
                            Exercise(id: "fr-listen-diner-surprise-q1", kind: "choice", prompt: "Où est-ce que Karim invite Léa ?", options: ["Au restaurant", "Au cinéma", "À la maison", "Au parc"], answers: ["Au restaurant"], explain: "Karim invite Léa au restaurant, c'est une surprise."),
                            Exercise(id: "fr-listen-diner-surprise-q2", kind: "choice", prompt: "Qu'est-ce que Léa prend finalement ?", options: ["Une quiche", "Une pizza", "Une salade", "Le poulet"], answers: ["Une quiche"], explain: "Il n'y a pas de pizza, alors elle prend une quiche."),
                            Exercise(id: "fr-listen-diner-surprise-q3", kind: "written", prompt: "Qu'est-ce que Karim commande comme plat ?", options: [], answers: ["le poulet", "poulet", "le poulet avec des frites"], explain: "Karim commande le poulet avec des frites."),
                            Exercise(id: "fr-listen-diner-surprise-q4", kind: "choice", prompt: "Qu'est-ce qu'ils prennent comme boisson ?", options: ["Une carafe d'eau et un jus d'orange", "Deux cafés", "Deux sodas", "Un thé et un café"], answers: ["Une carafe d'eau et un jus d'orange"], explain: "Ils prennent une carafe d'eau et un jus d'orange."),
                            Exercise(id: "fr-listen-diner-surprise-q5", kind: "written", prompt: "Qui paye l'addition ?", options: [], answers: ["karim", "c'est karim"], explain: "Léa veut payer, mais c'est Karim qui paye."),
                            Exercise(id: "fr-listen-diner-surprise-q6", kind: "choice", prompt: "Pourquoi Karim paye ?", options: ["C'est son cadeau d'anniversaire", "Léa n'a pas d'argent", "Le repas est gratuit", "C'est Léa qui invite"], answers: ["C'est son cadeau d'anniversaire"], explain: "Le repas est le cadeau d'anniversaire de Léa.")], skills: ["listening:gist", "listening:detail", "vocab:food", "function:order-food"]),
    ListeningText(id: "fr-listen-plan-anniversaire", languageID: "fr", title: "Le plan anniversaire", level: "A2", topic: "invitations", unitID: "fr-foundations-u17",
        text: "Samedi, c'est l'anniversaire de Mai. Karim appelle Léa pour organiser la surprise. Il va acheter un livre sur les voyages, parce que Mai adore partir. Léa, elle, va lui offrir des fleurs et un gâteau au chocolat : elle va passer à la boulangerie vendredi soir. Ils vont se retrouver chez Karim à sept heures et décorer le salon avant son arrivée. Léa ne peut pas rester tard, parce qu'elle travaille tôt dimanche, mais elle va venir quand même. Mai ne sait rien : elle va arriver à sept heures et demie. Et là, surprise !",
        questions: [
                            Exercise(id: "fr-listen-plan-anniversaire-q1", kind: "choice", prompt: "C'est l'anniversaire de qui samedi ?", options: ["De Mai", "De Léa", "De Karim", "Du frère de Karim"], answers: ["De Mai"], explain: "Samedi, c'est l'anniversaire de Mai."),
                            Exercise(id: "fr-listen-plan-anniversaire-q2", kind: "choice", prompt: "Qu'est-ce que Karim va acheter ?", options: ["Un livre sur les voyages", "Des fleurs", "Un gâteau au chocolat", "Des décorations"], answers: ["Un livre sur les voyages"], explain: "Il va acheter un livre sur les voyages, parce que Mai adore partir."),
                            Exercise(id: "fr-listen-plan-anniversaire-q3", kind: "written", prompt: "Qu'est-ce que Léa va offrir ?", options: [], answers: ["des fleurs et un gâteau", "des fleurs et un gâteau au chocolat", "des fleurs"], explain: "Léa va offrir des fleurs et un gâteau au chocolat."),
                            Exercise(id: "fr-listen-plan-anniversaire-q4", kind: "choice", prompt: "Pourquoi Léa ne reste pas tard ?", options: ["Elle travaille tôt dimanche", "Elle n'aime pas les fêtes", "Elle est malade", "Elle habite loin"], answers: ["Elle travaille tôt dimanche"], explain: "Elle travaille tôt dimanche, mais elle vient quand même."),
                            Exercise(id: "fr-listen-plan-anniversaire-q5", kind: "written", prompt: "À quelle heure Mai arrive-t-elle ?", options: [], answers: ["sept heures et demie", "7h30"], explain: "Elle va arriver à sept heures et demie."),
                            Exercise(id: "fr-listen-plan-anniversaire-q6", kind: "choice", prompt: "Où vont-ils décorer ?", options: ["Le salon de Karim", "La cuisine de Léa", "Le jardin", "Un restaurant"], answers: ["Le salon de Karim"], explain: "Ils vont se retrouver chez Karim et décorer le salon.")], skills: ["listening:gist", "listening:detail", "grammar:going-to", "vocab:social-expressions"], exposureSkills: ["grammar:future-forms"]),
    ListeningText(id: "fr-listen-anecdote-ete", languageID: "fr", title: "L'anecdote de l'été", level: "B1", topic: "récits", unitID: "fr-foundations-u18",
        text: "Cet été, Théo est allé à Marseille rendre visite à sa cousine. D'abord, tout s'est bien passé : ils ont visité le Vieux-Port et mangé des moules face à la mer. Ensuite, sur le chemin du retour, sa voiture est tombée en panne sur l'autoroute. Soudain, un camion s'est arrêté derrière lui, et un homme est descendu avec une grande boîte. Théo a cru qu'il allait lui vendre quelque chose. Mais il s'est avéré que cet homme réparait les voitures bénévolement le week-end : il a retrouvé Théo sur la route en vingt minutes. Au final, Théo est rentré plus tard que prévu, mais avec une belle histoire à raconter. « Sans blague ! », lui a dit sa cousine.",
        questions: [
                            Exercise(id: "fr-listen-anecdote-ete-q1", kind: "choice", prompt: "Pourquoi Théo est-il allé à Marseille ?", options: ["Pour rendre visite à sa cousine", "Pour travailler", "Pour voir un match", "Pour déménager"], answers: ["Pour rendre visite à sa cousine"], explain: "Il est allé à Marseille rendre visite à sa cousine."),
                            Exercise(id: "fr-listen-anecdote-ete-q2", kind: "choice", prompt: "Qu'est-ce qui s'est passé sur le chemin du retour ?", options: ["Sa voiture est tombée en panne", "Il a perdu son téléphone", "Il a manqué le train", "Il a oublié son sac"], answers: ["Sa voiture est tombée en panne"], explain: "Sa voiture est tombée en panne sur l'autoroute."),
                            Exercise(id: "fr-listen-anecdote-ete-q3", kind: "written", prompt: "Qu'est-ce que Théo a cru au début ?", options: [], answers: ["qu'il allait lui vendre quelque chose", "que l'homme allait lui vendre quelque chose"], explain: "Théo a cru que l'homme allait lui vendre quelque chose."),
                            Exercise(id: "fr-listen-anecdote-ete-q4", kind: "choice", prompt: "Que faisait l'homme du camion ?", options: ["Il réparait les voitures bénévolement", "Il vendait des pièces", "Il cherchait du travail", "Il faisait un contrôle"], answers: ["Il réparait les voitures bénévolement"], explain: "Il s'est avéré qu'il réparait les voitures bénévolement le week-end."),
                            Exercise(id: "fr-listen-anecdote-ete-q5", kind: "written", prompt: "En combien de temps l'homme a-t-il retrouvé Théo sur la route ?", options: [], answers: ["vingt minutes", "20 minutes", "vingt"], explain: "L'homme a retrouvé Théo sur la route en vingt minutes."),
                            Exercise(id: "fr-listen-anecdote-ete-q6", kind: "choice", prompt: "Quelle a été la réaction de la cousine ?", options: ["Sans blague !", "Et puis ?", "Bonne idée !", "Avec plaisir !"], answers: ["Sans blague !"], explain: "« Sans blague ! », lui a dit sa cousine.")], skills: ["listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors"], exposureSkills: ["vocab:social-expressions"]),
    ListeningText(id: "fr-listen-debat-tacte", languageID: "fr", title: "Débat : le tact qui dispute", level: "C1", topic: "débats", unitID: "fr-foundations-u9",
        text: "Sur une chaîne d'information, un débat vif mais courtois oppose Nadia Belkacem, économiste, à Gérard Vasseur, chef d'entreprise : la semaine de quatre jours. Nadia ouvre : « Je comprends votre point : la productivité par heure progresse. Cela dit, nos données montrent que les gains restent inégalement répartis. » Gérard enchaîne : « Je vois les choses autrement. Sans pour autant nier la fatigue des salariés, je crains que la mesure ne pénalise les PME. » Le modérateur reformule : « Autrement dit, vous vous accordez sur le diagnostic, mais pas sur le remède ? » Tous deux le concèdent. Nadia tempère : « Je ne suis pas certaine que la comparaison internationale soit transposable, mais je resterai attentive à vos résultats. » Vingt minutes de désaccord poli, sans une once d'agressivité.",
        questions: [
                            Exercise(id: "fr-listen-debat-tacte-q1", kind: "choice", prompt: "Quel est le sujet du débat ?", options: ["La semaine de quatre jours", "Les salaires des PME", "La productivité par heure", "La comparaison internationale"], answers: ["La semaine de quatre jours"], explain: "Le débat porte sur la semaine de quatre jours."),
                            Exercise(id: "fr-listen-debat-tacte-q2", kind: "written", prompt: "Avec quelle formule Nadia reconnaît-elle d'abord l'argument adverse ?", options: [], answers: ["je comprends votre point", "je comprend votre point"], explain: "« Je comprends votre point » : la reconnaissance avant l'objection."),
                            Exercise(id: "fr-listen-debat-tacte-q3", kind: "choice", prompt: "Que craint Gérard ?", options: ["Que la mesure pénalise les PME", "Que les salariés soient fatigués", "Que la productivité baisse par heure", "Que les données soient fausses"], answers: ["Que la mesure pénalise les PME"], explain: "Je crains que la mesure ne pénalise les PME."),
                            Exercise(id: "fr-listen-debat-tacte-q4", kind: "choice", prompt: "Sur quoi les deux invités s'accordent-ils ?", options: ["Le diagnostic", "Le remède", "Le calendrier", "Les salaires"], answers: ["Le diagnostic"], explain: "Vous vous accordez sur le diagnostic, mais pas sur le remède."),
                            Exercise(id: "fr-listen-debat-tacte-q5", kind: "written", prompt: "Quelle réserve finale Nadia formule-t-elle ?", options: [], answers: ["la comparaison internationale n'est peut-être pas transposable", "je ne suis pas certaine que la comparaison soit transposable", "la comparaison n'est pas transposable"], explain: "« Je ne suis pas certaine que la comparaison internationale soit transposable »."),
                            Exercise(id: "fr-listen-debat-tacte-q6", kind: "choice", prompt: "Comment le commentaire final décrit-il le débat ?", options: ["Poli et documenté", "Agressif", "Confus", "Superficiel"], answers: ["Poli et documenté"], explain: "Vingt minutes de désaccord poli, sans une once d'agressivité.")], skills: ["listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "fr-listen-soiree-vendredi", languageID: "fr", title: "La soirée du vendredi", level: "A1", topic: "amis", unitID: "fr-foundations-u19",
        text: "C'est vendredi soir. Léa arrive chez Mai pour dîner. Devant la porte, elle demande : « Je peux entrer ? » Mai ouvre : « Oui, bien sûr ! » Léa apporte des fleurs. Mai propose : « Tu veux un jus d'orange ? » Léa répond : « Volontiers ! » Le gâteau est délicieux : Léa prend deux morceaux. À dix heures, Léa dit : « Merci pour tout ! » Mai répond : « Bonne nuit ! » À la prochaine fois !",
        questions: [
                            Exercise(id: "fr-listen-soiree-vendredi-q1", kind: "choice", prompt: "Où est-ce que Léa va vendredi soir ?", options: ["Chez Mai", "Au restaurant", "Au cinéma", "Chez Karim"], answers: ["Chez Mai"], explain: "Léa arrive chez Mai pour le dîner."),
                            Exercise(id: "fr-listen-soiree-vendredi-q2", kind: "choice", prompt: "Qu'est-ce que Léa demande devant la porte ?", options: ["Je peux entrer ?", "Vous allez bien ?", "Où est la fête ?", "Tu es seule ?"], answers: ["Je peux entrer ?"], explain: "Devant la porte, elle demande : « Je peux entrer ? »"),
                            Exercise(id: "fr-listen-soiree-vendredi-q3", kind: "written", prompt: "Qu'est-ce que Léa apporte ?", options: [], answers: ["des fleurs", "fleurs", "elle apporte des fleurs"], explain: "Léa apporte des fleurs pour Mai."),
                            Exercise(id: "fr-listen-soiree-vendredi-q4", kind: "choice", prompt: "Qu'est-ce que Mai propose à boire ?", options: ["Un jus d'orange", "Un café", "Un thé", "De l'eau"], answers: ["Un jus d'orange"], explain: "Mai propose à boire : « Tu veux un jus d'orange ? »"),
                            Exercise(id: "fr-listen-soiree-vendredi-q5", kind: "choice", prompt: "Comment est le gâteau ?", options: ["Il est délicieux", "Il est brûlé", "Il est trop sucré", "Il est petit"], answers: ["Il est délicieux"], explain: "Le gâteau de Mai est délicieux : Léa prend deux morceaux."),
                            Exercise(id: "fr-listen-soiree-vendredi-q6", kind: "written", prompt: "Qu'est-ce que Léa dit à la fin de la soirée ?", options: [], answers: ["merci pour tout", "merci pour tout !", "elle dit merci pour tout"], explain: "À dix heures, Léa se lève : « Merci pour tout ! »")], skills: ["listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can"]),
    ListeningText(id: "fr-listen-reclamation-facture", languageID: "fr", title: "Au téléphone avec le magasin", level: "A2", topic: "réclamation", unitID: "fr-foundations-u20",
        text: "Bonjour, j'appelle au sujet d'une imprimante. Je l'ai achetée dans votre magasin la semaine dernière. Elle a bien marché deux jours, mais depuis hier elle ne s'allume plus. J'ai vérifié le câble et j'ai changé la prise, mais rien à faire. De plus, j'ai reçu deux factures pour le même article. Est-ce que je peux avoir un échange ? J'ai le ticket et la première facture sous la main. Le vendeur répond : « Bien sûr, apportez l'appareil au magasin avec les deux factures, et nous faisons l'échange tout de suite. » Le client est content : il passe cet après-midi.",
        questions: [
                            Exercise(id: "fr-listen-reclamation-facture-q1", kind: "choice", prompt: "Qu'est-ce que le client a acheté ?", options: ["Une imprimante", "Un vélo", "Un téléphone", "Une télévision"], answers: ["Une imprimante"], explain: "Bonjour, j'appelle au sujet d'une imprimante."),
                            Exercise(id: "fr-listen-reclamation-facture-q2", kind: "choice", prompt: "Quand est-ce que le client l'a achetée ?", options: ["La semaine dernière", "Hier", "Le mois dernier", "L'année dernière"], answers: ["La semaine dernière"], explain: "Je l'ai achetée dans votre magasin la semaine dernière."),
                            Exercise(id: "fr-listen-reclamation-facture-q3", kind: "written", prompt: "Depuis quand l'imprimante ne s'allume plus ?", options: [], answers: ["depuis hier", "hier"], explain: "Elle a bien marché deux jours, mais depuis hier elle ne s'allume plus."),
                            Exercise(id: "fr-listen-reclamation-facture-q4", kind: "choice", prompt: "Quel problème y a-t-il avec les factures ?", options: ["Il a reçu deux factures", "Il n'a pas de facture", "Il a perdu la facture", "La facture est illisible"], answers: ["Il a reçu deux factures"], explain: "De plus, j'ai reçu deux factures pour le même article."),
                            Exercise(id: "fr-listen-reclamation-facture-q5", kind: "written", prompt: "Qu'est-ce que le client demande ?", options: [], answers: ["un échange", "un echange", "il demande un échange"], explain: "Est-ce que je peux avoir un échange ? demande le client."),
                            Exercise(id: "fr-listen-reclamation-facture-q6", kind: "choice", prompt: "Que doit apporter le client au magasin ?", options: ["L'appareil et les deux factures", "Seulement le ticket", "Une nouvelle facture", "Rien, tout se fait au téléphone"], answers: ["L'appareil et les deux factures"], explain: "Apportez l'appareil au magasin avec les deux factures, dit le vendeur.")], skills: ["listening:detail", "listening:gist", "function:solve-problems", "grammar:past-simple-regular"]),
    ListeningText(id: "fr-listen-entretien-blanc", languageID: "fr", title: "L'entretien blanc", level: "B1", topic: "travail", unitID: "fr-foundations-u21",
        text: "Léa fait passer un entretien blanc à Karim, qui postule dans une agence de voyage. Léa : « Parlez-moi de votre expérience. » Karim : « J'ai travaillé trois ans dans une agence à Lyon, où j'ai géré les réservations et j'ai formé deux stagiaires. » Léa : « Quels sont vos points forts ? » Karim : « Je suis organisé et je reste calme quand un client s'énerve ; par contre, je parle encore peu anglais, mais je prends des cours le soir. » Léa : « Et vos objectifs ? » Karim : « J'aimerais évoluer vers le conseil, et à terme coordonner une équipe. » Léa : « Merci. Vous citez une vraie faiblesse, c'est plutôt bon signe : un candidat honnête inspire confiance. »",
        questions: [
                            Exercise(id: "fr-listen-entretien-blanc-q1", kind: "choice", prompt: "Où Karim veut-il travailler ?", options: ["Dans une agence de voyage", "Dans un restaurant", "Dans une école", "Dans un hôpital"], answers: ["Dans une agence de voyage"], explain: "Karim postule dans une agence de voyage."),
                            Exercise(id: "fr-listen-entretien-blanc-q2", kind: "written", prompt: "Combien d'années d'expérience Karim cite-t-il ?", options: [], answers: ["trois ans", "3 ans"], explain: "J'ai travaillé trois ans dans une agence à Lyon, dit Karim."),
                            Exercise(id: "fr-listen-entretien-blanc-q3", kind: "choice", prompt: "Quelle faiblesse Karim admet-il ?", options: ["Il parle peu anglais", "Il est désorganisé", "Il s'énerve vite", "Il n'a jamais formé personne"], answers: ["Il parle peu anglais"], explain: "Par contre, je parle encore peu anglais, mais je prends des cours le soir."),
                            Exercise(id: "fr-listen-entretien-blanc-q4", kind: "choice", prompt: "Que fait Karim pour progresser en anglais ?", options: ["Il prend des cours le soir", "Il regarde des films", "Il a arrêté d'apprendre", "Il voyage chaque mois"], answers: ["Il prend des cours le soir"], explain: "Mais je prends des cours le soir, précise Karim."),
                            Exercise(id: "fr-listen-entretien-blanc-q5", kind: "written", prompt: "Quel est l'objectif de long terme de Karim ?", options: [], answers: ["coordonner une équipe", "coordonner une equipe", "à terme coordonner une équipe"], explain: "Et à terme coordonner une équipe, dit Karim."),
                            Exercise(id: "fr-listen-entretien-blanc-q6", kind: "choice", prompt: "Pourquoi Léa juge-t-elle cet entretien bon signe ?", options: ["Karim est honnête sur sa faiblesse", "Karim parle parfaitement anglais", "Karim veut un salaire élevé", "Karim connaît déjà l'équipe"], answers: ["Karim est honnête sur sa faiblesse"], explain: "Vous citez une vraie faiblesse : un candidat honnête inspire confiance.")], skills: ["listening:inference", "listening:detail", "vocab:work", "function:talk-about-work"]),
    ListeningText(id: "fr-listen-ton-podcast", languageID: "fr", title: "Podcast : le ton juste", level: "C1", topic: "langue", unitID: "fr-foundations-u9",
        text: "Dans ce podcast, Léa interroge Mme Vasseur, rédactrice, sur le ton juste. Léa : « Un mail commence par je veux un délai : ça passe ? » Mme Vasseur : « Ça se comprend, mais ça sonne sec. On dira plutôt : j'aimerais qu'on envisage un délai supplémentaire. Le verbe envisager ouvre la discussion au lieu de la fermer. » Léa : « Et côté collocations ? » Mme Vasseur : « C'est là que ça se joue : on prend une décision, on tire une conclusion ; celui qui écrit faire une décision trahit une hâte. » Léa : « Donc le ton juste, c'est une affaire de mots choisis ? » Mme Vasseur : « Autant dire que oui : qui choisit ses verbes domine son sujet ; qui les subit paraît pressé, voire négligé. »",
        questions: [
                            Exercise(id: "fr-listen-ton-podcast-q1", kind: "choice", prompt: "Quel est le thème de l'émission ?", options: ["Le ton juste et les collocations", "L'orthographe des e-mails", "Le recrutement des rédacteurs", "La gestion du stress"], answers: ["Le ton juste et les collocations"], explain: "Léa interroge Mme Vasseur sur le ton juste, et la discussion porte sur les collocations."),
                            Exercise(id: "fr-listen-ton-podcast-q2", kind: "choice", prompt: "Quel problème Mme Vasseur relève-t-elle dans « je veux un délai » ?", options: ["Ça sonne sec", "C'est trop long", "C'est incorrect", "Ça manque d'exemples"], answers: ["Ça sonne sec"], explain: "Ça se comprend, mais ça sonne sec, dit-elle."),
                            Exercise(id: "fr-listen-ton-podcast-q3", kind: "written", prompt: "Quel verbe ouvre la discussion au lieu de la fermer ?", options: [], answers: ["envisager", "le verbe envisager"], explain: "Le verbe envisager ouvre la discussion au lieu de la fermer."),
                            Exercise(id: "fr-listen-ton-podcast-q4", kind: "choice", prompt: "Quelle paire de collocations Mme Vasseur donne-t-elle ?", options: ["Prendre une décision, tirer une conclusion", "Faire une décision, mettre une conclusion", "Prendre un choix, tirer une décision", "Faire un choix, prendre une conclusion"], answers: ["Prendre une décision, tirer une conclusion"], explain: "On prend une décision, on tire une conclusion."),
                            Exercise(id: "fr-listen-ton-podcast-q5", kind: "choice", prompt: "Que veut dire « qui choisit ses verbes domine son sujet » ?", options: ["Bien choisir ses mots rend crédible", "Écrire vite impressionne", "Les verbes font peur", "Les sujets dominent les mots"], answers: ["Bien choisir ses mots rend crédible"], explain: "Qui choisit ses verbes domine son sujet ; qui les subit paraît pressé."),
                            Exercise(id: "fr-listen-ton-podcast-q6", kind: "written", prompt: "Avec quelle formule Mme Vasseur conclut-elle ?", options: [], answers: ["autant dire que oui", "autant dire que"], explain: "Autant dire que oui, conclut Mme Vasseur.")], skills: ["listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion"]),
    ListeningText(id: "fr-listen-anniv-surprise", languageID: "fr", title: "La surprise de samedi", level: "A1", topic: "fête", unitID: "fr-foundations-u22",
        text: "Samedi, c'est l'anniversaire de Mai. Karim appelle Léa : « Tu es libre samedi soir ? On fait une surprise chez moi. » Léa accepte : « Bonne idée ! J'apporte le gâteau. » Karim prépare la musique et achète des fleurs, parce que Mai adore les fleurs. La fête commence à sept heures. C'est une surprise, alors Mai ne sait rien. À sept heures, elle arrive chez Karim et tout le monde crie : « Joyeux anniversaire ! » Mai est très contente et remercie tout le monde.",
        questions: [
                            Exercise(id: "fr-listen-anniv-surprise-q1", kind: "choice", prompt: "Qu'est-ce que c'est samedi ?", options: ["L'anniversaire de Mai", "L'anniversaire de Karim", "La fête du quartier", "Un mariage"], answers: ["L'anniversaire de Mai"], explain: "Samedi, c'est l'anniversaire de Mai."),
                            Exercise(id: "fr-listen-anniv-surprise-q2", kind: "choice", prompt: "Où est la fête ?", options: ["Chez Karim", "Chez Léa", "Au restaurant", "Chez Mai"], answers: ["Chez Karim"], explain: "À sept heures, elle arrive chez Karim."),
                            Exercise(id: "fr-listen-anniv-surprise-q3", kind: "choice", prompt: "Qu'est-ce que Léa apporte ?", options: ["Le gâteau", "La musique", "Les fleurs", "Les boissons"], answers: ["Le gâteau"], explain: "Léa accepte : « J'apporte le gâteau. »"),
                            Exercise(id: "fr-listen-anniv-surprise-q4", kind: "written", prompt: "À quelle heure commence la fête ?", options: [], answers: ["à sept heures", "a sept heures", "sept heures"], explain: "La fête commence à sept heures."),
                            Exercise(id: "fr-listen-anniv-surprise-q5", kind: "choice", prompt: "Pourquoi Mai ne sait rien ?", options: ["Parce que c'est une surprise", "Parce qu'elle est loin", "Parce qu'elle travaille", "Parce que Karim oublie"], answers: ["Parce que c'est une surprise"], explain: "C'est une surprise, alors Mai ne sait rien."),
                            Exercise(id: "fr-listen-anniv-surprise-q6", kind: "written", prompt: "Comment est Mai à la fin ?", options: [], answers: ["très contente", "tres contente", "contente", "très content"], explain: "Mai est très contente et remercie tout le monde.")], skills: ["listening:detail", "grammar:present-simple", "vocab:social-expressions"]),
    ListeningText(id: "fr-listen-cabine-essayage", languageID: "fr", title: "Dans la cabine", level: "A1", topic: "shopping", unitID: "fr-foundations-u23",
        text: "Léa est en boutique. Elle cherche une robe pour la fête de Mai. La vendeuse demande : « Vous cherchez quelle taille ? » Léa répond : « Du medium, je pense. » Elle trouve une robe verte : « Je peux l'essayer ? » La cabine est au fond. Dans la cabine, la robe est un peu trop grande. Léa demande : « Vous avez plus petit ? » La vendeuse apporte la taille en dessous. Léa l'essaie : ça va très bien. Elle dit : « Je la prends ! » À la caisse, ça fait 30 euros. Elle paie par carte et demande un sac.",
        questions: [
                            Exercise(id: "fr-listen-cabine-essayage-q1", kind: "choice", prompt: "Qu'est-ce que Léa cherche ?", options: ["Une robe", "Un t-shirt", "Un sac", "Des chaussures"], answers: ["Une robe"], explain: "Elle cherche une robe pour la fête de Mai."),
                            Exercise(id: "fr-listen-cabine-essayage-q2", kind: "choice", prompt: "Quelle est sa taille ?", options: ["Du medium", "Du small", "Du large", "Elle ne sait pas"], answers: ["Du medium"], explain: "Léa répond : « Du medium, je pense. »"),
                            Exercise(id: "fr-listen-cabine-essayage-q3", kind: "choice", prompt: "La première robe est comment ?", options: ["Un peu trop grande", "Trop petite", "Parfaite", "Trop chère"], answers: ["Un peu trop grande"], explain: "Dans la cabine, la robe est un peu trop grande."),
                            Exercise(id: "fr-listen-cabine-essayage-q4", kind: "written", prompt: "Qu'est-ce que Léa demande après ? (la taille)", options: [], answers: ["plus petit", "vous avez plus petit", "une taille plus petite"], explain: "Léa demande : « Vous avez plus petit ? »"),
                            Exercise(id: "fr-listen-cabine-essayage-q5", kind: "choice", prompt: "Comment paie-t-elle ?", options: ["Par carte", "En espèces", "Par chèque", "Avec le téléphone"], answers: ["Par carte"], explain: "Elle paie par carte et demande un sac."),
                            Exercise(id: "fr-listen-cabine-essayage-q6", kind: "written", prompt: "Combien ça fait à la caisse ?", options: [], answers: ["30 euros", "trente euros"], explain: "À la caisse, ça fait 30 euros.")], skills: ["listening:detail", "grammar:can", "vocab:shopping"]),
    ListeningText(id: "fr-listen-retour-magasin", languageID: "fr", title: "Retour au magasin", level: "A2", topic: "achats", unitID: "fr-foundations-u24",
        text: "Léa revient au magasin d'électronique. Elle a acheté un casque le 12 septembre, mais il ne marche plus : le son grésille à gauche. Au comptoir, elle explique : « J'ai bien vérifié la prise et j'ai changé le câble, mais rien à faire. » L'employé demande le ticket de caisse. Léa le sort de son sac. L'employé propose : « Vous pouvez l'échanger ou avoir un remboursement. » Léa choisit le remboursement : le modèle vert est moins cher et il est en stock, donc elle commandera celui-là. L'employé dit : « Vous recevrez l'argent sous cinq jours. » Léa repart contente : cette fois, elle prendra le moins cher des deux.",
        questions: [
                            Exercise(id: "fr-listen-retour-magasin-q1", kind: "choice", prompt: "Quel est le problème du casque ?", options: ["Le son grésille à gauche", "Il ne s'allume pas", "Le câble est cassé", "Il est trop petit"], answers: ["Le son grésille à gauche"], explain: "Il ne marche plus : le son grésille à gauche."),
                            Exercise(id: "fr-listen-retour-magasin-q2", kind: "written", prompt: "Quand Léa a-t-elle acheté le casque ?", options: [], answers: ["le 12 septembre", "12 septembre"], explain: "Elle a acheté un casque le 12 septembre."),
                            Exercise(id: "fr-listen-retour-magasin-q3", kind: "choice", prompt: "Quelles options l'employé propose-t-il ?", options: ["Échanger ou remboursement", "Réparer ou prêter", "Un avoir ou une carte cadeau", "Rien du tout"], answers: ["Échanger ou remboursement"], explain: "Vous pouvez l'échanger ou avoir un remboursement."),
                            Exercise(id: "fr-listen-retour-magasin-q4", kind: "choice", prompt: "Pourquoi Léa choisira le modèle vert ?", options: ["Il est moins cher et en stock", "Il est plus beau", "Il est plus solide", "Le bleu est épuisé"], answers: ["Il est moins cher et en stock"], explain: "Le modèle vert est moins cher et il est en stock."),
                            Exercise(id: "fr-listen-retour-magasin-q5", kind: "written", prompt: "Quand recevra-t-elle l'argent ?", options: [], answers: ["sous cinq jours", "dans cinq jours", "5 jours"], explain: "Vous recevrez l'argent sous cinq jours."),
                            Exercise(id: "fr-listen-retour-magasin-q6", kind: "choice", prompt: "Quel superlatif résume son choix final ?", options: ["Le moins cher des deux", "Le plus cher des deux", "Le plus grand", "Le plus lourd"], answers: ["Le moins cher des deux"], explain: "Cette fois, elle prendra le moins cher des deux.")], skills: ["listening:detail", "grammar:past-simple-regular", "function:solve-problems", "vocab:shopping"]),
    ListeningText(id: "fr-listen-veille-depart", languageID: "fr", title: "La veille du départ", level: "A2", topic: "voyage", unitID: "fr-foundations-u25",
        text: "Demain matin, Léa part pour Lisbonne à sept heures. Ce soir, elle fait sa valise. Elle va prendre trois t-shirts, un livre et, bien sûr, son maillot : l'hôtel a une piscine. Elle ne va pas prendre de parapluie, parce qu'il va faire beau toute la semaine. Il ne faut pas oublier les documents : passeport, billets et carte d'identité. À vingt heures, elle écrit un mot pour madame Roux : « Tu peux arroser les plantes ? Merci ! » Elle laisse le mot avec les clés. Enfin, elle met son réveil à cinq heures et demie, vérifie les fenêtres et va au lit. Tout est prêt.",
        questions: [
                            Exercise(id: "fr-listen-veille-depart-q1", kind: "choice", prompt: "Quand est-ce que Léa part ?", options: ["Demain à sept heures", "Ce soir à sept heures", "Demain à cinq heures et demie", "Après-demain"], answers: ["Demain à sept heures"], explain: "Demain matin, Léa part pour Lisbonne à sept heures."),
                            Exercise(id: "fr-listen-veille-depart-q2", kind: "written", prompt: "Qu'est-ce qu'elle va prendre pour la piscine ?", options: [], answers: ["son maillot", "le maillot", "un maillot"], explain: "Elle va prendre son maillot : l'hôtel a une piscine."),
                            Exercise(id: "fr-listen-veille-depart-q3", kind: "choice", prompt: "Pourquoi ne prend-elle pas de parapluie ?", options: ["Il va faire beau", "Elle en a déjà un", "L'hôtel en prête", "La valise est pleine"], answers: ["Il va faire beau"], explain: "Il ne va pas prendre de parapluie : il va faire beau toute la semaine."),
                            Exercise(id: "fr-listen-veille-depart-q4", kind: "written", prompt: "Qu'est-ce que madame Roux peut arroser ?", options: [], answers: ["les plantes"], explain: "Tu peux arroser les plantes ? Merci !"),
                            Exercise(id: "fr-listen-veille-depart-q5", kind: "choice", prompt: "À quelle heure est le réveil ?", options: ["À cinq heures et demie", "À cinq heures", "À sept heures", "À six heures"], answers: ["À cinq heures et demie"], explain: "Elle met son réveil à cinq heures et demie."),
                            Exercise(id: "fr-listen-veille-depart-q6", kind: "written", prompt: "Qu'est-ce qu'elle vérifie avant de dormir ?", options: [], answers: ["les fenêtres", "les fenetres"], explain: "Elle vérifie les fenêtres et va au lit.")], skills: ["listening:detail", "grammar:going-to", "vocab:travel"]),
    ListeningText(id: "fr-listen-quartier-reve", languageID: "fr", title: "Le débat de la place", level: "B1", topic: "ville", unitID: "fr-foundations-u26",
        text: "Au conseil de quartier, deux habitants débattent de la place végétalisée. Léa : « À mon avis, c'est une excellente idée. D'un côté, on aura plus d'ombre et moins de bruit ; de l'autre, les enfants auront un espace sûr. » Karim : « Je ne suis pas d'accord, parce que les arbres coûtent cher à entretenir. Et on se gare où ? » Léa : « Tu as raison sur le budget, mais les chiffres de Bordeaux sont clairs : ça attire plus de clients au marché. » Karim : « Concrètement, ça veut dire quoi ? » Léa : « Dix arbres, des pistes cyclables, et zéro voiture le dimanche. » Karim : « Bon, alors je vote pour. Mais on vote aussi sur les horaires ! »",
        questions: [
                            Exercise(id: "fr-listen-quartier-reve-q1", kind: "choice", prompt: "Quel est le projet débattu ?", options: ["Une place végétalisée", "Un parking souterrain", "Un marché couvert", "Une piscine"], answers: ["Une place végétalisée"], explain: "Deux habitants débattent du projet de place végétalisée."),
                            Exercise(id: "fr-listen-quartier-reve-q2", kind: "written", prompt: "Pour qui la place sera-t-elle un espace sûr ?", options: [], answers: ["les enfants", "pour les enfants"], explain: "Les enfants auront un espace sûr."),
                            Exercise(id: "fr-listen-quartier-reve-q3", kind: "choice", prompt: "Pourquoi Karim n'est-il pas d'accord ?", options: ["Les arbres coûtent cher à entretenir", "La place est trop petite", "Il préfère les voitures", "Les chiffres sont faux"], answers: ["Les arbres coûtent cher à entretenir"], explain: "Je ne suis pas d'accord, parce que les arbres coûtent cher à entretenir."),
                            Exercise(id: "fr-listen-quartier-reve-q4", kind: "choice", prompt: "Quel exemple convainc Karim ?", options: ["Les chiffres de Bordeaux", "Le vote du conseil", "Le prix du stationnement", "Une pétition des voisins"], answers: ["Les chiffres de Bordeaux"], explain: "Les chiffres de Bordeaux sont clairs : ça attire plus de clients au marché."),
                            Exercise(id: "fr-listen-quartier-reve-q5", kind: "written", prompt: "Combien d'arbres sont prévus ?", options: [], answers: ["dix arbres", "10 arbres"], explain: "Dix arbres, des pistes cyclables, et zéro voiture le dimanche."),
                            Exercise(id: "fr-listen-quartier-reve-q6", kind: "choice", prompt: "Qu'est-ce qui change le dimanche ?", options: ["Zéro voiture", "Le marché ferme", "Un grand nettoyage", "La vente de plantes"], answers: ["Zéro voiture"], explain: "Et zéro voiture le dimanche.")], skills: ["listening:inference", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "fr-listen-reunion-concrete", languageID: "fr", title: "Réunion de lundi", level: "B1", topic: "travail", unitID: "fr-work-u1",
        text: "Réunion de projet, lundi neuf heures. Le planning s'est encore tendu : le client attend la version finale vendredi. Léa ouvre : « Je pense que le planning est trop optimiste. D'un côté, on a presque fini la recherche ; de l'autre, les tests ne commencent que mercredi. » Karim propose : « Je propose de livrer sans le tableau de bord et de l'ajouter la semaine suivante. » Marta nuance : « Tu as raison, mais il faut prévenir le client tout de suite. » Après un court débat, Léa récapitule : « Je récapitule : on livre vendredi sans le tableau de bord, Marta écrit au client avant midi, Karim finit les tests jeudi. On est d'accord ? » Trois oui. La réunion dure douze minutes.",
        questions: [
                            Exercise(id: "fr-listen-reunion-concrete-q1", kind: "choice", prompt: "Quel est le problème principal ?", options: ["Le planning est trop optimiste", "Le client a annulé", "Le budget a explosé", "La recherche n'existe pas"], answers: ["Le planning est trop optimiste"], explain: "Je pense que le planning est trop optimiste."),
                            Exercise(id: "fr-listen-reunion-concrete-q2", kind: "choice", prompt: "Que propose Karim ?", options: ["Livrer sans le tableau de bord", "Annuler la livraison", "Recruter un testeur", "Avancer les tests à lundi"], answers: ["Livrer sans le tableau de bord"], explain: "Je propose de livrer sans le tableau de bord et de l'ajouter la semaine suivante."),
                            Exercise(id: "fr-listen-reunion-concrete-q3", kind: "written", prompt: "Qui écrit au client ?", options: [], answers: ["marta", "Marta"], explain: "Marta écrit au client avant midi."),
                            Exercise(id: "fr-listen-reunion-concrete-q4", kind: "written", prompt: "Quand Karim finit-il les tests ?", options: [], answers: ["jeudi", "le jeudi"], explain: "Karim finit les tests jeudi."),
                            Exercise(id: "fr-listen-reunion-concrete-q5", kind: "choice", prompt: "Combien de temps dure la réunion ?", options: ["Douze minutes", "Une heure", "Trente minutes", "Une demi-journée"], answers: ["Douze minutes"], explain: "La réunion dure douze minutes."),
                            Exercise(id: "fr-listen-reunion-concrete-q6", kind: "choice", prompt: "Qu'est-ce qui est livré vendredi ?", options: ["La version sans tableau de bord", "La version complète", "Un prototype papier", "Rien du tout"], answers: ["La version sans tableau de bord"], explain: "On livre vendredi sans le tableau de bord.")], skills: ["listening:detail", "function:talk-about-work", "grammar:connectors", "vocab:work"]),
    ListeningText(id: "fr-listen-mail-panne", languageID: "fr", title: "Le courriel à madame Dubois", level: "B1", topic: "travail", unitID: "fr-work-u1",
        text: "Karim doit écrire à madame Dubois, la cliente. Il demande conseil à Léa. Karim : « Je voudrais les chiffres du trimestre. Je lui écris : envoie-moi les chiffres ? » Léa sourit : « Trop direct. Écris : je vous écris au sujet des chiffres du trimestre. Pourriez-vous me les envoyer d'ici vendredi ? » Karim : « Et pour le devis ? » Léa : « Vous trouverez le devis ci-joint. Et termine par : je vous remercie par avance. » Karim envoie le courriel à onze heures. À quatorze heures, la réponse arrive : madame Dubois confirme tout et envoie même le rapport manquant. Karim apprend la leçon : en courriel pro, la politesse n'est pas du temps perdu.",
        questions: [
                            Exercise(id: "fr-listen-mail-panne-q1", kind: "choice", prompt: "Que veut Karim au début ?", options: ["Les chiffres du trimestre", "Un nouveau devis", "Une réunion avec Dubois", "Le rapport manquant"], answers: ["Les chiffres du trimestre"], explain: "Je voudrais les chiffres du trimestre."),
                            Exercise(id: "fr-listen-mail-panne-q2", kind: "written", prompt: "Pourquoi le premier message de Karim est-il mauvais ?", options: [], answers: ["trop direct", "il est trop direct", "parce qu'il est trop direct"], explain: "Léa sourit : « Trop direct. »"),
                            Exercise(id: "fr-listen-mail-panne-q3", kind: "choice", prompt: "Quelle échéance Léa propose-t-elle ?", options: ["D'ici vendredi", "D'ici lundi", "Avant midi", "Sans échéance"], answers: ["D'ici vendredi"], explain: "Pourriez-vous me les envoyer d'ici vendredi ?"),
                            Exercise(id: "fr-listen-mail-panne-q4", kind: "choice", prompt: "Quelle formule annonce la pièce jointe ?", options: ["Vous trouverez le devis ci-joint", "Je vous remercie par avance", "Cordialement", "Au sujet du devis"], answers: ["Vous trouverez le devis ci-joint"], explain: "Vous trouverez le devis ci-joint."),
                            Exercise(id: "fr-listen-mail-panne-q5", kind: "written", prompt: "À quelle heure la réponse arrive-t-elle ?", options: [], answers: ["à quatorze heures", "a quatorze heures", "14 heures", "quatorze heures"], explain: "À quatorze heures, la réponse arrive."),
                            Exercise(id: "fr-listen-mail-panne-q6", kind: "choice", prompt: "Quelle est la leçon de Karim ?", options: ["La politesse n'est pas du temps perdu", "Les courriels longs gagnent toujours", "Il ne faut jamais joindre de devis", "Les clientes répondent vite"], answers: ["La politesse n'est pas du temps perdu"], explain: "En courriel pro, la politesse n'est pas du temps perdu.")], skills: ["listening:detail", "writing:email", "vocab:work", "function:make-requests"]),
    ListeningText(id: "fr-listen-weekend-lyon", languageID: "fr", title: "Un week-end à Lyon", level: "A2", topic: "voyages", unitID: "fr-foundations-u25",
        text: "Mardi soir, dans le salon, Léa lance l'idée : « Et si on allait à Lyon ce week-end ? » Karim pose son téléphone : « Bonne idée. On va prendre le train de samedi matin ? » Léa vérifie sur son application : « Il y en a un à huit heures dix, on arrive vers dix. » Karim s'occupe de la suite : « Moi, je vais réserver l'hôtel ce soir, près de la place Bellecour. » Léa propose déjà le programme : « On va visiter le vieux Lyon samedi, et dimanche, on va manger dans un bouchon, tu sais, ces petits restaurants. » Karim sourit : « Parfait. Je vais prévenir ma sœur, elle nous prête son parapluie, il paraît qu'il va pleuvoir. »",
        questions: [
                            Exercise(id: "fr-listen-weekend-lyon-q1", kind: "choice", prompt: "Où va-t-on passer le week-end ?", options: ["À Lyon", "À Marseille", "À Paris", "À Nice"], answers: ["À Lyon"], explain: "« Et si on allait à Lyon ce week-end ? »"),
                            Exercise(id: "fr-listen-weekend-lyon-q2", kind: "written", prompt: "À quelle heure est le train du samedi ?", options: [], answers: ["à huit heures dix", "huit heures dix", "8h10", "a huit heures dix"], explain: "« Il y en a un à huit heures dix. »"),
                            Exercise(id: "fr-listen-weekend-lyon-q3", kind: "written", prompt: "Qui va réserver l'hôtel ?", options: [], answers: ["karim", "c'est karim", "karim va réserver l'hôtel"], explain: "« Moi, je vais réserver l'hôtel ce soir », dit Karim."),
                            Exercise(id: "fr-listen-weekend-lyon-q4", kind: "choice", prompt: "Où est l'hôtel ?", options: ["Près de la place Bellecour", "Près de la gare", "Dans le vieux Lyon", "Près du fleuve"], answers: ["Près de la place Bellecour"], explain: "« Près de la place Bellecour. »"),
                            Exercise(id: "fr-listen-weekend-lyon-q5", kind: "choice", prompt: "Que va-t-on faire dimanche ?", options: ["Manger dans un bouchon", "Visiter le vieux Lyon", "Rendre le parapluie", "Aller au musée"], answers: ["Manger dans un bouchon"], explain: "« Dimanche, on va manger dans un bouchon. »"),
                            Exercise(id: "fr-listen-weekend-lyon-q6", kind: "written", prompt: "Pourquoi la sœur de Karim prête-t-elle un parapluie ?", options: [], answers: ["parce qu'il va pleuvoir", "il va pleuvoir", "parce qu'il va pleuvoir"], explain: "« Il paraît qu'il va pleuvoir. »")], skills: ["listening:gist", "listening:detail", "grammar:going-to", "vocab:travel"]),
    ListeningText(id: "fr-listen-hotel-erreur", languageID: "fr", title: "La réservation disparue", level: "A2", topic: "problèmes", unitID: "fr-foundations-u20",
        text: "Vingt-deux heures, à la réception de l'hôtel. Karim pose son sac : « Bonsoir, j'ai une chambre au nom de Moreau, pour deux nuits. » La réceptionniste tape sur son clavier et fronce les sourcils : « Je suis désolée, je ne trouve rien. » Karim reste calme : « Il n'y a pas ma réservation ? J'ai la confirmation sur mon téléphone. » Elle regarde le courriel : « Ah, vous avez réservé dans l'hôtel du same nom, rue Voltaire. C'est à dix minutes d'ici. » Karim soupire : « Ah mince. Est-ce que vous pouvez m'aider ? » Elle appelle l'autre hôtel : « Bonne nouvelle : ils gardent votre chambre, et le tram s'arrête devant. » Karim reprend son sac : « Merci beaucoup. Pas grave, ça me va. »",
        questions: [
                            Exercise(id: "fr-listen-hotel-erreur-q1", kind: "choice", prompt: "Quel problème Karim découvre-t-il ?", options: ["Sa réservation n'est pas dans cet hôtel", "Sa chambre est trop petite", "Il a perdu sa confirmation", "L'hôtel est complet"], answers: ["Sa réservation n'est pas dans cet hôtel"], explain: "« Je ne trouve rien », dit la réceptionniste."),
                            Exercise(id: "fr-listen-hotel-erreur-q2", kind: "written", prompt: "Combien de nuits a-t-il réservées ?", options: [], answers: ["deux", "2", "deux nuits"], explain: "« Pour deux nuits. »"),
                            Exercise(id: "fr-listen-hotel-erreur-q3", kind: "choice", prompt: "Où est la vraie réservation ?", options: ["À l'hôtel du même nom, rue Voltaire", "Dans un hôtel près de la gare", "Dans un autre quartier de la ville", "L'hôtel n'existe pas"], answers: ["À l'hôtel du même nom, rue Voltaire"], explain: "« Vous avez réservé dans l'hôtel du même nom, rue Voltaire. »"),
                            Exercise(id: "fr-listen-hotel-erreur-q4", kind: "written", prompt: "À quelle distance est le bon hôtel ?", options: [], answers: ["à dix minutes", "dix minutes", "10 minutes", "a dix minutes"], explain: "« C'est à dix minutes d'ici. »"),
                            Exercise(id: "fr-listen-hotel-erreur-q5", kind: "choice", prompt: "Quelle est la bonne nouvelle à la fin ?", options: ["L'autre hôtel garde sa chambre", "Il obtient une chambre ici", "Il est remboursé", "La réceptionniste lui prête une chambre"], answers: ["L'autre hôtel garde sa chambre"], explain: "« Ils gardent votre chambre. »"),
                            Exercise(id: "fr-listen-hotel-erreur-q6", kind: "written", prompt: "Comment Karim réagit-il à la fin ?", options: [], answers: ["pas grave ça me va", "ça me va", "ca me va", "pas grave"], explain: "« Pas grave, ça me va. »")], skills: ["listening:detail", "listening:gist", "function:solve-problems", "vocab:travel"]),
    ListeningText(id: "fr-listen-train-annule", languageID: "fr", title: "Le train annulé", level: "A2", topic: "voyages", unitID: "fr-foundations-u25",
        text: "Samedi, huit heures, à la gare. Sur le panneau, en rouge : « Train de 8 h 10 — ANNULÉ ». Léa regarde Karim : « Ah mince ! Et maintenant ? » Karim consulte l'application : « Il y en a un à dix heures, mais il est complet. Le suivant, à onze heures trente, il reste des places. » Léa réfléchit : « Tu devrais réserver tout de suite, avant que ça se remplisse. » Karim réserve : « Voilà, c'est fait. On arrive à quatorze heures au lieu de onze. » Léa propose : « On pourrait déjeuner à la gare, comme ça, on ne perd rien. » Karim sourit : « Pas grave pour l'hôtel, je vais envoyer un message pour prévenir. » Léa : « Parfait. Bon, et si on prenait un café pendant d'attendre ? »",
        questions: [
                            Exercise(id: "fr-listen-train-annule-q1", kind: "choice", prompt: "Quel est le problème du samedi matin ?", options: ["Le train de huit heures dix est annulé", "La gare est fermée", "Ils ont perdu les billets", "Le train a une heure de retard"], answers: ["Le train de huit heures dix est annulé"], explain: "Sur le panneau : « Train de 8 h 10 — ANNULÉ »."),
                            Exercise(id: "fr-listen-train-annule-q2", kind: "written", prompt: "Quel train peut-on encore prendre ?", options: [], answers: ["celui de onze heures trente", "onze heures trente", "11h30", "de onze heures trente"], explain: "« Le suivant, à onze heures trente, il reste des places. »"),
                            Exercise(id: "fr-listen-train-annule-q3", kind: "choice", prompt: "Que conseille Léa ?", options: ["Réserver tout de suite", "Attendre demain", "Prendre le bus", "Annuler le voyage"], answers: ["Réserver tout de suite"], explain: "« Tu devrais réserver tout de suite. »"),
                            Exercise(id: "fr-listen-train-annule-q4", kind: "written", prompt: "À quelle heure arrivent-ils maintenant ?", options: [], answers: ["à quatorze heures", "quatorze heures", "14 heures", "a quatorze heures"], explain: "« On arrive à quatorze heures au lieu de onze. »"),
                            Exercise(id: "fr-listen-train-annule-q5", kind: "choice", prompt: "Quelle est l'alternative de Léa pour le déjeuner ?", options: ["Déjeuner à la gare", "Déjeuner dans le train", "Sauter le déjeuner", "Déjeuner à l'hôtel"], answers: ["Déjeuner à la gare"], explain: "« On pourrait déjeuner à la gare. »")], skills: ["listening:detail", "listening:inference", "grammar:modal-should", "vocab:transport"]),
    ListeningText(id: "fr-listen-soiree-potluck", languageID: "fr", title: "On organise la soirée", level: "A2", topic: "projets", unitID: "fr-foundations-u17",
        text: "Dans la cuisine, on prépare la soirée de samedi. Léa ouvre le frigo : « On va inviter Mai et Hugo, et chacun va apporter un plat. Comme ça, c'est moins cher. » Karim prend un papier : « Moi, je vais faire ma fameuse tarte aux pommes. » Léa rigole : « Si tu veux, mais je vais aussi préparer une salade, au cas où. » Karim continue la liste : « Hugo va apporter à boire, et Mai ? » Léa : « Elle va ramener ses jeux de société, elle a promis. » Karim note tout : « Et on va ranger le salon vendredi soir, comme ça, samedi on n'a rien à faire. » Léa attrape son téléphone : « Je vais envoyer le message au groupe, chacun sa mission ! »",
        questions: [
                            Exercise(id: "fr-listen-soiree-potluck-q1", kind: "choice", prompt: "Quel est le principe de la soirée ?", options: ["Chacun apporte un plat", "On commande des pizzas", "On va au restaurant", "Léa cuisine tout"], answers: ["Chacun apporte un plat"], explain: "« Chacun va apporter un plat. Comme ça, c'est moins cher. »"),
                            Exercise(id: "fr-listen-soiree-potluck-q2", kind: "written", prompt: "Que va préparer Karim ?", options: [], answers: ["une tarte aux pommes", "tarte aux pommes", "sa tarte aux pommes", "la tarte"], explain: "« Je vais faire ma fameuse tarte aux pommes. »"),
                            Exercise(id: "fr-listen-soiree-potluck-q3", kind: "choice", prompt: "Que va apporter Mai ?", options: ["Des jeux de société", "À boire", "Une salade", "Des desserts"], answers: ["Des jeux de société"], explain: "« Elle va ramener ses jeux de société. »"),
                            Exercise(id: "fr-listen-soiree-potluck-q4", kind: "written", prompt: "Quand va-t-on ranger le salon ?", options: [], answers: ["vendredi soir", "vendredi", "le vendredi soir"], explain: "« On va ranger le salon vendredi soir. »"),
                            Exercise(id: "fr-listen-soiree-potluck-q5", kind: "choice", prompt: "Que va faire Léa en dernier ?", options: ["Envoyer le message au groupe", "Préparer une salade", "Ranger le salon", "Acheter à boire"], answers: ["Envoyer le message au groupe"], explain: "« Je vais envoyer le message au groupe, chacun sa mission ! »")], skills: ["listening:gist", "listening:detail", "grammar:going-to", "vocab:food"]),
    ListeningText(id: "fr-listen-bagage-perdu", languageID: "fr", title: "La valise n'est pas arrivée", level: "A2", topic: "problèmes", unitID: "fr-foundations-u20",
        text: "À l'aéroport de Lisbonne, le tapis s'arrête, vide. Léa reste seule avec son sac à dos : « Non, pas ça… Ma valise n'est pas là. » Elle va au comptoir bagages avec l'étiquette bleue. L'employée tape le numéro : « Votre valise est restée à Paris, elle arrive avec le vol de ce soir. » Léa encaisse : « Ah mince. Est-ce que vous pouvez la livrer à mon hôtel ? Je suis à Albufeira jusqu'à dimanche. » L'employée note l'adresse : « Bien sûr, elle sera là demain matin. Vous avez besoin d'une trousse de toilette ? » Léa accepte le petit sac offert : « Oui, merci. Il y a ma brosse à dents dedans ? » L'employée sourit : « Il y a l'essentiel. Pas de panique, madame. »",
        questions: [
                            Exercise(id: "fr-listen-bagage-perdu-q1", kind: "choice", prompt: "Quel est le problème de Léa ?", options: ["Sa valise n'est pas arrivée", "Elle a perdu son billet", "Son vol est annulé", "Elle a oublié son sac à dos"], answers: ["Sa valise n'est pas arrivée"], explain: "« Ma valise n'est pas là. »"),
                            Exercise(id: "fr-listen-bagage-perdu-q2", kind: "written", prompt: "Où est restée la valise ?", options: [], answers: ["à paris", "paris", "a paris", "elle est restée à paris"], explain: "« Votre valise est restée à Paris. »"),
                            Exercise(id: "fr-listen-bagage-perdu-q3", kind: "written", prompt: "Quand la valise arrive-t-elle à l'aéroport ?", options: [], answers: ["ce soir", "avec le vol de ce soir", "soir"], explain: "« Elle arrive avec le vol de ce soir. »"),
                            Exercise(id: "fr-listen-bagage-perdu-q4", kind: "choice", prompt: "Quand Léa recevra-t-elle sa valise à l'hôtel ?", options: ["Demain matin", "Ce soir", "Dimanche", "Dans deux jours"], answers: ["Demain matin"], explain: "« Elle sera là demain matin. »"),
                            Exercise(id: "fr-listen-bagage-perdu-q5", kind: "choice", prompt: "Que donne l'employée à Léa ?", options: ["Une trousse de toilette", "Un nouveau billet", "Un repas gratuit", "Une autre valise"], answers: ["Une trousse de toilette"], explain: "« Vous avez besoin d'une trousse de toilette ? »")], skills: ["listening:detail", "function:solve-problems", "vocab:travel"]),
    ListeningText(id: "fr-listen-velos-location", languageID: "fr", title: "Location de vélos", level: "A2", topic: "voyages", unitID: "fr-foundations-u25",
        text: "Devant la boutique « Roule ma poule », Karim entre avec Léa. Le loueur s'avance : « Bonjour ! Pour la journée, c'est douze euros le vélo, casque compris. » Léa sort sa carte : « Deux vélos pour aujourd'hui, s'il vous plaît. » Le loueur remplit le formulaire : « Vous les rendez avant dix-neuf heures, la boutique ferme à dix-neuf heures trente. » Karim demande : « Le chemin de la côte, c'est loin ? » Le loueur sourit : « Comptez vingt minutes jusqu'à la plage, c'est plat. Mais prenez de l'eau, il fait trente degrés aujourd'hui. » Léa attrape son casque : « Et si on veut garder les vélos demain ? » Le loueur : « Le deuxième jour, c'est moitié prix. Vous me dites ce soir. »",
        questions: [
                            Exercise(id: "fr-listen-velos-location-q1", kind: "written", prompt: "Combien coûte la location d'un vélo pour la journée ?", options: [], answers: ["douze euros", "12 euros", "12€", "douze"], explain: "« Pour la journée, c'est douze euros le vélo. »"),
                            Exercise(id: "fr-listen-velos-location-q2", kind: "choice", prompt: "Qu'est-ce qui est compris dans le prix ?", options: ["Le casque", "Le pique-nique", "L'eau", "Le panier"], answers: ["Le casque"], explain: "« Douze euros le vélo, casque compris. »"),
                            Exercise(id: "fr-listen-velos-location-q3", kind: "written", prompt: "Avant quelle heure faut-il rendre les vélos ?", options: [], answers: ["dix-neuf heures", "19 heures", "19h", "dix neuf heures"], explain: "« Vous les rendez avant dix-neuf heures. »"),
                            Exercise(id: "fr-listen-velos-location-q4", kind: "written", prompt: "Combien de temps faut-il jusqu'à la plage ?", options: [], answers: ["vingt minutes", "20 minutes", "20 min"], explain: "« Comptez vingt minutes jusqu'à la plage. »"),
                            Exercise(id: "fr-listen-velos-location-q5", kind: "choice", prompt: "Quel est le tarif du deuxième jour ?", options: ["Moitié prix", "Le même prix", "Gratuit", "Le double"], answers: ["Moitié prix"], explain: "« Le deuxième jour, c'est moitié prix. »")], skills: ["listening:number-time", "listening:detail", "grammar:can", "vocab:transport"]),
    ListeningText(id: "fr-listen-debat-teletravail", languageID: "fr", title: "Débat : le bureau a-t-il encore un sens ?", level: "B2", topic: "débats", unitID: "fr-foundations-u7",
        text: "Sur le plateau, deux chroniqueurs s'affrontent. Nadia ouvre : « Le télétravail a tué le bureau, tant mieux. Moins de transports, plus d'autonomie : les études sur la productivité sont formelles. » Marc rebondit : « Formelles, vraiment ? Ces études oublient les jeunes embauchés qui apprennent leur métier seuls, devant un écran. L'entreprise, c'est aussi un lieu. » Nadia concède un point : « Je vous accorde l'apprentissage, mais la solution n'est pas le retour imposé à temps plein. Trois jours chez soi, deux au bureau : c'est le compromis que la plupart revendiquent. » Marc sourit : « Vous savez ce qui m'inquiète ? Les invisibles : ceux qui n'osent pas demander. Si le bureau devient un privilège de cadres, on aura remplacé une contrainte par une inégalité. » Le modérateur coupe : « Nous reviendrons dessus après la pause. »",
        questions: [
                            Exercise(id: "fr-listen-debat-teletravail-q1", kind: "choice", prompt: "Quelle est la position de Nadia ?", options: ["Le télétravail est une bonne chose", "Il faut revenir au bureau à temps plein", "Le télétravail devrait être interdit", "Elle ne prend pas position"], answers: ["Le télétravail est une bonne chose"], explain: "« Le télétravail a tué le bureau, tant mieux. »"),
                            Exercise(id: "fr-listen-debat-teletravail-q2", kind: "written", prompt: "Quel groupe Marc estime-t-on avoir oublié dans les études ?", options: [], answers: ["les jeunes embauchés", "les jeunes", "les nouveaux embauchés", "les jeunes qui apprennent leur métier seuls"], explain: "« Ces études oublient les jeunes embauchés qui apprennent leur métier seuls. »"),
                            Exercise(id: "fr-listen-debat-teletravail-q3", kind: "written", prompt: "Quel compromis Nadia défend-elle ?", options: [], answers: ["trois jours chez soi deux au bureau", "trois jours chez soi", "3 jours de télétravail et 2 au bureau", "deux jours au bureau"], explain: "« Trois jours chez soi, deux au bureau. »"),
                            Exercise(id: "fr-listen-debat-teletravail-q4", kind: "choice", prompt: "Quelle inégalité Marc redoute-t-il ?", options: ["Le bureau réservé aux cadres", "Les salaires plus bas en télétravail", "Les transports bondés", "Les écrans cassés"], answers: ["Le bureau réservé aux cadres"], explain: "« Si le bureau devient un privilège de cadres… »"),
                            Exercise(id: "fr-listen-debat-teletravail-q5", kind: "choice", prompt: "Comment Marc qualifie-t-il sa crainte ?", options: ["On remplace une contrainte par une inégalité", "La productivité va s'effondrer", "Les bureaux vont disparaître", "Les études sont truquées"], answers: ["On remplace une contrainte par une inégalité"], explain: "« On aura remplacé une contrainte par une inégalité. »")], skills: ["listening:inference", "function:express-opinion", "grammar:connectors", "vocab:work"]),
    ListeningText(id: "fr-listen-negoc-loyer", languageID: "fr", title: "Négocier le renouvellement du bail", level: "B2", topic: "négociation", unitID: "fr-foundations-u7",
        text: "Dans le salon de l'appartement, Inès reçoit le propriétaire. Il annonce la couleur : « Le voisinage monte, madame Diallo. Je passe le loyer à mille deux cents euros. » Inès ne se braque pas : « Je comprends le marché, mais trois ans de locataire sans un jour de retard, ça a une valeur. Je vous propose mille cent. » Il tique : « Mille cent ? Vous me faites rire. Mille cent soixante-quinze. » Elle sort un argument : « Je peux aussi m'engager sur vingt-quatre mois, pas dix-huit. Et je repeins le couloir à mes frais. » Il hésite, regarde le plafond : « Vingt-quatre mois, ça, c'est intéressant… Mille cent cinquante, et c'est ma dernière. » Inès tend la main : « Mille cent quarante, et on signe ce soir. » Il rit : « Vous négociez comme un agent ! Marché conclu. »",
        questions: [
                            Exercise(id: "fr-listen-negoc-loyer-q1", kind: "choice", prompt: "Combien le propriétaire demande-t-il au départ ?", options: ["Mille deux cents euros", "Mille cent euros", "Mille cent soixante-quinze euros", "Mille cent cinquante euros"], answers: ["Mille deux cents euros"], explain: "« Je passe le loyer à mille deux cents euros. »"),
                            Exercise(id: "fr-listen-negoc-loyer-q2", kind: "written", prompt: "Quel argument sur sa fiabilité Inès avance-t-elle ?", options: [], answers: ["trois ans sans un jour de retard", "trois ans de locataire sans retard", "elle n'a jamais eu de retard", "3 ans sans retard"], explain: "« Trois ans de locataire sans un jour de retard, ça a une valeur. »"),
                            Exercise(id: "fr-listen-negoc-loyer-q3", kind: "choice", prompt: "Que propose-t-elle en échange d'un meilleur prix ?", options: ["Vingt-quatre mois d'engagement et repeindre le couloir", "De partir dans six mois", "De payer deux mois d'avance", "De trouver un autre locataire"], answers: ["Vingt-quatre mois d'engagement et repeindre le couloir"], explain: "« Je peux m'engager sur vingt-quatre mois. Et je repeins le couloir à mes frais. »"),
                            Exercise(id: "fr-listen-negoc-loyer-q4", kind: "written", prompt: "À combien le propriétaire fixe-t-il sa dernière offre ?", options: [], answers: ["mille cent cinquante", "1150 euros", "mille cent cinquante euros", "1150"], explain: "« Mille cent cinquante, et c'est ma dernière. »"),
                            Exercise(id: "fr-listen-negoc-loyer-q5", kind: "written", prompt: "À quel prix signent-ils finalement ?", options: [], answers: ["mille cent quarante", "1140 euros", "mille cent quarante euros", "1140"], explain: "« Mille cent quarante, et on signe ce soir. »")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "fr-listen-actu-canicule", languageID: "fr", title: "Journal : la ville s'adapte à la chaleur", level: "B2", topic: "actualité", unitID: "fr-foundations-u8",
        text: "Dernière édition : la canicule qui s'installe oblige les métropoles à s'adapter. À Lyon, les fontaines brumisatrices, installées l'année dernière, ont été ouvertes en continu. Les écoles privées de cours d'école goudronnée reçoivent des subventions pour végétaliser leurs cours. La mairie, dont le plan a été voté à l'unanimité, fermera aussi les parcs à midi les jours d'alerte rouge. Le rapport présenté hier chiffre l'enjeu : la température urbaine a grimpé de deux degrés en dix ans. Les opposants, eux, dénoncent un plan cosmetic : « On brumise les piétons pendant que les parkings climatisés, eux, tournent à plein. » La ville répond que la deuxième phase, qui sera débattue en septembre, visera les bâtiments publics. Les associations demandent déjà des audiences ouvertes.",
        questions: [
                            Exercise(id: "fr-listen-actu-canicule-q1", kind: "choice", prompt: "Qu'est-ce qui oblige les métropoles à s'adapter ?", options: ["La canicule qui s'installe", "Une élection prochaine", "Une décision européenne", "Le coût de l'eau"], answers: ["La canicule qui s'installe"], explain: "« La canicule qui s'installe oblige les métropoles à s'adapter. »"),
                            Exercise(id: "fr-listen-actu-canicule-q2", kind: "written", prompt: "Que reçoivent les écoles à cour goudronnée ?", options: [], answers: ["des subventions", "subventions", "des subventions pour végétaliser", "de l'argent"], explain: "« Les écoles… reçoivent des subventions pour végétaliser leurs cours. »"),
                            Exercise(id: "fr-listen-actu-canicule-q3", kind: "written", prompt: "De combien la température urbaine a-t-elle grimpé en dix ans ?", options: [], answers: ["deux degrés", "2 degrés", "2°", "de deux degrés"], explain: "« La température urbaine a grimpé de deux degrés en dix ans. »"),
                            Exercise(id: "fr-listen-actu-canicule-q4", kind: "choice", prompt: "Que reprochent les opposants au plan ?", options: ["Il est surtout cosmétique", "Il coûte trop cher", "Il ferme trop d'écoles", "Il arrive trop tard"], answers: ["Il est surtout cosmétique"], explain: "« On brumise les piétons pendant que les parkings climatisés tournent à plein. »"),
                            Exercise(id: "fr-listen-actu-canicule-q5", kind: "choice", prompt: "Que visera la deuxième phase du plan ?", options: ["Les bâtiments publics", "Les parkings privés", "Les fontaines", "Les écoles maternelles"], answers: ["Les bâtiments publics"], explain: "« La deuxième phase… visera les bâtiments publics. »")], skills: ["listening:inference", "listening:detail", "grammar:passive-intro", "grammar:relative-clauses"]),
    ListeningText(id: "fr-listen-debat-notes", languageID: "fr", title: "Débat : faut-il supprimer les notes ?", level: "B2", topic: "débats", unitID: "fr-foundations-u7",
        text: "Thème du jour : l'école sans notes. Salif tranche d'entrée : « Une note, c'est un jugement qui remplace un retour. Un élève qui reçoit huit sur vingt ne sait pas ce qu'il doit corriger. » Claire oppose l'expérience : « Sans notes, mon frère n'aurait jamais ouvert un livre. La compétition le réveille. Ce qui compte, c'est ce qu'on met derrière : des commentaires précis. » Salif concède : « Je ne dis pas de tout supprimer du jour au lendemain. Je dis qu'on devrait tester : une année, deux collèges, des évaluations écrites détaillées. » Claire sourit : « Voilà une proposition intéressante, à condition de former les enseignants. Sinon, vous remplacez un chiffre par du blabla. » Le modérateur conclut : « Deux camps, un accord : tout dépendra de la mise en œuvre. »",
        questions: [
                            Exercise(id: "fr-listen-debat-notes-q1", kind: "choice", prompt: "Quel est le problème principal que Salif voit dans la note ?", options: ["Elle ne dit pas quoi corriger", "Elle est trop rare", "Elle favorise les bons élèves", "Elle stresse les parents"], answers: ["Elle ne dit pas quoi corriger"], explain: "« Un élève qui reçoit huit sur vingt ne sait pas ce qu'il doit corriger. »"),
                            Exercise(id: "fr-listen-debat-notes-q2", kind: "written", prompt: "Pourquoi Claire défend-elle la note ?", options: [], answers: ["la compétition réveille", "la compétition réveille les élèves", "elle motive", "parce que la compétition réveille"], explain: "« La compétition le réveille. »"),
                            Exercise(id: "fr-listen-debat-notes-q3", kind: "written", prompt: "Quelle expérience Salif propose-t-il ?", options: [], answers: ["une année deux collèges", "tester deux collèges pendant un an", "une année de test dans deux collèges", "2 collèges 1 an"], explain: "« On devrait tester : une année, deux collèges. »"),
                            Exercise(id: "fr-listen-debat-notes-q4", kind: "choice", prompt: "À quelle condition Claire accepte-t-elle l'expérience ?", options: ["Former les enseignants", "Garder les examens finaux", "Prévenir les parents", "Commencer en terminale"], answers: ["Former les enseignants"], explain: "« À condition de former les enseignants. »"),
                            Exercise(id: "fr-listen-debat-notes-q5", kind: "choice", prompt: "Sur quoi les deux camps se rejoignent-ils ?", options: ["Tout dépendra de la mise en œuvre", "Les notes doivent disparaître", "Les notes doivent rester", "L'école est en crise"], answers: ["Tout dépendra de la mise en œuvre"], explain: "« Deux camps, un accord : tout dépendra de la mise en œuvre. »")], skills: ["listening:inference", "function:express-opinion", "grammar:connectors", "vocab:collocations"]),
    ListeningText(id: "fr-listen-negoc-festival", languageID: "fr", title: "Négocier le budget du festival de quartier", level: "B2", topic: "négociation", unitID: "fr-foundations-u8",
        text: "À la mairie d'arrondissement, l'association des commerçants défend son festival. Madame Costa expose : « Trois mille euros, et la rue des Écoles devient une scène ouverte pendant deux jours. » L'adjoint secoue la tête : « Le budget culture est serré. Je peux vous accorder mille huit cents. » Madame Costa ne lâche pas : « Mille huit cents, c'est la sono et rien d'autre. Regardez les retombées : l'an dernier, les commerçants du voisinage ont fait un chiffre d'affaires supérieur de trente pour cent ce week-end-là. » L'adjoint ouvre son classeur : « Admettons deux mille deux cents. Vous trouvez le reste en parrainages. » Elle joue son dernier carton : « Deux mille quatre cents, et nous affichons le logo de la mairie sur la scène. » L'adjoint rit : « Vous me vendez ma propre publicité ! D'accord pour deux mille quatre, mais je veux le programme avant juin. »",
        questions: [
                            Exercise(id: "fr-listen-negoc-festival-q1", kind: "written", prompt: "Combien l'association demande-t-elle au départ ?", options: [], answers: ["trois mille euros", "3000 euros", "trois mille", "3000"], explain: "« Trois mille euros, et la rue des Écoles devient une scène ouverte. »"),
                            Exercise(id: "fr-listen-negoc-festival-q2", kind: "choice", prompt: "Que propose l'adjoint dans un premier temps ?", options: ["Mille huit cents euros", "Deux mille deux cents euros", "Rien du tout", "Deux mille quatre cents euros"], answers: ["Mille huit cents euros"], explain: "« Je peux vous accorder mille huit cents. »"),
                            Exercise(id: "fr-listen-negoc-festival-q3", kind: "written", prompt: "Quel chiffre d'affaires les commerçants ont-ils réalisé l'an dernier ce week-end ?", options: [], answers: ["trente pour cent de plus", "30 % de plus", "30% de plus", "trente pour cent supérieur"], explain: "« Un chiffre d'affaires supérieur de trente pour cent. »"),
                            Exercise(id: "fr-listen-negoc-festival-q4", kind: "choice", prompt: "Que promet Madame Costa en échange des deux mille quatre cents ?", options: ["Le logo de la mairie sur la scène", "Un concert gratuit", "Des places réservées", "Un stand pour la mairie"], answers: ["Le logo de la mairie sur la scène"], explain: "« Nous affichons le logo de la mairie sur la scène. »"),
                            Exercise(id: "fr-listen-negoc-festival-q5", kind: "written", prompt: "Quelle condition l'adjoint pose-t-il à la fin ?", options: [], answers: ["le programme avant juin", "recevoir le programme avant juin", "le programme avant juin", "programme avant juin"], explain: "« Je veux le programme avant juin. »")], skills: ["listening:inference", "function:negotiate", "grammar:first-conditional", "grammar:connectors"]),
    ListeningText(id: "fr-listen-anecdote-train-perdu", languageID: "fr", title: "L'anecdote du train manqué", level: "B1", topic: "récits", unitID: "fr-foundations-u18",
        text: "Au déjeuner, Hugo raconte encore son week-end catastrophique. « Je vous jure, tout est allé de travers. Samedi, je devais prendre le train de sept heures pour aller à l'anniversaire de ma cousine. Mon réveil n'a pas sonné — enfin, il a sonné, mais j'avais oublié de le mettre en sonnerie. Je me suis réveillé à sept heures et quart, chez moi, avec le train déjà parti. J'ai couru jusqu'à la gare en pyjama, enfin, à peu près, et l'agent m'a dit : le prochain est à midi. Ma cousine a ouvert la porte à vingt heures. Il ne restait qu'un morceau de gâteau. Le pire ? Le lendemain, la femme de ménage a trouvé mon pyjama dans le hall de la gare. Depuis, ma cousine m'appelle « monsieur midi ». »",
        questions: [
                            Exercise(id: "fr-listen-anecdote-train-perdu-q1", kind: "choice", prompt: "Pourquoi Hugo a-t-il raté son train ?", options: ["Son réveil n'était pas en sonnerie", "Il est tombé malade", "Le train est parti plus tôt", "Il s'est trompé de gare"], answers: ["Son réveil n'était pas en sonnerie"], explain: "« Il a sonné, mais j'avais oublié de le mettre en sonnerie. »"),
                            Exercise(id: "fr-listen-anecdote-train-perdu-q2", kind: "written", prompt: "À quelle heure s'est-il réveillé ?", options: [], answers: ["à sept heures et quart", "sept heures et quart", "7h15", "a sept heures et quart"], explain: "« Je me suis réveillé à sept heures et quart. »"),
                            Exercise(id: "fr-listen-anecdote-train-perdu-q3", kind: "written", prompt: "À quelle heure a-t-il finalement frappé chez sa cousine ?", options: [], answers: ["à vingt heures", "vingt heures", "8 heures du soir", "20 heures"], explain: "« Ma cousine a ouvert la porte à vingt heures. »"),
                            Exercise(id: "fr-listen-anecdote-train-perdu-q4", kind: "choice", prompt: "Où la femme de ménage a-t-elle trouvé son pyjama ?", options: ["Dans le hall de la gare", "Dans le train", "Chez sa cousine", "Dans la rue"], answers: ["Dans le hall de la gare"], explain: "« La femme de ménage a trouvé mon pyjama dans le hall de la gare. »"),
                            Exercise(id: "fr-listen-anecdote-train-perdu-q5", kind: "written", prompt: "Comment sa cousine l'appelle-t-elle maintenant ?", options: [], answers: ["monsieur midi", "m monsieur midi", "« monsieur midi »"], explain: "« Depuis, ma cousine m'appelle “monsieur midi”. »"),
                            Exercise(id: "fr-listen-anecdote-train-perdu-q6", kind: "choice", prompt: "Qu'est-ce qui restait du gâteau quand Hugo est arrivé ?", options: ["Un morceau", "La moitié", "Deux parts", "Rien du tout"], answers: ["Un morceau"], explain: "« Il ne restait qu'un morceau de gâteau. »")], skills: ["listening:inference", "function:tell-a-story", "grammar:connectors", "vocab:travel"]),
    ListeningText(id: "it-listen-cafe-morning", languageID: "it", title: "Un caffè prima del lavoro", level: "A1", topic: "routine", unitID: "it-foundations-u1",
        text: "Ogni mattina, Marta cammina fino a un piccolo caffè vicino a casa sua. Il cameriere conosce il suo nome, così non deve mai ordinare. Oggi si siede vicino alla finestra con un caffè e un cornetto. Il suo autobus parte alle otto e mezza, ma non è preoccupata. Il caffè è molto tranquillo a quell'ora. Beve il caffè lentamente e guarda la città che si sveglia.",
        questions: [
                            Exercise(id: "it-listen-cafe-morning-q1", kind: "choice", prompt: "Dove va Marta ogni mattina?", options: ["In un piccolo caffè", "Al suo ufficio", "Alla stazione degli autobus", "In un parco"], answers: ["In un piccolo caffè"], explain: "Cammina fino a un piccolo caffè vicino a casa sua."),
                            Exercise(id: "it-listen-cafe-morning-q2", kind: "choice", prompt: "Cosa fa colazione oggi?", options: ["Un caffè e un cornetto", "Tè e toast", "Succo d'arancia", "Niente"], answers: ["Un caffè e un cornetto"], explain: "Si siede vicino alla finestra con un caffè e un cornetto."),
                            Exercise(id: "it-listen-cafe-morning-q3", kind: "written", prompt: "A che ora parte il suo autobus?", options: [], answers: ["alle otto e mezza", "otto e mezza"], explain: "Il suo autobus parte alle otto e mezza."),
                            Exercise(id: "it-listen-cafe-morning-q4", kind: "choice", prompt: "Come si sente per l'orario?", options: ["Non è preoccupata", "È in grandissimo ritardo", "È arrabbiata", "Ha sonno"], answers: ["Non è preoccupata"], explain: "Il testo dice che non è preoccupata."),
                            Exercise(id: "it-listen-cafe-morning-q5", kind: "choice", prompt: "Chi conosce il suo nome?", options: ["Il cameriere", "L'autista dell'autobus", "Il suo capo", "Un vicino"], answers: ["Il cameriere"], explain: "Il cameriere conosce il suo nome, così non deve mai ordinare."),
                            Exercise(id: "it-listen-cafe-morning-q6", kind: "written", prompt: "Dove si siede oggi?", options: [], answers: ["vicino alla finestra", "accanto alla finestra", "alla finestra"], explain: "Oggi si siede vicino alla finestra.")], skills: ["listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine"]),
    ListeningText(id: "it-listen-language-class", languageID: "it", title: "Il corso di lingua", level: "A1", topic: "presentazioni", unitID: "it-foundations-u1",
        text: "Marta partecipa alla sua prima lezione di portoghese in un piccolo istituto. In classe ci sono sei persone e tutti vogliono parlare. L'insegnante chiede le presentazioni. « Mi chiamo Marta e sono della Bolivia », dice una signora. « Io sono Andrés, sono del Perù e lavoro in un ristorante », dice un ragazzo. Marta si presenta anche lei: « Sono Marta, sono argentina e sono infermiera ». L'insegnante è di Madrid e insegna con molto humour. Alla fine della lezione, gli studenti si scambiano i numeri di telefono. Non sono ancora amici, ma la prossima settimana vanno a prendere un caffè insieme per praticare.",
        questions: [
                            Exercise(id: "it-listen-language-class-q1", kind: "choice", prompt: "Quante persone ci sono in classe?", options: ["Sei", "Tre", "Dieci", "Quattordici"], answers: ["Sei"], explain: "In classe ci sono sei persone."),
                            Exercise(id: "it-listen-language-class-q2", kind: "choice", prompt: "Di dov'è Andrés?", options: ["Del Perù", "Della Bolivia", "Dell'Argentina", "Del Messico"], answers: ["Del Perù"], explain: "Andrés è del Perù e lavora in un ristorante."),
                            Exercise(id: "it-listen-language-class-q3", kind: "choice", prompt: "Qual è il lavoro di Marta?", options: ["Infermiera", "Insegnante", "Cameriera", "Studentessa"], answers: ["Infermiera"], explain: "Marta è argentina ed è infermiera."),
                            Exercise(id: "it-listen-language-class-q4", kind: "written", prompt: "Di che città è l'insegnante?", options: [], answers: ["madrid", "di madrid", "è di madrid"], explain: "L'insegnante è di Madrid."),
                            Exercise(id: "it-listen-language-class-q5", kind: "choice", prompt: "Cosa fanno alla fine della lezione?", options: ["Si scambiano i numeri di telefono", "Tornano a casa da soli", "Fanno un esame", "Cenano al ristorante"], answers: ["Si scambiano i numeri di telefono"], explain: "Gli studenti si scambiano i numeri di telefono."),
                            Exercise(id: "it-listen-language-class-q6", kind: "written", prompt: "Cosa fanno la prossima settimana?", options: [], answers: ["prendere un caffè", "vanno a prendere un caffè", "prendere un caffè insieme"], explain: "La prossima settimana vanno a prendere un caffè insieme per praticare.")], skills: ["listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself"]),
    ListeningText(id: "it-listen-little-sister", languageID: "it", title: "Mia sorella piccola", level: "A1", topic: "famiglia", unitID: "it-foundations-u1",
        text: "Mia sorella piccola si chiama Carla e ha nove anni. È molto simpatica e molto chiacchierona. Carla non è riservata: parla con tutti, con i vicini, con gli insegnanti e con i cani del parco. È bionda, come nostra madre, e ha gli occhi castani come mio padre. Non è alta per la sua età, ma è molto veloce e le piace tantissimo il calcio. La sua squadra non è molto buona, ma a lei non importa. « Non sono professionista », dice, « io sono solo felice con il pallone ». Mia sorella è piccola, ma la sua gioia è enorme.",
        questions: [
                            Exercise(id: "it-listen-little-sister-q1", kind: "choice", prompt: "Quanti anni ha Carla?", options: ["Nove", "Diciannove", "Sette", "Dieci"], answers: ["Nove"], explain: "Carla ha nove anni."),
                            Exercise(id: "it-listen-little-sister-q2", kind: "choice", prompt: "Com'è Carla?", options: ["Simpatica e chiacchierona", "Timida e riservata", "Seria", "Triste"], answers: ["Simpatica e chiacchierona"], explain: "È molto simpatica e molto chiacchierona."),
                            Exercise(id: "it-listen-little-sister-q3", kind: "written", prompt: "Di che colore sono i suoi occhi?", options: [], answers: ["castani", "gli occhi castani", "castani come suo padre"], explain: "Ha gli occhi castani come suo padre."),
                            Exercise(id: "it-listen-little-sister-q4", kind: "choice", prompt: "Che capelli ha?", options: ["Biondi, come sua madre", "Scuri, come suo padre", "Rossi", "Corti e neri"], answers: ["Biondi, come sua madre"], explain: "È bionda, come nostra madre."),
                            Exercise(id: "it-listen-little-sister-q5", kind: "choice", prompt: "Che cosa le piace tantissimo?", options: ["Il calcio", "Il nuoto", "La musica", "I videogiochi"], answers: ["Il calcio"], explain: "È molto veloce e le piace tantissimo il calcio."),
                            Exercise(id: "it-listen-little-sister-q6", kind: "written", prompt: "Com'è la sua gioia?", options: [], answers: ["enorme", "molto grande", "grande"], explain: "La sua gioia è enorme.")], skills: ["listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family"]),
    ListeningText(id: "it-listen-new-flatmate", languageID: "it", title: "Un nuovo coinquilino", level: "A1", topic: "casa", unitID: "it-foundations-u1",
        text: "Tom ha un nuovo coinquilino. Si chiama Leo e ha ventitré anni. Leo viene da un piccolo paese del nord, ma ora lavora in città. Ha due scatole, una chitarra e una bicicletta. L'appartamento ha due camere e una cucina molto luminosa. Tom spera che a Leo piaccia cucinare, perché a Tom non piace per niente.",
        questions: [
                            Exercise(id: "it-listen-new-flatmate-q1", kind: "choice", prompt: "Quanti anni ha Leo?", options: ["Ventitré", "Trentadue", "Venti", "Trenta"], answers: ["Ventitré"], explain: "Leo ha ventitré anni."),
                            Exercise(id: "it-listen-new-flatmate-q2", kind: "choice", prompt: "Cosa NON ha Leo?", options: ["Una televisione", "Due scatole", "Una chitarra", "Una bicicletta"], answers: ["Una televisione"], explain: "Ha due scatole, una chitarra e una bicicletta — niente televisione."),
                            Exercise(id: "it-listen-new-flatmate-q3", kind: "written", prompt: "Cosa odia fare Tom?", options: [], answers: ["cucinare", "odia cucinare", "tom odia cucinare"], explain: "A Tom non piace per niente cucinare."),
                            Exercise(id: "it-listen-new-flatmate-q4", kind: "choice", prompt: "Com'è l'appartamento?", options: ["Due camere e una cucina luminosa", "Una camera e un balcone", "Un giardino", "Due bagni"], answers: ["Due camere e una cucina luminosa"], explain: "L'appartamento ha due camere e una cucina molto luminosa."),
                            Exercise(id: "it-listen-new-flatmate-q5", kind: "choice", prompt: "Dove lavora Leo adesso?", options: ["In città", "In un piccolo paese", "Al nord", "Non lavora"], answers: ["In città"], explain: "Viene da un piccolo paese del nord, ma ora lavora in città."),
                            Exercise(id: "it-listen-new-flatmate-q6", kind: "written", prompt: "Quale strumento ha Leo?", options: [], answers: ["una chitarra", "la chitarra", "chitarra"], explain: "Leo ha una chitarra.")], skills: ["listening:gist", "listening:detail", "grammar:have-got", "vocab:home"]),
    ListeningText(id: "it-listen-new-neighbour", languageID: "it", title: "La nuova vicina", level: "A1", topic: "gente", unitID: "it-foundations-u1",
        text: "Nel palazzo c'è una nuova vicina. Si chiama Amélie ed è della Francia. Non è studentessa; è fotografa. Non lavora in ufficio: lavora a casa e viaggia molto. I vicini sono curiosi, ma sono anche timidi, quindi non le parlano. Poi, una mattina, Ben la incontra alla porta. « Sei tu la nuova vicina? », chiede lui. « Sì, sono io », risponde lei, « e sono contenta di essere qui ». Adesso sono amici, e lei non è più sola nel palazzo.",
        questions: [
                            Exercise(id: "it-listen-new-neighbour-q1", kind: "choice", prompt: "Di dov'è Amélie?", options: ["Della Francia", "Dell'Italia", "Del Giappone", "Del Brasile"], answers: ["Della Francia"], explain: "Amélie è della Francia."),
                            Exercise(id: "it-listen-new-neighbour-q2", kind: "choice", prompt: "Qual è il suo lavoro?", options: ["È fotografa", "È studentessa", "Lavora in ufficio", "È insegnante"], answers: ["È fotografa"], explain: "Non è studentessa; è fotografa."),
                            Exercise(id: "it-listen-new-neighbour-q3", kind: "choice", prompt: "Lavora in ufficio?", options: ["No, lavora a casa", "Sì, tutti i giorni", "Solo in estate", "Non lo dice"], answers: ["No, lavora a casa"], explain: "Non lavora in ufficio: lavora a casa."),
                            Exercise(id: "it-listen-new-neighbour-q4", kind: "written", prompt: "Perché i vicini non le parlano?", options: [], answers: ["sono timidi", "perché sono timidi", "timidi"], explain: "Sono curiosi, ma sono anche timidi."),
                            Exercise(id: "it-listen-new-neighbour-q5", kind: "choice", prompt: "Dove la incontra Ben?", options: ["Alla porta", "All'ascensore", "Per strada", "Al caffè"], answers: ["Alla porta"], explain: "Una mattina, Ben la incontra alla porta."),
                            Exercise(id: "it-listen-new-neighbour-q6", kind: "written", prompt: "Come si sente Amélie alla fine?", options: [], answers: ["contenta", "felice", "è contenta"], explain: "Dice che è contenta di essere qui.")], skills: ["listening:gist", "listening:detail", "function:describe-people"]),
    ListeningText(id: "it-listen-sunday-market", languageID: "it", title: "Il mercato della domenica", level: "A1", topic: "acquisti", unitID: "it-foundations-u1",
        text: "La domenica c'è un mercato nella piazza del paese. Anna e suo padre vanno lì alle nove, prima che si riempia. Comprano frutta, pane e fiori. Anna vuole delle fragole, ma suo padre dice che questa settimana sono troppo care. Alla fine portano a casa un grande sacco di arance e delle rose bianche per il tavolo della cucina.",
        questions: [
                            Exercise(id: "it-listen-sunday-market-q1", kind: "choice", prompt: "Quando Anna e suo padre vanno al mercato?", options: ["Alle nove", "A mezzogiorno", "Nel pomeriggio", "Alle sei e mezza"], answers: ["Alle nove"], explain: "Vanno alle nove, prima che si riempia."),
                            Exercise(id: "it-listen-sunday-market-q2", kind: "written", prompt: "Perché Anna non prende le fragole?", options: [], answers: ["sono troppo care", "troppo care", "perché sono troppo care"], explain: "Suo padre dice che sono troppo care questa settimana."),
                            Exercise(id: "it-listen-sunday-market-q3", kind: "choice", prompt: "Cosa portano a casa?", options: ["Arance e rose", "Fragole e pane", "Mele e tulipani", "Pane e formaggio"], answers: ["Arance e rose"], explain: "Portano a casa arance e rose bianche."),
                            Exercise(id: "it-listen-sunday-market-q4", kind: "choice", prompt: "Dov'è il mercato?", options: ["Nella piazza del paese", "Vicino al fiume", "Alla stazione", "In un supermercato"], answers: ["Nella piazza del paese"], explain: "La domenica c'è un mercato nella piazza del paese."),
                            Exercise(id: "it-listen-sunday-market-q5", kind: "choice", prompt: "Cosa comprano?", options: ["Frutta, pane e fiori", "Pesce e verdure", "Formaggio e carne", "Solo fiori"], answers: ["Frutta, pane e fiori"], explain: "Comprano frutta, pane e fiori."),
                            Exercise(id: "it-listen-sunday-market-q6", kind: "written", prompt: "Cosa vuole Anna?", options: [], answers: ["delle fragole", "fragole", "vuole delle fragole"], explain: "Anna vuole delle fragole.")], skills: ["listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping"]),
    ListeningText(id: "it-listen-appartamento-scelto", languageID: "it", title: "L'appartamento scelto", level: "A2", topic: "appartamenti", unitID: "it-foundations-u4",
        text: "Giulia e Marco cercano appartamento su un annuncio. Il primo è meno costoso, ma è più lontano dalla stazione: quaranta minuti a piedi. Il secondo costa cento euro in più al mese, ma è più luminoso e ha il balcone. Per Giulia la luce è la cosa più importante, perché lavora da casa. Alla fine decidono di chiedere una visita del secondo: costa di più, ma è il migliore dei due per loro.",
        questions: [
                            Exercise(id: "it-listen-appartamento-scelto-q1", kind: "choice", prompt: "Quanti appartamenti confrontano ?", options: ["Due", "Tre", "Quattro"], answers: ["Due"], explain: "Confrontano due appartamenti."),
                            Exercise(id: "it-listen-appartamento-scelto-q2", kind: "choice", prompt: "Qual è il problema del meno costoso ?", options: ["È lontano dalla stazione", "Non ha il balcone", "È molto costoso", "È piccolo"], answers: ["È lontano dalla stazione"], explain: "Quaranta minuti a piedi dalla stazione."),
                            Exercise(id: "it-listen-appartamento-scelto-q3", kind: "written", prompt: "Quanto costa in più il secondo al mese ?", options: [], answers: ["cento euro", "100 euro"], explain: "Cento euro in più al mese."),
                            Exercise(id: "it-listen-appartamento-scelto-q4", kind: "choice", prompt: "Cos'è più importante per Giulia ?", options: ["La luce", "Il prezzo", "Il balcone", "La cucina"], answers: ["La luce"], explain: "Lavora da casa."),
                            Exercise(id: "it-listen-appartamento-scelto-q5", kind: "choice", prompt: "Cosa decidono alla fine ?", options: ["Chiedere una visita del secondo", "Tenere il primo", "Continuare a cercare", "Chiedere uno sconto"], answers: ["Chiedere una visita del secondo"], explain: "È il migliore dei due per loro.")], skills: ["listening:gist", "listening:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ListeningText(id: "it-listen-sabato-organizzato", languageID: "it", title: "Il sabato organizzato", level: "A2", topic: "progetti", unitID: "it-foundations-u4",
        text: "Sara chiama suo fratello per organizzare il sabato. Lui propone la montagna, ma pioverà, quindi Sara suggerisce il museo nuovo. Si vedranno alle dieci all'ingresso principale e pranzeranno al mercato accanto, che è meno caro dei ristoranti del centro. La sera non hanno programmi: decideranno sul posto, quando sapranno che tempo fa.",
        questions: [
                            Exercise(id: "it-listen-sabato-organizzato-q1", kind: "choice", prompt: "Chi propone la montagna ?", options: ["Il fratello", "Sara", "La loro madre", "Un amico"], answers: ["Il fratello"], explain: "Suo fratello propone la montagna."),
                            Exercise(id: "it-listen-sabato-organizzato-q2", kind: "choice", prompt: "Perché non la montagna ?", options: ["Pioverà", "Sono stanchi", "Il museo è gratis", "La montagna è lontana"], answers: ["Pioverà"], explain: "Pioverà, quindi vanno al museo."),
                            Exercise(id: "it-listen-sabato-organizzato-q3", kind: "written", prompt: "A che ora si vedranno ?", options: [], answers: ["alle dieci", "dieci"], explain: "Alle dieci all'ingresso principale."),
                            Exercise(id: "it-listen-sabato-organizzato-q4", kind: "choice", prompt: "Dove pranzeranno ?", options: ["Al mercato accanto", "In un ristorante del centro", "A casa", "Al museo"], answers: ["Al mercato accanto"], explain: "Meno caro dei ristoranti del centro."),
                            Exercise(id: "it-listen-sabato-organizzato-q5", kind: "choice", prompt: "Cosa faranno la sera ?", options: ["Decideranno sul posto", "Andranno al cinema", "Torneranno presto", "Vedranno amici"], answers: ["Decideranno sul posto"], explain: "Decideranno secondo il tempo.")], skills: ["listening:gist", "listening:detail", "grammar:going-to"], exposureSkills: ["grammar:future-forms"]),
    ListeningText(id: "it-listen-mai-fatto", languageID: "it", title: "Cose che non ho mai fatto", level: "B1", topic: "viaggi", unitID: "it-foundations-u6",
        text: "Nella cucina di un ostello, tre viaggiatori paragonano le loro vite. Luca ha visitato venti paesi, ma non ha mai imparato a nuotare: « Lo so, è ridicolo ». Sara ha già fatto snorkeling due volte con le tartarughe, ma non è mai uscita dall'Europa prima di questo viaggio. E Elena, che è in viaggio da sei anni, non ha mai preso l'aereo: attraversa gli oceani in nave e i confini in autobus. « Mai ? » chiede Luca. « Mai. La paura è più vecchia di me. » Ridono delle cose che non hanno fatto, ed Elena dice una frase che resta: « Non serve aver fatto tutto. Basta avere ancora voglia ».",
        questions: [
                            Exercise(id: "it-listen-mai-fatto-q1", kind: "choice", prompt: "Cosa non ha mai fatto Luca ?", options: ["Imparare a nuotare", "Visitare venti paesi", "Attraversare in nave", "Uscire dall'Europa"], answers: ["Imparare a nuotare"], explain: "Ha visitato venti paesi, ma non ha mai imparato a nuotare."),
                            Exercise(id: "it-listen-mai-fatto-q2", kind: "written", prompt: "Quante volte ha fatto snorkeling Sara ?", options: [], answers: ["due volte", "2 volte", "due"], explain: "Sara ha già fatto snorkeling due volte con le tartarughe."),
                            Exercise(id: "it-listen-mai-fatto-q3", kind: "choice", prompt: "Come attraversa Elena gli oceani ?", options: ["In nave", "In aereo", "In autobus", "A piedi"], answers: ["In nave"], explain: "Attraversa gli oceani in nave e i confini in autobus."),
                            Exercise(id: "it-listen-mai-fatto-q4", kind: "choice", prompt: "Cosa dice Elena della paura ?", options: ["È più vecchia di lei", "È più giovane", "È ridicola", "Se n'è andata"], answers: ["È più vecchia di lei"], explain: "La paura è più vecchia di me."),
                            Exercise(id: "it-listen-mai-fatto-q5", kind: "written", prompt: "Cosa basta, secondo Elena ?", options: [], answers: ["avere ancora voglia", "aver voglia"], explain: "Basta avere ancora voglia.")], skills: ["listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"], exposureSkills: ["grammar:relative-clauses"]),
    ListeningText(id: "it-listen-citta-paese", languageID: "it", title: "Dalla città al paese", level: "B1", topic: "cambiamenti", unitID: "it-foundations-u6",
        text: "Marco racconta perché ha lasciato Milano. Prima viveva in un appartamento piccolo e lavorava undici ore al giorno: « Guadagnavo bene, ma non avevo vita ». Un inverno si è ammalato, e allora ha capito che doveva cambiare. Adesso vive in un paese di mille abitanti, lavora da casa la mattina e coltiva un orto nel pomeriggio. « Guadagno meno, ma mi avanza tempo. » All'inizio i suoi genitori non capivano; adesso vengono ogni mese. « Ti penti di qualcosa ? » gli chiede l'amica. « Di non averlo fatto prima ».",
        questions: [
                            Exercise(id: "it-listen-citta-paese-q1", kind: "choice", prompt: "Dove viveva Marco prima ?", options: ["A Milano", "In un paese", "A Roma", "In un ostello"], answers: ["A Milano"], explain: "Marco racconta perché ha lasciato Milano."),
                            Exercise(id: "it-listen-citta-paese-q2", kind: "written", prompt: "Quante ore lavorava al giorno ?", options: [], answers: ["undici ore", "11 ore", "undici"], explain: "Lavorava undici ore al giorno."),
                            Exercise(id: "it-listen-citta-paese-q3", kind: "choice", prompt: "Cosa l'ha fatto cambiare ?", options: ["Si è ammalato", "Ha perso il lavoro", "Ha vinto alla lotteria", "Ha conosciuto qualcuno"], answers: ["Si è ammalato"], explain: "Un inverno si è ammalato, e allora ha capito."),
                            Exercise(id: "it-listen-citta-paese-q4", kind: "choice", prompt: "Cosa fa nel pomeriggio adesso ?", options: ["Coltiva un orto", "Lavora più ore", "Viaggia ogni mese", "Studia"], answers: ["Coltiva un orto"], explain: "Lavora la mattina e coltiva un orto nel pomeriggio."),
                            Exercise(id: "it-listen-citta-paese-q5", kind: "written", prompt: "Di cosa si pente Marco ?", options: [], answers: ["di non averlo fatto prima", "non averlo fatto prima"], explain: "« Di non averlo fatto prima ».")], skills: ["listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions"]),
    ListeningText(id: "it-listen-trattativa-tavolo", languageID: "it", title: "La trattativa del tavolo", level: "B2", topic: "negoziazione", unitID: "it-foundations-u7",
        text: "Su un'app di usato, Chiara vuole un tavolo di legno da 80 euro. « E se chiudessimo a 60 ? », propone. Il venditore rifiuta: « Solo se la ritiri oggi ». Chiara riflette: « Le darei 65 se aggiunge la sedia ». « Impossibile », ride lui, « ma le lascerei il tavolo a 70 e glielo salirei al piano ». Chiara non dubita: « Lo salirebbe da solo ? ». « Ho una carriola », risponde. « Affare fatto », dice lei, e aggiunge: « Se è bello come in foto, le lascio cinque stelle ».",
        questions: [
                            Exercise(id: "it-listen-trattativa-tavolo-q1", kind: "choice", prompt: "Quanto chiede il venditore ?", options: ["80 euro", "60 euro", "70 euro", "65 euro"], answers: ["80 euro"], explain: "Il tavolo costa 80 euro."),
                            Exercise(id: "it-listen-trattativa-tavolo-q2", kind: "written", prompt: "Cosa propone Chiara all'inizio ?", options: [], answers: ["60 euro", "sessanta euro", "chiudere a 60"], explain: "« E se chiudessimo a 60 ? »."),
                            Exercise(id: "it-listen-trattativa-tavolo-q3", kind: "choice", prompt: "Che condizione mette il venditore ?", options: ["Ritirarla oggi", "Pagare in contanti", "Lasciare cinque stelle", "Tornare domani"], answers: ["Ritirarla oggi"], explain: "« Solo se la ritiri oggi »."),
                            Exercise(id: "it-listen-trattativa-tavolo-q4", kind: "choice", prompt: "Cosa offre il venditore per 70 ?", options: ["Salire il tavolo al piano", "Aggiungere la sedia", "Scendere a 60", "Prestare la carriola"], answers: ["Salire il tavolo al piano"], explain: "« Glielo salirei al piano »."),
                            Exercise(id: "it-listen-trattativa-tavolo-q5", kind: "written", prompt: "Cosa promette Chiara se il tavolo le piace ?", options: [], answers: ["cinque stelle", "5 stelle", "una recensione di cinque stelle"], explain: "Cinque stelle.")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "it-listen-notizia-quartiere", languageID: "it", title: "La notizia del quartiere", level: "B2", topic: "notizie", unitID: "it-foundations-u8",
        text: "Al mercato, Giulia e Paolo commentano quello che si dice. « Si dice che pedonalizzeranno la via principale », racconta Giulia. « Di nuovo ? », ride Paolo. « La notizia che ho letto dice che partono in primavera ». Secondo il comune, sarebbe solo il sabato, ma i negozianti, il cui fatturato dipenderebbe dal turismo, sono già scesi in piazza. « È vero che il rumore calerebbe », ammette Paolo, « ma, e il parcheggio ? ». Giulia difende la misura: « Da un lato, più gente camminerebbe; dall'altro, gli autobus arriverebbero all'angolo ». Non la decidono, ma promettono di riparlarne quando uscirà il piano.",
        questions: [
                            Exercise(id: "it-listen-notizia-quartiere-q1", kind: "choice", prompt: "Cosa si dice della via principale ?", options: ["Che la pedonalizzeranno", "Che la allargheranno", "Che la chiuderanno", "Che cambierà nome"], answers: ["Che la pedonalizzeranno"], explain: "« Si dice che pedonalizzeranno la via principale »."),
                            Exercise(id: "it-listen-notizia-quartiere-q2", kind: "written", prompt: "Quando partirebbe ?", options: [], answers: ["in primavera", "primavera"], explain: "« La notizia che ho letto dice che partono in primavera »."),
                            Exercise(id: "it-listen-notizia-quartiere-q3", kind: "choice", prompt: "Cosa dice il comune ?", options: ["Solo il sabato", "Tutti i giorni", "Solo d'estate", "I festivi"], answers: ["Solo il sabato"], explain: "Secondo il comune, sarebbe solo il sabato."),
                            Exercise(id: "it-listen-notizia-quartiere-q4", kind: "choice", prompt: "Chi è sceso in piazza ?", options: ["I negozianti", "I residenti", "I tassisti", "Il comune"], answers: ["I negozianti"], explain: "I negozianti sono già scesi in piazza."),
                            Exercise(id: "it-listen-notizia-quartiere-q5", kind: "written", prompt: "Cosa promettono Giulia e Paolo ?", options: [], answers: ["di riparlarne", "ripdirlo", "riparlarne quando uscira il piano"], explain: "Promettono di riparlarne quando uscirà il piano.")], skills: ["listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors"]),
    ListeningText(id: "it-listen-dibattito-radio", languageID: "it", title: "Dibattito alla radio", level: "C1", topic: "dibattito", unitID: "it-foundations-u9",
        text: "Studi aperti, torniamo sulla viabilità. Con noi Mara Bianchi, urbanista, e Sandro Lenzi, portavoce dei commercianti. Mara, la parola è Sua. « Grazie. A mio avviso, limitare il traffico non è una battaglia ideologica: è una questione di salute pubblica. In un certo senso, tutti ne guadagnerebbero, commercianti compresi ». Lenzi interviene: « Permettetemi di dissentire. È vero che il centro va ridisegnato, però senza parcheggi di scambio qualsiasi misura resta, per così dire, di facciata ». La conduttrice lancia i dati: « Secondo il comune, gli spostamenti a piedi sono cresciuti del dodici per cento ». « Proprio per questo », replica Bianchi, « conviene procedere per tappe ». « Purché le tappe non diventino eterne », chiude Lenzi.",
        questions: [
                            Exercise(id: "it-listen-dibattito-radio-q1", kind: "choice", prompt: "Qual è la posizione di Mara Bianchi?", options: ["Limitare il traffico è una questione di salute", "Una battaglia puramente ideologica", "Il traffico non è un problema", "Serve fermare ogni misura"], answers: ["Limitare il traffico è una questione di salute"], explain: "« Non è una battaglia ideologica: è una questione di salute pubblica »."),
                            Exercise(id: "it-listen-dibattito-radio-q2", kind: "choice", prompt: "Come definisce Lenzi una misura senza parcheggi di scambio?", options: ["Di facciata", "Eterna", "Salutare", "Impossibile"], answers: ["Di facciata"], explain: "« Resta, per così dire, di facciata »."),
                            Exercise(id: "it-listen-dibattito-radio-q3", kind: "written", prompt: "Di quanto sono cresciuti gli spostamenti a piedi?", options: [], answers: ["12%", "12 %", "del dodici per cento", "dodici per cento"], explain: "Cresciuti del dodici per cento."),
                            Exercise(id: "it-listen-dibattito-radio-q4", kind: "choice", prompt: "Che metodo propone Bianchi?", options: ["Procedere per tappe", "Un referendum immediato", "Chiudere tutto subito", "Attendere i fondi"], answers: ["Procedere per tappe"], explain: "« Conviene procedere per tappe »."),
                            Exercise(id: "it-listen-dibattito-radio-q5", kind: "written", prompt: "Con quale condizione Lenzi accetta le tappe?", options: [], answers: ["purche non diventino eterne", "purché le tappe non diventino eterne", "purché non diventino eterne"], explain: "« Purché le tappe non diventino eterne »."),
                            Exercise(id: "it-listen-dibattito-radio-q6", kind: "choice", prompt: "Che funzione ha « Permettetemi di dissentire »?", options: ["Marcare il disaccordo in forma cortese", "Chiedere un rinvio", "Aprire l'intervento", "Chiudere il dibattito"], answers: ["Marcare il disaccordo in forma cortese"], explain: "Disaccordo esplicito ma cortese.")], skills: ["listening:connected-speech", "listening:inference", "function:express-opinion", "grammar:connectors"]),
    ListeningText(id: "it-listen-intervento-chiavi", languageID: "it", title: "Intervento in riunione", level: "C1", topic: "lavoro", unitID: "it-foundations-u9",
        text: "Ultimo punto dell'ordine del giorno: il passaggio del progetto Lumen al team di Milano. Chiara Sarti ha cinque minuti. « Per iniziare, una rassicurazione: nessun cliente resterà senza referente. Il dossier che ho preparato contiene contratti, scadenze e contatti; pertanto chi subentrerà avrà tutto in mano. Venendo ai rischi, ne vedo due: la gara della biblioteca, che scade a marzo, e il rinnovo del fornitore di stampa, per così dire ancora a metà trattativa. In sintesi, il progetto è sano ma esige continuità. Per concludere, due richieste: nominare entro venerdì il nuovo referente e, se possibile, tenere il cliente pilota nel nostro gruppo. Sono certa che, sotto certi aspetti, il cambio sarà un'opportunità. Grazie dell'attenzione ».",
        questions: [
                            Exercise(id: "it-listen-intervento-chiavi-q1", kind: "choice", prompt: "Cosa garantisce Chiara per iniziare?", options: ["Nessun cliente resterà senza referente", "Il progetto sarà rinnovato", "La gara sarà vinta", "Il budget sarà aumentato"], answers: ["Nessun cliente resterà senza referente"], explain: "« Nessun cliente resterà senza referente »."),
                            Exercise(id: "it-listen-intervento-chiavi-q2", kind: "written", prompt: "Quando scade la gara della biblioteca?", options: [], answers: ["a marzo", "marzo", "in marzo"], explain: "Scade a marzo."),
                            Exercise(id: "it-listen-intervento-chiavi-q3", kind: "choice", prompt: "Com'è la trattativa col fornitore di stampa?", options: ["Ancora a metà", "Conclusa", "Annullata", "Rinviata a settembre"], answers: ["Ancora a metà"], explain: "« Per così dire ancora a metà trattativa »."),
                            Exercise(id: "it-listen-intervento-chiavi-q4", kind: "written", prompt: "Che cosa chiede entro venerdì?", options: [], answers: ["nominare il nuovo referente", "nominare entro venerdì il nuovo referente", "nominare entro venerdi il nuovo referente"], explain: "Chiede di nominare il nuovo referente."),
                            Exercise(id: "it-listen-intervento-chiavi-q5", kind: "choice", prompt: "Che funzione ha « Venendo ai rischi »?", options: ["Annuncia il cambio di punto", "Chiude l'intervento", "Sintetizza i contenuti", "Ringrazia i colleghi"], answers: ["Annuncia il cambio di punto"], explain: "Transizione annunciata verso un nuovo punto."),
                            Exercise(id: "it-listen-intervento-chiavi-q6", kind: "choice", prompt: "Com'è il progetto in sintesi?", options: ["Sano ma esige continuità", "Chiuso e archiviato", "In perdita", "Sospeso"], answers: ["Sano ma esige continuità"], explain: "« Il progetto è sano ma esige continuità ».")], skills: ["listening:detail", "listening:gist", "vocab:work", "grammar:connectors"]),
    ListeningText(id: "it-listen-podcast-sfumature", languageID: "it", title: "Podcast: l'arte della sfumatura", level: "C1", topic: "linguaggio", unitID: "it-foundations-u9",
        text: "Benvenuti a « Parole al lavoro », la puntata in cui ascoltiamo come si suona un'opinione in ufficio. Vi racconto un episodio vissuto. In una riunione, il nuovo responsabile avrebbe potuto dire: « Questa idea non funziona ». Invece ha detto: « A mio avviso, qui c'è ancora lavoro da fare ». Stesso fondo, musica diversa: nessuno si è messo sulla difensiva e la discussione è proseguita. Notate le mosse: prima la sfumatura, poi il punto, infine la proposta. « In un certo senso », « per così dire », « direi che » non sono giri di parole: sono la cortesia della precisione. Per così dire, naturalmente. Nella prossima puntata analizziamo il linguaggio delle email: ci vediamo lì.",
        questions: [
                            Exercise(id: "it-listen-podcast-sfumature-q1", kind: "choice", prompt: "Che alternativa ha proposto il responsabile al giudizio netto?", options: ["Qui c'è ancora lavoro da fare", "L'idea è inutile", "Cambiate subito team", "Non dico niente"], answers: ["Qui c'è ancora lavoro da fare"], explain: "« A mio avviso, qui c'è ancora lavoro da fare »."),
                            Exercise(id: "it-listen-podcast-sfumature-q2", kind: "choice", prompt: "Che effetto ha prodotto la formula sfumata?", options: ["Nessuno si è messo sulla difensiva", "La riunione è finita prima", "Il capo si è arrabbiato", "L'idea è stata approvata subito"], answers: ["Nessuno si è messo sulla difensiva"], explain: "Nessuno in difesa, la discussione è proseguita."),
                            Exercise(id: "it-listen-podcast-sfumature-q3", kind: "written", prompt: "Quale sequenza indica l'autore per costruire un rilievo?", options: [], answers: ["prima la sfumatura poi il punto infine la proposta", "sfumatura punto proposta", "la sfumatura poi il punto e la proposta"], explain: "Prima la sfumatura, poi il punto, infine la proposta."),
                            Exercise(id: "it-listen-podcast-sfumature-q4", kind: "choice", prompt: "Come definisce l'autore locuzioni come « direi che »?", options: ["La cortesia della precisione", "Un giro di parole da evitare", "Un segno di insicurezza", "Un tratto regionale"], answers: ["La cortesia della precisione"], explain: "« Non sono giri di parole: sono la cortesia della precisione »."),
                            Exercise(id: "it-listen-podcast-sfumature-q5", kind: "choice", prompt: "Di cosa parlerà la prossima puntata?", options: ["Del linguaggio delle email", "Delle riunioni efficienti", "Del telegiornale", "Del nuovo responsabile"], answers: ["Del linguaggio delle email"], explain: "« Analizziamo il linguaggio delle email »."),
                            Exercise(id: "it-listen-podcast-sfumature-q6", kind: "choice", prompt: "Che registro ha questo podcast?", options: ["Divulgativo e colloquiale", "Legale", "Burocratico", "Accademico e freddo"], answers: ["Divulgativo e colloquiale"], explain: "Tono divulgativo, con episodi vissuti e battute.")], skills: ["listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion"]),
    ListeningText(id: "it-listen-appartamento-nuovo", languageID: "it", title: "Un appartamento nuovo", level: "A1", topic: "casa", unitID: "it-foundations-u10",
        text: "Anna ha un appartamento nuovo. « È piccolo, ma mi piace. La porta è gialla. C'è una cucina piccola e luminosa: ci sono un tavolo, due sedie e un frigo nuovo. Il soggiorno è grande: c'è un divano blu e ci sono due finestre. La camera da letto è tranquilla: il letto è sotto la finestra e c'è un armadio bianco. Il bagno è piccolo ma pulito. Il mio gatto dorme sul divano. La mia casa è piccola, ma è la mia casa. »",
        questions: [
                            Exercise(id: "it-listen-appartamento-nuovo-q1", kind: "choice", prompt: "Com'è l'appartamento ?", options: ["Piccolo, ma ad Anna piace", "Grande e moderno", "Molto costoso", "Senza cucina"], answers: ["Piccolo, ma ad Anna piace"], explain: "« È piccolo, ma mi piace »."),
                            Exercise(id: "it-listen-appartamento-nuovo-q2", kind: "choice", prompt: "Cosa c'è nella cucina ?", options: ["Un tavolo, due sedie e un frigo", "Un divano blu", "Un armadio bianco", "Niente"], answers: ["Un tavolo, due sedie e un frigo"], explain: "« Ci sono un tavolo, due sedie e un frigo nuovo »."),
                            Exercise(id: "it-listen-appartamento-nuovo-q3", kind: "written", prompt: "Dove sta il letto ?", options: [], answers: ["sotto la finestra", "sotto la finestra della camera"], explain: "« Il letto è sotto la finestra »."),
                            Exercise(id: "it-listen-appartamento-nuovo-q4", kind: "choice", prompt: "Com'è il bagno ?", options: ["Piccolo ma pulito", "Grande e luminoso", "Giallo", "Non c'è"], answers: ["Piccolo ma pulito"], explain: "« Il bagno è piccolo ma pulito »."),
                            Exercise(id: "it-listen-appartamento-nuovo-q5", kind: "written", prompt: "Dove dorme il gatto ?", options: [], answers: ["sul divano", "sopra il divano", "sul divano blu"], explain: "« Il mio gatto dorme sul divano »."),
                            Exercise(id: "it-listen-appartamento-nuovo-q6", kind: "choice", prompt: "Quante finestre ci sono nel soggiorno ?", options: ["Due", "Una", "Tre", "Nessuna"], answers: ["Due"], explain: "« Ci sono due finestre ».")], skills: ["listening:gist", "listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home"]),
    ListeningText(id: "it-listen-passeggiata-quartiere", languageID: "it", title: "Una passeggiata nel quartiere", level: "A1", topic: "quartiere", unitID: "it-foundations-u11",
        text: "Marco è nuovo nel quartiere. Oggi fa una passeggiata. « Scusi, c'è un supermercato qui vicino ? » chiede a una signora. « Sì, vada sempre dritto e alla piazza giri a sinistra. È lì, accanto alla farmacia ». Marco cammina cinque minuti. Il supermercato è piccolo ma c'è di tutto. Dopo entra nel parco: ci sono alberi, panchine e un chiosco. Torna a casa con le mele e due arance. Il suo quartiere è tranquillo e lui è contento.",
        questions: [
                            Exercise(id: "it-listen-passeggiata-quartiere-q1", kind: "choice", prompt: "Cosa chiede Marco alla signora ?", options: ["Dov'è un supermercato", "L'ora", "Il suo nome", "Il prezzo delle mele"], answers: ["Dov'è un supermercato"], explain: "« Scusi, c'è un supermercato qui vicino ? »."),
                            Exercise(id: "it-listen-passeggiata-quartiere-q2", kind: "written", prompt: "Che cosa deve fare alla piazza ?", options: [], answers: ["giri a sinistra", "gira a sinistra", "andare a sinistra"], explain: "« Alla piazza giri a sinistra »."),
                            Exercise(id: "it-listen-passeggiata-quartiere-q3", kind: "choice", prompt: "Dov'è il supermercato ?", options: ["Accanto alla farmacia", "Dietro il parco", "In piazza", "Vicino alla stazione"], answers: ["Accanto alla farmacia"], explain: "« È lì, accanto alla farmacia »."),
                            Exercise(id: "it-listen-passeggiata-quartiere-q4", kind: "written", prompt: "Quanto cammina Marco ?", options: [], answers: ["cinque minuti", "5 minuti"], explain: "« Marco cammina cinque minuti »."),
                            Exercise(id: "it-listen-passeggiata-quartiere-q5", kind: "choice", prompt: "Cosa c'è nel parco ?", options: ["Alberi, panchine e un chiosco", "Un supermercato", "Una farmacia", "Niente"], answers: ["Alberi, panchine e un chiosco"], explain: "« Ci sono alberi, panchine e un chiosco »."),
                            Exercise(id: "it-listen-passeggiata-quartiere-q6", kind: "written", prompt: "Com'è il quartiere ?", options: [], answers: ["tranquillo", "è tranquillo", "e tranquillo"], explain: "« Il suo quartiere è tranquillo ».")], skills: ["listening:gist", "listening:detail", "grammar:prepositions-place", "function:ask-for-directions", "vocab:town"]),
    ListeningText(id: "it-listen-chiamata-nonna", languageID: "it", title: "Una chiamata alla nonna", level: "A1", topic: "famiglia", unitID: "it-foundations-u12",
        text: "Luca telefona alla nonna. « Pronto, nonna ! Sono Luca. C'è il nonno ? » « Sì, è in giardino con il gatto. E tu, come va ? » « Bene, nonna. La mattina lavoro e la sera cucino sempre con Sara. » « Molto bene ! E Giulia, com'è ? » « Giulia è simpatica, ma è un po' timida. Domenica vengo a trovare voi. » « D'accordo, a domenica ! Ora chiamo il nonno. »",
        questions: [
                            Exercise(id: "it-listen-chiamata-nonna-q1", kind: "choice", prompt: "Chi telefona alla nonna ?", options: ["Luca", "Marco", "Il nonno", "Sara"], answers: ["Luca"], explain: "« Pronto, nonna ! Sono Luca »."),
                            Exercise(id: "it-listen-chiamata-nonna-q2", kind: "choice", prompt: "Dov'è il nonno ?", options: ["In giardino", "Al lavoro", "In cucina", "A letto"], answers: ["In giardino"], explain: "« Sì, è in giardino con il gatto »."),
                            Exercise(id: "it-listen-chiamata-nonna-q3", kind: "written", prompt: "Cosa fa Luca la sera, sempre ?", options: [], answers: ["cucino con Sara", "cucina con Sara", "cucino"], explain: "« La sera cucino sempre con Sara »."),
                            Exercise(id: "it-listen-chiamata-nonna-q4", kind: "choice", prompt: "Com'è Giulia ?", options: ["Simpatica ma un po' timida", "Timida e seria", "Sempre allegra", "Molto lavoratrice"], answers: ["Simpatica ma un po' timida"], explain: "« Giulia è simpatica, ma è un po' timida »."),
                            Exercise(id: "it-listen-chiamata-nonna-q5", kind: "written", prompt: "Quando va dai nonni Luca ?", options: [], answers: ["Domenica", "domenica", "La domenica"], explain: "« Domenica vengo a trovare voi »."),
                            Exercise(id: "it-listen-chiamata-nonna-q6", kind: "choice", prompt: "Cosa dice la nonna alla fine ?", options: ["Richiama il nonno", "Esce con il gatto", "Cucina con Sara", "Guarda la TV"], answers: ["Richiama il nonno"], explain: "« Ora chiamo il nonno ».")], skills: ["listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ListeningText(id: "it-listen-weekend-piovoso", languageID: "it", title: "Un weekend piovoso", level: "A1", topic: "meteo", unitID: "it-foundations-u13",
        text: "È sabato e piove. Anna guarda la finestra: che tempo fa ? Fa freddo e piove ancora. Marco telefona: « Che noia, non usciamo ! » « D'accordo, » dice Anna. « Di solito il sabato corro al parco, ma oggi no. Quando piove, qualche volta leggo. E tu ? » « Io guardo spesso dei film, » risponde Marco. « Domenica fa bel tempo: andiamo al parco ! »",
        questions: [
                            Exercise(id: "it-listen-weekend-piovoso-q1", kind: "choice", prompt: "Che tempo fa sabato ?", options: ["Piove e fa freddo", "C'è il sole", "Nevica", "Fa caldo"], answers: ["Piove e fa freddo"], explain: "« Fa freddo e piove ancora »."),
                            Exercise(id: "it-listen-weekend-piovoso-q2", kind: "written", prompt: "Cosa fa di solito Anna il sabato ?", options: [], answers: ["corro al parco", "corre al parco", "correre al parco"], explain: "« Di solito il sabato corro al parco »."),
                            Exercise(id: "it-listen-weekend-piovoso-q3", kind: "choice", prompt: "Cosa fa Anna qualche volta quando piove ?", options: ["Legge", "Corre", "Guarda i film", "Dorme"], answers: ["Legge"], explain: "« Quando piove, qualche volta leggo »."),
                            Exercise(id: "it-listen-weekend-piovoso-q4", kind: "written", prompt: "Cosa fa spesso Marco ?", options: [], answers: ["guardo dei film", "guarda dei film", "guarda film"], explain: "« Io guardo spesso dei film »."),
                            Exercise(id: "it-listen-weekend-piovoso-q5", kind: "choice", prompt: "Cosa decidono per domenica ?", options: ["Andare al parco", "Stare a casa", "Andare al mare", "Cucinare"], answers: ["Andare al parco"], explain: "« Domenica fa bel tempo: andiamo al parco »."),
                            Exercise(id: "it-listen-weekend-piovoso-q6", kind: "choice", prompt: "Perché Anna non corre al parco oggi ?", options: ["Perché piove", "Perché lavora", "Perché legge", "Perché è stanca"], answers: ["Perché piove"], explain: "Oggi no: piove e fa freddo.")], skills: ["listening:gist", "listening:detail", "vocab:weather", "vocab:daily-routine", "grammar:frequency-adverbs", "function:talk-about-weather"]),
    ListeningText(id: "it-listen-metro-perso", languageID: "it", title: "Perso in metro", level: "A1", topic: "trasporti", unitID: "it-foundations-u14",
        text: "Marco va al lavoro in metro. Ogni mattina prende la metro alle otto e un quarto alla stazione Garibaldi. Stamattina guarda i messaggi sul telefono e non sente l'annuncio: « Prossima fermata: Duomo ». Marco non scende e la metro parte. Arriva a San Babila e chiede: « Scusi, come vado al Duomo ? » « Facile: prendi la metro in direzione opposta, due fermate e sei a posto ! » Marco prende l'altra metro ed è in ufficio alle nove e dieci. « Scusate il ritardo ! »",
        questions: [
                            Exercise(id: "it-listen-metro-perso-q1", kind: "choice", prompt: "Come va al lavoro Marco ?", options: ["In metro", "A piedi", "In bici", "In treno"], answers: ["In metro"], explain: "« Marco va al lavoro in metro »."),
                            Exercise(id: "it-listen-metro-perso-q2", kind: "choice", prompt: "A che ora prende la metro ?", options: ["Alle otto e un quarto", "Alle otto e mezza", "Alle nove e dieci", "Alle sette"], answers: ["Alle otto e un quarto"], explain: "« Prende la metro alle otto e un quarto »."),
                            Exercise(id: "it-listen-metro-perso-q3", kind: "written", prompt: "Perché non scende al Duomo ?", options: [], answers: ["Guarda i messaggi sul telefono", "Perché guarda il telefono", "Guarda il telefono", "Perche guarda il telefono"], explain: "« Guarda i messaggi sul telefono e non sente l'annuncio »."),
                            Exercise(id: "it-listen-metro-perso-q4", kind: "written", prompt: "A che ora è in ufficio ?", options: [], answers: ["Alle nove e dieci", "Nove e dieci", "Alle 9:10"], explain: "« È in ufficio alle nove e dieci »."),
                            Exercise(id: "it-listen-metro-perso-q5", kind: "choice", prompt: "Quante fermate per tornare al Duomo ?", options: ["Due", "Tre", "Quattro", "Una"], answers: ["Due"], explain: "« Due fermate e sei a posto »."),
                            Exercise(id: "it-listen-metro-perso-q6", kind: "choice", prompt: "Cosa dice Marco in ufficio ?", options: ["Scusate il ritardo", "Grazie mille", "A domani", "Buongiorno"], answers: ["Scusate il ritardo"], explain: "« Scusate il ritardo ! ».")], skills: ["listening:gist", "listening:detail", "vocab:transport", "function:tell-time"]),
    ListeningText(id: "it-listen-farmacia-sabato", languageID: "it", title: "Sabato in farmacia", level: "A1", topic: "salute", unitID: "it-foundations-u15",
        text: "È sabato mattina. Anna non si sente bene: ha la febbre e la testa le fa male. In casa non ci sono medicine: Anna non le compra mai. Va in farmacia. « Buongiorno, ho la febbre e ho mal di testa. » « Da quanti giorni ? » « Da due giorni. » « Ecco questo: due compresse al giorno, una la mattina e una la sera. Bevi molta acqua. » « Quanto costano ? » « Sette euro. » « Grazie, buona giornata ! »",
        questions: [
                            Exercise(id: "it-listen-farmacia-sabato-q1", kind: "choice", prompt: "Come si sente Anna ?", options: ["Ha la febbre e mal di testa", "Ha mal di pancia", "Ha la tosse", "È solo stanca"], answers: ["Ha la febbre e mal di testa"], explain: "« Ho la febbre e ho mal di testa »."),
                            Exercise(id: "it-listen-farmacia-sabato-q2", kind: "written", prompt: "Quante compresse al giorno prende Anna ?", options: [], answers: ["Due", "2", "Due compresse"], explain: "« Due compresse al giorno »."),
                            Exercise(id: "it-listen-farmacia-sabato-q3", kind: "choice", prompt: "Quando prende le compresse ?", options: ["La mattina e la sera", "Solo la mattina", "Solo la sera", "A mezzogiorno"], answers: ["La mattina e la sera"], explain: "« Una la mattina e una la sera »."),
                            Exercise(id: "it-listen-farmacia-sabato-q4", kind: "written", prompt: "Quanto costano le medicine ?", options: [], answers: ["Sette euro", "7 euro", "Sette"], explain: "« Sette euro »."),
                            Exercise(id: "it-listen-farmacia-sabato-q5", kind: "choice", prompt: "Cosa non fa mai Anna ?", options: ["Compra le medicine", "Beve l'acqua", "Va in farmacia", "Dorme otto ore"], answers: ["Compra le medicine"], explain: "« Anna non le compra mai »."),
                            Exercise(id: "it-listen-farmacia-sabato-q6", kind: "choice", prompt: "Che altro deve bere Anna ?", options: ["Molta acqua", "Il caffè", "Il latte", "Il tè freddo"], answers: ["Molta acqua"], explain: "« Bevi anche molta acqua ».")], skills: ["listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs"]),
    ListeningText(id: "it-listen-cena-sorpresa", languageID: "it", title: "Una cena a sorpresa", level: "A1", topic: "ristorante", unitID: "it-foundations-u16",
        text: "È sabato sera. Marco porta Anna al ristorante: è il suo compleanno, la cena è una sorpresa. Il cameriere chiede: « Che cosa prende ? ». Marco prende le tagliatelle, Anna preferisce la pizza. Per bere ordinano un’acqua naturale e un vino rosso. Il cameriere porta anche il tiramisù, il dolce preferito di Anna. Marco chiede il conto: « Quanto fa ? » « Venticinque euro. » Paga in contanti e lascia la mancia: « Tenga il resto ! ». Anna sorride: « Che bella sorpresa ! »",
        questions: [
                            Exercise(id: "it-listen-cena-sorpresa-q1", kind: "choice", prompt: "Dove sono Marco e Anna ?", options: ["Al ristorante", "A casa", "Al bar", "In pizzeria"], answers: ["Al ristorante"], explain: "Marco porta Anna al ristorante."),
                            Exercise(id: "it-listen-cena-sorpresa-q2", kind: "choice", prompt: "Cosa prende Anna ?", options: ["La pizza", "Le tagliatelle", "Il pesce", "Il vino"], answers: ["La pizza"], explain: "Anna preferisce la pizza."),
                            Exercise(id: "it-listen-cena-sorpresa-q3", kind: "written", prompt: "Per bere, cosa ordinano ?", options: [], answers: ["un'acqua naturale e un vino rosso", "acqua naturale e vino rosso", "acqua e vino rosso"], explain: "Ordinano un’acqua naturale e un vino rosso."),
                            Exercise(id: "it-listen-cena-sorpresa-q4", kind: "choice", prompt: "Quanto fa il conto ?", options: ["Venticinque euro", "Quindici euro", "Trenta euro", "Cinque euro"], answers: ["Venticinque euro"], explain: "« Quanto fa ? » « Venticinque euro. »"),
                            Exercise(id: "it-listen-cena-sorpresa-q5", kind: "choice", prompt: "Come paga Marco ?", options: ["In contanti", "Con la carta", "Con il telefono", "Non paga"], answers: ["In contanti"], explain: "Paga in contanti e lascia la mancia."),
                            Exercise(id: "it-listen-cena-sorpresa-q6", kind: "choice", prompt: "Perché Marco porta Anna al ristorante ?", options: ["È il compleanno di Anna", "È il compleanno di Marco", "È sabato", "Anna invita Marco"], answers: ["È il compleanno di Anna"], explain: "È il suo compleanno: la cena è una sorpresa.")], skills: ["listening:gist", "listening:detail", "vocab:food", "function:order-food"]),
    ListeningText(id: "it-listen-piano-compleanno", languageID: "it", title: "Il piano per il compleanno", level: "A2", topic: "inviti", unitID: "it-foundations-u17",
        text: "Sabato è il compleanno di Giulia, e lei non sa niente. Sara chiama Marco per organizzare la sorpresa. « Cosa le andiamo a regalare ? » chiede Marco. « Le piace la fotografia: vado a cercare un libro di foto », risponde Sara. « Io vado a preparare la torta: al cioccolato, la sua preferita. » « Perfetto. E la festa ? » « È una sorpresa: alle otto, da Luca. Io porto i fiori, tu la musica. » « D’accordo. Peccato: sabato lavoro fino alle sei. » « Nessun problema: la festa comincia dopo. » « Va bene. Sarà una bella festa ! »",
        questions: [
                            Exercise(id: "it-listen-piano-compleanno-q1", kind: "choice", prompt: "Di chi è il compleanno ?", options: ["Di Giulia", "Di Sara", "Di Marco", "Di Luca"], answers: ["Di Giulia"], explain: "Sabato è il compleanno di Giulia."),
                            Exercise(id: "it-listen-piano-compleanno-q2", kind: "choice", prompt: "Cosa va a cercare Sara ?", options: ["Un libro di foto", "Una torta", "I fiori", "La musica"], answers: ["Un libro di foto"], explain: "Le piace la fotografia: vado a cercare un libro di foto."),
                            Exercise(id: "it-listen-piano-compleanno-q3", kind: "written", prompt: "Che torta va a preparare Marco ?", options: [], answers: ["al cioccolato", "torta al cioccolato", "di cioccolato"], explain: "Vado a preparare la torta: al cioccolato."),
                            Exercise(id: "it-listen-piano-compleanno-q4", kind: "choice", prompt: "A che ora è la festa ?", options: ["Alle otto", "Alle nove", "Alle sette", "Alle dieci"], answers: ["Alle otto"], explain: "È una sorpresa: alle otto, da Luca."),
                            Exercise(id: "it-listen-piano-compleanno-q5", kind: "choice", prompt: "Dov’è la festa ?", options: ["Da Luca", "Da Sara", "Da Marco", "A casa di Giulia"], answers: ["Da Luca"], explain: "Alle otto, da Luca."),
                            Exercise(id: "it-listen-piano-compleanno-q6", kind: "written", prompt: "Chi porta i fiori ?", options: [], answers: ["sara", "sara li porta"], explain: "« Io porto i fiori », risponde Sara.")], skills: ["listening:gist", "listening:detail", "grammar:going-to", "function:make-suggestions"]),
    ListeningText(id: "it-listen-aneddoto-estate", languageID: "it", title: "L'aneddoto dell'estate", level: "B1", topic: "racconti", unitID: "it-foundations-u18",
        text: "Al bar, Martina racconta l’aneddoto dell’estate. « Quest’estate, in Sardegna, è successa una cosa incredibile. Prima ho perso il traghetto della sera, poi ho dormito in auto, al campeggio. All’improvviso è arrivato un ragazzo con una torcia: si è scoperto che era il gestore. Mi ha offerto un posto nella tavola calda… » « Non mi dire ! » « E poi sono rimasta una settimana: ho lavorato, ho nuotato e ho fatto amicizia con sua sorella. » « E poi ? Sei tornata a casa ? » « Certo, ma meno male che il traghetto è ripartito: l’auto non partiva più ! » Martina ride: « Che disastro, ma che bella estate ».",
        questions: [
                            Exercise(id: "it-listen-aneddoto-estate-q1", kind: "choice", prompt: "Cosa è successo prima ?", options: ["Ha perso il traghetto", "Ha dormito in auto", "Ha fatto amicizia", "È rimasta una settimana"], answers: ["Ha perso il traghetto"], explain: "« Prima ho perso il traghetto della sera »."),
                            Exercise(id: "it-listen-aneddoto-estate-q2", kind: "written", prompt: "Dove ha dormito la prima notte ?", options: [], answers: ["in auto", "nella sua auto", "in macchina"], explain: "Poi ho dormito in auto, al campeggio."),
                            Exercise(id: "it-listen-aneddoto-estate-q3", kind: "choice", prompt: "Chi è il ragazzo con la torcia ?", options: ["Il gestore del campeggio", "Un turista", "Un suo amico", "Un poliziotto"], answers: ["Il gestore del campeggio"], explain: "Si è scoperto che era il gestore."),
                            Exercise(id: "it-listen-aneddoto-estate-q4", kind: "choice", prompt: "Quanto è rimasta in Sardegna ?", options: ["Una settimana", "Un mese", "Due giorni", "Tutta l’estate"], answers: ["Una settimana"], explain: "« Sono rimasta una settimana »."),
                            Exercise(id: "it-listen-aneddoto-estate-q5", kind: "choice", prompt: "Com’è finita l’estate, per Martina ?", options: ["Un disastro, ma bella", "Terribile e noiosa", "Da dimenticare", "Solo lavoro"], answers: ["Un disastro, ma bella"], explain: "« Che disastro, ma che bella estate »."),
                            Exercise(id: "it-listen-aneddoto-estate-q6", kind: "choice", prompt: "Che reazione ha l’amico durante la storia ?", options: ["Sorpresa e curiosità", "Noia", "Paura", "Delusione"], answers: ["Sorpresa e curiosità"], explain: "« Non mi dire ! » e « E poi ? » chiedono il seguito.")], skills: ["listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors"]),
    ListeningText(id: "it-listen-dibattito-tatto", languageID: "it", title: "Il dibattito con tatto", level: "C1", topic: "opinioni", unitID: "it-foundations-u9",
        text: "Apertura in studio: la questione del ritorno in ufficio. Con noi Elena Ricci, responsabile delle risorse umane, e Tommaso Galli, delegato dei dipendenti. Signora Ricci, Lei propone tre giorni in presenza. « Sì. Capisco il punto di chi ama la casa, però la collaborazione si impara di persona: i nuovi, in particolare, si formano meglio in ufficio ». Galli dissentisce con tatto: « Pur condividendo l’obiettivo, i dati del settore dicono altro: la produttività non è calata. Sono d’accordo in parte sulla formazione; quanto al resto, preferisco fidarmi dei team ». Ricci conclude: « Proviamo allora con due giorni, e tra sei mesi valutiamo insieme ». « Su questo », risponde Galli, « troviamo subito un punto comune ».",
        questions: [
                            Exercise(id: "it-listen-dibattito-tatto-q1", kind: "choice", prompt: "Che proposta fa Ricci ?", options: ["Tre giorni in presenza", "Solo lavoro da casa", "Ritorno completo a tempo pieno", "Eliminare l’ufficio"], answers: ["Tre giorni in presenza"], explain: "« Lei propone tre giorni in presenza »."),
                            Exercise(id: "it-listen-dibattito-tatto-q2", kind: "choice", prompt: "Chi, secondo Ricci, si forma meglio in ufficio ?", options: ["I nuovi assunti", "I dirigenti", "I team esperti", "I delegati"], answers: ["I nuovi assunti"], explain: "« I nuovi, in particolare, si formano meglio in ufficio »."),
                            Exercise(id: "it-listen-dibattito-tatto-q3", kind: "written", prompt: "Che dicono i dati del settore, secondo Galli ?", options: [], answers: ["la produttività non è calata", "la produttivita non e calata", "la produttivita non e calata"], explain: "« I dati del settore dicono altro: la produttività non è calata »."),
                            Exercise(id: "it-listen-dibattito-tatto-q4", kind: "choice", prompt: "Su cosa Galli è d’accordo in parte ?", options: ["Sulla formazione", "Sui trasporti", "Sui computer", "Sui team"], answers: ["Sulla formazione"], explain: "« Sono d’accordo in parte sulla formazione »."),
                            Exercise(id: "it-listen-dibattito-tatto-q5", kind: "written", prompt: "Che compromesso propone Ricci alla fine ?", options: [], answers: ["due giorni", "provare con due giorni", "due giorni e valutiamo tra sei mesi"], explain: "« Proviamo allora con due giorni »."),
                            Exercise(id: "it-listen-dibattito-tatto-q6", kind: "choice", prompt: "Che tono ha il dibattito ?", options: ["Cortese e costruttivo", "Aspro e velato", "Indifferente", "Umoristico"], answers: ["Cortese e costruttivo"], explain: "« Capisco il punto », « punto comune »: dissenso con tatto.")], skills: ["listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "it-listen-aperitivo-venerdi", languageID: "it", title: "L’aperitivo del venerdì", level: "A1", topic: "aperitivo", unitID: "it-foundations-u19",
        text: "È venerdì sera. Luca suona il citofono: è l’aperitivo da Sara. « Posso entrare ? » chiede Luca. « Certo, entra ! ». Luca entra e mette sul tavolo una bottiglia di vino. « Grazie ! Prendi un caffè ? ». « Volentieri ! ». Sul tavolo ci sono olive e biscotti. Parlano del weekend. Alle nove Luca guarda l’orologio: « È tardi, devo andare. Grazie per l’aperitivo ! ». « Grazie a te per il vino ! A presto ! ». « Ciao, alla prossima ! ».",
        questions: [
                            Exercise(id: "it-listen-aperitivo-venerdi-q1", kind: "choice", prompt: "Chi va da Sara ?", options: ["Luca", "Marco", "Anna", "Paolo"], answers: ["Luca"], explain: "Luca suona il citofono: è l’aperitivo da Sara."),
                            Exercise(id: "it-listen-aperitivo-venerdi-q2", kind: "written", prompt: "Cosa mette Luca sul tavolo ?", options: [], answers: ["una bottiglia di vino", "una bottiglia di vino rosso"], explain: "Luca mette sul tavolo una bottiglia di vino."),
                            Exercise(id: "it-listen-aperitivo-venerdi-q3", kind: "choice", prompt: "Cosa offre Sara a Luca ?", options: ["Un caffè", "Un tè", "Un succo", "Una birra"], answers: ["Un caffè"], explain: "« Prendi un caffè ? » « Volentieri ! »."),
                            Exercise(id: "it-listen-aperitivo-venerdi-q4", kind: "choice", prompt: "Cosa c’è anche sul tavolo ?", options: ["Olive e biscotti", "Torta e frutta", "Vino e formaggio", "Panini"], answers: ["Olive e biscotti"], explain: "Sul tavolo ci sono anche olive e biscotti."),
                            Exercise(id: "it-listen-aperitivo-venerdi-q5", kind: "written", prompt: "Perché Luca deve andare ?", options: [], answers: ["è tardi", "e tardi", "perché è tardi", "perche e tardi"], explain: "Alle nove: « È tardi, devo andare »."),
                            Exercise(id: "it-listen-aperitivo-venerdi-q6", kind: "choice", prompt: "Come salutano alla fine ?", options: ["Alla prossima", "A domani", "Buonanotte", "A lunedì"], answers: ["Alla prossima"], explain: "« Ciao, alla prossima ! ».")], skills: ["listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can"]),
    ListeningText(id: "it-listen-reclamo-fattura", languageID: "it", title: "Un reclamo al telefono", level: "A2", topic: "reclami", unitID: "it-foundations-u20",
        text: "Martedì Anna telefona al negozio. « Buongiorno, vorrei segnalare un problema: ho ricevuto la fattura sbagliata ». « Mi dispiace. Che cosa è successo ? ». « Ho comprato una stampante venerdì, ma nella fattura ci sono due stampanti. E la macchina non funziona bene: si è spenta due volte ». « Capisco. Devo chiedere scusa: c’è stato un errore nostro. Manda la fattura per email e mandiamo subito la fattura giusta. Per la stampante: può portarla in negozio ? ». « Certo, vengo domani mattina ». « Grazie per la pazienza. Buona giornata ! ».",
        questions: [
                            Exercise(id: "it-listen-reclamo-fattura-q1", kind: "choice", prompt: "Che problema segnala Anna ?", options: ["La fattura sbagliata", "Il ritardo della consegna", "Il prezzo alto", "Un computer rotto"], answers: ["La fattura sbagliata"], explain: "« Ho ricevuto la fattura sbagliata »."),
                            Exercise(id: "it-listen-reclamo-fattura-q2", kind: "choice", prompt: "Quante stampanti ci sono nella fattura ?", options: ["Due", "Una", "Tre", "Nessuna"], answers: ["Due"], explain: "« Nella fattura ci sono due stampanti »."),
                            Exercise(id: "it-listen-reclamo-fattura-q3", kind: "written", prompt: "Che cosa è successo alla stampante ?", options: [], answers: ["si è spenta due volte", "si e spenta due volte"], explain: "« La macchina non funziona bene: si è spenta due volte »."),
                            Exercise(id: "it-listen-reclamo-fattura-q4", kind: "written", prompt: "Che cosa deve mandare Anna per email ?", options: [], answers: ["la fattura", "la fattura sbagliata"], explain: "« Manda la fattura per email »."),
                            Exercise(id: "it-listen-reclamo-fattura-q5", kind: "choice", prompt: "Quando va Anna in negozio ?", options: ["Domani mattina", "Domani sera", "Stasera", "Venerdì"], answers: ["Domani mattina"], explain: "« Certo, vengo domani mattina ».")], skills: ["listening:gist", "listening:detail", "function:solve-problems", "vocab:social-expressions"]),
    ListeningText(id: "it-listen-colloquio-finto", languageID: "it", title: "Il colloquio finto", level: "B1", topic: "colloqui", unitID: "it-foundations-u21",
        text: "Il colloquio finto di oggi è con Sara, che si prepara a un’azienda di comunicazione. « Raccontaci la sua esperienza ». « Ho lavorato quattro anni in un’agenzia: prima mi occupavo dei social, poi ho gestito due clienti importanti ». « E i suoi punti di forza ? ». « Sono una persona organizzata e calma sotto pressione. Imparo in fretta ». « Perché vuole cambiare ? ». « Cerco una nuova sfida: vorrei occuparmi di progetti internazionali ». « Dove si vede tra cinque anni ? ». « Mi piacerebbe guidare un piccolo team ». « Ha domande ? ». « Sì: come sono gli orari, e c’è possibilità di lavoro ibrido ? ».",
        questions: [
                            Exercise(id: "it-listen-colloquio-finto-q1", kind: "choice", prompt: "Dove vuole lavorare Sara ?", options: ["In un’azienda di comunicazione", "In una scuola", "In un ospedale", "In una banca"], answers: ["In un’azienda di comunicazione"], explain: "Si prepara a un’azienda di comunicazione."),
                            Exercise(id: "it-listen-colloquio-finto-q2", kind: "choice", prompt: "Che cosa ha gestito nell’agenzia ?", options: ["Due clienti importanti", "I social dell’agenzia", "Un piccolo team", "Il budget annuale"], answers: ["Due clienti importanti"], explain: "« Poi ho gestito due clienti importanti »."),
                            Exercise(id: "it-listen-colloquio-finto-q3", kind: "written", prompt: "Che punti di forza dice Sara ?", options: [], answers: ["organizzata e calma sotto pressione", "sono organizzata e calma"], explain: "« Sono una persona organizzata e calma sotto pressione »."),
                            Exercise(id: "it-listen-colloquio-finto-q4", kind: "written", prompt: "Perché vuole cambiare lavoro ?", options: [], answers: ["cerca una nuova sfida", "per una nuova sfida"], explain: "« Cerco una nuova sfida »."),
                            Exercise(id: "it-listen-colloquio-finto-q5", kind: "choice", prompt: "Dove si vede tra cinque anni ?", options: ["A guidare un piccolo team", "All’estero", "In un’altra città", "Da freelance"], answers: ["A guidare un piccolo team"], explain: "« Mi piacerebbe guidare un piccolo team »."),
                            Exercise(id: "it-listen-colloquio-finto-q6", kind: "choice", prompt: "Che cosa chiede alla fine ?", options: ["Orari e lavoro ibrido", "Lo stipendio esatto", "Le ferie", "Il nome del capo"], answers: ["Orari e lavoro ibrido"], explain: "« Come sono gli orari, e c’è possibilità di lavoro ibrido ? ».")], skills: ["listening:inference", "listening:detail", "vocab:work", "function:talk-about-work"]),
    ListeningText(id: "it-listen-tono-podcast", languageID: "it", title: "Podcast: il tono esatto", level: "C1", topic: "registri", unitID: "it-foundations-u9",
        text: "Benvenuti a « Parole al lavoro », il podcast di chi scrive per mestiere. Oggi: il tono esatto. Scrivere bene non è questione di parole rare, ma di scelte precise: si prende una decisione, non la si fa; si ha voglia di leggere, non la voglia. Le collocazioni sono le coppie che la lingua ci consegna già pronte. E i verbi del dire pesano: sostenere una tesi è neutro, asserire suona distante, rivendicare suona da battaglia. Il consiglio di oggi ? Leggete ad alta voce: dove il fiato manca, la frase è troppo lunga; dove il tono sale, forse la parola è sbagliata. In definitiva, esprimere un’opinione è decidere: parola per parola.",
        questions: [
                            Exercise(id: "it-listen-tono-podcast-q1", kind: "choice", prompt: "Che tema ha il podcast di oggi ?", options: ["Il tono esatto", "Le parole rare", "La lettura veloce", "I podcast letterari"], answers: ["Il tono esatto"], explain: "« Oggi: il tono esatto »."),
                            Exercise(id: "it-listen-tono-podcast-q2", kind: "choice", prompt: "Quale collocazione cita come esatta ?", options: ["Prendere una decisione", "Fare una decisione", "Dare una decisione", "Mettere una decisione"], answers: ["Prendere una decisione"], explain: "« Si prende una decisione, non la si fa »."),
                            Exercise(id: "it-listen-tono-podcast-q3", kind: "written", prompt: "Che effetto ha « asserire », secondo il relatore ?", options: [], answers: ["suona distante", "un tono distante"], explain: "« asserire suona distante »."),
                            Exercise(id: "it-listen-tono-podcast-q4", kind: "choice", prompt: "Che effetto ha « rivendicare » ?", options: ["Suona da battaglia", "Suona neutro", "Suona gentile", "Suona antico"], answers: ["Suona da battaglia"], explain: "« rivendicare suona da battaglia »."),
                            Exercise(id: "it-listen-tono-podcast-q5", kind: "written", prompt: "Che consiglio pratico dà il relatore ?", options: [], answers: ["leggere ad alta voce", "leggete ad alta voce", "leggere a voce alta"], explain: "« Leggete ad alta voce »."),
                            Exercise(id: "it-listen-tono-podcast-q6", kind: "choice", prompt: "Come definisce l’opinione alla fine ?", options: ["Decidere parola per parola", "Un gioco di caso", "Una questione di musica", "Un lavoro solitario"], answers: ["Decidere parola per parola"], explain: "« Esprimere un’opinione è decidere: parola per parola ».")], skills: ["listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion"]),
    ListeningText(id: "it-listen-compleanno-sorpresa", languageID: "it", title: "Il compleanno a sorpresa", level: "A1", topic: "compleanni", unitID: "it-foundations-u22",
        text: "« Marco, sabato è il compleanno di Luca ! » « Davvero ? Facciamo una festa a sorpresa ? » « Sì ! A casa tua ? » « Sì, alle otto di sera. Tu cosa porti ? » « Io porto la torta. Tu compri le bibite ? » « Ok. E la musica ? » « Luca ama il jazz, ma per la festa metto la musica pop. » « E gli invitati ? » « Io chiamo Anna e Piero, tu chiami i colleghi. » « Perfetto. È un segreto, eh ? » « Certo ! Tanti auguri a Luca… sabato sera ! »",
        questions: [
                            Exercise(id: "it-listen-compleanno-sorpresa-q1", kind: "choice", prompt: "Che cosa organizzano Marco e Giulia ?", options: ["Una festa a sorpresa", "Una cena al ristorante", "Una partita di calcio", "Un viaggio"], answers: ["Una festa a sorpresa"], explain: "« Facciamo una festa a sorpresa ? »."),
                            Exercise(id: "it-listen-compleanno-sorpresa-q2", kind: "choice", prompt: "Chi porta la torta ?", options: ["Giulia", "Marco", "Anna", "Luca"], answers: ["Giulia"], explain: "« Io porto la torta », dice Giulia."),
                            Exercise(id: "it-listen-compleanno-sorpresa-q3", kind: "written", prompt: "A che ora inizia la festa ?", options: [], answers: ["alle otto", "alle otto di sera", "8 di sera"], explain: "« Sì, alle otto di sera »."),
                            Exercise(id: "it-listen-compleanno-sorpresa-q4", kind: "choice", prompt: "Che musica mette Giulia per la festa ?", options: ["La musica pop", "Il jazz", "Il rock", "Nessuna musica"], answers: ["La musica pop"], explain: "« Per la festa metto la musica pop »."),
                            Exercise(id: "it-listen-compleanno-sorpresa-q5", kind: "written", prompt: "Che cosa compra Marco ?", options: [], answers: ["le bibite"], explain: "« Tu compri le bibite ? » — sì, Marco le compra."),
                            Exercise(id: "it-listen-compleanno-sorpresa-q6", kind: "choice", prompt: "Perché la festa è un segreto ?", options: ["Perché è a sorpresa", "Perché Luca non è invitato", "Perché è a casa di Anna", "Perché è di mattina"], answers: ["Perché è a sorpresa"], explain: "« È un segreto »: la festa è a sorpresa.")], skills: ["listening:detail", "vocab:social-expressions", "function:make-suggestions", "grammar:present-simple"]),
    ListeningText(id: "it-listen-camerino", languageID: "it", title: "Al negozio di vestiti", level: "A1", topic: "negozi", unitID: "it-foundations-u23",
        text: "« Buongiorno, cerco una camicia per il lavoro. » « Certamente. Che colore preferisce ? » « Blu, per favore. » « Ecco una camicia blu, taglia M. » « Posso provarla ? » « Certo, il camerino è lì a destra. » « La camicia è un po’ stretta. Ha la taglia più grande ? » « Ecco la L. » « Adesso va bene ! Quant’è ? » « Trentanove euro. » « Per me è un po’ caro… c’è uno sconto ? » « Oggi sì: in cassa il prezzo è trentaquattro euro. » « Perfetto, la prendo. Pago con la carta. » « Grazie a lei e arrivederci ! »",
        questions: [
                            Exercise(id: "it-listen-camerino-q1", kind: "choice", prompt: "Che cosa cerca la cliente ?", options: ["Una camicia", "Un pantalone", "Una giacca", "Un vestito"], answers: ["Una camicia"], explain: "« Cerco una camicia per il lavoro »."),
                            Exercise(id: "it-listen-camerino-q2", kind: "choice", prompt: "Che colore preferisce ?", options: ["Blu", "Nero", "Bianco", "Verde"], answers: ["Blu"], explain: "« Blu, per favore »."),
                            Exercise(id: "it-listen-camerino-q3", kind: "written", prompt: "Che problema ha la camicia nel camerino ?", options: [], answers: ["è un po’ stretta", "e un po stretta", "e stretta", "un po stretta"], explain: "« La camicia è un po’ stretta »."),
                            Exercise(id: "it-listen-camerino-q4", kind: "choice", prompt: "Quanto costa alla fine ?", options: ["Trentaquattro euro", "Trentanove euro", "Quaranta euro", "Trenta euro"], answers: ["Trentaquattro euro"], explain: "« In cassa il prezzo è trentaquattro euro »."),
                            Exercise(id: "it-listen-camerino-q5", kind: "written", prompt: "Come paga la cliente ?", options: [], answers: ["con la carta", "paga con la carta", "carta"], explain: "« Pago con la carta »."),
                            Exercise(id: "it-listen-camerino-q6", kind: "choice", prompt: "Che taglia prende alla fine ?", options: ["La L", "La M", "La S", "La XL"], answers: ["La L"], explain: "« Ecco la L » — « Adesso va bene ! ».")], skills: ["listening:detail", "function:go-shopping", "vocab:shopping", "grammar:can"]),
    ListeningText(id: "it-listen-restituzione", languageID: "it", title: "La stampante da restituire", level: "A2", topic: "restituzioni", unitID: "it-foundations-u24",
        text: "« Buongiorno, ho comprato questa stampante sabato, ma non funziona bene. » « Mi dispiace. Che cosa succede ? » « Stampa le pagine a metà. L’ho usata solo tre volte. » « Ha lo scontrino ? » « Sì, eccolo. » « Vuole un’altra stampante uguale oppure preferisce restituirla ? » « Vorrei restituirla e prendere il modello più grande: costa dieci euro in più, però ha recensioni migliori. » « Nessun problema. Ecco il rimborso di ottantanove euro; la differenza sono dieci euro. » « Posso pagare la differenza con la carta ? » « Certo. Anche in tre rate, se preferisce. » « No, tutta insieme, grazie. »",
        questions: [
                            Exercise(id: "it-listen-restituzione-q1", kind: "written", prompt: "Che cosa ha comprato il cliente ?", options: [], answers: ["una stampante", "la stampante"], explain: "« Ho comprato questa stampante sabato »."),
                            Exercise(id: "it-listen-restituzione-q2", kind: "written", prompt: "Quante volte l’ha usata ?", options: [], answers: ["tre volte", "3 volte"], explain: "« L’ho usata solo tre volte »."),
                            Exercise(id: "it-listen-restituzione-q3", kind: "choice", prompt: "Che cosa vuole il cliente ?", options: ["Restituirla e prendere il modello più grande", "Cambiare lo scontrino", "Un rimborso senza sostituzione", "Un tecnico a casa"], answers: ["Restituirla e prendere il modello più grande"], explain: "« Vorrei restituirla e prendere il modello più grande »."),
                            Exercise(id: "it-listen-restituzione-q4", kind: "written", prompt: "Quanto costa la differenza ?", options: [], answers: ["dieci euro", "10 euro"], explain: "« La differenza sono dieci euro »."),
                            Exercise(id: "it-listen-restituzione-q5", kind: "choice", prompt: "Perché sceglie il modello più grande ?", options: ["Perché ha recensioni migliori", "Perché costa meno", "Perché è più piccolo", "Perché è in saldo"], answers: ["Perché ha recensioni migliori"], explain: "« Costa dieci euro in più, però ha recensioni migliori »."),
                            Exercise(id: "it-listen-restituzione-q6", kind: "written", prompt: "Come vuole pagare la differenza ?", options: [], answers: ["tutta insieme", "tutta insieme con la carta", "insieme"], explain: "« No, tutta insieme, grazie ».")], skills: ["listening:detail", "grammar:past-simple-regular", "function:solve-problems", "vocab:shopping"]),
    ListeningText(id: "it-listen-vigilia-partenza", languageID: "it", title: "La vigilia della partenza", level: "A2", topic: "viaggi", unitID: "it-foundations-u25",
        text: "« Domani parto per Lisbona ! » « Hai già fatto la valigia ? » « Sto per chiuderla adesso. Mi mancano solo il caricatore e l’adattatore. » « E i documenti ? » « Il passaporto l’ho già messo nella borsa; il biglietto ce l’ho sul telefono. » « A che ora parte il volo ? » « Alle nove e dieci. Devo essere all’aeroporto due ore prima, quindi domani mi sveglio alle sei. » « Prendi il treno o il pullman ? » « Il treno per l’aeroporto: parte dalla stazione centrale alle sei e mezza. » « E l’albergo ? » « È in centro, vicino alla metro. Stasera faccio il check-in online, poi a letto presto ! »",
        questions: [
                            Exercise(id: "it-listen-vigilia-partenza-q1", kind: "choice", prompt: "Dove parte la persona ?", options: ["A Lisbona", "A Barcellona", "A Roma", "A Londra"], answers: ["A Lisbona"], explain: "« Domani parto per Lisbona ! »."),
                            Exercise(id: "it-listen-vigilia-partenza-q2", kind: "written", prompt: "Che cosa manca ancora nella valigia ?", options: [], answers: ["il caricatore e l’adattatore", "il caricatore e l adattatore", "caricatore e adattatore", "il caricatore"], explain: "« Mi mancano solo il caricatore e l’adattatore »."),
                            Exercise(id: "it-listen-vigilia-partenza-q3", kind: "choice", prompt: "A che ora parte il volo ?", options: ["Alle nove e dieci", "Alle sei e mezza", "Alle nove", "Alle sei"], answers: ["Alle nove e dieci"], explain: "« Alle nove e dieci »."),
                            Exercise(id: "it-listen-vigilia-partenza-q4", kind: "written", prompt: "A che ora si sveglia domani ?", options: [], answers: ["alle sei", "6"], explain: "« Domani mi sveglio alle sei »."),
                            Exercise(id: "it-listen-vigilia-partenza-q5", kind: "choice", prompt: "Che mezzo prende per l’aeroporto ?", options: ["Il treno", "Il pullman", "Un taxi", "La metro"], answers: ["Il treno"], explain: "« Il treno per l’aeroporto »."),
                            Exercise(id: "it-listen-vigilia-partenza-q6", kind: "choice", prompt: "Perché si sveglia presto ?", options: ["Perché deve essere all’aeroporto due ore prima", "Perché vuole fare colazione", "Perché l’albergo è lontano", "Perché il volo parte alle sei"], answers: ["Perché deve essere all’aeroporto due ore prima"], explain: "« Devo essere all’aeroporto due ore prima, quindi domani mi sveglio alle sei ».")], skills: ["listening:detail", "grammar:going-to", "vocab:travel", "grammar:connectors"]),
    ListeningText(id: "it-listen-quartiere-sogno", languageID: "it", title: "La piazza che vogliamo", level: "B1", topic: "quartieri", unitID: "it-foundations-u26",
        text: "« Hai visto l’assemblea di giovedì ? Si parla della zona pedonale in piazza Nucci. » « Sì, e la mia opinione è chiara: da un lato la piazza diventa più viva, dall’altro i commercianti temono per i clienti. » « Anch’io sono divisa. Secondo me servono dati, non solo opinioni. » « Allora leggi lo studio del comune: il settanta per cento dei clienti arriva a piedi o in bici. » « Davvero ? Però il parcheggio resta un problema. » « Infatti la proposta prevede trenta posti nuovi in via Ferretti. » « Mmm, in questo caso sono d’accordo con il progetto. » « Propongo un test di sei mesi, poi si valuta con i numeri. » « Giusto: meno parole, più fatti. Giovedì, allora ! »",
        questions: [
                            Exercise(id: "it-listen-quartiere-sogno-q1", kind: "choice", prompt: "Di che cosa si parla all’assemblea ?", options: ["Della zona pedonale in piazza", "Dei prezzi dei negozi", "Dei mezzi pubblici", "Dei rifiuti"], answers: ["Della zona pedonale in piazza"], explain: "« Si parla della zona pedonale in piazza Nucci »."),
                            Exercise(id: "it-listen-quartiere-sogno-q2", kind: "written", prompt: "Che percentuale dei clienti arriva a piedi o in bici ?", options: [], answers: ["il settanta per cento", "settanta per cento", "70 per cento", "il 70%"], explain: "« Il settanta per cento dei clienti arriva a piedi o in bici »."),
                            Exercise(id: "it-listen-quartiere-sogno-q3", kind: "choice", prompt: "Che cosa temono i commercianti ?", options: ["Per i clienti", "Per i posti auto", "Per i rifiuti", "Per il rumore"], answers: ["Per i clienti"], explain: "« I commercianti temono per i clienti »."),
                            Exercise(id: "it-listen-quartiere-sogno-q4", kind: "written", prompt: "Che cosa prevede la proposta per i parcheggi ?", options: [], answers: ["trenta posti nuovi in via ferretti", "trenta posti nuovi", "30 posti nuovi"], explain: "« La proposta prevede trenta posti nuovi in via Ferretti »."),
                            Exercise(id: "it-listen-quartiere-sogno-q5", kind: "written", prompt: "Quanto dura il test proposto ?", options: [], answers: ["sei mesi", "6 mesi"], explain: "« Io propongo un test di sei mesi »."),
                            Exercise(id: "it-listen-quartiere-sogno-q6", kind: "choice", prompt: "Come si chiude la discussione ?", options: ["Con un accordo e un appuntamento", "Con una lite", "Con l’annullamento dell’assemblea", "Con un voto subito"], answers: ["Con un accordo e un appuntamento"], explain: "« In questo caso sono d’accordo… Ci vediamo giovedì, allora ! ».")], skills: ["listening:inference", "function:express-opinion", "grammar:connectors", "speaking:justify-opinion"]),
    ListeningText(id: "it-listen-riunione-finale", languageID: "it", title: "La riunione del progetto", level: "B1", topic: "riunioni", unitID: "it-work-u1",
        text: "« Dove siamo con il progetto Tevere ? » « Ho finito la parte analitica e ho parlato col cliente: vuole risultati entro marzo. » « Marzo è fattibile, però il budget attuale non basta. Da un lato possiamo ridurre i test, dall’altro chiedere fondi extra. » « A mio avviso è rischioso: è la parte che il cliente valuta di più. » « Capisco il punto. Quanto costano i fondi extra ? » « Circa quindicimila euro, entro fine mese. » « Allora propongo di presentarla domani, con i numeri in mano. » « D’accordo, ma chi la presenta ? » « Io, se sei d’accordo. Preparo le slide stanotte e le mando in allegato. » « Perfetto. Sentiamo il cliente giovedì. Grazie a tutti. »",
        questions: [
                            Exercise(id: "it-listen-riunione-finale-q1", kind: "choice", prompt: "Che problema ha il progetto ?", options: ["Il budget non basta", "Il cliente è scomparso", "La parte analitica è incompleta", "La scadenza è passata"], answers: ["Il budget non basta"], explain: "« Il budget attuale non basta »."),
                            Exercise(id: "it-listen-riunione-finale-q2", kind: "written", prompt: "Entro quando vuole i risultati il cliente ?", options: [], answers: ["entro marzo", "marzo"], explain: "« Vuole risultati entro marzo »."),
                            Exercise(id: "it-listen-riunione-finale-q3", kind: "choice", prompt: "Perché ridurre i test è rischioso ?", options: ["Perché il cliente valuta molto quella parte", "Perché costano troppo", "Perché non c’è tempo", "Perché il cliente non li vuole"], answers: ["Perché il cliente valuta molto quella parte"], explain: "« È la parte che il cliente valuta di più »."),
                            Exercise(id: "it-listen-riunione-finale-q4", kind: "written", prompt: "Quanto costano i fondi extra ?", options: [], answers: ["circa quindicimila euro", "quindicimila euro", "15000 euro"], explain: "« Circa quindicimila euro »."),
                            Exercise(id: "it-listen-riunione-finale-q5", kind: "written", prompt: "Che cosa fa chi presenta la richiesta, entro stanotte ?", options: [], answers: ["prepara le slide", "prepara le slide e le manda in allegato", "prepara le slide e le manda", "le slide"], explain: "« Preparo le slide stanotte e le mando in allegato »."),
                            Exercise(id: "it-listen-riunione-finale-q6", kind: "choice", prompt: "Quando sentono il cliente ?", options: ["Giovedì", "Domani", "Venerdì", "Entro fine mese"], answers: ["Giovedì"], explain: "« Sentiamo il cliente giovedì ».")], skills: ["listening:inference", "function:express-opinion", "grammar:connectors", "vocab:work"]),
    ListeningText(id: "it-listen-trasloco-lista", languageID: "it", title: "La lista del trasloco", level: "A2", topic: "trasloco", unitID: "it-foundations-u28",
        text: "Quando Marco dice: « Sabato trasloco! », io apro la lista delle cose da fare. Per prima cosa compro le scatole: me ne servono almeno dieci, grandi e piccole. Poi imballo la cucina, che è la parte più lenta: piatti, bicchieri e pentole, con tanta carta di giornale. I libri vanno in scatole piccole, perché diventano pesantissime. Devo anche chiamare il furgone: devo farlo entro giovedì, altrimenti non troviamo nulla. Bisogna poi pensare alle cose che non si imballano: le piante, ad esempio, vengono in macchina con me. La sera prima chiudo tutte le scatole e scrivo su ognuna il nome della stanza. Così, nella casa nuova, tutto va direttamente al suo posto.",
        questions: [
                            Exercise(id: "it-listen-trasloco-lista-q1", kind: "choice", prompt: "Che cosa fa Marco il sabato?", options: ["Trasloca di casa", "Compra un furgone", "Trova lavoro", "Vende la cucina"], answers: ["Trasloca di casa"], explain: "« Sabato trasloco! », dice Marco: si trasferisce di casa."),
                            Exercise(id: "it-listen-trasloco-lista-q2", kind: "written", prompt: "Quante scatole servono almeno?", options: [], answers: ["dieci", "10", "dieci scatole"], explain: "« Me ne servono almeno dieci, grandi e piccole »."),
                            Exercise(id: "it-listen-trasloco-lista-q3", kind: "choice", prompt: "Qual è la parte più lenta da imballare?", options: ["La cucina", "I libri", "Le piante", "Il salotto"], answers: ["La cucina"], explain: "« Imballo la cucina, che è la parte più lenta »."),
                            Exercise(id: "it-listen-trasloco-lista-q4", kind: "written", prompt: "Entro quando deve chiamare il furgone?", options: [], answers: ["entro giovedì", "giovedì", "entro giovedi"], explain: "« Devo farlo entro giovedì, altrimenti non troviamo nulla »."),
                            Exercise(id: "it-listen-trasloco-lista-q5", kind: "choice", prompt: "Come viaggiano le piante?", options: ["In macchina con lui", "Nel furgone", "Restano a casa", "Per posta"], answers: ["In macchina con lui"], explain: "« Le piante… vengono in macchina con me »."),
                            Exercise(id: "it-listen-trasloco-lista-q6", kind: "written", prompt: "Che cosa scrive sulle scatole?", options: [], answers: ["il nome della stanza", "la stanza", "il nome della stanza di destinazione"], explain: "« Scrivo su ognuna il nome della stanza ».")], skills: ["listening:detail", "listening:number-time", "grammar:modal-must-have-to", "vocab:home"]),
    ListeningText(id: "it-listen-vicini-furgone", languageID: "it", title: "Il furgone di Giulia", level: "A2", topic: "richieste", unitID: "it-foundations-u28",
        text: "« Giulia, tu hai il furgone, vero? »\n« Sì, quello piccolo. Perché, ti serve? »\n« Ti devo dire una cosa: sabato trasloco e devo portare i libri e le piante. Puoi prestarmelo per la mattina? »\n« Certo! Ma devi riportarmelo entro le due, perché alle tre esco. »\n« Perfetto, per le due è da riportare. Posso darti una mano con qualcosa in cambio? »\n« Mmm… puoi aiutarmi a montare lo scaffale nuovo? Da sola ci metto ore! »\n« Affare fatto. E grazie mille, sei gentilissima! »\n« Figurati! Poi mi racconti com'è la casa nuova. »",
        questions: [
                            Exercise(id: "it-listen-vicini-furgone-q1", kind: "choice", prompt: "Che cosa chiede Marco a Giulia?", options: ["Il furgone per sabato mattina", "I libri di scuola", "Una pianta nuova", "Lo scaffale di casa"], answers: ["Il furgone per sabato mattina"], explain: "« Puoi prestarmelo per la mattina? », chiede Marco per il trasloco del sabato."),
                            Exercise(id: "it-listen-vicini-furgone-q2", kind: "written", prompt: "Entro che ora deve riportare il furgone?", options: [], answers: ["entro le due", "le due", "alle due"], explain: "« Devi riportarmelo entro le due, perché alle tre esco »."),
                            Exercise(id: "it-listen-vicini-furgone-q3", kind: "choice", prompt: "Che cosa chiede Giulia in cambio?", options: ["Aiuto per montare uno scaffale", "Dieci euro di benzina", "Un vaso per le piante", "Un aiuto col trasloco"], answers: ["Aiuto per montare uno scaffale"], explain: "« Puoi aiutarmi a montare lo scaffale nuovo? »."),
                            Exercise(id: "it-listen-vicini-furgone-q4", kind: "written", prompt: "Come risponde Giulia al grazie?", options: [], answers: ["figurati", "Figurati", "figurati!"], explain: "« Figurati! »: è la risposta tipica a un grazie."),
                            Exercise(id: "it-listen-vicini-furgone-q5", kind: "choice", prompt: "Com'è il furgone di Giulia?", options: ["Piccolo", "Enorme", "Nuovo di zecca", "Rosso"], answers: ["Piccolo"], explain: "« Sì, quello piccolo », risponde Giulia.")], skills: ["listening:detail", "function:make-requests", "grammar:can", "vocab:social-expressions"]),
    ListeningText(id: "it-listen-prima-notte-sistemi", languageID: "it", title: "La prima notte", level: "A2", topic: "casa nuova", unitID: "it-foundations-u28",
        text: "« Allora, com'è la casa nuova? »\n« Strana! Ci sono scatole ovunque e adesso sto sistemando i libri nella libreria. »\n« E la camera? »\n« C'è un letto grande e un balcone sul cortile, molto tranquillo. Ma non ci sono ancora le tende, quindi domani il sole entra alle sei! »\n« E la cucina? »\n« C'è il forno nuovo, ma manca il tavolo: per ora mangiamo sul divano, che comunque è arrivato! »\n« Almeno una cosa! C'è l'ascensore o fai le scale? »\n« C'è, per fortuna: sono al terzo piano e con le scatole sarebbe un disastro. »\n« Ti auguro la prima buona notte nella casa nuova! »",
        questions: [
                            Exercise(id: "it-listen-prima-notte-sistemi-q1", kind: "choice", prompt: "Che cosa fa Marco adesso?", options: ["Sistema i libri", "Monta il letto", "Fa la spesa", "Pulisce la cucina"], answers: ["Sistema i libri"], explain: "« Adesso sto sistemando i libri nella libreria »."),
                            Exercise(id: "it-listen-prima-notte-sistemi-q2", kind: "written", prompt: "Che cosa manca nella camera da letto?", options: [], answers: ["le tende", "tenda", "le tende ancora"], explain: "« Non ci sono ancora le tende »."),
                            Exercise(id: "it-listen-prima-notte-sistemi-q3", kind: "choice", prompt: "Che cosa c'è in cucina?", options: ["Il forno nuovo", "Il tavolo nuovo", "Il divano rosso", "La lavastoviglie"], answers: ["Il forno nuovo"], explain: "« C'è il forno nuovo, ma manca il tavolo »."),
                            Exercise(id: "it-listen-prima-notte-sistemi-q4", kind: "written", prompt: "A che piano abita?", options: [], answers: ["al terzo piano", "terzo piano", "3 piano"], explain: "« Sono al terzo piano »."),
                            Exercise(id: "it-listen-prima-notte-sistemi-q5", kind: "choice", prompt: "Perché l'ascensore è importante?", options: ["Perché ci sono molte scatole", "Perché abita all'ultimo piano", "Perché il palazzo è vecchio", "Perché il divano è pesante"], answers: ["Perché ci sono molte scatole"], explain: "« Con le scatole sarebbe un disastro ».")], skills: ["listening:detail", "grammar:there-is-are", "vocab:home", "listening:gist"]),
    ListeningText(id: "it-listen-aeroporto-ritardo", languageID: "it", title: "Il volo in ritardo", level: "A2", topic: "aeroporto", unitID: "it-foundations-u25",
        text: "« Buongiorno, dove posso fare il check-in per il volo di Lisbona? »\n« Al banco dodici, signora, è lì al fondo. »\nPoi arriva l'annuncio: « Signore e signori, il volo AZ 452 per Lisbona è in ritardo di quaranta minuti. L'imbarco avverrà al gate quindici, che chiude alle nove e mezza. Vi invitiamo a recarvi al gate. »\n« Scusi, il volo è in ritardo: perdo la coincidenza di Lisbona. Devo cambiare il biglietto? »\n« No, signora: la coincidenza è protetta. Al suo arrivo troverà il prossimo volo. »\n« Perfetto. E dove aspetto adesso? »\n« C'è un caffè dopo i controlli di sicurezza: il gate apre tra mezz'ora. »",
        questions: [
                            Exercise(id: "it-listen-aeroporto-ritardo-q1", kind: "written", prompt: "Di quanto è in ritardo il volo?", options: [], answers: ["quaranta minuti", "40 minuti"], explain: "« Il volo AZ 452 per Lisbona è in ritardo di quaranta minuti »."),
                            Exercise(id: "it-listen-aeroporto-ritardo-q2", kind: "choice", prompt: "Dove avviene l'imbarco?", options: ["Al gate quindici", "Al banco dodici", "Al gate cinquanta", "Al caffè"], answers: ["Al gate quindici"], explain: "« L'imbarco avverrà al gate quindici »."),
                            Exercise(id: "it-listen-aeroporto-ritardo-q3", kind: "written", prompt: "A che ora chiude il gate?", options: [], answers: ["alle nove e mezza", "nove e mezza", "alle 9 e 30"], explain: "« …che chiude alle nove e mezza »."),
                            Exercise(id: "it-listen-aeroporto-ritardo-q4", kind: "choice", prompt: "Che cosa succede alla coincidenza di Lisbona?", options: ["È protetta: prende il volo dopo", "È persa per sempre", "È annullata", "Parte senza di lei"], answers: ["È protetta: prende il volo dopo"], explain: "« La coincidenza è protetta. Al suo arrivo troverà il prossimo volo »."),
                            Exercise(id: "it-listen-aeroporto-ritardo-q5", kind: "choice", prompt: "Che cosa può fare mentre aspetta?", options: ["Prendere un caffè dopo i controlli", "Tornare a casa", "Cambiare il banco", "Comprare un altro biglietto"], answers: ["Prendere un caffè dopo i controlli"], explain: "« C'è un caffè dopo i controlli di sicurezza ».")], skills: ["listening:detail", "listening:number-time", "vocab:travel", "function:solve-problems"]),
    ListeningText(id: "it-listen-progetto-camper", languageID: "it", title: "Il progetto dell'estate", level: "A2", topic: "progetti", unitID: "it-foundations-u4",
        text: "« Quest'estate finalmente facciamo il viaggio in camper! »\n« Davvero? Dove andate? »\n« Prima andiamo in Toscana, per una settimana, poi scendiamo in Umbria. Il campeggio in Toscana l'ho già prenotato. »\n« E come preparate il camper? »\n« Sto facendo la lista: dobbiamo portare il frigo portatile, le sedie e il tavolo pieghevole. E devo controllare la ruota di scorta. »\n« Quanto costa il campeggio? »\n« Venti euro a notte, con la corrente inclusa. Domani vado a comprare l'adattatore per la corrente. »\n« Ad agosto ci sono mosche e zanzare, eh? »\n« Lo so: per questo prendo anche la zanzariera. L'anno scorso mi hanno mangiato! »",
        questions: [
                            Exercise(id: "it-listen-progetto-camper-q1", kind: "choice", prompt: "Dove vanno prima?", options: ["In Toscana", "In Umbria", "Al mare", "In montagna"], answers: ["In Toscana"], explain: "« Prima andiamo in Toscana, per una settimana »."),
                            Exercise(id: "it-listen-progetto-camper-q2", kind: "written", prompt: "Che cosa ha già prenotato?", options: [], answers: ["il campeggio", "campeggio", "il campeggio in toscana"], explain: "« Il campeggio in Toscana l'ho già prenotato »."),
                            Exercise(id: "it-listen-progetto-camper-q3", kind: "choice", prompt: "Quanto costa il campeggio a notte?", options: ["Venti euro", "Dodici euro", "Trenta euro", "Due euro"], answers: ["Venti euro"], explain: "« Venti euro a notte, con la corrente inclusa »."),
                            Exercise(id: "it-listen-progetto-camper-q4", kind: "written", prompt: "Che cosa compra domani?", options: [], answers: ["l'adattatore", "l adattatore", "adattatore"], explain: "« Domani vado a comprare l'adattatore per la corrente »."),
                            Exercise(id: "it-listen-progetto-camper-q5", kind: "choice", prompt: "Perché prende la zanzariera?", options: ["Per le zanzare di agosto", "Per la pioggia", "Per il sole", "Per il frigo"], answers: ["Per le zanzare di agosto"], explain: "« Ad agosto ci sono mosche e zanzare… per questo prendo anche la zanzariera ».")], skills: ["listening:detail", "listening:number-time", "function:make-future-plans", "vocab:travel"]),
    ListeningText(id: "it-listen-bici-riparata", languageID: "it", title: "La bici riparata", level: "A2", topic: "problemi", unitID: "it-foundations-u20",
        text: "« Ciao Paolo! Ma la bici com'è? L'hai riparata? »\n« Sì! Sabato la gomma era buciata e io ero senza strumenti. »\n« E che cosa hai fatto? »\n« Ho chiesto a un ragazzo del quartiere che ripara le bici nel cortile di palazzo. In mezz'ora la gomma era a posto e ha cambiato anche la camera d'aria. »\n« Quanto ti è costato? »\n« Dodici euro, pezzi e manodopera. Un biglietto di autobus costa un euro e cinquanta, quindi in un mese mi sono già rifatto! »\n« E adesso ci vai al lavoro in bici? »\n« Certo: in venti minuti sono in ufficio. E non trovo più un posto per l'auto: perdo più tempo a parcheggiare che a pedalare! »",
        questions: [
                            Exercise(id: "it-listen-bici-buciata-q1", kind: "choice", prompt: "Qual era il problema di sabato?", options: ["La gomma era buciata", "La catena era rotta", "Il freno non funzionava", "Non c'era la sella"], answers: ["La gomma era buciata"], explain: "« Sabato la gomma era buciata »."),
                            Exercise(id: "it-listen-bici-buciata-q2", kind: "written", prompt: "Quanto è costata la riparazione?", options: [], answers: ["dodici euro", "12 euro"], explain: "« Dodici euro, pezzi e manodopera »."),
                            Exercise(id: "it-listen-bici-buciata-q3", kind: "choice", prompt: "Che cosa ha cambiato il ragazzo?", options: ["La camera d'aria", "La catena", "La sella", "Il manubrio"], answers: ["La camera d'aria"], explain: "« Ha cambiato anche la camera d'aria »."),
                            Exercise(id: "it-listen-bici-buciata-q4", kind: "written", prompt: "Quanto tempo ci mette ora per andare al lavoro in bici?", options: [], answers: ["venti minuti", "20 minuti"], explain: "« In venti minuti sono in ufficio »."),
                            Exercise(id: "it-listen-bici-buciata-q5", kind: "choice", prompt: "Perché preferisce la bici all'auto?", options: ["Perché parcheggiare è difficile", "Perché l'auto è rotta", "Perché il lavoro è lontano", "Perché l'autobus è caro"], answers: ["Perché parcheggiare è difficile"], explain: "« Non trovo più un posto per l'auto: perdo più tempo a parcheggiare ».")], skills: ["listening:detail", "listening:number-time", "function:solve-problems", "vocab:transport"]),
    ListeningText(id: "it-listen-colloquio-vero", languageID: "it", title: "Il secondo colloquio", level: "B1", topic: "lavoro", unitID: "it-foundations-u21",
        text: "« Bentornata, Chiara. Il primo colloquio è andato bene, ma ora vuole conoscerla il direttore: ha qualche domanda da farci? »\n« Sì: vorrei sapere com'è organizzato il team e con chi lavorerò ogni giorno. »\n« Siamo sei persone, due in sede e il resto in remoto. Il direttore, poi, apprezza chi porta idee nuove: le è mai capitato di proporre un cambiamento? »\n« Nel mio lavoro attuale ho proposto un nuovo turno di apertura del negozio: le vendite del sabato sono aumentate del dieci per cento. »\n« Perfetto. E che cosa si aspetta da noi? »\n« Prima di tutto imparare, poi crescere. Non cerco solo uno stipendio: cerco un posto dove rimanere. »\n« Bella risposta. La richiameremo entro venerdì. »",
        questions: [
                            Exercise(id: "it-listen-colloquio-vero-q1", kind: "choice", prompt: "Chi vuole conoscere Chiara?", options: ["Il direttore", "Il suo capo attuale", "I clienti del negozio", "I colleghi in remoto"], answers: ["Il direttore"], explain: "« Ora vuole conoscerla il direttore »."),
                            Exercise(id: "it-listen-colloquio-vero-q2", kind: "written", prompt: "Di quante persone è composto il team?", options: [], answers: ["sei persone", "6 persone", "sei"], explain: "« Siamo sei persone, due in sede e il resto in remoto »."),
                            Exercise(id: "it-listen-colloquio-vero-q3", kind: "choice", prompt: "Che cosa ha proposto nel lavoro attuale?", options: ["Un nuovo turno di apertura", "Un nuovo negozio", "Uno stipendio più alto", "Un lavoro in remoto"], answers: ["Un nuovo turno di apertura"], explain: "« Ho proposto un nuovo turno di apertura del negozio »."),
                            Exercise(id: "it-listen-colloquio-vero-q4", kind: "written", prompt: "Di quanto sono aumentate le vendite del sabato?", options: [], answers: ["del dieci per cento", "dieci per cento", "10 per cento"], explain: "« Le vendite del sabato sono aumentate del dieci per cento »."),
                            Exercise(id: "it-listen-colloquio-vero-q5", kind: "choice", prompt: "Che cosa cerca Chiara?", options: ["Un posto dove rimanere", "Solo uno stipendio", "Un lavoro in remoto", "Un contratto breve"], answers: ["Un posto dove rimanere"], explain: "« Non cerco solo uno stipendio: cerco un posto dove rimanere ».")], skills: ["listening:inference", "listening:detail", "function:talk-about-work", "vocab:work"]),
    ListeningText(id: "it-listen-trattativa-affitto", languageID: "it", title: "La trattativa dell'affitto", level: "B2", topic: "affitto", unitID: "it-foundations-u7",
        text: "« Allora, signor Ferri, l'appartamento le piace. L'offerta è di novecento euro al mese, spese escluse. »\n« Mi permetta un'osservazione: per un quarto piano senza ascensore, novecento sono tanti. Le propongo ottocento, spese incluse. »\n« Ottocento è impossibile, lo capisca. Ma posso fare un passo: ottocentosessanta, e le spese restano a suo carico. »\n« Se mi garantisce un contratto di tre anni con rinnovo, accetto ottocentosessanta. »\n« Tre anni vanno bene, ma il rinnovo automatico no: preferiamo rivedere le condizioni ogni anno, è giusto per entrambi. »\n« D'accordo, a patto che l'aumento non superi l'inflazione. E una cosa ancora: chi paga le tapparelle rotte della camera? »\n« Quelle le sistemo io, prima che entri. È un piacere trattare con qualcuno che sa quello che vuole. »",
        questions: [
                            Exercise(id: "it-listen-trattativa-affitto-q1", kind: "choice", prompt: "Che cosa propone il signor Ferri all'inizio?", options: ["Ottocento euro, spese incluse", "Novecento euro, spese escluse", "Ottocentosessanta euro", "Un contratto di tre anni"], answers: ["Ottocento euro, spese incluse"], explain: "« Le propongo ottocento, spese incluse »."),
                            Exercise(id: "it-listen-trattativa-affitto-q2", kind: "written", prompt: "Perché il signor Ferri ritiene alto il prezzo?", options: [], answers: ["perché è un quarto piano senza ascensore", "quarto piano senza ascensore", "perche non c e l ascensore"], explain: "« Per un quarto piano senza ascensore, novecento sono tanti »."),
                            Exercise(id: "it-listen-trattativa-affitto-q3", kind: "choice", prompt: "Che condizione mette per accettare ottocentosessanta?", options: ["Un contratto di tre anni", "Le spese incluse", "Un aumento annuale", "Le tapparelle nuove"], answers: ["Un contratto di tre anni"], explain: "« Se mi garantisce un contratto di tre anni con rinnovo, accetto ottocentosessanta »."),
                            Exercise(id: "it-listen-trattativa-affitto-q4", kind: "choice", prompt: "Come vuole gestire i rinnovi la proprietaria?", options: ["Rivedendo le condizioni ogni anno", "Con un rinnovo automatico", "Senza mai aumentare", "Con un contratto di un mese"], answers: ["Rivedendo le condizioni ogni anno"], explain: "« Preferiamo rivedere le condizioni ogni anno, è giusto per entrambi »."),
                            Exercise(id: "it-listen-trattativa-affitto-q5", kind: "written", prompt: "Chi ripara le tapparelle rotte?", options: [], answers: ["la proprietaria", "il proprietario", "la padrona di casa"], explain: "« Quelle le sistemo io », dice la proprietaria."),
                            Exercise(id: "it-listen-trattativa-affitto-q6", kind: "choice", prompt: "Come si può descrivere il signor Ferri?", options: ["Sa negoziare punto per punto", "Ha fretta di firmare", "Non vuole il contratto", "Accetta tutto subito"], answers: ["Sa negoziare punto per punto"], explain: "« È un piacere trattare con qualcuno che sa quello che vuole ».")], skills: ["listening:inference", "function:negotiate", "speaking:negotiate", "listening:connected-speech"]),
    ListeningText(id: "it-listen-dibattito-turismo", languageID: "it", title: "Il dibattito sul turismo", level: "B2", topic: "attualità", unitID: "it-foundations-u8",
        text: "« Microfoni aperti » torna sul turismo eccessivo. Con noi Elena Marchi, guida turistica a Venezia, e Paolo Sarti, albergatore.\nElena: « In centro i residenti sono meno di cinquantamila, e ogni giorno arrivano ottantamila visitatori. Non sono contro il turismo: sono contro un turismo che svuota i negozi di quartiere e riempie solo i negozi di souvenir. Serve una prenotazione obbligatoria, come per i musei. »\nPaolo: « La prenotazione penalizza chi viene per un weekend e spende qui. Il problema non sono i turisti, ma i case vacanza: limitare quelle, non le persone. »\nElena: « Limitarle è giusto, ma da sole non bastano: senza un limite d'ingresso, nel 2030 il centro è un parco a tema. »\nPaolo: « E chi controlla questo limite? Alcuni residenti vorrebbero la città vuota. »",
        questions: [
                            Exercise(id: "it-listen-dibattito-turismo-q1", kind: "choice", prompt: "Che cosa propone Elena per l'ingresso in centro?", options: ["Una prenotazione obbligatoria", "Un biglietto più caro", "La chiusura dei souvenir", "Più alberghi"], answers: ["Una prenotazione obbligatoria"], explain: "« Serve una prenotazione obbligatoria, come per i musei »."),
                            Exercise(id: "it-listen-dibattito-turismo-q2", kind: "written", prompt: "Quanti residenti restano in centro, secondo Elena?", options: [], answers: ["meno di cinquantamila", "cinquantamila", "meno di 50000"], explain: "« I residenti sono meno di cinquantamila »."),
                            Exercise(id: "it-listen-dibattito-turismo-q3", kind: "choice", prompt: "Secondo Paolo, qual è il vero problema?", options: ["I case vacanza", "I souvenir", "I musei", "I residenti"], answers: ["I case vacanza"], explain: "« Il problema non sono i turisti, ma i case vacanza »."),
                            Exercise(id: "it-listen-dibattito-turismo-q4", kind: "choice", prompt: "Che relazione c'è tra i due ospiti?", options: ["Posizioni diverse, ma ragionano sui numeri", "Sono completamente d'accordo", "Non si parlano", "Elena difende gli albergatori"], answers: ["Posizioni diverse, ma ragionano sui numeri"], explain: "Elena concede un punto (« Limitarle è giusto, ma da sole non bastano ») e poi torna al suo limite d'ingresso."),
                            Exercise(id: "it-listen-dibattito-turismo-q5", kind: "written", prompt: "Che cosa diventerà il centro nel 2030, secondo Elena, senza limiti?", options: [], answers: ["un parco a tema", "parco a tema", "il centro è un parco a tema"], explain: "« Senza un limite d'ingresso, nel 2030 il centro è un parco a tema ».")], skills: ["listening:inference", "listening:gist", "function:express-opinion", "speaking:justify-opinion"]),
    ListeningText(id: "it-listen-podcast-social", languageID: "it", title: "Podcast: social a tavola", level: "B2", topic: "social", unitID: "it-foundations-u8",
        text: "Bentornati a « Controcorrente ». Oggi la domanda è semplice: il telefono a tavola, colpa nostra o abitudine del secolo? Io dico la mia: a casa mia il telefono resta nel cassetto dell'ingresso. Non per purismo, ma perché i primi venti minuti di cena senza schermi sono i più interessanti: è lì che i figli raccontano davvero la giornata. Mi rispondo da solo: « Ma il gruppo di lavoro? ». No, grazie: il mondo può aspettare quaranta minuti. E se proprio serve, c'è la lavagna della cucina per gli appunti. Non è nostalgia: è una scelta. L'abitudine non si combatte con i sermoni, si combatte con alternative. Provateci una sera e scriveteci: la casella degli ascoltatori è aperta.",
        questions: [
                            Exercise(id: "it-listen-podcast-social-q1", kind: "choice", prompt: "Dove resta il telefono nell'opinione del conduttore?", options: ["Nel cassetto dell'ingresso", "Sul tavolo", "In tasca", "In cucina"], answers: ["Nel cassetto dell'ingresso"], explain: "« A casa mia il telefono resta nel cassetto dell'ingresso »."),
                            Exercise(id: "it-listen-podcast-social-q2", kind: "written", prompt: "Perché i primi venti minuti senza schermi sono importanti?", options: [], answers: ["perché i figli raccontano davvero la giornata", "i figli raccontano davvero la giornata", "li figli raccontano la giornata"], explain: "« È lì che i figli raccontano davvero la giornata »."),
                            Exercise(id: "it-listen-podcast-social-q3", kind: "choice", prompt: "Come risponde all'obiezione del gruppo di lavoro?", options: ["Il mondo può aspettare", "Serve subito", "Solo per emergenze", "Non ne parla"], answers: ["Il mondo può aspettare"], explain: "« No, grazie: il mondo può aspettare quaranta minuti »."),
                            Exercise(id: "it-listen-podcast-social-q4", kind: "choice", prompt: "Come si combatte l'abitudine, per lui?", options: ["Con alternative, non con sermoni", "Con i sermoni", "Vietando i telefoni a scuola", "Spegnendo il wifi"], answers: ["Con alternative, non con sermoni"], explain: "« L'abitudine non si combatte con i sermoni, si combatte con alternative »."),
                            Exercise(id: "it-listen-podcast-social-q5", kind: "written", prompt: "Che cosa chiede ai suoi ascoltatori?", options: [], answers: ["di provare una sera e scrivere", "provare una sera", "che provino una sera"], explain: "« Provateci una sera e scriveteci ».")], skills: ["listening:inference", "function:express-opinion", "speaking:justify-opinion", "listening:connected-speech"]),
    ListeningText(id: "it-listen-notizia-caldo", languageID: "it", title: "Il notiziario: ondata di caldo", level: "B2", topic: "attualità", unitID: "it-foundations-u8",
        text: "Alle ore tredici il termometro ha segnato trentanove gradi all'ombra, un record per il mese. La protezione civile ha attivato il livello massimo di allerta fino a giovedì. Il sindaco ha annunciato che le fontane storiche resteranno aperte anche di notte e che i parchi municipali prolungano l'orario fino alle ventitre. I servizi sociali distribuiranno bottiglie d'acqua nei quartieri con più anziani soli, e i volontari dell'associazione di quartiere faranno i giri porta a porta. Le scuole mantengono gli orari mattutini, mentre i cantieri stradali fermeranno i lavori nelle ore centrali. Si prevede l'arrivo di perturbazioni atlantiche per il weekend, con temporali e un calo di dieci gradi. Aggiornamenti ogni mezz'ora sulle nostre pagine.",
        questions: [
                            Exercise(id: "it-listen-notizia-caldo-q1", kind: "written", prompt: "Quanti gradi ha segnato il termometro all'ombra?", options: [], answers: ["trentanove", "39 gradi", "trentanove gradi"], explain: "« Il termometro ha segnato trentanove gradi all'ombra »."),
                            Exercise(id: "it-listen-notizia-caldo-q2", kind: "choice", prompt: "Fino a quando dura l'allerta?", options: ["Fino a giovedì", "Fino a venerdì", "Fino al weekend", "Fino a mezzanotte"], answers: ["Fino a giovedì"], explain: "« Ha attivato il livello massimo di allerta fino a giovedì »."),
                            Exercise(id: "it-listen-notizia-caldo-q3", kind: "choice", prompt: "Che cosa faranno i volontari nei quartieri?", options: ["I giri porta a porta", "Le docce pubbliche", "I cantieri nuovi", "Le scuole aperte"], answers: ["I giri porta a porta"], explain: "« I volontari… faranno i giri porta a porta »."),
                            Exercise(id: "it-listen-notizia-caldo-q4", kind: "written", prompt: "Fino a che ora restano aperti i parchi municipali?", options: [], answers: ["fino alle ventitre", "alle ventitre", "ventitre", "fino alle 23"], explain: "« I parchi municipali prolungano l'orario fino alle ventitre »."),
                            Exercise(id: "it-listen-notizia-caldo-q5", kind: "choice", prompt: "Che cosa prevedono per il weekend?", options: ["Temporali e un calo di dieci gradi", "Ancora più caldo", "Pioggia leggera e vento", "Sereno e afa"], answers: ["Temporali e un calo di dieci gradi"], explain: "« Con temporali e un calo di dieci gradi ».")], skills: ["listening:detail", "listening:number-time", "listening:gist", "vocab:weather"]),
    ListeningText(id: "it-listen-tavola-rotonda-auto", languageID: "it", title: "Tavola rotonda: auto in centro", level: "B2", topic: "città", unitID: "it-foundations-u7",
        text: "Tavola rotonda al circolo culturale: le auto possono restare in centro? La moderatrice dà la parola a Nadia, negoziante in piazza: « Io devo caricare la merce alle sei del mattino: se vietate le auto, vietate il mio negozio. Con una deroga per il carico, sono d'accordo ». Poi è il turno di Samuele, studente: « Prendere la macchina per andare all'università è un'abitudine, non una necessità: il tram ci mette lo stesso tempo. Servono piste ciclabili continue, non più parcheggi ». La moderatrice cita il dato del consiglio: il trenta per cento dei viaggi in centro è sotto i due chilometri. Nadia conclude: « Allora partiamo da lì: meno tragitti corti in auto, e il traffico si dimezza senza vietare niente a nessuno ».",
        questions: [
                            Exercise(id: "it-listen-tavola-rotonda-auto-q1", kind: "choice", prompt: "Che problema ha Nadia con un divieto totale?", options: ["Deve caricare la merce al mattino", "Non ha un'auto", "Abita fuori centro", "Ha parcheggi a pagamento"], answers: ["Deve caricare la merce al mattino"], explain: "« Io devo caricare la merce alle sei del mattino »."),
                            Exercise(id: "it-listen-tavola-rotonda-auto-q2", kind: "written", prompt: "A che ora carica la merce Nadia?", options: [], answers: ["alle sei", "sei", "le sei"], explain: "« Devo caricare la merce alle sei del mattino »."),
                            Exercise(id: "it-listen-tavola-rotonda-auto-q3", kind: "choice", prompt: "Che cosa propone Samuele invece dei parcheggi?", options: ["Piste ciclabili continue", "Più strade", "Nuovi ponti", "Zone blu gratuite"], answers: ["Piste ciclabili continue"], explain: "« Servono piste ciclabili continue, non più parcheggi »."),
                            Exercise(id: "it-listen-tavola-rotonda-auto-q4", kind: "written", prompt: "Quanti viaggi in centro sono sotto i due chilometri?", options: [], answers: ["il trenta per cento", "trenta per cento", "il 30 per cento", "30 per cento"], explain: "« Il trenta per cento dei viaggi in centro è sotto i due chilometri »."),
                            Exercise(id: "it-listen-tavola-rotonda-auto-q5", kind: "choice", prompt: "Che soluzione finale emerge dal dibattito?", options: ["Ridurre i tragitti corti in auto", "Vietare tutte le auto", "Costruire parcheggi sotterranei", "Togliere il tram"], answers: ["Ridurre i tragitti corti in auto"], explain: "« Meno tragitti corti in auto, e il traffico si dimezza senza vietare niente ».")], skills: ["listening:inference", "listening:detail", "function:express-opinion", "speaking:justify-opinion"]),
    ListeningText(id: "pt-listen-cafe-morning", languageID: "pt", title: "Um café antes do trabalho", level: "A1", topic: "rotina", unitID: "pt-foundations-u1",
        text: "Todas as manhãs, Marta caminha até uma cafeteria pequena perto do apartamento dela. O garçom sabe o nome dela, então ela nunca precisa pedir. Hoje ela senta perto da janela com um café e um pão de queijo. O ônibus dela sai às oito e meia, mas ela não está preocupada. A cafeteria é muito tranquila nessa hora. Ela bebe o café devagar e vê a cidade acordar.",
        questions: [
                            Exercise(id: "pt-listen-cafe-morning-q1", kind: "choice", prompt: "Para onde a Marta vai todas as manhãs?", options: ["Para uma cafeteria pequena", "Para o escritório dela", "Para o ponto de ônibus", "Para um parque"], answers: ["Para uma cafeteria pequena"], explain: "Ela caminha até uma cafeteria pequena perto do apartamento dela."),
                            Exercise(id: "pt-listen-cafe-morning-q2", kind: "choice", prompt: "O que ela toma no café da manhã hoje?", options: ["Um café e um pão de queijo", "Chá e torradas", "Suco de laranja", "Nada"], answers: ["Um café e um pão de queijo"], explain: "Ela senta perto da janela com um café e um pão de queijo."),
                            Exercise(id: "pt-listen-cafe-morning-q3", kind: "written", prompt: "A que horas sai o ônibus dela?", options: [], answers: ["às oito e meia", "oito e meia"], explain: "O ônibus dela sai às oito e meia."),
                            Exercise(id: "pt-listen-cafe-morning-q4", kind: "choice", prompt: "Como ela se sente com o horário?", options: ["Não está preocupada", "Está muito atrasada", "Está com raiva", "Está com sono"], answers: ["Não está preocupada"], explain: "O texto diz que ela não está preocupada."),
                            Exercise(id: "pt-listen-cafe-morning-q5", kind: "choice", prompt: "Quem sabe o nome dela?", options: ["O garçom", "O motorista do ônibus", "O chefe dela", "Um vizinho"], answers: ["O garçom"], explain: "O garçom sabe o nome dela, então ela nunca precisa pedir."),
                            Exercise(id: "pt-listen-cafe-morning-q6", kind: "written", prompt: "Onde ela senta hoje?", options: [], answers: ["perto da janela", "ao lado da janela", "na janela"], explain: "Hoje ela senta perto da janela.")], skills: ["listening:detail", "listening:number-time", "grammar:present-simple", "vocab:daily-routine"]),
    ListeningText(id: "pt-listen-language-class", languageID: "pt", title: "A aula de idiomas", level: "A1", topic: "apresentações", unitID: "pt-foundations-u1",
        text: "Marta participa da primeira aula de português para estrangeiros em um instituto pequeno. Na turma há seis pessoas e todas querem conversar. A professora pede as apresentações. “Meu nome é Marta e sou da Bolívia”, diz uma senhora. “Eu sou o Andrés, sou do Peru e trabalho em um restaurante”, diz um rapaz. Marta também se apresenta: “Sou a Marta, sou argentina e sou enfermeira”. A professora é de Madri e ensina com muito bom humor. No final da aula, os alunos trocam os números de telefone. Ainda não são amigos, mas na próxima semana vão tomar um café juntos e praticar.",
        questions: [
                            Exercise(id: "pt-listen-language-class-q1", kind: "choice", prompt: "Quantas pessoas há na turma?", options: ["Seis", "Três", "Dez", "Quatorze"], answers: ["Seis"], explain: "Na turma há seis pessoas."),
                            Exercise(id: "pt-listen-language-class-q2", kind: "choice", prompt: "De onde é o Andrés?", options: ["Do Peru", "Da Bolívia", "Da Argentina", "Do México"], answers: ["Do Peru"], explain: "O Andrés é do Peru e trabalha em um restaurante."),
                            Exercise(id: "pt-listen-language-class-q3", kind: "choice", prompt: "Qual é o trabalho da Marta?", options: ["Enfermeira", "Professora", "Garçonete", "Estudante"], answers: ["Enfermeira"], explain: "A Marta é argentina e é enfermeira."),
                            Exercise(id: "pt-listen-language-class-q4", kind: "written", prompt: "De onde é a professora?", options: [], answers: ["madril", "de madri", "madri", "madrid", "de madrid"], explain: "A professora é de Madri."),
                            Exercise(id: "pt-listen-language-class-q5", kind: "choice", prompt: "O que eles fazem no final da aula?", options: ["Trocam os números de telefone", "Voltam para casa sozinhos", "Fazem uma prova", "Jantam em um restaurante"], answers: ["Trocam os números de telefone"], explain: "Os alunos trocam os números de telefone."),
                            Exercise(id: "pt-listen-language-class-q6", kind: "written", prompt: "O que eles vão fazer na próxima semana?", options: [], answers: ["tomar um café", "vão tomar um café", "tomar um café juntos"], explain: "Na próxima semana vão tomar um café juntos e praticar.")], skills: ["listening:gist", "grammar:verb-be", "vocab:introductions", "function:introduce-yourself"]),
    ListeningText(id: "pt-listen-little-sister", languageID: "pt", title: "Minha irmã mais nova", level: "A1", topic: "família", unitID: "pt-foundations-u1",
        text: "Minha irmã mais nova se chama Carla e tem nove anos. É muito simpática e muito falante. Carla não é tímida: fala com todo mundo, com os vizinhos, com os professores e com os cachorros do parque. É loira, como a nossa mãe, e tem olhos castanhos como o meu pai. Não é alta para a idade dela, mas é muito rápida e adora futebol. O time dela não é muito bom, mas isso não é importante para ela. “Não sou profissional”, diz ela, “só sou feliz com a bola”. Minha irmã é pequena, mas a alegria dela é enorme.",
        questions: [
                            Exercise(id: "pt-listen-little-sister-q1", kind: "choice", prompt: "Quantos anos a Carla tem?", options: ["Nove", "Dezenove", "Sete", "Dez"], answers: ["Nove"], explain: "A Carla tem nove anos."),
                            Exercise(id: "pt-listen-little-sister-q2", kind: "choice", prompt: "Como é a Carla?", options: ["Simpática e falante", "Tímida e calada", "Séria", "Triste"], answers: ["Simpática e falante"], explain: "É muito simpática e muito falante."),
                            Exercise(id: "pt-listen-little-sister-q3", kind: "written", prompt: "De que cor são os olhos dela?", options: [], answers: ["castanhos", "olhos castanhos", "castanhos como o pai dela"], explain: "Ela tem olhos castanhos como o pai dela."),
                            Exercise(id: "pt-listen-little-sister-q4", kind: "choice", prompt: "Como é o cabelo dela?", options: ["Loiro, como o da mãe", "Escuro, como o do pai", "Ruivo", "Curto e preto"], answers: ["Loiro, como o da mãe"], explain: "É loira, como a nossa mãe."),
                            Exercise(id: "pt-listen-little-sister-q5", kind: "choice", prompt: "O que ela adora?", options: ["Futebol", "Natação", "Música", "Videogame"], answers: ["Futebol"], explain: "É muito rápida e adora futebol."),
                            Exercise(id: "pt-listen-little-sister-q6", kind: "written", prompt: "Como é a alegria dela?", options: [], answers: ["enorme", "muito grande", "grande"], explain: "A alegria dela é enorme.")], skills: ["listening:detail", "grammar:verb-be", "grammar:possessives", "vocab:family"]),
    ListeningText(id: "pt-listen-new-flatmate", languageID: "pt", title: "Um novo colega de apartamento", level: "A1", topic: "casa", unitID: "pt-foundations-u1",
        text: "Tom tem um colega de apartamento novo. O nome dele é Leo e ele tem vinte e três anos. Leo vem de uma cidade pequena do interior, mas agora trabalha na capital. Ele tem duas caixas, um violão e uma bicicleta. O apartamento tem dois quartos e uma cozinha clara. Tom espera que Leo goste de cozinhar, porque o Tom não gosta nem um pouco.",
        questions: [
                            Exercise(id: "pt-listen-new-flatmate-q1", kind: "choice", prompt: "Quantos anos o Leo tem?", options: ["Vinte e três", "Trinta e dois", "Vinte", "Trinta"], answers: ["Vinte e três"], explain: "O Leo tem vinte e três anos."),
                            Exercise(id: "pt-listen-new-flatmate-q2", kind: "choice", prompt: "O que o Leo NÃO tem?", options: ["Uma televisão", "Duas caixas", "Um violão", "Uma bicicleta"], answers: ["Uma televisão"], explain: "Ele tem duas caixas, um violão e uma bicicleta — sem televisão."),
                            Exercise(id: "pt-listen-new-flatmate-q3", kind: "written", prompt: "O que o Tom odeia fazer?", options: [], answers: ["cozinhar", "ele odeia cozinhar", "tom odeia cozinhar"], explain: "O Tom não gosta nem um pouco de cozinhar."),
                            Exercise(id: "pt-listen-new-flatmate-q4", kind: "choice", prompt: "Como é o apartamento?", options: ["Dois quartos e uma cozinha clara", "Um quarto e uma varanda", "Um jardim", "Dois banheiros"], answers: ["Dois quartos e uma cozinha clara"], explain: "O apartamento tem dois quartos e uma cozinha clara."),
                            Exercise(id: "pt-listen-new-flatmate-q5", kind: "choice", prompt: "Onde o Leo trabalha agora?", options: ["Na capital", "Em uma cidade pequena", "No interior", "Ele não trabalha"], answers: ["Na capital"], explain: "Ele vem de uma cidade pequena do interior, mas agora trabalha na capital."),
                            Exercise(id: "pt-listen-new-flatmate-q6", kind: "written", prompt: "Que instrumento o Leo tem?", options: [], answers: ["um violão", "o violão", "violão"], explain: "O Leo tem um violão.")], skills: ["listening:gist", "listening:detail", "grammar:have-got", "vocab:home"]),
    ListeningText(id: "pt-listen-new-neighbour", languageID: "pt", title: "A nova vizinha", level: "A1", topic: "pessoas", unitID: "pt-foundations-u1",
        text: "No prédio há uma vizinha nova. Ela se chama Amélie e é da França. Não é estudante; é fotógrafa. Não trabalha em um escritório: trabalha em casa e viaja muito. Os vizinhos são curiosos, mas também são tímidos, por isso não falam com ela. Então, uma manhã, Ben a encontra na porta. “Você é a vizinha nova?”, pergunta ele. “Sim, sou eu”, responde ela, “e estou contente de estar aqui”. Agora são amigos, e ela não está mais sozinha no prédio.",
        questions: [
                            Exercise(id: "pt-listen-new-neighbour-q1", kind: "choice", prompt: "De onde é a Amélie?", options: ["Da França", "Da Itália", "Do Japão", "Do Brasil"], answers: ["Da França"], explain: "A Amélie é da França."),
                            Exercise(id: "pt-listen-new-neighbour-q2", kind: "choice", prompt: "Qual é o trabalho dela?", options: ["É fotógrafa", "É estudante", "Trabalha em um escritório", "É professora"], answers: ["É fotógrafa"], explain: "Não é estudante; é fotógrafa."),
                            Exercise(id: "pt-listen-new-neighbour-q3", kind: "choice", prompt: "Ela trabalha em um escritório?", options: ["Não, trabalha em casa", "Sim, todos os dias", "Só no verão", "Ela não diz"], answers: ["Não, trabalha em casa"], explain: "Não trabalha em um escritório: trabalha em casa."),
                            Exercise(id: "pt-listen-new-neighbour-q4", kind: "written", prompt: "Por que os vizinhos não falam com ela?", options: [], answers: ["são tímidos", "porque são tímidos", "tímidos"], explain: "São curiosos, mas também são tímidos."),
                            Exercise(id: "pt-listen-new-neighbour-q5", kind: "choice", prompt: "Onde o Ben a encontra?", options: ["Na porta", "No elevador", "Na rua", "No café"], answers: ["Na porta"], explain: "Uma manhã, o Ben a encontra na porta."),
                            Exercise(id: "pt-listen-new-neighbour-q6", kind: "written", prompt: "Como a Amélie se sente no final?", options: [], answers: ["contente", "feliz", "está contente"], explain: "Ela diz que está contente de estar aqui.")], skills: ["listening:gist", "listening:detail", "function:describe-people"]),
    ListeningText(id: "pt-listen-sunday-market", languageID: "pt", title: "A feira de domingo", level: "A1", topic: "compras", unitID: "pt-foundations-u1",
        text: "Aos domingos tem uma feira na praça do bairro. A Ana e o pai dela vão para lá às nove horas, antes de ficar cheio. Eles compram fruta, pão e flores. A Ana quer morangos, mas o pai dela diz que estão muito caros nesta semana. No final, eles levam para casa um saco grande de laranjas e rosas brancas para a mesa da cozinha.",
        questions: [
                            Exercise(id: "pt-listen-sunday-market-q1", kind: "choice", prompt: "Quando a Ana e o pai dela vão à feira?", options: ["Às nove horas", "Ao meio-dia", "À tarde", "Às seis e meia"], answers: ["Às nove horas"], explain: "Eles vão às nove horas, antes de ficar cheio."),
                            Exercise(id: "pt-listen-sunday-market-q2", kind: "written", prompt: "Por que a Ana não leva os morangos?", options: [], answers: ["estão muito caros", "muito caros", "porque estão muito caros"], explain: "O pai diz que estão muito caros nesta semana."),
                            Exercise(id: "pt-listen-sunday-market-q3", kind: "choice", prompt: "O que eles levam para casa?", options: ["Laranjas e rosas", "Morangos e pão", "Maçãs e tulipas", "Pão e queijo"], answers: ["Laranjas e rosas"], explain: "Eles levam laranjas e rosas brancas."),
                            Exercise(id: "pt-listen-sunday-market-q4", kind: "choice", prompt: "Onde fica a feira?", options: ["Na praça do bairro", "Perto do rio", "Na estação", "Num supermercado"], answers: ["Na praça do bairro"], explain: "Aos domingos tem uma feira na praça do bairro."),
                            Exercise(id: "pt-listen-sunday-market-q5", kind: "choice", prompt: "O que eles compram?", options: ["Fruta, pão e flores", "Peixe e legumes", "Queijo e carne", "Somente flores"], answers: ["Fruta, pão e flores"], explain: "Eles compram fruta, pão e flores."),
                            Exercise(id: "pt-listen-sunday-market-q6", kind: "written", prompt: "O que a Ana quer?", options: [], answers: ["morangos", "quer morangos"], explain: "A Ana quer morangos.")], skills: ["listening:gist", "listening:number-time", "grammar:some-any", "vocab:shopping"]),
    ListeningText(id: "pt-listen-apartamento-escolhido", languageID: "pt", title: "O apartamento escolhido", level: "A2", topic: "apartamentos", unitID: "pt-foundations-u4",
        text: "Bia e Rafa procuram apartamento no aplicativo. O primeiro é mais barato, mas fica mais longe da estação: quarenta minutos a pé. O segundo custa cem reais a mais por mês, mas é mais claro e tem varanda. Para a Bia, a luz é o mais importante, porque ela trabalha de casa. No final, decidem pedir uma visita ao segundo: é mais caro, mas é o melhor dos dois para eles.",
        questions: [
                            Exercise(id: "pt-listen-apartamento-escolhido-q1", kind: "choice", prompt: "Quantos apartamentos eles comparam ?", options: ["Dois", "Três", "Quatro"], answers: ["Dois"], explain: "Comparam dois apartamentos no aplicativo."),
                            Exercise(id: "pt-listen-apartamento-escolhido-q2", kind: "choice", prompt: "Qual é o problema do mais barato ?", options: ["Fica longe da estação", "Não tem varanda", "É muito caro", "É pequeno"], answers: ["Fica longe da estação"], explain: "Quarenta minutos a pé da estação."),
                            Exercise(id: "pt-listen-apartamento-escolhido-q3", kind: "written", prompt: "Quanto custa a mais o segundo por mês ?", options: [], answers: ["cem reais", "100 reais"], explain: "Cem reais a mais por mês."),
                            Exercise(id: "pt-listen-apartamento-escolhido-q4", kind: "choice", prompt: "O que é mais importante para a Bia ?", options: ["A luz", "O preço", "A varanda", "A cozinha"], answers: ["A luz"], explain: "Ela trabalha de casa."),
                            Exercise(id: "pt-listen-apartamento-escolhido-q5", kind: "choice", prompt: "O que eles decidem no final ?", options: ["Pedir visita ao segundo", "Ficar com o primeiro", "Continuar procurando", "Pedir desconto"], answers: ["Pedir visita ao segundo"], explain: "É o melhor dos dois para eles.")], skills: ["listening:gist", "listening:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ListeningText(id: "pt-listen-sabado-organizado", languageID: "pt", title: "O sábado organizado", level: "A2", topic: "planos", unitID: "pt-foundations-u4",
        text: "Lu liga para o irmão para organizar o sábado. Ele sugere a montanha, mas vai chover, então Lu propõe o museu novo. Vão se encontrar às dez na entrada principal e almoçar na feira ao lado, que é mais barata que os restaurantes do centro. À noite não têm plano: vão decidir lá, quando souberem como vai estar o tempo.",
        questions: [
                            Exercise(id: "pt-listen-sabado-organizado-q1", kind: "choice", prompt: "Quem sugere a montanha ?", options: ["O irmão", "Lu", "A mãe", "Um amigo"], answers: ["O irmão"], explain: "O irmão sugere a montanha."),
                            Exercise(id: "pt-listen-sabado-organizado-q2", kind: "choice", prompt: "Por que não a montanha ?", options: ["Vai chover", "Estão cansados", "O museu é grátis", "A montanha é longe"], answers: ["Vai chover"], explain: "Vai chover, então vão ao museu."),
                            Exercise(id: "pt-listen-sabado-organizado-q3", kind: "written", prompt: "A que horas vão se encontrar ?", options: [], answers: ["as dez", "às dez", "dez horas"], explain: "Às dez na entrada principal."),
                            Exercise(id: "pt-listen-sabado-organizado-q4", kind: "choice", prompt: "Onde vão almoçar ?", options: ["Na feira ao lado", "Num restaurante do centro", "Em casa", "No museu"], answers: ["Na feira ao lado"], explain: "Mais barata que os restaurantes do centro."),
                            Exercise(id: "pt-listen-sabado-organizado-q5", kind: "choice", prompt: "O que vão fazer à noite ?", options: ["Decidir lá", "Ir ao cinema", "Voltar cedo", "Encontrar amigos"], answers: ["Decidir lá"], explain: "Dependendo do tempo.")], skills: ["listening:gist", "listening:detail", "grammar:going-to"], exposureSkills: ["grammar:future-forms"]),
    ListeningText(id: "pt-listen-nunca-fez", languageID: "pt", title: "Coisas que nunca fiz", level: "B1", topic: "viagens", unitID: "pt-foundations-u6",
        text: "Na cozinha de um hostel, três viajantes comparam as vidas. Caio já visitou vinte países, mas nunca aprendeu a nadar: « Eu sei, é ridículo ». Marina já mergulhou duas vezes com tartarugas, mas não tinha saído do Brasil antes desta viagem. E Beatriz, que está na estrada há seis anos, nunca pegou avião: ela atravessa os oceanos de navio e as fronteiras de ônibus. « Nunca ? » pergunta Caio. « Nunca. O medo é mais velho do que eu. » Eles riem das coisas que não fizeram, e Beatriz diz uma frase que fica: « Não precisa ter feito tudo. Basta ainda querer ».",
        questions: [
                            Exercise(id: "pt-listen-nunca-fez-q1", kind: "choice", prompt: "O que Caio nunca fez ?", options: ["Aprender a nadar", "Visitar vinte países", "Atravessar de navio", "Sair do Brasil"], answers: ["Aprender a nadar"], explain: "Já visitou vinte países, mas nunca aprendeu a nadar."),
                            Exercise(id: "pt-listen-nunca-fez-q2", kind: "written", prompt: "Quantas vezes Marina mergulhou ?", options: [], answers: ["duas vezes", "2 vezes", "duas"], explain: "Marina já mergulhou duas vezes com tartarugas."),
                            Exercise(id: "pt-listen-nunca-fez-q3", kind: "choice", prompt: "Como Beatriz atravessa os oceanos ?", options: ["De navio", "De avião", "De ônibus", "A pé"], answers: ["De navio"], explain: "Ela atravessa os oceanos de navio e as fronteiras de ônibus."),
                            Exercise(id: "pt-listen-nunca-fez-q4", kind: "choice", prompt: "O que Beatriz diz sobre o medo ?", options: ["É mais velho do que ela", "É mais jovem", "É ridículo", "Se foi"], answers: ["É mais velho do que ela"], explain: "O medo é mais velho do que eu."),
                            Exercise(id: "pt-listen-nunca-fez-q5", kind: "written", prompt: "O que basta, segundo Beatriz ?", options: [], answers: ["ainda querer", "basta ainda querer"], explain: "Basta ainda querer.")], skills: ["listening:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"], exposureSkills: ["grammar:relative-clauses"]),
    ListeningText(id: "pt-listen-cidade-interior", languageID: "pt", title: "Da cidade para o interior", level: "B1", topic: "mudanças", unitID: "pt-foundations-u6",
        text: "Pedro conta por que saiu de São Paulo. Antes ele morava num apartamento pequeno e trabalhava onze horas por dia: « Eu ganhava bem, mas não tinha vida ». Num inverno ele adoeceu, e aí entendeu que precisava mudar. Agora mora num vilarejo de mil habitantes, trabalha de casa pela manhã e cuida de uma horta à tarde. « Ganho menos, mas sobra tempo. » No começo os pais não entendiam; agora vêm todo mês. « Você se arrepende de algo ? », pergunta a amiga. « De não ter feito isso antes ».",
        questions: [
                            Exercise(id: "pt-listen-cidade-interior-q1", kind: "choice", prompt: "Onde Pedro morava antes ?", options: ["Em São Paulo", "Num vilarejo", "No Rio de Janeiro", "Num hostel"], answers: ["Em São Paulo"], explain: "Pedro conta por que saiu de São Paulo."),
                            Exercise(id: "pt-listen-cidade-interior-q2", kind: "written", prompt: "Quantas horas ele trabalhava por dia ?", options: [], answers: ["onze horas", "11 horas", "onze"], explain: "Trabalhava onze horas por dia."),
                            Exercise(id: "pt-listen-cidade-interior-q3", kind: "choice", prompt: "O que o fez mudar ?", options: ["Ele adoeceu", "Perdeu o emprego", "Ganhou na loteria", "Conheceu alguém"], answers: ["Ele adoeceu"], explain: "Num inverno ele adoeceu, e aí entendeu."),
                            Exercise(id: "pt-listen-cidade-interior-q4", kind: "choice", prompt: "O que ele faz à tarde agora ?", options: ["Cuida de uma horta", "Trabalha mais horas", "Viaja todo mês", "Estuda"], answers: ["Cuida de uma horta"], explain: "Trabalha pela manhã e cuida de uma horta à tarde."),
                            Exercise(id: "pt-listen-cidade-interior-q5", kind: "written", prompt: "De que Pedro se arrepende ?", options: [], answers: ["de nao ter feito isso antes", "de não ter feito isso antes", "nao ter feito antes", "não ter feito antes"], explain: "« De não ter feito isso antes ».")], skills: ["listening:inference", "grammar:used-to", "grammar:connectors", "vocab:social-expressions"]),
    ListeningText(id: "pt-listen-pechincha-mesa", languageID: "pt", title: "A pechincha da mesa", level: "B2", topic: "negociação", unitID: "pt-foundations-u7",
        text: "Num aplicativo de usados, Bia quer uma mesa de madeira por 80 reais. « E se combinarmos em 60 ? », propõe ela. O vendedor recusa: « Só se você levar hoje ». Bia pensa: « Eu lhe daria 65 se incluir a cadeira ». « Impossível », ri ele, « mas eu deixaria a mesa por 70 e a subitaria para você ». Bia não hesita: « Você a subiria sozinho ? ». « Tenho um carrinho », responde. « Fechado », diz ela, e acrescenta: « Se ela for tão bonita quanto na foto, você ganha cinco estrelas ».",
        questions: [
                            Exercise(id: "pt-listen-pechincha-mesa-q1", kind: "choice", prompt: "Quanto o vendedor pede ?", options: ["80 reais", "60 reais", "70 reais", "65 reais"], answers: ["80 reais"], explain: "A mesa custa 80 reais."),
                            Exercise(id: "pt-listen-pechincha-mesa-q2", kind: "written", prompt: "O que Bia propõe primeiro ?", options: [], answers: ["60 reais", "sessenta reais", "combinar em 60"], explain: "« E se combinarmos em 60 ? »."),
                            Exercise(id: "pt-listen-pechincha-mesa-q3", kind: "choice", prompt: "Que condição o vendedor põe ?", options: ["Levar hoje", "Pagar à vista", "Dar cinco estrelas", "Voltar amanhã"], answers: ["Levar hoje"], explain: "« Só se você levar hoje »."),
                            Exercise(id: "pt-listen-pechincha-mesa-q4", kind: "choice", prompt: "O que o vendedor oferece por 70 ?", options: ["Subir a mesa", "Incluir a cadeira", "Baixar para 60", "Emprestar o carrinho"], answers: ["Subir a mesa"], explain: "« Eu a subitaria para você »."),
                            Exercise(id: "pt-listen-pechincha-mesa-q5", kind: "written", prompt: "O que Bia promete se gostar ?", options: [], answers: ["cinco estrelas", "5 estrelas"], explain: "Cinco estrelas.")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "pt-listen-noticia-bairro", languageID: "pt", title: "A notícia do bairro", level: "B2", topic: "notícias", unitID: "pt-foundations-u8",
        text: "Na feira, Camila e Rafael comentam o que se diz. « Dizem que vão peatonalizar a rua principal », conta Camila. « De novo ? », ri Rafael. « A notícia que li diz que começa na primavera ». Segundo a prefeitura, seria só aos sábados, mas os comerciantes, cujo faturamento dependeria do turismo, já se manifestaram. « É verdade que o barulho cairia », admite Rafael, « mas, e o estacionamento ? ». Camila defende a medida: « Por um lado, mais gente caminharia; por outro, os ônibus parariam na porta ». Eles não decidem nada, mas prometem voltar a falar disso quando o plano sair.",
        questions: [
                            Exercise(id: "pt-listen-noticia-bairro-q1", kind: "choice", prompt: "O que dizem da rua principal ?", options: ["Que será peatonalizada", "Que será alargada", "Que será fechada", "Que mudará de nome"], answers: ["Que será peatonalizada"], explain: "« Dizem que vão peatonalizar a rua principal »."),
                            Exercise(id: "pt-listen-noticia-bairro-q2", kind: "written", prompt: "Quando começaria ?", options: [], answers: ["na primavera", "primavera"], explain: "« A notícia que li diz que começa na primavera »."),
                            Exercise(id: "pt-listen-noticia-bairro-q3", kind: "choice", prompt: "O que diz a prefeitura ?", options: ["Só aos sábados", "Todos os dias", "Só no verão", "Nos feriados"], answers: ["Só aos sábados"], explain: "Seria só aos sábados."),
                            Exercise(id: "pt-listen-noticia-bairro-q4", kind: "choice", prompt: "Quem se manifestou ?", options: ["Os comerciantes", "Os moradores", "Os taxistas", "A prefeitura"], answers: ["Os comerciantes"], explain: "Os comerciantes já se manifestaram."),
                            Exercise(id: "pt-listen-noticia-bairro-q5", kind: "written", prompt: "O que Camila e Rafael prometem ?", options: [], answers: ["voltar a falar disso", "falar disso de novo"], explain: "Prometem voltar a falar disso quando o plano sair.")], skills: ["listening:inference", "grammar:relative-clauses", "grammar:passive-intro", "grammar:connectors"]),
    ListeningText(id: "pt-listen-debate-radio", languageID: "pt", title: "Debate no rádio", level: "C1", topic: "debate", unitID: "pt-foundations-u9",
        text: "No debate desta quinta, a economista Helena Vaz defendeu a semana de quatro dias: « A produtividade não cai; ela se redistribui », afirmou, « e as equipes relatam menos afastamentos ». O apresentador contrapôs: « Mas e as pequenas empresas, que já operam no limite ? ». Helena matizou: « De certa forma, o senhor tem razão; por isso defendo um programa piloto, e não uma lei para todos ». O empresário Rui Costa, convidado ao estúdio, resumiu sua posição: « Para começar, preciso de dados do meu setor; para encerrar, digo que apoio a experiência — com exceções ». O mediador fechou o bloco lembrando que o relatório final sai em novembro e que o debate continua na próxima semana, com a participação de sindicalistas.",
        questions: [
                            Exercise(id: "pt-listen-debate-radio-q1", kind: "choice", prompt: "Qual é a proposta central do debate ?", options: ["Semana de quatro dias", "Salário mínimo por hora", "Fim do home office", "Mais horas extras"], answers: ["Semana de quatro dias"], explain: "Helena defende a semana de quatro dias."),
                            Exercise(id: "pt-listen-debate-radio-q2", kind: "written", prompt: "Segundo Helena, o que acontece com a produtividade ?", options: [], answers: ["ela se redistribui", "nao cai ela se redistribui", "se redistribui"], explain: "« A produtividade não cai; ela se redistribui »."),
                            Exercise(id: "pt-listen-debate-radio-q3", kind: "choice", prompt: "O que Helena defende como caminho ?", options: ["Um programa piloto", "Uma lei imediata", "Nenhuma mudança", "Um referendo"], answers: ["Um programa piloto"], explain: "« Defendo um programa piloto, e não uma lei para todos »."),
                            Exercise(id: "pt-listen-debate-radio-q4", kind: "choice", prompt: "O que Rui pede antes de apoiar ?", options: ["Dados do seu setor", "Mais reuniões", "Um aumento", "Novos sócios"], answers: ["Dados do seu setor"], explain: "« Para começar, preciso de dados do meu setor »."),
                            Exercise(id: "pt-listen-debate-radio-q5", kind: "written", prompt: "Quando sai o relatório final ?", options: [], answers: ["em novembro", "novembro"], explain: "O relatório final sai em novembro."),
                            Exercise(id: "pt-listen-debate-radio-q6", kind: "choice", prompt: "Quem participa do debate da próxima semana ?", options: ["Sindicalistas", "A diretoria", "Estudantes", "Ninguém"], answers: ["Sindicalistas"], explain: "« O debate continua na próxima semana, com a participação de sindicalistas ».")], skills: ["listening:inference", "listening:connected-speech", "function:express-opinion", "grammar:connectors"]),
    ListeningText(id: "pt-listen-palestra-chaves", languageID: "pt", title: "Palestra: três chaves", level: "C1", topic: "palestra", unitID: "pt-foundations-u9",
        text: "Na abertura do congresso, a consultora Marta Reis fez uma pergunta ao plenário: « Quantas reuniões vocês suportaram esta semana ? ». Risos. « É disso que quero tratar: da fala que respeita quem ouve ». Ela organizou a palestra em três chaves. « Para começar, anuncie o destino: se o ouvinte não souber aonde você quer chegar, ele viaja com medo. Depois, dê um dado por ponto — números demais enterram a mensagem. E, para encerrar, peça algo concreto: um voto, um prazo, um apoio ». Ao sintetizar, Marta voltou à pergunta inicial: « Resumindo: quem estrutura bem fala menos — e decide mais ». A plateia respondeu de pé, e a fala dela virou referência interna das equipes.",
        questions: [
                            Exercise(id: "pt-listen-palestra-chaves-q1", kind: "choice", prompt: "Como Marta abre a palestra ?", options: ["Com uma pergunta ao plenário", "Com uma estatística", "Com um vídeo", "Com um silêncio"], answers: ["Com uma pergunta ao plenário"], explain: "« Quantas reuniões vocês suportaram esta semana ? »."),
                            Exercise(id: "pt-listen-palestra-chaves-q2", kind: "choice", prompt: "Quantas chaves ela apresenta ?", options: ["Três", "Duas", "Quatro", "Cinco"], answers: ["Três"], explain: "« Ela organizou a palestra em três chaves »."),
                            Exercise(id: "pt-listen-palestra-chaves-q3", kind: "written", prompt: "O que ela recomenda anunciar primeiro ?", options: [], answers: ["o destino", "o destino da fala", "onde a fala quer chegar"], explain: "« Para começar, anuncie o destino »."),
                            Exercise(id: "pt-listen-palestra-chaves-q4", kind: "choice", prompt: "Por que ela evita números demais ?", options: ["Enterram a mensagem", "Faltam dados", "Confundem o orçamento", "Cansam o orador"], answers: ["Enterram a mensagem"], explain: "« Números demais enterram a mensagem »."),
                            Exercise(id: "pt-listen-palestra-chaves-q5", kind: "written", prompt: "O que se deve pedir ao encerrar, segundo Marta ?", options: [], answers: ["algo concreto", "um pedido concreto", "um voto um prazo um apoio"], explain: "« Peça algo concreto: um voto, um prazo, um apoio »."),
                            Exercise(id: "pt-listen-palestra-chaves-q6", kind: "choice", prompt: "Qual é a síntese da palestra ?", options: ["Quem estrutura bem fala menos", "Quem fala mais lidera", "Reuniões devem ser longas", "Dados valem mais que palavras"], answers: ["Quem estrutura bem fala menos"], explain: "« Quem estrutura bem fala menos — e decide mais ».")], skills: ["listening:detail", "listening:gist", "vocab:work"]),
    ListeningText(id: "pt-listen-podcast-matices", languageID: "pt", title: "Podcast: matizando", level: "C1", topic: "podcast", unitID: "pt-foundations-u9",
        text: "No episódio de hoje, Lívia e Tomás discutem o aviso da empresa: três dias presenciais por semana. « Eu vejo com bons olhos », diz Tomás, « o escritório me dá ritmo ». Lívia não concorda de todo: « De certa forma, faz sentido para quem mora perto; no meu caso, eram três horas de metrô por dia ». Tomás reconhece o ponto: « É verdade que o time ficou mais rápido em casa; tiramos conclusões apressadas sobre presença ». « Pois é », resume Lívia, « por assim dizer, virou questão de logística — e de confiança ». Eles fecham o episódio com uma pergunta aos ouvintes: regime fixo ou flexível ? As respostas viram pauta do próximo programa.",
        questions: [
                            Exercise(id: "pt-listen-podcast-matices-q1", kind: "choice", prompt: "Qual é o novo regime da empresa ?", options: ["Três dias presenciais", "Trabalho cem por cento remoto", "Só reuniões online", "Horário livre"], answers: ["Três dias presenciais"], explain: "O aviso manda três dias presenciais por semana."),
                            Exercise(id: "pt-listen-podcast-matices-q2", kind: "choice", prompt: "Como Tomás reage ao aviso ?", options: ["Vê com bons olhos", "Rejeita de pronto", "Pede demissão", "Fica neutro"], answers: ["Vê com bons olhos"], explain: "« Eu vejo com bons olhos »."),
                            Exercise(id: "pt-listen-podcast-matices-q3", kind: "written", prompt: "Qual era o custo do deslocamento de Lívia ?", options: [], answers: ["tres horas de metro por dia", "três horas de metrô por dia", "tres horas de metro"], explain: "« Eram três horas de metrô por dia »."),
                            Exercise(id: "pt-listen-podcast-matices-q4", kind: "choice", prompt: "Que conclusão apressada o time admite ter tirado ?", options: ["Sobre a presença", "Sobre o salário", "Sobre o orçamento", "Sobre o produto"], answers: ["Sobre a presença"], explain: "« Tiramos conclusões apressadas sobre presença »."),
                            Exercise(id: "pt-listen-podcast-matices-q5", kind: "written", prompt: "Como Lívia resume a questão ?", options: [], answers: ["questao de logistica e de confianca", "de logística e de confiança", "logística e confiança"], explain: "« Virou questão de logística — e de confiança »."),
                            Exercise(id: "pt-listen-podcast-matices-q6", kind: "choice", prompt: "O que os ouvintes vão responder ?", options: ["Regime fixo ou flexível", "O próximo convidado", "O nome do podcast", "O dia do encontro"], answers: ["Regime fixo ou flexível"], explain: "A pergunta do fecho: regime fixo ou flexível ?")], skills: ["listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion"]),
    ListeningText(id: "pt-listen-apartamento-novo", languageID: "pt", title: "O apartamento novo da Bia", level: "A1", topic: "casa", unitID: "pt-foundations-u10",
        text: "A Bia muda para um apartamento novo no centro. O apartamento é pequeno, mas é claro. Tem dois quartos, uma cozinha ampla e uma varanda com plantas. Na sala tem um sofá velho da avó dela e uma estante cheia de livros. Os livros ficam em cima da estante e as chaves ficam na gaveta. Não tem garagem, mas tem uma bicicletaria no térreo. O melhor é o bairro: tem padaria, farmácia e uma praça aqui perto.",
        questions: [
                            Exercise(id: "pt-listen-apartamento-novo-q1", kind: "choice", prompt: "Como é o apartamento da Bia?", options: ["Pequeno, mas claro", "Grande e escuro", "Velho e vazio", "Longe do centro"], answers: ["Pequeno, mas claro"], explain: "O texto diz: o apartamento é pequeno, mas é claro."),
                            Exercise(id: "pt-listen-apartamento-novo-q2", kind: "choice", prompt: "O que tem na sala?", options: ["Um sofá e uma estante", "Uma mesa e seis cadeiras", "Uma cama grande", "Uma televisão nova"], answers: ["Um sofá e uma estante"], explain: "Na sala tem um sofá velho da avó dela e uma estante cheia de livros."),
                            Exercise(id: "pt-listen-apartamento-novo-q3", kind: "choice", prompt: "Onde ficam as chaves?", options: ["Na gaveta", "Em cima da estante", "Embaixo da cama", "Na cozinha"], answers: ["Na gaveta"], explain: "As chaves ficam na gaveta."),
                            Exercise(id: "pt-listen-apartamento-novo-q4", kind: "choice", prompt: "O que o apartamento não tem?", options: ["Garagem", "Varanda", "Quartos", "Cozinha"], answers: ["Garagem"], explain: "Não tem garagem, mas tem uma bicicletaria no térreo."),
                            Exercise(id: "pt-listen-apartamento-novo-q5", kind: "written", prompt: "O que tem na varanda?", options: [], answers: ["plantas", "tem plantas", "as plantas"], explain: "Tem dois quartos, uma cozinha ampla e uma varanda com plantas."),
                            Exercise(id: "pt-listen-apartamento-novo-q6", kind: "written", prompt: "O que tem aqui perto no bairro? Dê duas coisas.", options: [], answers: ["padaria e farmácia", "padaria e farmacia", "padaria, farmácia e praça", "padaria, farmacia e praca"], explain: "Tem padaria, farmácia e uma praça aqui perto.")], skills: ["listening:detail", "grammar:there-is-are", "grammar:prepositions-place", "vocab:home"]),
    ListeningText(id: "pt-listen-passeio-bairro", languageID: "pt", title: "Um passeio pelo bairro", level: "A1", topic: "bairro", unitID: "pt-foundations-u11",
        text: "Hoje o Leo quer conhecer o bairro novo. Ele para um vizinho na rua: « Desculpe, tem um mercado aqui perto ? ». O vizinho responde: « Tem, sim. Siga em frente duas quadras e vire à esquerda. O mercado fica na esquina, ao lado da farmácia ». O Leo agradece e caminha. No caminho ele vê uma praça com crianças e um ponto de ônibus. O mercado é pequeno, mas tem de tudo. E é perto: em cinco minutos ele está em casa com as compras.",
        questions: [
                            Exercise(id: "pt-listen-passeio-bairro-q1", kind: "choice", prompt: "O que o Leo quer saber?", options: ["Onde tem um mercado", "Que horas abre a praça", "Onde mora o vizinho", "Como vai ao trabalho"], answers: ["Onde tem um mercado"], explain: "Ele pergunta: tem um mercado aqui perto ?"),
                            Exercise(id: "pt-listen-passeio-bairro-q2", kind: "choice", prompt: "O que o vizinho manda fazer primeiro?", options: ["Siga em frente duas quadras", "Vire à direita", "Pegue um ônibus", "Espere na praça"], answers: ["Siga em frente duas quadras"], explain: "Siga em frente duas quadras e vire à esquerda."),
                            Exercise(id: "pt-listen-passeio-bairro-q3", kind: "choice", prompt: "Onde o mercado fica?", options: ["Na esquina, ao lado da farmácia", "Em frente à praça", "Perto do ponto de ônibus", "Dentro do centro"], answers: ["Na esquina, ao lado da farmácia"], explain: "O mercado fica na esquina, ao lado da farmácia."),
                            Exercise(id: "pt-listen-passeio-bairro-q4", kind: "choice", prompt: "O que o Leo vê no caminho?", options: ["Uma praça com crianças", "Uma escola grande", "Um cinema novo", "Um mercado enorme"], answers: ["Uma praça com crianças"], explain: "No caminho ele vê uma praça com crianças e um ponto de ônibus."),
                            Exercise(id: "pt-listen-passeio-bairro-q5", kind: "written", prompt: "Como é o mercado?", options: [], answers: ["é pequeno", "e pequeno", "pequeno", "pequeno mas tem de tudo"], explain: "O mercado é pequeno, mas tem de tudo."),
                            Exercise(id: "pt-listen-passeio-bairro-q6", kind: "written", prompt: "Em quanto tempo o Leo chega em casa?", options: [], answers: ["em cinco minutos", "cinco minutos", "5 minutos"], explain: "Em cinco minutos ele está em casa com as compras.")], skills: ["listening:gist", "function:ask-for-directions", "vocab:town"]),
    ListeningText(id: "pt-listen-ligacao-avo", languageID: "pt", title: "Uma ligação para a avó", level: "A1", topic: "família", unitID: "pt-foundations-u12",
        text: "Hoje é domingo e a Ana liga para a avó. A avó atende: « Alô ? ». A Ana pergunta: « Está tudo bem ? ». A avó responde: « Está, sim. Moro sozinha, mas nunca fico triste. Às vezes os primos vêm almoçar ». A avó conta a rotina: acorda às seis, caminha no parque e sempre almoça às doze. A Ana diz: « Que bom ! Eu ligo mais tarde para o meu tio ». A avó sorri: « Beijo, minha neta ».",
        questions: [
                            Exercise(id: "pt-listen-ligacao-avo-q1", kind: "choice", prompt: "Quem liga para quem?", options: ["A Ana liga para a avó", "A avó liga para a Ana", "O tio liga para a Ana", "A Ana liga para o tio"], answers: ["A Ana liga para a avó"], explain: "Hoje é domingo e a Ana liga para a avó."),
                            Exercise(id: "pt-listen-ligacao-avo-q2", kind: "choice", prompt: "Com quem a avó mora?", options: ["Sozinha", "Com a neta", "Com o tio", "Com os primos"], answers: ["Sozinha"], explain: "Moro sozinha, mas nunca fico triste."),
                            Exercise(id: "pt-listen-ligacao-avo-q3", kind: "choice", prompt: "O que a avó nunca faz?", options: ["Fica triste", "Caminha no parque", "Almoça às doze", "Acorda às seis"], answers: ["Fica triste"], explain: "Moro sozinha, mas nunca fico triste."),
                            Exercise(id: "pt-listen-ligacao-avo-q4", kind: "choice", prompt: "O que a avó faz às seis?", options: ["Acorda", "Almoça", "Liga", "Vem"], answers: ["Acorda"], explain: "Acorda às seis, caminha no parque e sempre almoça às doze."),
                            Exercise(id: "pt-listen-ligacao-avo-q5", kind: "choice", prompt: "Quem vem almoçar às vezes?", options: ["Os primos", "Os pais", "As amigas", "Os vizinhos"], answers: ["Os primos"], explain: "Às vezes os primos vêm almoçar."),
                            Exercise(id: "pt-listen-ligacao-avo-q6", kind: "written", prompt: "Para quem a Ana liga mais tarde?", options: [], answers: ["para o meu tio", "para o tio", "o tio"], explain: "Eu ligo mais tarde para o meu tio.")], skills: ["listening:gist", "listening:detail", "vocab:family", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ListeningText(id: "pt-listen-fim-de-semana-chuvoso", languageID: "pt", title: "Fim de semana chuvoso", level: "A1", topic: "clima", unitID: "pt-foundations-u13",
        text: "É sábado de manhã e chove. O Leo olha pela janela: « Que tempo faz ? ». A Bia responde: « Está frio e chove muito ». O plano é caminhar no parque, mas com chuva não dá. Então eles ficam em casa: preparam um chocolate quente e assistem a um filme. O Leo diz: « Eu gosto de chuva, mas só às vezes ». Chove sempre na primavera, diz a Bia, e no verão faz calor.",
        questions: [
                            Exercise(id: "pt-listen-fim-de-semana-chuvoso-q1", kind: "choice", prompt: "Como está o tempo no sábado?", options: ["Chove e está frio", "Faz calor", "Neva", "Está ensolarado"], answers: ["Chove e está frio"], explain: "Está frio e chove muito."),
                            Exercise(id: "pt-listen-fim-de-semana-chuvoso-q2", kind: "choice", prompt: "Qual é o plano do grupo?", options: ["Caminhar no parque", "Nadar na praia", "Ir à feira", "Dormir a manhã toda"], answers: ["Caminhar no parque"], explain: "O plano é caminhar no parque, mas com chuva não dá."),
                            Exercise(id: "pt-listen-fim-de-semana-chuvoso-q3", kind: "choice", prompt: "O que eles fazem em casa?", options: ["Tomam chocolate quente e veem um filme", "Jogam futebol", "Ligam para a avó", "Preparam o almoço"], answers: ["Tomam chocolate quente e veem um filme"], explain: "Preparam um chocolate quente e assistem a um filme."),
                            Exercise(id: "pt-listen-fim-de-semana-chuvoso-q4", kind: "choice", prompt: "Quando o Leo gosta de chuva?", options: ["Só às vezes", "Sempre", "Nunca", "Todas as manhãs"], answers: ["Só às vezes"], explain: "Eu gosto de chuva, mas só às vezes."),
                            Exercise(id: "pt-listen-fim-de-semana-chuvoso-q5", kind: "written", prompt: "Quando chove sempre?", options: [], answers: ["na primavera", "primavera"], explain: "Chove sempre na primavera."),
                            Exercise(id: "pt-listen-fim-de-semana-chuvoso-q6", kind: "written", prompt: "Como está o tempo no verão?", options: [], answers: ["faz calor", "no verão faz calor", "no verao faz calor"], explain: "No verão faz calor.")], skills: ["listening:gist", "listening:detail", "vocab:weather", "function:talk-about-weather", "grammar:frequency-adverbs"]),
    ListeningText(id: "pt-listen-metro-perdido", languageID: "pt", title: "O metrô perdido", level: "A1", topic: "transporte", unitID: "pt-foundations-u14",
        text: "Hoje o Leo vai ao centro de metrô. Ele pega o metrô na estação São João. O trem sai às oito e chega às oito e vinte. O Leo quer ir ao museu, mas sai na estação errada. Ele pergunta a uma funcionária: « A que horas vem o próximo trem ? ». A funcionária responde: « O trem sai às oito e meia ». O Leo pega o trem certo e chega ao museu às nove. « Eu sempre viajo de metrô », diz ele.",
        questions: [
                            Exercise(id: "pt-listen-metro-perdido-q1", kind: "choice", prompt: "Como o Leo vai ao centro ?", options: ["De metrô", "De ônibus", "A pé", "De carro"], answers: ["De metrô"], explain: "Hoje o Leo vai ao centro de metrô."),
                            Exercise(id: "pt-listen-metro-perdido-q2", kind: "choice", prompt: "A que horas chega o trem da manhã ?", options: ["Às oito e vinte", "Às oito", "Às oito e meia", "Às nove"], answers: ["Às oito e vinte"], explain: "O trem sai às oito e chega às oito e vinte."),
                            Exercise(id: "pt-listen-metro-perdido-q3", kind: "choice", prompt: "Qual é o problema do Leo ?", options: ["Ele sai na estação errada", "Ele não encontra a estação", "Ele perde a passagem", "Ele esquece o museu"], answers: ["Ele sai na estação errada"], explain: "O Leo quer ir ao museu, mas sai na estação errada."),
                            Exercise(id: "pt-listen-metro-perdido-q4", kind: "choice", prompt: "A que horas sai o próximo trem ?", options: ["Às oito e meia", "Às oito", "Às nove e vinte", "Às nove"], answers: ["Às oito e meia"], explain: "« O trem sai às oito e meia », diz a funcionária."),
                            Exercise(id: "pt-listen-metro-perdido-q5", kind: "choice", prompt: "A que horas o Leo chega ao museu ?", options: ["Às nove", "Às oito e meia", "Às nove e vinte", "Às dez"], answers: ["Às nove"], explain: "O Leo pega o trem certo e chega ao museu às nove."),
                            Exercise(id: "pt-listen-metro-perdido-q6", kind: "written", prompt: "O que o Leo sempre faz ?", options: [], answers: ["viaja de metrô", "viaja de metro", "viajo de metro"], explain: "« Eu sempre viajo de metrô », diz o Leo.")], skills: ["listening:gist", "listening:detail", "vocab:transport", "function:tell-time"]),
    ListeningText(id: "pt-listen-farmacia-sabado", languageID: "pt", title: "Sábado na farmácia", level: "A1", topic: "saúde", unitID: "pt-foundations-u15",
        text: "É sábado de manhã e a Ana não se sente bem. Ela está com dor de cabeça e está com febre. O Leo diz: « Vamos à farmácia ». Na farmácia, a Ana fala com o farmacêutico: « Estou com dor de cabeça ». O farmacêutico dá um remédio: « Você toma um comprimido de manhã e um à noite ». Custa dez reais. A Ana nunca toma remédio, mas hoje é preciso. Ela toma o remédio e dorme um pouco. À tarde, está melhor.",
        questions: [
                            Exercise(id: "pt-listen-farmacia-sabado-q1", kind: "choice", prompt: "Como está a Ana no sábado ?", options: ["Não se sente bem", "Muito feliz", "Com fome", "Muito cansada"], answers: ["Não se sente bem"], explain: "É sábado de manhã e a Ana não se sente bem."),
                            Exercise(id: "pt-listen-farmacia-sabado-q2", kind: "choice", prompt: "Quais são os sintomas da Ana ?", options: ["Dor de cabeça e febre", "Tosse e febre", "Dor de cabeça e tosse", "Febre e dor de barriga"], answers: ["Dor de cabeça e febre"], explain: "Ela está com dor de cabeça e está com febre."),
                            Exercise(id: "pt-listen-farmacia-sabado-q3", kind: "choice", prompt: "Quando a Ana toma o comprimido ?", options: ["De manhã e à noite", "Só de manhã", "Só à noite", "Só à tarde"], answers: ["De manhã e à noite"], explain: "« Você toma um comprimido de manhã e um à noite »."),
                            Exercise(id: "pt-listen-farmacia-sabado-q4", kind: "choice", prompt: "Quanto custa o remédio ?", options: ["Dez reais", "Doze reais", "Três reais", "Treze reais"], answers: ["Dez reais"], explain: "Custa dez reais."),
                            Exercise(id: "pt-listen-farmacia-sabado-q5", kind: "written", prompt: "O que a Ana nunca faz ?", options: [], answers: ["toma remédio", "toma remedio", "nunca toma remedio"], explain: "A Ana nunca toma remédio, mas hoje é preciso."),
                            Exercise(id: "pt-listen-farmacia-sabado-q6", kind: "written", prompt: "Como está a Ana à tarde ?", options: [], answers: ["melhor", "está melhor", "esta melhor"], explain: "À tarde, está melhor.")], skills: ["listening:gist", "listening:detail", "vocab:health", "grammar:frequency-adverbs"]),
    ListeningText(id: "pt-listen-jantar-surpresa", languageID: "pt", title: "O jantar de surpresa", level: "A1", topic: "restaurante", unitID: "pt-foundations-u16",
        text: "É sexta-feira. A Ana e o Leo esperam a Bia num restaurante. É um jantar de surpresa pelo aniversário dela. A Ana pede uma pizza margherita e um suco de laranja. O Leo quer a lasanha e uma água sem gelo. « Mais alguma coisa ? », pergunta o garçom. « Só o pudim, por favor », diz a Ana. A Bia chega às oito e vê as velas na sobremesa. Ela chora de alegria. No fim, o Leo pede a conta e cada um deixa a gorjeta.",
        questions: [
                            Exercise(id: "pt-listen-jantar-surpresa-q1", kind: "choice", prompt: "O que a Ana pede ?", options: ["Uma pizza e um suco", "Uma lasanha e uma água", "Um pudim", "Uma água com gelo"], answers: ["Uma pizza e um suco"], explain: "A Ana pede uma pizza margherita e um suco de laranja."),
                            Exercise(id: "pt-listen-jantar-surpresa-q2", kind: "choice", prompt: "O que o Leo quer ?", options: ["A lasanha", "A pizza", "O pudim", "O suco"], answers: ["A lasanha"], explain: "O Leo quer a lasanha e uma água sem gelo."),
                            Exercise(id: "pt-listen-jantar-surpresa-q3", kind: "written", prompt: "A que horas a Bia chega ?", options: [], answers: ["as oito", "às oito", "oito horas"], explain: "A Bia chega às oito."),
                            Exercise(id: "pt-listen-jantar-surpresa-q4", kind: "choice", prompt: "O que a Bia vê na sobremesa ?", options: ["As velas", "A conta", "O cardápio", "A gorjeta"], answers: ["As velas"], explain: "Vê as velas na sobremesa e chora de alegria."),
                            Exercise(id: "pt-listen-jantar-surpresa-q5", kind: "written", prompt: "O que o Leo pede no fim ?", options: [], answers: ["a conta", "pede a conta", "a conta por favor"], explain: "No fim, o Leo pede a conta."),
                            Exercise(id: "pt-listen-jantar-surpresa-q6", kind: "choice", prompt: "Como é o jantar ?", options: ["De surpresa", "De trabalho", "Com o garçom", "Em casa"], answers: ["De surpresa"], explain: "É um jantar de surpresa pelo aniversário da Bia.")], skills: ["listening:gist", "listening:detail", "vocab:food", "function:order-food"]),
    ListeningText(id: "pt-listen-plano-aniversario", languageID: "pt", title: "O plano de aniversário", level: "A2", topic: "planos", unitID: "pt-foundations-u17",
        text: "A Duda liga para o Téo para combinar a festa de aniversário da Bia, que vai ser no sábado. « Vamos fazer uma surpresa ? », pergunta a Duda. O Téo aceita, mas não pode de manhã, porque vai almoçar com a avó. Então vão se encontrar às três na casa da Duda: ela vai fazer o bolo, e o Téo vai comprar as bebidas e as velas. A Lu vai levar o presente e vai embrulhar com papel colorido. A Bia não pode saber de nada. « Que horas ela chega ? », pergunta o Téo. « Oito, mas vamos estar prontos às sete », responde a Duda.",
        questions: [
                            Exercise(id: "pt-listen-plano-aniversario-q1", kind: "choice", prompt: "Para quem é a festa ?", options: ["Para a Bia", "Para a Duda", "Para a avó", "Para a Lu"], answers: ["Para a Bia"], explain: "A festa de aniversário da Bia."),
                            Exercise(id: "pt-listen-plano-aniversario-q2", kind: "choice", prompt: "Por que o Téo não pode de manhã ?", options: ["Vai almoçar com a avó", "Vai viajar", "Vai trabalhar", "Vai ao médico"], answers: ["Vai almoçar com a avó"], explain: "Não pode de manhã, porque vai almoçar com a avó."),
                            Exercise(id: "pt-listen-plano-aniversario-q3", kind: "written", prompt: "A que horas vão se encontrar ?", options: [], answers: ["as tres", "às três", "tres horas"], explain: "Vão se encontrar às três na casa da Duda."),
                            Exercise(id: "pt-listen-plano-aniversario-q4", kind: "written", prompt: "O que o Téo vai comprar ?", options: [], answers: ["as bebidas e as velas", "bebidas e velas"], explain: "O Téo vai comprar as bebidas e as velas."),
                            Exercise(id: "pt-listen-plano-aniversario-q5", kind: "choice", prompt: "O que a Lu vai fazer com o presente ?", options: ["Vai embrulhar com papel colorido", "Vai comprar outro", "Vai esconder na casa dela", "Vai entregar antes"], answers: ["Vai embrulhar com papel colorido"], explain: "A Lu vai embrulhar o presente com papel colorido."),
                            Exercise(id: "pt-listen-plano-aniversario-q6", kind: "written", prompt: "A que horas a Bia chega ?", options: [], answers: ["as oito", "às oito", "oito"], explain: "« Oito », responde a Duda.")], skills: ["listening:gist", "listening:detail", "grammar:going-to"], exposureSkills: ["vocab:social-expressions"]),
    ListeningText(id: "pt-listen-episodio-verao", languageID: "pt", title: "O episódio do verão", level: "B1", topic: "histórias", unitID: "pt-foundations-u18",
        text: "Deixa eu contar o episódio do verão. Fui passar uma semana na casa da minha tia em Paraty. No segundo dia, resolvi conhecer as praias de barco, mas perdi o último horário. Fiquei na praça, sem plano. De repente, um senhor que vendia coco me chamou: ele tinha um barquinho e ofereceu um passeio. Desconfiei no começo, mas acabei que aceitei. E não é que foi o melhor passeio da viagem ? Ele me levou a uma praia deserta, só com tartarugas e vento. Quando voltei, contei tudo para a minha tia. « Não me diga ! », ela gritou. « Sozinha com um estranho ? Aí eu passei mal ». No fim, demos risada até chorar.",
        questions: [
                            Exercise(id: "pt-listen-episodio-verao-q1", kind: "choice", prompt: "O que aconteceu no segundo dia ?", options: ["Perdeu o último horário do barco", "Choveu o dia todo", "A tia ficou doente", "O barco quebrou"], answers: ["Perdeu o último horário do barco"], explain: "Resolvi conhecer as praias de barco, mas perdi o último horário."),
                            Exercise(id: "pt-listen-episodio-verao-q2", kind: "choice", prompt: "Quem ofereceu o passeio ?", options: ["Um senhor que vendia coco", "A tia dela", "Um guia da praia", "Ninguém"], answers: ["Um senhor que vendia coco"], explain: "Um senhor que vendia coco tinha um barquinho e ofereceu um passeio."),
                            Exercise(id: "pt-listen-episodio-verao-q3", kind: "written", prompt: "Como a narradora reagiu no começo ?", options: [], answers: ["ficou desconfiada", "desconfiou", "desconfiada"], explain: "Desconfiei no começo, mas acabei que aceitei."),
                            Exercise(id: "pt-listen-episodio-verao-q4", kind: "written", prompt: "O que tinha na praia deserta ?", options: [], answers: ["tartarugas e vento", "tartarugas"], explain: "Uma praia deserta, só com tartarugas e vento."),
                            Exercise(id: "pt-listen-episodio-verao-q5", kind: "choice", prompt: "Como a tia reage à história ?", options: ["Se assusta e não acredita", "Diz que já sabia", "Quer ir no barquinho", "Ri na hora"], answers: ["Se assusta e não acredita"], explain: "« Não me diga ! Sozinha com um estranho ? Aí eu passei mal »."),
                            Exercise(id: "pt-listen-episodio-verao-q6", kind: "choice", prompt: "Como a história termina ?", options: ["Rindo até chorar", "Brigando com a tia", "Voltando ao barco", "Ficando na praça"], answers: ["Rindo até chorar"], explain: "No fim, demos risada até chorar.")], skills: ["listening:inference", "listening:detail", "grammar:past-simple-irregular", "grammar:connectors"]),
    ListeningText(id: "pt-listen-debate-jeito", languageID: "pt", title: "Debate: discordar com jeito", level: "C1", topic: "debate", unitID: "pt-foundations-u9",
        text: "No programa de hoje, Helena e Caio debatem a proposta de proibir celulares nas escolas. Helena abre: « Eu vejo com simpatia a medida; a distração custa caro ». Caio não vai por aí: « Entendo o seu ponto, mas proibir não ensina a usar ». Helena concede um terreno: « Até certo ponto; por outro lado, ninguém aprende algoritmo em sala de aula ». Caio pesa: « Por um lado, os dados te dão razão; por outro, proibição vira má fama do colégio ». No fim, não há vencedor: « Concordo em discordar », resume Helena. O mediador agradece e adianta a pauta da próxima semana: tela ou caderno, o que forma melhor leitor ?",
        questions: [
                            Exercise(id: "pt-listen-debate-jeito-q1", kind: "choice", prompt: "Qual é a proposta em debate ?", options: ["Proibir celulares na escola", "Proibir provas", "Aumentar as férias", "Mudar o uniforme"], answers: ["Proibir celulares na escola"], explain: "A proposta em debate: proibir celulares nas escolas."),
                            Exercise(id: "pt-listen-debate-jeito-q2", kind: "choice", prompt: "Como Helena abre o debate ?", options: ["Vê com simpatia a medida", "Rejeita a proposta", "Muda de assunto", "Pede dados"], answers: ["Vê com simpatia a medida"], explain: "« Eu vejo com simpatia a medida »."),
                            Exercise(id: "pt-listen-debate-jeito-q3", kind: "written", prompt: "Qual é o contra-argumento do Caio ?", options: [], answers: ["proibir não ensina a usar", "proibir nao ensina a usar", "proibição não ensina"], explain: "« Entendo o seu ponto, mas proibir não ensina a usar »."),
                            Exercise(id: "pt-listen-debate-jeito-q4", kind: "choice", prompt: "O que Helena concede ao Caio ?", options: ["Até certo ponto ele tem razão", "Que a distração não existe", "Que celulares ensinam tudo", "Que a proposta é perfeita"], answers: ["Até certo ponto ele tem razão"], explain: "« Até certo ponto; por outro lado… »."),
                            Exercise(id: "pt-listen-debate-jeito-q5", kind: "written", prompt: "Como o debate termina ?", options: [], answers: ["concordo em discordar", "sem vencedor", "não há vencedor", "nao ha vencedor"], explain: "« Concordo em discordar »: não há vencedor."),
                            Exercise(id: "pt-listen-debate-jeito-q6", kind: "choice", prompt: "Qual é a pauta da próxima semana ?", options: ["Tela ou caderno", "Salário dos professores", "A reforma da escola", "Notas e exames"], answers: ["Tela ou caderno"], explain: "O mediador adianta: tela ou caderno, o que forma melhor leitor ?")], skills: ["listening:inference", "listening:connected-speech", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "pt-listen-roda-sexta", languageID: "pt", title: "A roda de sexta", level: "A1", topic: "visita", unitID: "pt-foundations-u19",
        text: "É sexta à noite e tem uma roda de conversa na casa da Bia. A Ana chega com uma lembrancinha: « Trago um bolo ». A Bia abre a porta: « Entre, pode deixar o bolo na mesa ». « Posso tirar os sapatos ? — Pode sim », trocam na porta. Na sala, a Bia oferece café: « Aceita um café ? — Aceito, obrigada ! ». No fim, a Ana agradece: « Obrigada por tudo ». « Volte sempre ! », responde a Bia.",
        questions: [
                            Exercise(id: "pt-listen-roda-sexta-q1", kind: "choice", prompt: "Onde é a roda de conversa ?", options: ["Na casa da Bia", "No trabalho", "Num café", "Na rua"], answers: ["Na casa da Bia"], explain: "É sexta à noite e tem uma roda de conversa na casa da Bia."),
                            Exercise(id: "pt-listen-roda-sexta-q2", kind: "choice", prompt: "O que a Ana traz ?", options: ["Um bolo", "Um café", "Um livro", "Doces"], answers: ["Um bolo"], explain: "« Trago um bolo », diz a Ana ao chegar."),
                            Exercise(id: "pt-listen-roda-sexta-q3", kind: "written", prompt: "O que a Ana pede para tirar ?", options: [], answers: ["os sapatos", "sapatos"], explain: "« Posso tirar os sapatos ? — Pode sim »."),
                            Exercise(id: "pt-listen-roda-sexta-q4", kind: "choice", prompt: "A Bia deixa tirar os sapatos ?", options: ["Pode sim", "Não pode", "Talvez", "De jeito nenhum"], answers: ["Pode sim"], explain: "A resposta na porta é « Pode sim »."),
                            Exercise(id: "pt-listen-roda-sexta-q5", kind: "written", prompt: "O que a Bia oferece na sala ?", options: [], answers: ["um café", "um cafe", "café", "cafe"], explain: "Na sala, a Bia oferece café: « Aceita um café ? »."),
                            Exercise(id: "pt-listen-roda-sexta-q6", kind: "choice", prompt: "Como a Bia se despede ?", options: ["Volte sempre !", "Até nunca !", "Feche a porta !", "Sem café !"], answers: ["Volte sempre !"], explain: "A despedida da Bia é « Volte sempre ! ».")], skills: ["listening:gist", "listening:detail", "vocab:social-expressions", "grammar:can"]),
    ListeningText(id: "pt-listen-reclamacao-nota", languageID: "pt", title: "A reclamação na nota", level: "A2", topic: "problemas", unitID: "pt-foundations-u20",
        text: "— Boa tarde ! Em que posso ajudar ? — Boa tarde. Comprei um liquidificador aqui na semana passada, mas ele está com defeito: liga e para na hora. — Sinto muito. Você trouxe a nota fiscal ? — Trouxe, está aqui. — O senhor quer trocar por outro igual ou prefere o dinheiro de volta ? — Prefiro outro igual, o vermelho. — Claro: a compra é recente, ainda tem garantia. — Preciso fazer mais alguma coisa ? — Só assinar aqui na nota. Pronto, está trocado. Obrigado pela paciência !",
        questions: [
                            Exercise(id: "pt-listen-reclamacao-nota-q1", kind: "choice", prompt: "O que o cliente comprou ?", options: ["Um liquidificador", "Um fone", "Uma torneira", "Um ventilador"], answers: ["Um liquidificador"], explain: "Comprei um liquidificador aqui na semana passada."),
                            Exercise(id: "pt-listen-reclamacao-nota-q2", kind: "written", prompt: "Quando ele comprou o produto ?", options: [], answers: ["na semana passada", "semana passada"], explain: "Comprei um liquidificador aqui na semana passada."),
                            Exercise(id: "pt-listen-reclamacao-nota-q3", kind: "choice", prompt: "Qual é o defeito ?", options: ["Liga e para na hora", "Não liga nada", "Faz muito barulho", "Vaza água"], answers: ["Liga e para na hora"], explain: "Ele está com defeito: liga e para na hora."),
                            Exercise(id: "pt-listen-reclamacao-nota-q4", kind: "written", prompt: "O que o cliente trouxe para provar a compra ?", options: [], answers: ["a nota fiscal", "a nota", "nota fiscal"], explain: "Você trouxe a nota fiscal ? — Trouxe, está aqui."),
                            Exercise(id: "pt-listen-reclamacao-nota-q5", kind: "choice", prompt: "O que o cliente prefere como solução ?", options: ["Trocar por outro igual", "O dinheiro de volta", "Consertar em casa", "Esperar o técnico"], answers: ["Trocar por outro igual"], explain: "Prefiro outro igual, o vermelho."),
                            Exercise(id: "pt-listen-reclamacao-nota-q6", kind: "choice", prompt: "O que o cliente faz no fim ?", options: ["Assina a nota", "Volta na sexta", "Chama o técnico", "Pede desconto"], answers: ["Assina a nota"], explain: "Só assinar aqui na nota. Pronto, está trocado.")], skills: ["listening:gist", "listening:detail", "function:solve-problems", "vocab:social-expressions"]),
    ListeningText(id: "pt-listen-entrevista-ensaio", languageID: "pt", title: "O ensaio da entrevista", level: "B1", topic: "trabalho", unitID: "pt-foundations-u21",
        text: "— Ana, vamos ensaiar a entrevista ? Imagina que eu sou o recrutador. — Fechado. — Conte um pouco da sua experiência. — Trabalho com atendimento há cinco anos e já coordenei uma equipe pequena. — E qual é o seu ponto forte ? — Sou organizada e aprendo rápido. Falar em público ainda é difícil, mas estou fazendo um curso. — Por que você quer mudar de empresa ? — Quero novos desafios e eu gostaria de trabalhar com projetos maiores. — E a meta para este ano ? — Até dezembro, quero assumir uma liderança e melhorar os indicadores do time. — Muito bom. Só um conselho: deixe o tema do salário para o final.",
        questions: [
                            Exercise(id: "pt-listen-entrevista-ensaio-q1", kind: "choice", prompt: "Qual é o papel do Leo no ensaio ?", options: ["O recrutador imaginário", "O gerente da loja", "Um colega de trabalho", "O professor de inglês"], answers: ["O recrutador imaginário"], explain: "Imagina que eu sou o recrutador."),
                            Exercise(id: "pt-listen-entrevista-ensaio-q2", kind: "written", prompt: "Há quanto tempo a Ana trabalha com atendimento ?", options: [], answers: ["cinco anos", "há cinco anos", "ha cinco anos", "5 anos"], explain: "Trabalho com atendimento há cinco anos."),
                            Exercise(id: "pt-listen-entrevista-ensaio-q3", kind: "choice", prompt: "Qual é o ponto forte da Ana ?", options: ["É organizada", "Fala bem em público", "Gerencia equipes grandes", "Negocia salários"], answers: ["É organizada"], explain: "Sou organizada e aprendo rápido."),
                            Exercise(id: "pt-listen-entrevista-ensaio-q4", kind: "choice", prompt: "Por que a Ana quer mudar de empresa ?", options: ["Quer novos desafios", "O salário é baixo", "Não gosta do time", "Vai morar fora"], answers: ["Quer novos desafios"], explain: "Quero novos desafios e eu gostaria de trabalhar com projetos maiores."),
                            Exercise(id: "pt-listen-entrevista-ensaio-q5", kind: "written", prompt: "Qual é a meta da Ana até dezembro ?", options: [], answers: ["assumir uma liderança", "assumir uma lideranca", "uma liderança", "uma lideranca"], explain: "Até dezembro, quero assumir uma liderança."),
                            Exercise(id: "pt-listen-entrevista-ensaio-q6", kind: "choice", prompt: "O que o conselho final do Leo sugere ?", options: ["Deixar o salário para o final", "Chegar cedo à entrevista", "Enviar o currículo antes", "Estudar inglês mais"], answers: ["Deixar o salário para o final"], explain: "Só um conselho: deixe o tema do salário para o final.")], skills: ["listening:inference", "listening:detail", "vocab:work", "function:talk-about-work"]),
    ListeningText(id: "pt-listen-tom-podcast", languageID: "pt", title: "Podcast: o tom exato", level: "C1", topic: "tom", unitID: "pt-foundations-u9",
        text: "« Fala, gente ! No podcast de hoje: por que o tom importa mais do que a palavra ? Marina, você revisa texto — abre o jogo. — Abro, sim: ninguém vê, mas todo mundo sente as colocações trocadas. « Tomar uma decisão » flui; « fazer uma decisão » range. — E no e-mail da diretoria ? — Lá cada conector pesa: « no entanto » eleva o registro; « mas » abaixa na hora. Eu, pessoalmente, pondero os prós e os contras antes de escolher o verbo. — Eu já mandei um « te dou um retorno » para a diretoria. — E aí, que sensação ficou ? — Aquela, sabe ? Saudade do tom exato, por assim dizer. — Fecho com chave de ouro: quem domina as colocações domina a conversa. Até a próxima !",
        questions: [
                            Exercise(id: "pt-listen-tom-podcast-q1", kind: "choice", prompt: "Qual é o tema do episódio ?", options: ["O tom e as colocações", "A gramática do subjuntivo", "Como escrever e-mails longos", "O sotaque no trabalho"], answers: ["O tom e as colocações"], explain: "No podcast de hoje: por que o tom importa mais do que a palavra ?"),
                            Exercise(id: "pt-listen-tom-podcast-q2", kind: "choice", prompt: "O que a Marina diz de « fazer uma decisão » ?", options: ["Não flui; o certo é tomar", "É a forma formal", "É uso regional aceito", "É sinônimo exato de tomar"], answers: ["Não flui; o certo é tomar"], explain: "« Tomar uma decisão » flui; « fazer uma decisão » range."),
                            Exercise(id: "pt-listen-tom-podcast-q3", kind: "written", prompt: "Que colocação a Marina usa antes de escolher o verbo ?", options: [], answers: ["pondero os prós e os contras", "pondero os pros e os contras", "os prós e os contras", "os pros e os contras"], explain: "Eu, pessoalmente, pondero os prós e os contras antes de escolher o verbo."),
                            Exercise(id: "pt-listen-tom-podcast-q4", kind: "choice", prompt: "O que « abaixa na hora » sugere sobre o « mas » ?", options: ["Reduz o registro da frase", "Nega a frase anterior", "Acelera a leitura", "Soa antiquado"], answers: ["Reduz o registro da frase"], explain: "« No entanto » eleva o registro; « mas » abaixa na hora: o contraste coloquial."),
                            Exercise(id: "pt-listen-tom-podcast-q5", kind: "choice", prompt: "O que a brincadeira com a « saudade do tom exato » revela ?", options: ["Arrependimento do recado informal", "Orgulho do recado", "Vontade de demitir", "Alívio com o e-mail"], answers: ["Arrependimento do recado informal"], explain: "O « te dou um retorno » ficou informal para a diretoria; a saudade do tom exato mostra arrependimento."),
                            Exercise(id: "pt-listen-tom-podcast-q6", kind: "written", prompt: "Qual fórmula de suavização aparece no episódio ?", options: [], answers: ["por assim dizer", "assim dizer"], explain: "« Saudade do tom exato, por assim dizer »: a fórmula suaviza a afirmação.")], skills: ["listening:inference", "listening:connected-speech", "vocab:collocations", "function:express-opinion"]),
    ListeningText(id: "pt-listen-aniversario-surpresa", languageID: "pt", title: "A festa surpresa", level: "A1", topic: "festa", unitID: "pt-foundations-u22",
        text: "A Duda liga para a Lu: — Alô, Lu ! Vamos fazer uma festa para a Bia no sábado. — Que legal ! Na sua casa ? — Isso, às oito. Que tal um bolo de chocolate ? — Boa ideia ! Eu levo as bebidas e as velas. — Pode contar comigo para a música também. — Fechado. E não conte nada para a Bia, é surpresa !",
        questions: [
                            Exercise(id: "pt-listen-aniversario-surpresa-q1", kind: "choice", prompt: "Quem faz aniversário ?", options: ["A Bia", "A Duda", "A Lu", "A mãe da Lu"], answers: ["A Bia"], explain: "Vamos fazer uma festa para a Bia no sábado."),
                            Exercise(id: "pt-listen-aniversario-surpresa-q2", kind: "choice", prompt: "Que dia e hora é a festa ?", options: ["Sábado, às oito", "Sexta, às oito", "Sábado, às sete", "Domingo, às nove"], answers: ["Sábado, às oito"], explain: "Isso, às oito — a festa é no sábado."),
                            Exercise(id: "pt-listen-aniversario-surpresa-q3", kind: "written", prompt: "O que a Lu leva ?", options: [], answers: ["as bebidas e as velas", "bebidas e velas"], explain: "Eu levo as bebidas e as velas."),
                            Exercise(id: "pt-listen-aniversario-surpresa-q4", kind: "written", prompt: "Que bolo vai ter ?", options: [], answers: ["bolo de chocolate", "um bolo de chocolate", "chocolate"], explain: "Que tal um bolo de chocolate ?"),
                            Exercise(id: "pt-listen-aniversario-surpresa-q5", kind: "choice", prompt: "Por que a Bia não pode saber ?", options: ["É uma surpresa", "É segredo da Lu", "A festa cancelou", "A Bia viaja"], answers: ["É uma surpresa"], explain: "E não conte nada para a Bia, é surpresa !")], skills: ["listening:detail", "vocab:social-expressions", "grammar:present-simple"]),
    ListeningText(id: "pt-listen-provador", languageID: "pt", title: "No provador", level: "A1", topic: "loja", unitID: "pt-foundations-u23",
        text: "Na loja de roupas: — Pois não, posso ajudar ? — Procuro uma camiseta azul. — Que tamanho você usa ? — Eu uso M. — Tem essa aqui em M. — Posso provar ? — Claro, o provador fica ali. — Fica um pouco apertada. Pode trazer um G ? — Um momento, já trago. — Esse fica melhor. Quanto custa ? — Oitenta reais. — Fechado, vou levar.",
        questions: [
                            Exercise(id: "pt-listen-provador-q1", kind: "written", prompt: "O que a cliente procura ?", options: [], answers: ["uma camiseta azul", "camiseta azul"], explain: "Procuro uma camiseta azul."),
                            Exercise(id: "pt-listen-provador-q2", kind: "choice", prompt: "Que tamanho ela usa ?", options: ["M", "P", "G", "GG"], answers: ["M"], explain: "Que tamanho você usa ? — Eu uso M."),
                            Exercise(id: "pt-listen-provador-q3", kind: "choice", prompt: "Por que ela pede outro tamanho ?", options: ["Fica apertada", "Fica barata", "Não gosta da cor", "Está rasgada"], answers: ["Fica apertada"], explain: "Fica um pouco apertada. Pode trazer um G ?"),
                            Exercise(id: "pt-listen-provador-q4", kind: "written", prompt: "Quanto custa a camiseta ?", options: [], answers: ["oitenta reais", "80 reais"], explain: "Oitenta reais."),
                            Exercise(id: "pt-listen-provador-q5", kind: "choice", prompt: "Qual é a decisão final ?", options: ["Ela leva a camiseta", "Ela volta depois", "Ela troca de loja", "Ela pede desconto"], answers: ["Ela leva a camiseta"], explain: "Fechado, vou levar.")], skills: ["listening:detail", "vocab:shopping", "function:go-shopping"]),
    ListeningText(id: "pt-listen-devolucao", languageID: "pt", title: "A troca do celular", level: "A2", topic: "troca", unitID: "pt-foundations-u24",
        text: "No balcão de trocas: — Bom dia ! Em que posso ajudar ? — Comprei esse celular há uma semana e a câmera apresentou defeito. — A senhora trouxe o recibo ? — Sim, aqui está, e a caixa também. — Perfeito. Prefere outro aparelho igual ou o reembolso ? — Quero trocar por outro igual, se possível. — Temos o modelo em estoque; em dez minutos está pronto. — Ótimo. Preciso tirar meus dados do aparelho antigo. — Pode conferir tranquila, a senhora tem tempo.",
        questions: [
                            Exercise(id: "pt-listen-devolucao-q1", kind: "written", prompt: "Quando ela comprou o celular ?", options: [], answers: ["há uma semana", "ha uma semana", "uma semana atrás", "uma semana atras"], explain: "Comprei esse celular há uma semana."),
                            Exercise(id: "pt-listen-devolucao-q2", kind: "written", prompt: "Qual é o problema ?", options: [], answers: ["a câmera", "a camera", "o defeito na câmera", "o defeito na camera"], explain: "A câmera apresentou defeito."),
                            Exercise(id: "pt-listen-devolucao-q3", kind: "choice", prompt: "O que ela mostra no balcão ?", options: ["O recibo e a caixa", "O cartão de crédito", "Só o aparelho antigo", "A garantia do trabalho"], answers: ["O recibo e a caixa"], explain: "Sim, aqui está, e a caixa também."),
                            Exercise(id: "pt-listen-devolucao-q4", kind: "choice", prompt: "O que ela prefere ?", options: ["Trocar por outro igual", "O reembolso do dinheiro", "Um modelo melhor", "Consertar a câmera"], answers: ["Trocar por outro igual"], explain: "Quero trocar por outro igual, se possível."),
                            Exercise(id: "pt-listen-devolucao-q5", kind: "choice", prompt: "Em quanto tempo a troca fica pronta ?", options: ["Dez minutos", "Uma hora", "Dois dias", "Na semana seguinte"], answers: ["Dez minutos"], explain: "Em dez minutos está pronto.")], skills: ["listening:detail", "listening:inference", "vocab:shopping", "function:solve-problems"]),
    ListeningText(id: "pt-listen-vespera-viagem", languageID: "pt", title: "Na véspera da viagem", level: "A2", topic: "viagem", unitID: "pt-foundations-u25",
        text: "Na véspera da viagem: — Amanhã você vai sair cedo, né ? — Isso, o voo é às sete. Vou conferir se está tudo pronto. — Já fez a mala ? — Primeiro a mala, depois os documentos. Não vou esquecer o passaporte nem o carregador. — Confere se falta algo, então. — Confiro, sim. Levo só uma mala de mão. — Boa viagem, Duda ! Me avise quando chegar. — Claro, te aviso no desembarque. Obrigada por tudo !",
        questions: [
                            Exercise(id: "pt-listen-vespera-viagem-q1", kind: "written", prompt: "A que horas é o voo ?", options: [], answers: ["às sete", "as sete", "sete horas"], explain: "Isso, o voo é às sete."),
                            Exercise(id: "pt-listen-vespera-viagem-q2", kind: "choice", prompt: "Qual é a ordem dos preparativos ?", options: ["Mala, depois documentos", "Documentos, depois mala", "Mala e documentos juntos", "Só os documentos"], answers: ["Mala, depois documentos"], explain: "Primeiro a mala, depois os documentos."),
                            Exercise(id: "pt-listen-vespera-viagem-q3", kind: "written", prompt: "O que ela não vai esquecer ?", options: [], answers: ["o passaporte e o carregador", "passaporte e carregador"], explain: "Não vou esquecer o passaporte nem o carregador."),
                            Exercise(id: "pt-listen-vespera-viagem-q4", kind: "choice", prompt: "Quantas malas ela leva ?", options: ["Uma mala de mão", "Duas malas grandes", "Uma mala e uma mochila", "Nenhuma"], answers: ["Uma mala de mão"], explain: "Levo só uma mala de mão."),
                            Exercise(id: "pt-listen-vespera-viagem-q5", kind: "choice", prompt: "O que a Duda promete ?", options: ["Avisar quando chegar", "Voltar cedo", "Enviar fotos do hotel", "Ficar um mês"], answers: ["Avisar quando chegar"], explain: "Claro, te aviso no desembarque.")], skills: ["listening:detail", "vocab:travel", "grammar:going-to"]),
    ListeningText(id: "pt-listen-bairro-sonho", languageID: "pt", title: "O bairro que a gente quer", level: "B1", topic: "bairro", unitID: "pt-foundations-u26",
        text: "Na reunião do bairro, o mediador abre o debate: — Boa noite a todos, vamos começar. O que falta na nossa vizinhança ? — Por um lado, o comércio local está vivo; por outro, faltam lugares de encontro. Na minha opinião, precisamos de uma horta na praça. — Eu acho que a horta é uma boa proposta, mas quem cuida ? — Concordo em parte; por isso sugiro um grupo de moradores por semana. — Além disso, podíamos proibir plástico na feira. — Embora seja difícil no começo, apoiar essas ideias melhora o bairro para todos. — Então está encaminhado: horta, grupo de cuidado e feira sem plástico.",
        questions: [
                            Exercise(id: "pt-listen-bairro-sonho-q1", kind: "choice", prompt: "Qual é o problema que a turma aponta ?", options: ["Faltam lugares de encontro", "O comércio está morto", "A praça é grande demais", "Falta segurança à noite"], answers: ["Faltam lugares de encontro"], explain: "Por um lado, o comércio local está vivo; por outro, faltam lugares de encontro."),
                            Exercise(id: "pt-listen-bairro-sonho-q2", kind: "written", prompt: "O que o primeiro morador propõe ?", options: [], answers: ["uma horta na praça", "uma horta na praca", "uma horta", "horta na praça", "horta na praca"], explain: "Na minha opinião, precisamos de uma horta na praça."),
                            Exercise(id: "pt-listen-bairro-sonho-q3", kind: "choice", prompt: "Qual é a objeção à proposta ?", options: ["Quem cuida da horta", "O preço da praça", "A prefeitura proíbe", "Falta água no bairro"], answers: ["Quem cuida da horta"], explain: "Eu acho que a horta é uma boa proposta, mas quem cuida ?"),
                            Exercise(id: "pt-listen-bairro-sonho-q4", kind: "written", prompt: "Que solução o grupo sugere para o cuidado ?", options: [], answers: ["um grupo de moradores por semana", "grupo de moradores por semana", "um grupo por semana"], explain: "Por isso sugiro um grupo de moradores por semana."),
                            Exercise(id: "pt-listen-bairro-sonho-q5", kind: "choice", prompt: "O que se decide sobre a feira ?", options: ["Proibir o plástico", "Fechar aos domingos", "Aumentar os preços", "Mudar de lugar"], answers: ["Proibir o plástico"], explain: "Além disso, podíamos proibir plástico na feira."),
                            Exercise(id: "pt-listen-bairro-sonho-q6", kind: "choice", prompt: "Como o último morador avalia as ideias ?", options: ["Difíceis, mas melhoram o bairro", "Inúteis para a vizinhança", "Boas só para a prefeitura", "Caras e inviáveis"], answers: ["Difíceis, mas melhoram o bairro"], explain: "Embora seja difícil no começo, apoiar essas ideias melhora o bairro para todos.")], skills: ["listening:inference", "listening:detail", "grammar:connectors", "function:express-opinion"]),
    ListeningText(id: "pt-listen-reuniao-final", languageID: "pt", title: "A reunião de pauta", level: "B1", topic: "reunião", unitID: "pt-work-u1",
        text: "Segunda-feira, reunião de pauta: — Bom dia, equipe. Na minha opinião, o prazo do cliente é curto. — Por um lado, temos gente; por outro, falta tempo de teste. — Eu acho que dá para dividir a tarefa em duas frentes. — Sugiro começar pelo relatório; por isso ele precisa ficar pronto até quinta. — De acordo. Quem assume a parte de dados ? — Eu assumo. O restante fica com o time de produto, então. — Se ninguém se opõe, vamos assim: relatório até quinta e dados com a Ana. Vamos revisar na sexta.",
        questions: [
                            Exercise(id: "pt-listen-reuniao-final-q1", kind: "choice", prompt: "Qual é a preocupação inicial na reunião ?", options: ["O prazo do cliente é curto", "O time falta à reunião", "O cliente cancelou", "O relatório está pronto"], answers: ["O prazo do cliente é curto"], explain: "Na minha opinião, o prazo do cliente é curto."),
                            Exercise(id: "pt-listen-reuniao-final-q2", kind: "choice", prompt: "Como a turma pesa a decisão ?", options: ["Temos gente, mas falta tempo de teste", "Temos tempo, mas falta gente", "Não há prazo nem gente", "O cliente vai esticar o prazo"], answers: ["Temos gente, mas falta tempo de teste"], explain: "Por um lado, temos gente; por outro, falta tempo de teste."),
                            Exercise(id: "pt-listen-reuniao-final-q3", kind: "written", prompt: "O que sugere fazer com a tarefa ?", options: [], answers: ["dividir a tarefa em duas frentes", "dividir a tarefa", "dividir em duas frentes"], explain: "Eu acho que dá para dividir a tarefa em duas frentes."),
                            Exercise(id: "pt-listen-reuniao-final-q4", kind: "written", prompt: "Quando o relatório precisa ficar pronto ?", options: [], answers: ["até quinta", "ate quinta", "até a quinta", "ate a quinta", "quinta"], explain: "Por isso ele precisa ficar pronto até quinta."),
                            Exercise(id: "pt-listen-reuniao-final-q5", kind: "choice", prompt: "Quem assume a parte de dados ?", options: ["A Ana", "O chefe", "O time do cliente", "Ninguém ainda"], answers: ["A Ana"], explain: "Vamos assim: relatório até quinta e dados com a Ana.")], skills: ["listening:inference", "listening:detail", "function:talk-about-work", "grammar:connectors"]),
    ListeningText(id: "pt-listen-email-urgente", languageID: "pt", title: "O e-mail do cliente", level: "B1", topic: "e-mail", unitID: "pt-work-u1",
        text: "No corredor, a Ana para o Téo: — Você já respondeu o e-mail do cliente ? — Ainda não. O que escrevo na abertura ? — Algo como « Prezado Sr. Costa »; em e-mail formal, o objetivo vem na primeira linha. — Tipo « escrevo para confirmar a reunião de quinta » ? — Isso. Se pedir o relatório, use « gostaria de receber até sexta »; prazo no pedido ajuda o cliente a organizar. — E o fecho ? — « Desde já, agradeço » e « Atenciosamente ». Guarde « abraços » para o time interno. — Perfeito, escrevo agora antes da reunião.",
        questions: [
                            Exercise(id: "pt-listen-email-urgente-q1", kind: "choice", prompt: "Quem ainda não respondeu o e-mail ?", options: ["O Téo", "A Ana", "O cliente", "O chefe"], answers: ["O Téo"], explain: "Você já respondeu o e-mail do cliente ? — Ainda não."),
                            Exercise(id: "pt-listen-email-urgente-q2", kind: "written", prompt: "Qual é a saudação sugerida ?", options: [], answers: ["prezado sr costa", "prezado senhor costa", "prezado"], explain: "Algo como « Prezado Sr. Costa »."),
                            Exercise(id: "pt-listen-email-urgente-q3", kind: "choice", prompt: "Onde fica o objetivo do e-mail ?", options: ["Na primeira linha", "No título do arquivo", "No rodapé", "Na assinatura"], answers: ["Na primeira linha"], explain: "Em e-mail formal, o objetivo vem na primeira linha."),
                            Exercise(id: "pt-listen-email-urgente-q4", kind: "written", prompt: "Como pedir o relatório com prazo ?", options: [], answers: ["gostaria de receber até sexta", "gostaria de receber ate sexta"], explain: "Use « gostaria de receber até sexta »; prazo no pedido ajuda."),
                            Exercise(id: "pt-listen-email-urgente-q5", kind: "choice", prompt: "Para quem fica o « abraços » ?", options: ["O time interno", "O cliente novo", "A diretoria", "O recrutador"], answers: ["O time interno"], explain: "Guarde « abraços » para o time interno.")], skills: ["listening:detail", "writing:email", "vocab:work", "function:make-requests"]),
    ListeningText(id: "pt-listen-voo-atrasado", languageID: "pt", title: "O voo mudou", level: "A2", topic: "atraso", unitID: "pt-foundations-u28",
        text: "— Boa noite, senhora. O voo 402 para Salvador mudou. — Mudou ? A que horas sai agora ? — Sai às dez e vinte, duas horas depois do previsto. — Foi porque chove muito, né ? — Isso. Chove forte, por isso os voos atrasam hoje. — E o meu assento, continua igual ? — Continua, senhora. O portão também é o mesmo, o nove. — Ótimo. Então vou esperar aqui perto. — Pode ir tomar um café; eu chamo pelo alto-falante quando o embarque começar. — Obrigada. Uma hora a mais, não tem problema.",
        questions: [
                            Exercise(id: "pt-listen-voo-atrasado-q1", kind: "choice", prompt: "A que horas sai o novo voo ?", options: ["Dez e vinte", "Oito e vinte", "Nove e vinte", "Onze e meia"], answers: ["Dez e vinte"], explain: "« Sai às dez e vinte, duas horas depois do previsto »."),
                            Exercise(id: "pt-listen-voo-atrasado-q2", kind: "written", prompt: "Qual é o motivo do atraso ?", options: [], answers: ["a chuva", "chuva", "chove muito", "chove forte"], explain: "« Chove forte, por isso os voos atrasam hoje »."),
                            Exercise(id: "pt-listen-voo-atrasado-q3", kind: "choice", prompt: "O que acontece com o assento dela ?", options: ["Continua igual", "Muda para a frente", "Vira assento de corredor", "Some do sistema"], answers: ["Continua igual"], explain: "« Continua, senhora »."),
                            Exercise(id: "pt-listen-voo-atrasado-q4", kind: "choice", prompt: "Qual é o portão de embarque ?", options: ["O nove", "O quatro", "O dois", "O dez"], answers: ["O nove"], explain: "« O portão também é o mesmo, o nove »."),
                            Exercise(id: "pt-listen-voo-atrasado-q5", kind: "written", prompt: "O que ela vai fazer enquanto espera ?", options: [], answers: ["tomar um café", "tomar um cafe", "beber um café", "beber um cafe"], explain: "« Pode ir tomar um café; eu chamo pelo alto-falante ».")], skills: ["listening:detail", "listening:inference", "grammar:connectors", "vocab:transport"]),
    ListeningText(id: "pt-listen-mala-extraviada", languageID: "pt", title: "A mala no balcão", level: "A2", topic: "mala", unitID: "pt-foundations-u28",
        text: "— Boa tarde. Em que posso ajudar ? — Minha mala não chegou. Esperei até a esteira parar e nada. — Sinto muito. A senhora vem de qual voo ? — Do voo 118, de Curitiba. — Me descreve a mala, por favor. — É azul, média, de quatro rodas, e tem uma fita amarela na alça. — Perfeito. Vou registrar o pedido e procurar no sistema. — Quanto tempo costuma levar ? — Normalmente um dia. Quando chegar, fazemos a entrega no seu hotel, sem custo. — Está bem. Meu número está no cadastro. — A senhora recebe uma mensagem hoje à noite.",
        questions: [
                            Exercise(id: "pt-listen-mala-extraviada-q1", kind: "written", prompt: "Qual é o problema dela ?", options: [], answers: ["a mala não chegou", "a mala nao chegou", "perdeu a mala", "a mala sumiu"], explain: "« Minha mala não chegou »."),
                            Exercise(id: "pt-listen-mala-extraviada-q2", kind: "choice", prompt: "Como é a mala ?", options: ["Azul, com fita amarela", "Preta, com rodas grandes", "Vermelha e pequena", "Azul e sem rodas"], answers: ["Azul, com fita amarela"], explain: "« É azul… e tem uma fita amarela na alça »."),
                            Exercise(id: "pt-listen-mala-extraviada-q3", kind: "choice", prompt: "Em quanto tempo a mala costuma chegar ?", options: ["Em um dia", "Em uma hora", "Em três dias", "Na próxima semana"], answers: ["Em um dia"], explain: "« Normalmente um dia »."),
                            Exercise(id: "pt-listen-mala-extraviada-q4", kind: "written", prompt: "Onde a mala será entregue ?", options: [], answers: ["no hotel", "no seu hotel", "no hotel dela"], explain: "« Fazemos a entrega no seu hotel »."),
                            Exercise(id: "pt-listen-mala-extraviada-q5", kind: "choice", prompt: "Quanto ela paga pela entrega ?", options: ["Nada, é sem custo", "Metade do valor", "Só a taxa do hotel", "Vinte reais"], answers: ["Nada, é sem custo"], explain: "« A entrega no seu hotel, sem custo ».")], skills: ["listening:detail", "vocab:travel", "function:solve-problems", "grammar:present-questions"]),
    ListeningText(id: "pt-listen-reserva-mudada", languageID: "pt", title: "A reserva nova", level: "A2", topic: "reserva", unitID: "pt-foundations-u28",
        text: "— Hotel Bela Vista, bom dia ! — Bom dia. Queria mudar a minha reserva; está no nome de Téo Prado. — Claro. O senhor quer mudar a data ou o quarto ? — A data: de quarta para sexta, se der. — Deixa eu ver… tem vaga, sim, e não tem custo extra. — Que bom. É um quarto duplo, com café. — Isso, e já tem estacionamento incluído. — Perfeito. Então fica sexta, duas noites. — Confirmado, senhor. Mando a nova confirmação por mensagem. — Obrigado ! Até sexta.",
        questions: [
                            Exercise(id: "pt-listen-reserva-mudada-q1", kind: "written", prompt: "O que o Téo quer mudar ?", options: [], answers: ["a data", "a data da reserva"], explain: "« Queria mudar a minha reserva »… « A data »."),
                            Exercise(id: "pt-listen-reserva-mudada-q2", kind: "choice", prompt: "De que dia para que dia muda a reserva ?", options: ["De quarta para sexta", "De sexta para quarta", "De quinta para sábado", "De sexta para domingo"], answers: ["De quarta para sexta"], explain: "« De quarta para sexta, se der »."),
                            Exercise(id: "pt-listen-reserva-mudada-q3", kind: "choice", prompt: "A mudança tem custo extra ?", options: ["Não, não tem custo", "Sim, cinquenta reais", "Sim, uma diária", "Só o estacionamento"], answers: ["Não, não tem custo"], explain: "« Tem vaga, sim, e não tem custo extra »."),
                            Exercise(id: "pt-listen-reserva-mudada-q4", kind: "choice", prompt: "Que tipo de quarto é a reserva ?", options: ["Quarto duplo, com café", "Quarto single, com varanda", "Suíte, com banheira", "Quarto triplo"], answers: ["Quarto duplo, com café"], explain: "« É um quarto duplo, com café »."),
                            Exercise(id: "pt-listen-reserva-mudada-q5", kind: "written", prompt: "Como o hotel manda a confirmação ?", options: [], answers: ["por mensagem", "mensagem", "por mensagem no celular"], explain: "« Mando a nova confirmação por mensagem ».")], skills: ["listening:detail", "listening:inference", "vocab:travel", "function:make-requests"]),
    ListeningText(id: "pt-listen-fds-praia", languageID: "pt", title: "Praia no fim de semana", level: "A2", topic: "planos", unitID: "pt-foundations-u17",
        text: "— Gente, o que vamos fazer no fim de semana ? — Vou levar todo mundo para a praia, na minha casa de Guaratuba. — Sério ? E como vamos chegar ? — De carro; saio sábado de manhã cedo, às sete. — Eu levo o guarda-sol e as cadeiras. — Ótimo. E vamos levar comida ou paramos num mercado ? — Vou fazer sanduíches em casa, é mais barato. — Então eu levo os refrescos. — Combinado: sábado às sete, na esquina da minha rua. — Perfeito, não vou me atrasar !",
        questions: [
                            Exercise(id: "pt-listen-fds-praia-q1", kind: "choice", prompt: "Para onde o grupo vai no fim de semana ?", options: ["Para a praia", "Para a serra", "Para a casa da avó", "Para um hotel na cidade"], answers: ["Para a praia"], explain: "« Vou levar todo mundo para a praia »."),
                            Exercise(id: "pt-listen-fds-praia-q2", kind: "written", prompt: "A que horas saem no sábado ?", options: [], answers: ["às sete", "as sete", "sete horas", "às 7"], explain: "« Saio sábado de manhã cedo, às sete »."),
                            Exercise(id: "pt-listen-fds-praia-q3", kind: "choice", prompt: "Como o grupo vai viajar ?", options: ["De carro", "De ônibus", "De trem", "De avião"], answers: ["De carro"], explain: "« De carro; saio sábado de manhã cedo »."),
                            Exercise(id: "pt-listen-fds-praia-q4", kind: "written", prompt: "O que vão comer lá ?", options: [], answers: ["sanduíches", "sanduiches", "sanduíches feitos em casa"], explain: "« Vou fazer sanduíches em casa, é mais barato »."),
                            Exercise(id: "pt-listen-fds-praia-q5", kind: "choice", prompt: "Onde o grupo se encontra ?", options: ["Na esquina da rua dele", "Na estação de trem", "Na entrada da praia", "No mercado"], answers: ["Na esquina da rua dele"], explain: "« Sábado às sete, na esquina da minha rua ».")], skills: ["listening:detail", "grammar:going-to", "function:make-suggestions"]),
    ListeningText(id: "pt-listen-chave-porta", languageID: "pt", title: "A chave ficou dentro", level: "A2", topic: "problemas", unitID: "pt-foundations-u20",
        text: "— Alô, mãe ? Travei a porta e a chave ficou dentro de casa. — Nossa ! Olha, a chave reserva está aqui comigo, mas não consigo subir agora. — Então vou ligar para o chaveiro do prédio. — Pede o orçamento antes, hein ? — Pede, sim. Ah, o vizinho do terceiro tem uma escada grande. — Menina, não sobe em escada nenhuma ! Espera o chaveiro, com calma. — Está bem, está bem. Fico no corredor esperando. — Assim eu fico tranquila. Depois me conta quanto custou, ouviu ?",
        questions: [
                            Exercise(id: "pt-listen-chave-porta-q1", kind: "written", prompt: "O que aconteceu com a chave ?", options: [], answers: ["ficou dentro de casa", "a chave ficou dentro", "ficou dentro do apartamento"], explain: "« A chave ficou dentro de casa »."),
                            Exercise(id: "pt-listen-chave-porta-q2", kind: "choice", prompt: "O que a mãe tem em casa ?", options: ["A chave reserva", "Uma escada", "Outro apartamento", "O telefone do chaveiro"], answers: ["A chave reserva"], explain: "« A chave reserva está aqui comigo »."),
                            Exercise(id: "pt-listen-chave-porta-q3", kind: "choice", prompt: "O que a mãe não permite ?", options: ["Subir na escada", "Ligar para o chaveiro", "Esperar no corredor", "Pedir o orçamento"], answers: ["Subir na escada"], explain: "« Não sobe em escada nenhuma ! »"),
                            Exercise(id: "pt-listen-chave-porta-q4", kind: "written", prompt: "Onde a filha decide esperar ?", options: [], answers: ["no corredor", "no corredor do prédio", "no corredor do predio"], explain: "« Fico no corredor esperando »."),
                            Exercise(id: "pt-listen-chave-porta-q5", kind: "choice", prompt: "O que a mãe pede antes do serviço ?", options: ["O orçamento", "A foto do chaveiro", "Um documento", "A nota fiscal antiga"], answers: ["O orçamento"], explain: "« Pede o orçamento antes, hein ? »")], skills: ["listening:inference", "vocab:home", "function:solve-problems", "grammar:connectors"]),
    ListeningText(id: "pt-listen-fds-serra", languageID: "pt", title: "O fim de semana na serra", level: "A2", topic: "viagem", unitID: "pt-foundations-u3",
        text: "— Então, como foi o fim de semana na serra ? — Foi maravilhoso ! Saímos sexta à noite e chegamos na cabana às dez. — E o tempo, ajudou ? — Choveu só no sábado de manhã; à tarde abriu e subimos ao mirante. — Que vista, né ? E a comida da região ? — Provei o fondue e um pão de queijo incrível. — E as fotos ? — Tirei um monte; domingo à noite mostro tudo para vocês. — Que inveja boa ! Da próxima vez eu vou junto.",
        questions: [
                            Exercise(id: "pt-listen-fds-serra-q1", kind: "choice", prompt: "Quando eles viajaram ?", options: ["Sexta à noite", "Sábado de manhã", "Domingo cedo", "Quinta à noite"], answers: ["Sexta à noite"], explain: "« Saímos sexta à noite »."),
                            Exercise(id: "pt-listen-fds-serra-q2", kind: "written", prompt: "O que aconteceu no sábado de manhã ?", options: [], answers: ["choveu", "choveu de manhã", "choveu um pouco"], explain: "« Choveu só no sábado de manhã »."),
                            Exercise(id: "pt-listen-fds-serra-q3", kind: "choice", prompt: "O que fizeram quando abriu ?", options: ["Subiram ao mirante", "Ficaram na cabana", "Voltaram para casa", "Foram a um restaurante"], answers: ["Subiram ao mirante"], explain: "« À tarde abriu e subimos ao mirante »."),
                            Exercise(id: "pt-listen-fds-serra-q4", kind: "choice", prompt: "O que ele provou na viagem ?", options: ["Fondue e pão de queijo", "Pizza e açaí", "Truta e vinho", "Chocolate quente"], answers: ["Fondue e pão de queijo"], explain: "« Provei o fondue e um pão de queijo incrível »."),
                            Exercise(id: "pt-listen-fds-serra-q5", kind: "written", prompt: "Quando ele mostra as fotos ?", options: [], answers: ["domingo à noite", "domingo a noite", "no domingo à noite"], explain: "« Domingo à noite mostro tudo para vocês ».")], skills: ["listening:detail", "grammar:past-simple-regular", "function:describe-past-events", "vocab:travel"]),
    ListeningText(id: "pt-listen-entrevista-inflacao", languageID: "pt", title: "O preço do carrinho", level: "B2", topic: "notícias", unitID: "pt-foundations-u8",
        text: "— Boa noite. Hoje falamos do preço da comida com a economista Helena Braga. Dona Helena, por que o carrinho subiu tanto este ano ? — Dois motivos: a seca reduziu a colheita do arroz e o frete internacional ficou mais caro. Quando o frete sobe, o supermercado repassa o aumento. — E o que muda na mesa das famílias ? — Muda a marca, não a refeição: muita gente troca produtos de marca por itens de armazém. — O governo anunciou a redução de impostos sobre alimentos básicos. Isso resolve ? — Ajuda, mas não resolve tudo; sem chuva boa, o problema volta no ano que vem. — Obrigado pela análise, dona Helena.",
        questions: [
                            Exercise(id: "pt-listen-entrevista-inflacao-q1", kind: "choice", prompt: "Quais são os dois motivos citados para a alta ?", options: ["A seca e o frete mais caro", "O aluguel e a energia", "Os impostos e o salário", "A seca e o desemprego"], answers: ["A seca e o frete mais caro"], explain: "« A seca reduziu a colheita… e o frete internacional ficou mais caro »."),
                            Exercise(id: "pt-listen-entrevista-inflacao-q2", kind: "choice", prompt: "O que as famílias mudam na compra ?", options: ["Trocam a marca, não a refeição", "Param de comprar arroz", "Compram só importado", "Deixam de cozinhar"], answers: ["Trocam a marca, não a refeição"], explain: "« Muda a marca, não a refeição »."),
                            Exercise(id: "pt-listen-entrevista-inflacao-q3", kind: "written", prompt: "O que o governo anunciou ?", options: [], answers: ["a redução de impostos", "redução de impostos sobre alimentos", "reduzir impostos", "a reducao de impostos"], explain: "« O governo anunciou a redução de impostos sobre alimentos básicos »."),
                            Exercise(id: "pt-listen-entrevista-inflacao-q4", kind: "choice", prompt: "Qual é a ressalva da economista ?", options: ["Sem chuva boa, o problema volta", "Os impostos não existem mais", "O frete vai cair sozinho", "Ninguém troca de marca"], answers: ["Sem chuva boa, o problema volta"], explain: "« Sem chuva boa, o problema volta no ano que vem »."),
                            Exercise(id: "pt-listen-entrevista-inflacao-q5", kind: "written", prompt: "Quem é Helena Braga ?", options: [], answers: ["economista", "uma economista", "a economista"], explain: "« Falamos do preço da comida com a economista Helena Braga ».")], skills: ["listening:inference", "listening:detail", "grammar:connectors", "grammar:first-conditional"]),
    ListeningText(id: "pt-listen-debate-carros", languageID: "pt", title: "Carros no centro: sim ou não ?", level: "B2", topic: "debate", unitID: "pt-foundations-u8",
        text: "Apresentador: Nossa pauta de hoje: proibir carros no centro, sim ou não ? — Lucas: A favor. O centro vive engarrafado; se os carros saíssem, o transporte público ficaria mais rápido e o ar, mais limpo. — Marta: Discordo. Meu pai é comerciante e depende do carro para a entrega da manhã. Se proibirem, ele perde clientes. — Lucas: As entregas podem ser de bicicleta elétrica, como em outras cidades. — Marta: Bonito no papel; na prática, quem paga a diferença ? — Apresentador: E os pedestres, o que dizem ? — Lucas: Andamos mais e com segurança; a calçada vira espaço de gente, não de motor. — Marta: Que seja aos domingos, como teste. — Apresentador: Um bom meio-termo. Continuem a discussão no nosso site.",
        questions: [
                            Exercise(id: "pt-listen-debate-carros-q1", kind: "choice", prompt: "Qual é o argumento principal de Lucas ?", options: ["Centro engarrafado e ar mais limpo", "Estacionamento mais barato", "Mais vagas de garagem", "Táxis mais rápidos"], answers: ["Centro engarrafado e ar mais limpo"], explain: "« O centro vive engarrafado… e o ar, mais limpo »."),
                            Exercise(id: "pt-listen-debate-carros-q2", kind: "written", prompt: "De que o pai de Marta depende para trabalhar ?", options: [], answers: ["do carro", "do carro para a entrega", "do carro de entrega"], explain: "« Meu pai… depende do carro para a entrega da manhã »."),
                            Exercise(id: "pt-listen-debate-carros-q3", kind: "choice", prompt: "Qual alternativa Lucas propõe para as entregas ?", options: ["Bicicleta elétrica", "Caminhão pequeno", "Moto de entrega", "Drone"], answers: ["Bicicleta elétrica"], explain: "« As entregas podem ser de bicicleta elétrica »."),
                            Exercise(id: "pt-listen-debate-carros-q4", kind: "written", prompt: "Qual concessão Marta aceita no fim ?", options: [], answers: ["aos domingos", "teste aos domingos", "um teste aos domingos", "proibir aos domingos"], explain: "« Que seja aos domingos, como teste »."),
                            Exercise(id: "pt-listen-debate-carros-q5", kind: "choice", prompt: "Como o apresentador classifica o acordo ?", options: ["Um bom meio-termo", "Uma péssima ideia", "Uma decisão final", "Um empate técnico"], answers: ["Um bom meio-termo"], explain: "« Um bom meio-termo ».")], skills: ["listening:inference", "function:express-opinion", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "pt-listen-aluguel-negociado", languageID: "pt", title: "O reajuste do aluguel", level: "B2", topic: "negociação", unitID: "pt-foundations-u7",
        text: "— Então, senhora Rosa, o contrato vence em março e o senhorio pede um reajuste de doze por cento. — Doze ? Isso está acima do índice; foi o que li no jornal. — Ele argumenta com as reformas: pintura nova e o portão eletrônico. — As melhorias são bem-vindas, reconheço. Mas proponho oito por cento, dentro do índice. — Ele aceitaria dez, com contrato de dois anos. — Dez e dois anos… Aceito, com uma condição: ele conserta a infiltração da varanda antes de junho. — Vou levar a proposta; acho que fecha. — Ótimo. Mande o contrato por escrito para eu ler com calma.",
        questions: [
                            Exercise(id: "pt-listen-aluguel-negociado-q1", kind: "written", prompt: "Quanto o senhorio pede de reajuste ?", options: [], answers: ["doze por cento", "12%", "12 %", "doze"], explain: "« Pede um reajuste de doze por cento »."),
                            Exercise(id: "pt-listen-aluguel-negociado-q2", kind: "choice", prompt: "Com que argumento o senhorio justifica o valor ?", options: ["As reformas feitas", "O IPTU novo", "A inflação do mês", "Os vizinhos que saíram"], answers: ["As reformas feitas"], explain: "« Ele argumenta com as reformas: pintura nova e o portão eletrônico »."),
                            Exercise(id: "pt-listen-aluguel-negociado-q3", kind: "written", prompt: "O que a senhora Rosa propõe primeiro ?", options: [], answers: ["oito por cento", "8%", "8 %", "oito"], explain: "« Proponho oito por cento, dentro do índice »."),
                            Exercise(id: "pt-listen-aluguel-negociado-q4", kind: "choice", prompt: "Qual acordo final se desenha ?", options: ["Dez por cento com contrato de dois anos", "Oito por cento sem contrato", "Doze por cento com pintura", "Nenhum reajuste"], answers: ["Dez por cento com contrato de dois anos"], explain: "« Ele aceitaria dez, com contrato de dois anos »."),
                            Exercise(id: "pt-listen-aluguel-negociado-q5", kind: "written", prompt: "Qual condição a senhora coloca ?", options: [], answers: ["consertar a infiltração", "a infiltração da varanda", "conserto da infiltração", "consertar a infiltracao"], explain: "« Ele conserta a infiltração da varanda antes de junho ».")], skills: ["listening:inference", "function:negotiate", "grammar:second-conditional", "grammar:connectors"]),
    ListeningText(id: "pt-listen-aumento-pedido", languageID: "pt", title: "A conversa do aumento", level: "B2", topic: "trabalho",
        text: "— Rafael, senta aqui. Vi que você assumiu três clientes novos este trimestre. — Sim, e o resultado do time cresceu: entregamos vinte por cento mais que no ano passado. — Os números são bons, reconheço. O que você tem em mente ? — Gostaria de conversar sobre o meu salário. Pesquisei o mercado: o cargo paga de quinze a vinte por cento acima do que recebo. — Vou ser franco: o orçamento deste semestre está apertado. — E se eu assumir a coordenação do projeto novo ? Aí o ajuste se paga sozinho. — Deixa-me conversar com a diretoria. Volto a falar com você na próxima sexta. — Combinado; levo uma proposta por escrito.",
        questions: [
                            Exercise(id: "pt-listen-aumento-pedido-q1", kind: "written", prompt: "O que Rafael quer conversar ?", options: [], answers: ["o salário", "meu salário", "o aumento salarial", "o salario"], explain: "« Gostaria de conversar sobre o meu salário »."),
                            Exercise(id: "pt-listen-aumento-pedido-q2", kind: "choice", prompt: "Que número Rafael apresenta ?", options: ["Vinte por cento mais entregas", "Três projetos cancelados", "Quinze clientes perdidos", "Meta cumprida pela metade"], answers: ["Vinte por cento mais entregas"], explain: "« Entregamos vinte por cento mais que no ano passado »."),
                            Exercise(id: "pt-listen-aumento-pedido-q3", kind: "choice", prompt: "Qual é a objeção do gestor ?", options: ["O orçamento está apertado", "Rafael é novo demais", "O mercado está ruim", "A diretoria recusou"], answers: ["O orçamento está apertado"], explain: "« O orçamento deste semestre está apertado »."),
                            Exercise(id: "pt-listen-aumento-pedido-q4", kind: "written", prompt: "O que Rafael oferece em troca ?", options: [], answers: ["assumir a coordenação", "a coordenação do projeto", "assumir a coordenação do projeto novo", "assumir a coordenacao"], explain: "« E se eu assumir a coordenação do projeto novo ? »"),
                            Exercise(id: "pt-listen-aumento-pedido-q5", kind: "choice", prompt: "Quando o gestor dá a resposta ?", options: ["Na próxima sexta", "Hoje à noite", "No fim do mês", "Depois do projeto"], answers: ["Na próxima sexta"], explain: "« Volto a falar com você na próxima sexta ».")], skills: ["listening:inference", "function:negotiate", "vocab:work", "grammar:connectors"]),
    ListeningText(id: "pt-listen-noticia-energia", languageID: "pt", title: "Solar nos telhados", level: "B2", topic: "notícias", unitID: "pt-foundations-u8",
        text: "Locutor: Notícias da cidade. O programa de energia solar dos telhados foi aprovado ontem pela câmara. Pelas regras, famílias que instalarem painéis até o fim do ano recebem desconto na taxa de instalação, e escolas públicas ganham kits gratuitos. O prefeito comemorou: segundo ele, a conta de luz cairia até trinta por cento nas unidades beneficiadas. A oposição pede cuidado: o custo do programa seria alto e os prazos, otimistas. A associação de moradores do bairro Norte apoia, mas cobra um detalhe — as oficinas de manutenção precisam treinar técnicos locais, não trazê-los de fora. A previsão da prefeitura é publicar o edital no próximo mês.",
        questions: [
                            Exercise(id: "pt-listen-noticia-energia-q1", kind: "choice", prompt: "O que foi aprovado ontem ?", options: ["O programa de energia solar dos telhados", "A tarifa do ônibus", "O novo mercado municipal", "O plano da ciclovia"], answers: ["O programa de energia solar dos telhados"], explain: "« O programa de energia solar dos telhados foi aprovado ontem pela câmara »."),
                            Exercise(id: "pt-listen-noticia-energia-q2", kind: "written", prompt: "O que ganham as escolas públicas ?", options: [], answers: ["kits gratuitos", "kits", "kits de painéis", "kits gratis"], explain: "« Escolas públicas ganham kits gratuitos »."),
                            Exercise(id: "pt-listen-noticia-energia-q3", kind: "choice", prompt: "Qual é a promessa do prefeito ?", options: ["A conta de luz cairia até trinta por cento", "Empregos para cem técnicos", "Ônibus solar em junho", "Imposto zero em janeiro"], answers: ["A conta de luz cairia até trinta por cento"], explain: "« A conta de luz cairia até trinta por cento nas unidades beneficiadas »."),
                            Exercise(id: "pt-listen-noticia-energia-q4", kind: "choice", prompt: "O que a oposição critica ?", options: ["O custo alto e os prazos otimistas", "O desconto das famílias", "Os kits das escolas", "O bairro Norte"], answers: ["O custo alto e os prazos otimistas"], explain: "« O custo do programa seria alto e os prazos, otimistas »."),
                            Exercise(id: "pt-listen-noticia-energia-q5", kind: "written", prompt: "O que a associação de moradores cobra ?", options: [], answers: ["treinar técnicos locais", "treinar tecnicos locais", "oficinas de manutenção locais"], explain: "« As oficinas… precisam treinar técnicos locais ».")], skills: ["listening:inference", "grammar:passive-intro", "grammar:connectors", "vocab:town"])
    ]
}
